if ( ! function_exists( 'formatUkMobile' ) ) {
    function formatUkMobile( $number ) {
        $number = preg_replace( '/[^0-9]/', '', $number );
        if ( substr( $number, 0, 2 ) == '07' && strlen( $number ) == 11 ) {
            return '44' . substr( $number, 1 );
        }
        if ( substr( $number, 0, 3 ) == '447' && strlen( $number ) == 12 ) {
            return $number;
        }
        return false;
    }
}

/**
 * Normalise a supported mobile number to digits-only E.164 format.
 *
 * UK numbers remain stored as 447..., while US/NANP numbers are stored as
 * 1... . A leading + or 00 international prefix is accepted for other E.164
 * senders so FireText webhook callbacks can be matched consistently.
 */
if ( ! function_exists( 'aimee_format_mobile' ) ) {
    function aimee_format_mobile( $number, $market = null ) {
        $raw = trim( (string) $number );
        if ( $raw === '' || is_email( $raw ) ) {
            return false;
        }

        $had_international_prefix = strpos( $raw, '+' ) === 0
            || preg_match( '/^\s*00/', $raw );
        $digits = preg_replace( '/[^0-9]/', '', $raw );

        if ( strpos( $digits, '00' ) === 0 ) {
            $digits = substr( $digits, 2 );
        }

        $uk = formatUkMobile( $digits );
        if ( $uk ) {
            return $uk;
        }

        // North American Numbering Plan: +1 followed by ten digits. Area and
        // exchange codes cannot start with 0 or 1.
        if (
            strlen( $digits ) === 11
            && substr( $digits, 0, 1 ) === '1'
            && preg_match( '/^1[2-9][0-9]{2}[2-9][0-9]{6}$/', $digits )
        ) {
            return $digits;
        }

        if (
            strlen( $digits ) === 10
            && preg_match( '/^[2-9][0-9]{2}[2-9][0-9]{6}$/', $digits )
            && ( $market === 'us' || $had_international_prefix )
        ) {
            return '1' . $digits;
        }

        // Preserve explicitly supplied international E.164 numbers. FireText
        // expects the destination without a leading plus sign.
        if (
            $had_international_prefix
            && preg_match( '/^[1-9][0-9]{7,14}$/', $digits )
        ) {
            return $digits;
        }

        return false;
    }
}

if ( ! function_exists( 'aimee_mobile_login_candidates' ) ) {
    function aimee_mobile_login_candidates( $login, $market = null ) {
        $login = trim( (string) $login );
        $candidates = [ $login ];
        $digits = preg_replace( '/[^0-9]/', '', $login );
        $normalised = aimee_format_mobile( $login, $market );

        if ( $digits !== '' ) {
            $candidates[] = $digits;
        }
        if ( $normalised ) {
            $candidates[] = $normalised;
            if ( strpos( $normalised, '44' ) === 0 && strlen( $normalised ) === 12 ) {
                $candidates[] = '0' . substr( $normalised, 2 );
            }
            if ( strpos( $normalised, '1' ) === 0 && strlen( $normalised ) === 11 ) {
                $candidates[] = substr( $normalised, 1 );
            }
        }

        $sanitised = [];
        foreach ( $candidates as $candidate ) {
            $candidate = sanitize_user( (string) $candidate, true );
            if ( $candidate !== '' ) {
                $sanitised[] = $candidate;
            }
        }

        return array_values( array_unique( $sanitised ) );
    }
}

if ( ! function_exists( 'aimee_profile_market' ) ) {
    function aimee_profile_market( $profile ) {
        if ( is_object( $profile ) && ! empty( $profile->market ) ) {
            return sanitize_key( (string) $profile->market ) === 'us' ? 'us' : 'uk';
        }
        // The profile row is the sole billing-market authority. UI cookies and
        // former user-meta values must never select a payment rail.
        return 'uk';
    }
}

// Let users sign in with 07/447 or 10-digit/+1 variants of the same mobile.
add_filter( 'authenticate', function ( $user, $username, $password ) {
    if ( $user instanceof WP_User || $username === '' || $password === '' || is_email( $username ) ) {
        return $user;
    }

    $market = function_exists( 'aimee_global_market' )
        ? aimee_global_market()
        : null;

    foreach ( aimee_mobile_login_candidates( $username, $market ) as $candidate ) {
        if ( hash_equals( (string) $username, (string) $candidate ) ) {
            continue;
        }
        $attempt = wp_authenticate_username_password( null, $candidate, $password );
        if ( $attempt instanceof WP_User ) {
            return $attempt;
        }
    }

    return $user;
}, 30, 3 );


