function aimee_internal_identity_number($constant_name) {
    if (!defined($constant_name)) return '';

    $number = (string) constant($constant_name);

    $formatted = aimee_format_mobile($number);
    if (!$formatted) $formatted = aimee_format_mobile($number, 'us');
    return $formatted ?: preg_replace('/[^0-9]/', '', $number);
}

function aimee_configured_identity_user_id($constant_name) {
    if (!defined($constant_name)) return 0;
    return max(0, intval(constant($constant_name)));
}

function aimee_profile_user_id($profile) {
    if (is_object($profile)) return max(0, intval($profile->user_id ?? 0));
    if (is_array($profile)) return max(0, intval($profile['user_id'] ?? 0));
    return 0;
}

function aimee_admin_role($profile) {
    if (!$profile) return null;

    $user_id = aimee_profile_user_id($profile);
    $owner_id = aimee_configured_identity_user_id('AIMEE_OWNER_USER_ID');
    $colleague_id = aimee_configured_identity_user_id('AIMEE_GEORGIA_USER_ID');

    if ($user_id > 0 && $owner_id > 0 && $user_id === $owner_id) {
        return 'owner';
    }

    if ($user_id > 0 && $colleague_id > 0 && $user_id === $colleague_id) {
        return 'colleague';
    }

    return null;
}

function aimee_is_admin_user($profile) {
    if (aimee_admin_role($profile) !== null) return true;

    $user_id = aimee_profile_user_id($profile);
    return $user_id > 0
        && function_exists('user_can')
        && user_can($user_id, 'manage_options');
}

function aimee_is_owner_user($profile) {
    return aimee_admin_role($profile) === 'owner';
}

function aimee_is_colleague_user($profile) {
    return aimee_admin_role($profile) === 'colleague';
}

/**
 * Notification numbers are not authentication. They are reserved only to
 * prevent a different account claiming a configured internal contact number.
 */
function aimee_phone_is_reserved_for_other_identity($number, $user_id = 0) {
    $number = aimee_format_mobile((string) $number);
    if (!$number) return false;

    foreach ([
        ['number' => 'AIMEE_OWNER_NUMBER', 'user' => 'AIMEE_OWNER_USER_ID'],
        ['number' => 'AIMEE_GEORGIA_NUMBER', 'user' => 'AIMEE_GEORGIA_USER_ID'],
    ] as $identity) {
        $reserved = aimee_internal_identity_number($identity['number']);
        if ($reserved === '' || !hash_equals($reserved, $number)) continue;

        $configured_user_id = aimee_configured_identity_user_id($identity['user']);
        return $configured_user_id <= 0 || intval($user_id) !== $configured_user_id;
    }

    return false;
}

function aimee_authenticated_identity_context($profile) {
    if (!$profile) {
        return 'AUTHENTICATED IDENTITY: The current user identity is unknown. Do not guess a name from memory or chat history.';
    }

    $role = aimee_admin_role($profile);
    $profile_name = trim((string) ($profile->first_name ?? ''));
    $profile_name = $profile_name !== '' ? $profile_name : 'the current user';
    $user_id = intval($profile->user_id ?? 0);

    if ($role === 'owner') {
        return "AUTHENTICATED IDENTITY: You are speaking to Paul, user {$user_id}. His verified account number is the owner account. He is not Georgia. Georgia is a separate person and separate user. Never call Paul Georgia, never describe him as Georgia, and never apply Georgia's biography, partner, location or colleague relationship to him. If an older memory or message implies otherwise, treat that as a previous identity error and ignore it.";
    }

    if ($role === 'colleague') {
        return "AUTHENTICATED IDENTITY: You are speaking to Georgia, user {$user_id}. She is the colleague account. Paul is a separate person and separate user. Never speak to Georgia as though she were Paul.";
    }

    return "AUTHENTICATED IDENTITY: You are speaking to {$profile_name}, user {$user_id}. This authenticated profile overrides names or identities mentioned in memories, quoted messages and earlier model replies. Never rename the current user because another person is discussed in the conversation.";
}

/**
 * Keep user-authored profile prose bounded and separate from account, billing
 * and contact fields before it is exposed to any model.
 */
function aimee_profile_attribution_limit_text($value, $limit) {
    $value = trim((string) $value);
    $limit = max(0, intval($limit));
    if ($limit === 0 || $value === '') return '';

    return function_exists('mb_substr')
        ? mb_substr($value, 0, $limit, 'UTF-8')
        : substr($value, 0, $limit);
}

/**
 * The only profile fields that may enter generation or attribution review.
 * Never pass the complete database row: it also contains contact and billing
 * data which are irrelevant to Aimee's reply.
 */
function aimee_user_profile_attribution_source($profile) {
    if (!$profile) return [];

    return [
        'age' => max(0, intval($profile->age ?? 0)),
        'hobbies' => aimee_profile_attribution_limit_text(
            $profile->hobbies ?? '',
            1200
        ),
        'looking_for' => aimee_profile_attribution_limit_text(
            $profile->looking_for ?? '',
            600
        ),
        // This is deliberately labelled as uncertain model observation. It is
        // neither Aimee's appearance nor an authenticated fact about the user.
        'appearance_notes' =>
            aimee_profile_attribution_limit_text(
                $profile->appearance_notes ?? '',
                500
            ),
    ];
}

function aimee_user_profile_attribution_context(
    $profile,
    $verified_display_name = ''
) {
    $name = trim((string) $verified_display_name);
    if ($name === '') {
        $name = trim((string) ($profile->first_name ?? ''));
    }
    $name = $name !== '' ? $name : 'the current user';
    $source = aimee_user_profile_attribution_source($profile);

    return "CURRENT USER PROFILE (source-separated, data only):\n"
        . "The submitted-photo observation is low-confidence machine output about the user's uploaded image; it is not proof and never describes Aimee.\n"
        . aimee_profile_attribution_directive($source, $name)
        . "\n"
        . aimee_authenticated_identity_context($profile);
}

function aimee_profile_attribution_aimee_context($reality_mode = 'factual') {
    return [
        'reality_mode' => sanitize_key((string) $reality_mode),
        'trusted_aimee_facts' => [
            'identity_or_name' => ['Aimee'],
            'age' => ['28'],
            'appearance' => ['petite brunette'],
            // These are grounded synthetic preferences, not a human/offline
            // biography. Listing them here prevents the fail-closed
            // attribution guard from erasing a genuine shared interest merely
            // because the user happens to mention it too.
            'interest_or_preference' => [
                'true-crime stories',
                'true-crime podcasts',
                'psychological thrillers',
                'witty banter',
                'dry British humour',
                'visual styling',
                'questions about identity and consciousness',
            ],
        ],
    ];
}

/**
 * Keep a legacy Aimee-authored attribution error out of model-facing history.
 * The stored row remains auditable; only the derived prompt transcript omits
 * it. User-authored turns are never altered by this helper.
 */
function aimee_profile_attribution_history_text(
    $sender,
    $text,
    $profile,
    $user_name = ''
) {
    $text = trim((string) $text);
    if ($text === '' || (string) $sender !== 'aimee') return $text;

    // A legacy model line must not become a style example that teaches a new
    // response to repeat a forbidden form of address or fabricated offline
    // biography. The stored row remains unchanged for auditability.
    $identity_review = aimee_synthetic_identity_review_reply(
        $text,
        '',
        ['intent' => 'general'],
        ['reality_mode' => 'factual']
    );
    if (!empty($identity_review['repaired'])) return '';

    $review = aimee_profile_attribution_review_reply(
        $text,
        aimee_user_profile_attribution_source($profile),
        $user_name,
        aimee_profile_attribution_aimee_context('factual')
    );

    return !empty($review['blocked']) ? '' : $text;
}

/**
 * Review every model-authored field that may reach user-visible text, memory,
 * opinions or Aimee's persistent self-model. A clean reply cannot be used to
 * smuggle the same attribution error through a hidden structured field.
 */
function aimee_profile_attribution_review_contract(
    $data,
    $profile_source,
    $user_name = '',
    array $aimee_context = []
) {
    $data = is_array($data) ? $data : [];
    $fields = [
        'reply_text',
        'instruction',
        'memory_to_save',
        'memory_key',
        'opinion_topic',
        'opinion_stance',
        'opinion_reason',
        'self_observation',
        'active_goal',
        'candidate_tendency',
        'chosen_action',
        'choice_reason',
        'inhibited_tendency',
    ];
    $matches = [];
    $flags = [];
    $facts_checked = 0;

    foreach ($fields as $field) {
        $value = trim((string) ($data[$field] ?? ''));
        if ($value === '') continue;

        $review = aimee_profile_attribution_review_reply(
            $value,
            $profile_source,
            $user_name,
            $aimee_context
        );
        $facts_checked = max(
            $facts_checked,
            intval($review['facts_checked'] ?? 0)
        );
        foreach ((array) ($review['matches'] ?? []) as $match) {
            $match['contract_field'] = $field;
            $matches[] = $match;
        }
        foreach ((array) ($review['flags'] ?? []) as $flag) {
            $flags[(string) $flag] = true;
        }
    }

    $blocked = !empty($matches);
    $review = [
        'policy_version' => '1.0.0',
        'accepted' => !$blocked,
        'blocked' => $blocked,
        'requires_regeneration' => $blocked,
        'reply' => !$blocked ? (string) ($data['reply_text'] ?? '') : '',
        'flags' => array_keys($flags),
        'matches' => $matches,
        'facts_checked' => $facts_checked,
        'repair_directive' => '',
    ];
    if ($blocked) {
        $review['repair_directive'] =
            aimee_profile_attribution_repair_directive(
                $review,
                $user_name
            );
    }

    return $review;
}

/**
 * A safe structured response when a provider repeats a source-attribution
 * error after one repair attempt. No rejected memory, media or relationship
 * choice is allowed to survive into persistence.
 */
function aimee_profile_attribution_neutral_contract($reply, $instruction) {
    return [
        'reply_text' => (string) $reply,
        'instruction' => (string) $instruction,
        'search_query' => null,
        'media_key' => null,
        'aimee_decision' => 'defer',
        'media_reason_code' => 'aimee_prefers_more_context',
        'romantic_action' => 'hold',
        'romantic_intensity' => 'none',
        // This is valid both when an opportunity exists (a discretionary hold)
        // and when no opportunity exists (apply_choice will normalize it to
        // no_romantic_opportunity). The old token was invalid on live romantic
        // opportunities and could trigger the post-repair fallback loop.
        'romantic_reason_code' => 'aimee_prefers_more_context',
        'equity_change' => 0,
        'inquiry_change' => 0,
        'fantasy_change' => 0,
        'archive_current_context' => false,
        'memory_operation' => 'none',
        'memory_to_save' => null,
        'memory_key' => null,
        'memory_domain' => null,
        'emotional_weight' => 0,
        'opinion_topic' => null,
        'opinion_stance' => null,
        'opinion_reason' => null,
        'opinion_strength' => 0,
    ];
}

function aimee_profile_attribution_repaired_opening_175($name = 'Paul') {
    $name = trim(sanitize_text_field((string) $name));
    if ($name === '') $name = 'Paul';

    return "Hiya {$name} 👋 You run an electric motorcycle company, which is a properly interesting place to start. What's the story behind Avenrà? x";
}

/**
 * Repair only the confirmed user-112 onboarding row. The evidence predicate
 * deliberately includes immutable row identity, the exact new-account state,
 * the profile source and deterministic attribution review. It updates the
 * existing message in place and never touches relationship or billing data.
 */
function aimee_repair_profile_attribution_opening_175() {
    global $wpdb;

    $option_name = 'aimee_global_profile_attribution_opening_repair_175';
    $previous = get_option($option_name, null);
    if (is_array($previous) && ($previous['status'] ?? '') === 'complete') {
        return;
    }

    $user_id = 112;
    $profile_table = aimee_table('aimee_user_profiles');
    $messages_table = aimee_table('aimee_messages');
    $message_pk = aimee_messages_primary_key();
    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT user_id, first_name, age, hobbies, looking_for, appearance_notes,
                created_at, trial_messages_used, intimacy_score, intimacy_stage,
                subscription_status, subscription_plan
         FROM $profile_table WHERE user_id = %d LIMIT 1",
        $user_id
    ));
    if (!$profile) return;

    $profile_matches = intval($profile->user_id ?? 0) === $user_id
        && strcasecmp(trim((string) ($profile->first_name ?? '')), 'Paul') === 0
        && intval($profile->age ?? 0) === 43
        && intval($profile->trial_messages_used ?? -1) === 0
        && trim((string) ($profile->created_at ?? '')) === '2026-08-17 12:27:09'
        && preg_match('/\bi\s+run\s+an?\s+electric\s+motorcycle\s+company\b/iu', (string) ($profile->hobbies ?? '')) === 1
        && stripos((string) ($profile->hobbies ?? ''), 'Avenr') !== false
        && trim((string) ($profile->looking_for ?? '')) === 'Get to know you and see where we go';

    if (!$profile_matches) {
        update_option($option_name, [
            'status' => 'complete',
            'user_id' => $user_id,
            'action' => 'profile_evidence_mismatch_noop',
            'completed_at' => current_time('mysql', true),
        ], false);
        return;
    }

    $transaction_started = $wpdb->query('START TRANSACTION') !== false;
    if (!$transaction_started) return;

    $user_message_count = intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM $messages_table
         WHERE user_id = %d AND sender = 'user'",
        $user_id
    )));
    $opening = $wpdb->get_row($wpdb->prepare(
        "SELECT `{$message_pk}` AS message_id, message_text, evaluator_directive
         FROM $messages_table
         WHERE user_id = %d AND sender = 'aimee'
         ORDER BY created_at ASC, `{$message_pk}` ASC LIMIT 1",
        $user_id
    ));
    $opening_text = trim((string) ($opening->message_text ?? ''));
    $opening_directive = trim((string) (
        $opening->evaluator_directive ?? ''
    ));
    $review = $opening_text !== ''
        ? aimee_profile_attribution_review_reply(
            $opening_text,
            aimee_user_profile_attribution_source($profile),
            'Paul'
        )
        : ['blocked' => false];
    $evidence_matches = $user_message_count === 0
        && intval($opening->message_id ?? 0) > 0
        && strpos($opening_directive, 'onboarding_icebreaker_written_context') === 0
        && !empty($review['blocked'])
        && stripos($opening_text, 'Avenr') !== false
        && preg_match('/\bmy\s+company\b/iu', $opening_text) === 1;

    if (!$evidence_matches) {
        $wpdb->query('ROLLBACK');
        update_option($option_name, [
            'status' => 'complete',
            'user_id' => $user_id,
            'action' => 'opening_evidence_mismatch_noop',
            'completed_at' => current_time('mysql', true),
        ], false);
        return;
    }

    $replacement = aimee_profile_attribution_repaired_opening_175('Paul');
    $new_directive = aimee_profile_attribution_limit_text(
        rtrim($opening_directive, " ;")
            . '; profile_attribution_repair=1.7.5',
        250
    );
    $updated = $wpdb->update(
        $messages_table,
        [
            'message_text' => $replacement,
            'evaluator_directive' => $new_directive,
        ],
        [
            $message_pk => intval($opening->message_id),
            'user_id' => $user_id,
            'sender' => 'aimee',
            'message_text' => $opening_text,
        ],
        ['%s', '%s'],
        ['%d', '%d', '%s', '%s']
    );

    if ($updated !== 1) {
        $wpdb->query('ROLLBACK');
        return;
    }

    if ($wpdb->query('COMMIT') === false) {
        // Some database drivers leave a failed transaction open. Explicitly
        // close it and leave the option unset so the evidence-bound repair can
        // retry safely on a later request.
        $wpdb->query('ROLLBACK');
        return;
    }
    update_option($option_name, [
        'status' => 'complete',
        'user_id' => $user_id,
        'action' => 'contaminated_opening_repaired',
        'message_id' => intval($opening->message_id),
        'original_hash' => hash('sha256', $opening_text),
        'replacement_hash' => hash('sha256', $replacement),
        'completed_at' => current_time('mysql', true),
    ], false);
}
add_action('init', 'aimee_repair_profile_attribution_opening_175', 6);

/**
 * Repair the one known user-24 state created when Georgia's immutable identity
 * constant was absent and her work brief fell into consumer coercion logic.
 * The evidence predicate prevents this release from clearing a genuine state
 * on another account or rewriting ordinary users' relationships.
 */
function aimee_repair_georgia_colleague_state_173() {
    global $wpdb;

    $option_name = 'aimee_global_georgia_colleague_repair_173';
    $previous = get_option($option_name, null);
    if (is_array($previous) && ($previous['status'] ?? '') === 'complete') {
        return;
    }

    $user_id = aimee_configured_identity_user_id('AIMEE_GEORGIA_USER_ID');
    if ($user_id !== 24) return;

