function aimee_ni_bond_state_is_restored_189($profile, array $relationship, array $inner) {
    if (
        !$profile
        || intval($profile->user_id ?? 0) !== 27
        || intval($profile->intimacy_score ?? 0) !== 100
        || (string) ($profile->intimacy_stage ?? '') !== 'bonded'
    ) {
