    return intval($relationship['frustration'] ?? -1) === 0
        && intval($relationship['meaningful_interaction_count'] ?? 0) >= 35
        && intval($relationship['qualified_session_count'] ?? 0) >= 5
        && trim((string) ($inner['unresolved_rupture'] ?? '')) === ''
        && (string) ($inner['repair_status'] ?? '') === 'clear'
        && intval($inner['irritation'] ?? -1) === 0
        && intval($inner['romantic_openness'] ?? 0) === 100;
}

