/**
 * One-time site-specific repair for Ni's operator-confirmed user 27 account.
 *
 * The migration is deliberately narrow and auditable. It updates only the
 * relationship dimensions, profile score/stage, inner
 * emotional posture and any false rupture events for this exact account.
 * Adult verification, special-category consent, membership, billing, media
 * unlocks and current-turn consent remain independent and unchanged.
 */
function aimee_repair_ni_bond_state_189() {
    global $wpdb;

    $option_name = 'aimee_global_ni_bond_repair_189';
    $previous = get_option($option_name, null);
    if (is_array($previous) && ($previous['status'] ?? '') === 'complete') {
        return;
    }

    $user_id = 27;
    if (
        !function_exists('aimee_global_schema_claim_lock')
        || !function_exists('aimee_global_schema_release_lock')
        || !aimee_relationship_dimensions_table_available()
    ) {
        return;
    }

    $claim = aimee_global_schema_claim_lock('ni_bond_repair_189', 120);
    if ($claim === '') return;

    $profile_table = aimee_table('aimee_user_profiles');
    $dimensions_table = aimee_relationship_dimensions_table();
    $decisions_table = aimee_table('aimee_relationship_decisions');
    $events_table = aimee_table('aimee_relationship_events');
    $evidence_cutoff = '2026-08-21 04:51:38';
    $now = current_time('mysql', true);
    $completed = false;
    $summary = [];

    if ($wpdb->query('START TRANSACTION') !== false) {
        do {
            // Bind this site-specific mutation to an exact production audit
            // row supplied during the operator's 1.8.8 log review. User ID
            // alone is not sufficient evidence on a copied installation.
            $evidence_count = intval($wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $decisions_table
                 WHERE user_id = %d
                   AND decision_id = %s
                   AND policy_version = '2.2.0'
                   AND created_at = %s",
                $user_id,
                '73c7a1bb-25dd-4a97-a136-75b6a51e6538',
                $evidence_cutoff
            )));
            if ($evidence_count !== 1) break;

            // Invalidate only unresolved rupture rows that pre-date the exact
            // reviewed evidence. A resolved historical event or any genuine
            // event arriving during/after deployment is outside this repair.
            // This is also the live-turn lock order: event -> inner ->
            // dimensions -> profile, avoiding an inverse-order deadlock.
            $events_corrected = $wpdb->query($wpdb->prepare(
                "UPDATE $events_table
                 SET event_type = 'state_correction',
                     actor = 'system',
                     summary = %s,
                     emotional_impact = 0,
                     trust_impact = 0,
                     unresolved = 0,
                     resolved_at = %s
                 WHERE user_id = %d
                   AND event_type = 'relationship_rupture'
                   AND unresolved = 1
                   AND occurred_at <= %s",
                'A previously unresolved rupture was reviewed as an incorrect system-state classification; Ni did not damage the relationship.',
                $now,
                $user_id,
                $evidence_cutoff
            ));
            if ($events_corrected === false) break;

            // Lock rows in the same order used by live turns before loading
            // and replacing state. Missing rows are valid and will be created
            // by their normal save helpers under the transaction gap lock.
            $wpdb->get_row($wpdb->prepare(
                "SELECT user_id FROM `aimee_inner_state` WHERE user_id = %d FOR UPDATE",
                $user_id
            ));
            $wpdb->get_row($wpdb->prepare(
                "SELECT user_id, state_version FROM $dimensions_table WHERE user_id = %d FOR UPDATE",
                $user_id
            ));
            $profile = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM $profile_table WHERE user_id = %d FOR UPDATE",
                $user_id
            ));
            if (!$profile || intval($profile->user_id ?? 0) !== $user_id) break;

            $relationship_before = aimee_load_relationship_state($profile);
            $inner_before = aimee_load_inner_state($user_id);
            $score_before = aimee_relationship_intimacy_score($relationship_before);

            if (
                aimee_ni_bond_state_is_restored_189(
                    $profile,
                    $relationship_before,
                    $inner_before
                )
            ) {
                $summary = [
                    'status' => 'complete',
                    'user_id' => $user_id,
                    'action' => 'already_repaired_verified',
                    'score_before' => 100,
                    'score_after' => 100,
                    'stage_after' => 'bonded',
                    'rupture_events_corrected' => max(0, intval($events_corrected)),
                    'completed_at' => $now,
                ];
                $completed = true;
                break;
            }

            $inner_after = aimee_ni_bond_inner_state_189($inner_before);
            if (!aimee_save_inner_state($user_id, $inner_after)) break;

            $relationship_after = aimee_ni_bond_relationship_state_189(
                $relationship_before
            );
            if (!aimee_save_relationship_state($user_id, $relationship_after)) break;

            $profile_updated = $wpdb->update(
                $profile_table,
                [
                    'intimacy_score' => 100,
                    'intimacy_stage' => 'bonded',
                ],
                ['user_id' => $user_id],
                ['%d', '%s'],
                ['%d']
            );
            if ($profile_updated === false) break;

            $summary = [
                'status' => 'complete',
                'user_id' => $user_id,
                'action' => 'operator_confirmed_bond_restored',
                'score_before' => $score_before,
                'score_after' => 100,
                'stage_after' => 'bonded',
                'rupture_events_corrected' => max(0, intval($events_corrected)),
                'completed_at' => $now,
            ];
            $completed = true;
        } while (false);

        if ($completed && $wpdb->query('COMMIT') !== false) {
            update_option($option_name, $summary, false);
        } else {
            $completed = false;
            $wpdb->query('ROLLBACK');
        }
    }

    aimee_global_schema_release_lock($claim);
}
