            'gallery_visibility' => 'unlock_after_send',
        ],
    ];

    // In operator-approved public mode the manifest is the complete authority.
    // Built-ins may enrich records that are actually declared, but must never
    // resurrect a missing/invalid manifest or an omitted required key.
    $raw_catalog = aimee_public_media_catalogue_mode_enabled() ? [] : $fallback;
    $catalog_path = aimee_private_media_catalog_path();
    if (is_readable($catalog_path)) {
        $decoded = json_decode((string) file_get_contents($catalog_path), true);
        if (is_array($decoded)) {
            foreach ($decoded as $external_key => $external_item) {
                if (!is_array($external_item)) continue;
                $external_key = (string) $external_key;
                if (
                    sanitize_key($external_key) === ''
                    || sanitize_key($external_key) !== $external_key
                ) {
                    continue;
                }
                $external_item = aimee_private_media_public_legacy_item($external_item);
                $raw_catalog[$external_key] = isset($fallback[$external_key])
                    ? array_replace($fallback[$external_key], $external_item)
                    : $external_item;
            }
        }
    }

    $catalog = [];
    $seen_keys = [];
    $collided_keys = [];
    foreach ($raw_catalog as $key => $item) {
        $raw_key = (string) $key;
        $safe_key = sanitize_key($raw_key);
        if ($safe_key === '' || $safe_key !== $raw_key) continue;
        if (isset($seen_keys[$safe_key]) || isset($collided_keys[$safe_key])) {
            unset($catalog[$safe_key]);
            $collided_keys[$safe_key] = true;
            continue;
        }
        $seen_keys[$safe_key] = true;
        $normalized = aimee_normalize_private_media_item(
            $raw_key,
            aimee_private_media_public_legacy_item($item)
        );
        if ($normalized) $catalog[$safe_key] = $normalized;
    }

    return $catalog;
}

