        . '(same |last |previous )?(photo|picture|pic|image|one)\b.{0,20}\b(again|once more|back)\b'
        . '|\b(resend|re-send)\b.{0,30}\b(photo|picture|pic|image|that|it)\b'
        . '|\b(send|show)\b.{0,20}\b(that|the same|the last|the previous) one again\b/u',
        $text
    ) === 1;
