/**
 * Decide whether the immediate conversation is already about Aimee sharing a
 * photograph. Only the recent tail is inspected so an old image discussion
 * cannot turn an unrelated "send me one" into a photo request.
 */
function aimee_recent_history_has_photo_context($recent_history = '') {
    $history = mb_strtolower(trim((string) $recent_history));
    if ($history === '') return false;

    $history = mb_substr($history, -2600);
    $lines = preg_split('/\R/u', $history, -1, PREG_SPLIT_NO_EMPTY);
    $tail = implode("\n", array_slice((array) $lines, -8));

    $has_photo_noun = preg_match(
        '/\b(?:selfie|selfies|photo|photos|picture|pictures|pic|pics|image|images)\b/u',
        $tail
    ) === 1;

    if (!$has_photo_noun) return false;

    return preg_match(
        '/\b(?:aimee|you|your|yourself|send|show|share|pick|choose|one|them|sarah)\b/u',
        $tail
    ) === 1;
}

/**
 * Resolve references such as "send me one", "any of them", "one with Sarah"
 * and "surprise me" when recent turns establish that "one" means one of
 * Aimee's photographs.
 */
function aimee_user_requests_contextual_photo_reference($text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $text));
    $text = str_replace(['’', '‘'], "'", $text);

    if ($text === '') return false;

    if (preg_match(
        '/\b(?:do not|don\'t|dont|no need to|not asking|please do not|please don\'t)\b'
        . '.{0,45}\b(?:send|show|share|give|pick|choose|one|photo|picture|image|selfie)\b/u',
        $text
    )) {
        return false;
    }

    $photo_noun_here = preg_match(
        '/\b(?:selfie|selfies|photo|photos|picture|pictures|pic|pics|image|images)\b/u',
        $text
    ) === 1;

    if (
        !$photo_noun_here
        && preg_match(
            '/\b(?:invoice|document|file|link|code|message|email|receipt|version|option)\b/u',
            $text
        )
    ) {
        return false;
    }

    $reference_request = preg_match(
        '/\b(?:send|show|share|give|pick|choose)\b.{0,48}'
        . '\b(?:me\s+)?(?:one|one of them|any|any of them|whichever|whatever)\b/u',
        $text
    ) === 1
        || preg_match(
            '/\b(?:one|any|whichever|whatever)\s+(?:of\s+)?(?:you|yourself)\b'
            . '(?:.{0,24}\bwith\b.{0,24})?/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:one|any|whichever)\s+(?:with|from|at|in)\s+[\p{L}\p{N}][^?.!]{0,38}/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:any of them|one of them|just (?:send|pick|choose) one|'
            . 'pick one|choose one|you choose|you pick|your choice|surprise me|'
            . 'whichever you (?:like|want|think)|whatever you (?:like|want))\b/u',
            $text
        ) === 1;

    if (!$reference_request) return false;
    if ($photo_noun_here) return true;

    return aimee_recent_history_has_photo_context($recent_history);
}

function aimee_photo_request_level($text, $recent_history = '') {
    if (aimee_user_requests_erotic_photo($text)) return 'erotic';
    if (aimee_user_requests_explicit_photo($text)) return 'explicit';
    if (aimee_user_requests_suggestive_photo($text)) return 'suggestive';
    if (aimee_user_requests_flirty_photo($text)) return 'flirty';
    if (aimee_user_requests_standard_aimee_photo($text, $recent_history)) return 'safe';
    return '';
}

