 * Only the tail of the conversation is inspected so an erotic discussion from
 * hours or days earlier cannot contaminate a normal photograph request now.
 */
function aimee_recent_history_is_active_explicit_exchange($recent_history = '') {
    $history = mb_strtolower(trim((string) $recent_history));
    if ($history === '') return false;

    $history = mb_substr($history, -5000);

    $explicit_pattern = '/\b(?:'
        . 'touching (?:myself|yourself)|masturbat(?:e|ing|ion)|'
        . 'cock|dick|pussy|clit|nipples?|breasts?|tits?|'
        . 'orgasm|cum|cumming|come for me|inside me|inside you|'
        . 'suck(?:ing)?|lick(?:ing)?|fuck(?:ing)?|'
        . 'naked|nude|topless|garter|stockings?|lingerie|'
        . 'hard for you|wet for you|aroused|horny'
        . ')\b/u';

    preg_match_all($explicit_pattern, $history, $matches);

    return count($matches[0]) >= 2;
