function aimee_current_message_has_explicit_arousal_context($text) {
    $text = mb_strtolower(trim((string) $text));
    if ($text === '') return false;

    return preg_match(
        '/\b(?:'
        . 'touching myself|playing with myself|masturbat(?:e|ing)|'
        . 'i(?:\'m| am) hard|hard thinking about you|'
        . 'i(?:\'m| am) wet|i(?:\'m| am) horny|'
        . 'about to cum|about to come|make me cum|make me come|'
        . 'while i touch myself|want to see you too'
        . ')\b/u',
