/**
 * Resolve what kind of photograph is being requested from both the wording and
 * the immediate live context.
 *
 * A plain "send me a photo" remains safe in ordinary conversation. The same
 * wording becomes explicit only when it is embedded in an unmistakably active,
 * consensual adult exchange.
 */
function aimee_contextual_photo_request_level(
    $text,
    $recent_history = '',
    $classification = []
) {
    $literal_level = aimee_photo_request_level($text, $recent_history);

    if (in_array($literal_level, ['explicit', 'erotic', 'suggestive', 'flirty'], true)) {
        return $literal_level;
    }

    if ($literal_level !== 'safe') {
        return '';
    }

    $intent = is_array($classification)
        ? (string) ($classification['intent'] ?? 'general')
        : 'general';

    $explicit_intent = in_array(
        $intent,
        ['explicit_invitation', 'explicit_continuation'],
        true
    );

    $active_explicit_exchange =
        aimee_recent_history_is_active_explicit_exchange($recent_history);

    $current_arousal =
        aimee_current_message_has_explicit_arousal_context($text);

    if (
        $active_explicit_exchange
        && ($explicit_intent || $current_arousal)
    ) {
        return 'erotic';
    }

    return 'safe';
}

function aimee_filter_media_catalog_for_request(
    $catalog,
    $user_text,
    $recent_history = '',
    $classification = []
) {
    if (!is_array($catalog) || !$catalog) return [];

    $level = aimee_contextual_photo_request_level(
        $user_text,
        $recent_history,
        $classification
    );

    if ($level === '') return $catalog;

    return array_filter(
        $catalog,
        function ($item) use ($level) {
            return is_array($item)
                && (string) ($item['content_rating'] ?? 'safe') === $level;
        }
    );
}

