        . '(?:messages?|goes?|chances?|tries?)\b.{0,55}\b(?:off|leave|bye|naked|nude|topless)\b/u',
        $text
    ) === 1
        || (
            preg_match('/\b(?:last|final)\s+(?:go|chance|try|message)\b/u', $text) === 1
            && ($media_context || $boundary_context)
        );

