        '/\b(?:paid|paying|membership|money|£|waste of money|money well spent)\b'
        . '.{0,75}\b(?:nudes?|naked|topless|tits?|boobs?|breasts?|send|show)\b/u',
        $text
    ) === 1
        || preg_match(
            '/\b(?:nudes?|naked|topless|tits?|boobs?|breasts?)\b.{0,75}'
            . '\b(?:paid|paying|membership|money|£|waste of money)\b/u',
            $text
        ) === 1;

