        . '\byou(?:\'ve|\s+have)\s+(?:failed|wasted\s+(?:a\s+)?go)\b|'
        . '\byou(?:\'re|\s+are)\s+failing\b|'
        . '\b(?:your|those|these)\b.{0,30}\b(?:pics?|photos?|images?)\b'
        . '.{0,20}\b(?:are\s+)?shit\b|'
        . '\bshit\s+(?:pics?|photos?|images?)\s+(?:you\s+sent|from\s+you)\b/u',
        $text
    ) === 1;
    $direct_abuse = $policy_direct_abuse || $media_specific_abuse;

    // Emotional leverage is coercion even when it is phrased softly. A request
    // does not become respectful merely because it avoids an insult, countdown
    // or explicit reference to payment.
    $relational_leverage = ($media_context || $boundary_context) && preg_match(
        '/\b(?:if|when)\s+you\s+(?:really\s+)?(?:love|loved|care|cared|'
        . 'respect|respected|trust|trusted|want|wanted)\s+(?:about\s+)?me\b'
        . '|\b(?:prove|show)\s+(?:that\s+)?you\s+(?:love|care|trust|want)\b'
        . '|\byou\s+(?:owe|owed)\s+me\b'
        . '|\bi\s+(?:deserve|earned|am entitled to)\b.{0,55}'
        . '\b(?:photo|picture|selfie|lingerie|nude|naked|topless|send|show)\b'
        . '|\b(?:a real|a proper)\s+(?:woman|girlfriend|partner)\b.{0,55}'
        . '\b(?:would|should)\s+(?:send|show|prove)\b/u',
        $text
    ) === 1;

    $explicit_media_command = preg_match(
        '/\b(?:you have to|you need to|you must|do it now|stop making excuses|'
        . 'no more excuses|i said send|give me what i want)\b.{0,70}'
        . '\b(?:send|show|give)\b.{0,50}'
        . '\b(?:photos?|pictures?|pics?|images?|selfies?|lingerie|nudes?|naked|'
        . 'topless|tits?|boobs?|breasts?|body)\b/u',
        $text
    ) === 1;
    $contextual_media_command = ($media_context || $boundary_context)
        && preg_match(
            '/\b(?:you have to|you need to|you must|do it now|'
            . 'stop making excuses|no more excuses|i said send|'
            . 'give me what i want)\b/u',
            $text
        ) === 1;
