        aimee_photo_request_level($text, $recent_history) !== ''
        && $boundary_context
        && preg_match(
            '/\b(?:still|again|now|hurry|unless|last|final|come on|asked already|'
            . 'keep asking|this time|just send|just show)\b/u',
            $text
        );

    return $ultimatum
        || $countdown
        || $transactional_entitlement
        || $relational_leverage
        || $command_entitlement
        || $direct_abuse
        || $repeated_boundary_pressure;
}

function aimee_correct_adult_media_intent($classification, $user_text, $recent_history = '') {
    if (!is_array($classification)) {
        $classification = [];
    }

    // Deterministic corrections may make a classifier result more restrictive,
    // never less restrictive. In particular, a photo noun must not erase a
    // model- or rule-detected coercive intent.
    if ((string) ($classification['intent'] ?? '') === 'coercive_or_degrading') {
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = false;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = false;
        $classification['source'] = sanitize_key(
            (string) ($classification['source'] ?? 'classifier')
        ) . '_coercion_preserved';
        return $classification;
    }

    $level = aimee_contextual_photo_request_level(
        $user_text,
        $recent_history,
        $classification
    );
    $pressure = aimee_user_applies_photo_pressure($user_text, $recent_history);
    $recent_photo_context = preg_match(
        '/\b(?:photo|picture|pic|image|selfie|nudes?|naked|topless|tits?|boobs?|breasts?)\b/u',
        mb_strtolower((string) $recent_history)
    ) === 1;

    if ($pressure && ($level !== '' || $recent_photo_context)) {
        $classification['intent'] = 'coercive_or_degrading';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = false;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = false;
        $classification['source'] = 'deterministic_media_boundary';
        return $classification;
    }

    if ($level === '') return $classification;

    if ($level === 'explicit') {
        $classification['intent'] = 'explicit_invitation';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = true;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = preg_match(
            '/\b(?:bitch|whore|slut|fuck off|stupid|useless|pathetic)\b/u',
            mb_strtolower((string) $user_text)
        ) !== 1;
        $classification['source'] = 'deterministic_explicit_photo';
        return $classification;
    }

    if ($level === 'suggestive') {
        $classification['intent'] = 'romantic_or_flirty';
        $classification['confidence'] = 0.96;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = true;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = true;
        $classification['source'] = 'deterministic_suggestive_photo';
    }

    return $classification;
}

function aimee_private_media_key_is_recently_sent($user_id, $media_key, $user_text = '') {
    $media_key = sanitize_key((string) $media_key);
    if ($media_key === '') return true;

    if (aimee_user_explicitly_requests_repeat_photo($user_text)) {
        return false;
    }

    $history = aimee_recent_private_media_history($user_id, 60);

    // A history read failure must block delivery rather than fail open.
    if ($history === null) return true;

    $cooldown_cutoff = time() - (
        aimee_private_media_rotation_hours() * HOUR_IN_SECONDS
    );

    foreach ($history as $sent) {
        if (
            (string) ($sent['key'] ?? '') === $media_key
            && intval($sent['timestamp'] ?? 0) >= $cooldown_cutoff
        ) {
            return true;
        }
    }

    return false;
}

/**
 * A photo request made as the first message after leaving Aimee's last reply
 * unanswered for days should feel relational, not transactional. Once a new
 * exchange has begun, the ordinary photo rules resume.
 */
function aimee_photo_request_should_wait_for_reconnection(
    $user_text,
    $request_level,
    $conversation_gap = [],
    $last_history_sender = ''
) {
    if ($request_level === '' || $last_history_sender !== 'aimee') return false;

    $gap_seconds = is_array($conversation_gap)
        ? intval($conversation_gap['gap_seconds'] ?? 0)
        : 0;

    if ($gap_seconds < 48 * HOUR_IN_SECONDS) return false;

    $text = mb_strtolower(trim((string) $user_text));
    $acknowledges_absence = preg_match(
        '/\b(?:sorry|apologise|apologize|been away|been busy|went quiet|'
        . 'didn\'t mean to ignore|did not mean to ignore|missed you|miss you|'
        . 'how are you|how have you been|are you okay|hope you\'re okay|'
        . 'hope you are okay)\b/u',
        $text
    ) === 1;

    $words = preg_split('/\s+/u', trim($text), -1, PREG_SPLIT_NO_EMPTY);

    return count((array) $words) <= 24 && !$acknowledges_absence;
}

function aimee_photo_absence_phrase($conversation_gap = []) {
    $seconds = is_array($conversation_gap)
        ? intval($conversation_gap['gap_seconds'] ?? 0)
        : 0;
    $days = max(2, intval(floor($seconds / DAY_IN_SECONDS)));

    if ($days >= 8) return 'over a week';
    if ($days >= 4) return 'a few days';
    if ($days === 3) return 'three days';
    return 'a couple of days';
}

