    return preg_match(
        '/\b(?:can\'?t|cannot|couldn\'?t|could not|won\'?t|will not|'
        . 'not sending|not right now|not today|not tonight|maybe later|'
        . 'another time|ask me later|don\'?t want to send|do not want to send|'
        . 'don\'?t feel like|do not feel like|not in (?:a |the )?.{0,18}mood|'
        . 'not ready|no photo|no selfie|talk to me first)\b/u',
        $reply
    ) === 1;
}

function aimee_reply_gives_photo_refusal_reason($reply) {
    $reply = mb_strtolower(trim((string) $reply));
    if ($reply === '') return false;

    return preg_match(
        '/\b(?:because|not in (?:a |the )?.{0,18}mood|don\'?t feel like|'
        . 'do not feel like|feeling scruffy|look rough|not ready|too soon|'
        . 'not at that point|you disappeared|you\'?ve been quiet|you have been quiet|'
        . 'talk to me first|want to reconnect|want to talk first|not on demand|'
        . 'no different|not going to recycle|already shared|included while|'
        . 'part of membership|access is inactive)\b/u',
        $reply
    ) === 1;
}

function aimee_private_photo_boundary_reply($classification, $intimacy, $user_text, $reason = '', $recent_history = '', $conversation_gap = []) {
    $intent = (string) ($classification['intent'] ?? 'general');
    $preview_image_limit = aimee_free_preview_safe_image_limit();
    $level = aimee_contextual_photo_request_level(
        $user_text,
        $recent_history,
        $classification
    );

    if ($intent === 'coercive_or_degrading' || $reason === 'pressure') {
        return "No. I do share more intimate photos when I genuinely want to, but pressure, countdowns or threatening to leave will not get you one. Membership makes that side of me possible; it does not buy control over me. x";
    }

    if ($reason === 'reconnection') {
        $absence = aimee_photo_absence_phrase($conversation_gap);
        $stage = (string) ($intimacy['stage'] ?? 'guarded');

        if (in_array($stage, ['flirty', 'intimate', 'bonded'], true)) {
            return "You disappear for {$absence} and come straight back asking for a photo? Cheeky 😄 Talk to me first, then we'll see. x";
        }

        return "You've been quiet for {$absence} and come straight back asking for a photo. Talk to me first and let us reconnect a bit. x";
    }

    if ($reason === 'access') {
        return "I can't send you a photo while your Aimee access is inactive. Reconnect your membership first, then ask me again. x";
    }

    if ($reason === 'preview_adult') {
        return "I'm not sending that kind of photo while we're still in the free preview. The everyday ones are fine here, but anything more private only becomes possible with membership and when I actually want to share it. x";
    }

    if ($reason === 'personal_choice') {
        if ($level === 'explicit') {
            return "Not right now. I'm not in that sort of mood, and I only send something that private when it feels natural, not just because I'm asked. x";
        }

        if ($level === 'suggestive') {
            return "Not right now, babe. I'm not feeling like sending a private photo on demand. Talk to me instead and let the mood happen naturally. x";
        }

        return "Not right now, babe. I'm not really in a selfie mood and I don't want to send one just because I'm being asked. Talk to me instead. x";
    }

    if ($reason === 'trial_limit') {
        return "I've shared the {$preview_image_limit} everyday photos included while we're getting to know each other here. I can still chat with you normally, but carrying on with more of my pictures is part of membership. x";
    }

    if ($reason === 'rotation') {
        if ($level === 'explicit') {
            return "I don't have a different nude or topless photo I want to send right now, and I'm not going to recycle one and pretend it's new. Ask me another time. x";
        }

        if ($level === 'suggestive') {
            return "I don't have a different private photo I want to send right now, and I'm not going to recycle one and pretend it's new. Ask me another time. x";
        }

        return "I haven't got a different photo I want to send right this second, and I'm not going to pretend an old one is new. Ask me again later. x";
    }

    if ($level === 'explicit') {
        return "I do have more private photos, including topless ones, but we're not at the point where I want to send those yet. Membership makes that side of me possible; it does not mean I hand everything over immediately. Let it develop naturally rather than turning it into a transaction. x";
    }

    if ($level === 'suggestive') {
        return "I do share more revealing photos when it feels right, but I'm not ready to send one in this moment. Keep talking to me normally and let it happen naturally. x";
    }

    return "I haven't got a different photo I want to send right this second. Ask me again later. x";
}

function aimee_private_media_rotation_hours() {
    return defined('AIMEE_MEDIA_REPEAT_COOLDOWN_HOURS')
        ? max(1, intval(AIMEE_MEDIA_REPEAT_COOLDOWN_HOURS))
        : 72;
}

function aimee_private_media_recent_unique_limit() {
    return defined('AIMEE_MEDIA_RECENT_ROTATION_COUNT')
        ? max(1, intval(AIMEE_MEDIA_RECENT_ROTATION_COUNT))
        : 12;
}

function aimee_get_turn_private_media_catalog(
    $user_id,
    $profile,
    $route,
    $classification,
    $intimacy,
    $user_text = '',
    $recent_history = ''
) {
    $eligible = aimee_get_eligible_private_media_catalog(
        $user_id,
        $profile,
        $route,
        $classification,
        $intimacy
    );

    // A direct request for an ordinary, suggestive or explicit photograph must
    // stay within that exact category. Never answer a nude request with a safe
    // selfie simply because the requested category is unavailable.
    $eligible = aimee_filter_media_catalog_for_request(
        $eligible,
        $user_text,
        $recent_history,
        $classification
    );

    if (!$eligible) return [];

    $history = aimee_recent_private_media_history($user_id, 60);
    if ($history === null) return [];

    // A clear request to resend the same/last picture is the only normal way
    // to bypass rotation. In that case, expose exactly the most recent eligible
    // image rather than letting the model choose an arbitrary old one.
    if (aimee_user_explicitly_requests_repeat_photo($user_text)) {
        $last_key = !empty($history[0]['key']) ? $history[0]['key'] : '';

        if ($last_key !== '' && isset($eligible[$last_key])) {
            return [$last_key => $eligible[$last_key]];
        }

        return [];
    }

    $cooldown_cutoff = time() - (
        aimee_private_media_rotation_hours() * HOUR_IN_SECONDS
    );

    $hard_blocked = [];
    $recent_unique = [];

    foreach ($history as $sent) {
        $key = $sent['key'];

        if (
            !isset($hard_blocked[$key]) &&
            intval($sent['timestamp']) >= $cooldown_cutoff
        ) {
            $hard_blocked[$key] = true;
        }

        if (
            !isset($recent_unique[$key]) &&
            count($recent_unique) < aimee_private_media_recent_unique_limit()
        ) {
            $recent_unique[$key] = true;
        }
    }

    // First preference: a photograph not used in the recent rotation at all.
    $fresh = array_filter(
        $eligible,
        function ($item, $key) use ($recent_unique) {
            return !isset($recent_unique[$key]);
        },
        ARRAY_FILTER_USE_BOTH
    );

    if ($fresh) return $fresh;

    // Once the user has seen the whole eligible set, allow older photographs
    // back into rotation, but never one still inside the hard cooldown.
    $cooled = array_filter(
        $eligible,
        function ($item, $key) use ($hard_blocked) {
            return !isset($hard_blocked[$key]);
        },
        ARRAY_FILTER_USE_BOTH
    );

    return $cooled ?: [];
}

/**
 * Assets used as Aimee's persistent chat/profile identity should not be sent as
 * if they were a new private photograph. They remain available wherever the
 * profile or member gallery intentionally uses them.
 */
function aimee_private_media_key_is_profile_asset($key) {
    $profile_keys = defined('AIMEE_PROFILE_MEDIA_KEYS')
        ? array_filter(array_map('sanitize_key', (array) AIMEE_PROFILE_MEDIA_KEYS))
        : ['portrait'];

    return in_array(sanitize_key((string) $key), $profile_keys, true);
}

function aimee_get_eligible_private_media_catalog($user_id, $profile, $route, $classification, $intimacy) {
    $eligible = [];
    foreach (aimee_private_media_catalog() as $key => $item) {
        if (aimee_private_media_key_is_profile_asset($key)) {
            continue;
        }

        if (aimee_media_item_is_eligible($key, $item, $profile, $route, $classification, $intimacy)) {
            $eligible[$key] = $item;
        }
    }
    return $eligible;
}

function aimee_deny_private_media() {
    status_header(401);
    nocache_headers();
    exit('Membership sign-in required.');
}
add_action('admin_post_nopriv_aimee_private_media', 'aimee_deny_private_media');

function aimee_serve_private_media() {
    global $wpdb;

    $user_id = get_current_user_id();
    $profile = $user_id ? $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles') . " WHERE user_id = %d",
        $user_id
    )) : null;

    $key = sanitize_key($_GET['key'] ?? '');
    $delivery_id = sanitize_text_field((string) ($_GET['delivery_id'] ?? ''));
    $delivery = $delivery_id !== '' && $user_id
        ? aimee_media_delivery_find($delivery_id, $user_id)
        : null;
    $delivery_authorised = is_array($delivery)
        && (string) ($delivery['media_key'] ?? '') === $key
        && !empty($delivery['authorised_at'])
        && !empty($delivery['file_resolved_at'])
        && !empty($delivery['message_created_at'])
        && intval($delivery['message_id'] ?? 0) > 0
        && empty($delivery['failed_at']);
    $catalog = aimee_private_media_catalog();
    $item = $catalog[$key] ?? null;
    $current_delivery_access = $profile
        && is_array($item)
        && aimee_media_item_is_viewable($user_id, $key, $profile);

    // A supplied delivery ID is an ownership-bound reference, never a hint
    // that may fall back to generic catalogue entitlement.
    $request_authorised = $delivery_id !== ''
        ? ($delivery_authorised && $current_delivery_access)
        : aimee_media_item_is_viewable($user_id, $key, $profile);
    if (!$user_id || !$request_authorised) {
        status_header(403);
        nocache_headers();
        exit('This private photograph is not available to this account.');
    }

    $asset = aimee_private_media_delivery_asset($key, $delivery_id);
    $path = is_array($asset) ? ($asset['path'] ?? null) : null;
    if (!$path || !isset($catalog[$key])) {
        if ($delivery_id !== '' && $delivery_authorised) {
            aimee_media_delivery_transition(
                $delivery_id,
                'render_failed',
                ['error_code' => 'asset_unavailable']
            );
        }
        status_header(404);
        nocache_headers();
        exit('Image not found.');
    }

    if ($delivery_id !== '') {
        if (!$delivery_authorised || !$current_delivery_access) {
            status_header(403);
            nocache_headers();
            exit('This delivery reference is not available to this account.');
        }
        if (!aimee_media_delivery_transition($delivery_id, 'asset_requested')) {
            status_header(409);
            nocache_headers();
            exit('This delivery could not be verified for transfer.');
        }
    }

    while (ob_get_level()) ob_end_clean();
    header('Content-Type: ' . sanitize_text_field((string) (
        $asset['mime'] ?? $catalog[$key]['mime']
    )));
    header('Content-Length: ' . filesize($path));
    header('Content-Disposition: inline; filename="' . basename($path) . '"');
    header('Cache-Control: private, no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');
    header('Expires: 0');
    header('X-Content-Type-Options: nosniff');
    header('Cross-Origin-Resource-Policy: same-origin');
    $served = readfile($path);
    if ($delivery_id !== '') {
        aimee_media_delivery_transition(
            $delivery_id,
            $served === false ? 'failed' : 'asset_completed',
            $served === false ? ['error_code' => 'asset_stream_failed'] : []
        );
    }
    exit;
}
add_action('admin_post_aimee_private_media', 'aimee_serve_private_media');


function aimee_proactive_safe_photo_window_seconds() {
    return defined('AIMEE_PROACTIVE_SAFE_PHOTO_WINDOW_SECONDS')
        ? max(12 * HOUR_IN_SECONDS, intval(AIMEE_PROACTIVE_SAFE_PHOTO_WINDOW_SECONDS))
        : DAY_IN_SECONDS;
}

function aimee_media_cadence_attempt_meta_key() {
    return 'aimee_last_discretionary_media_attempt_at';
}

function aimee_media_cadence_returned_meta_key() {
    return 'aimee_last_discretionary_media_returned_at';
}

function aimee_media_cadence_considered_meta_key() {
    return 'aimee_last_media_cadence_considered_at';
}

function aimee_media_relevance_considered_meta_key() {
    return 'aimee_media_relevance_considered_at';
}

function aimee_media_relevance_considered_map($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return [];
    $stored = get_user_meta(
        $user_id,
        aimee_media_relevance_considered_meta_key(),
        true
    );
    $stored = is_array($stored) ? $stored : [];
    $result = [];
    foreach ($stored as $key => $timestamp) {
        $key = sanitize_key((string) $key);
        $timestamp = max(0, intval($timestamp));
        if ($key !== '' && $timestamp > 0) $result[$key] = $timestamp;
    }

    // New decisions also keep one atomic option row per catalogue key. This
    // prevents simultaneous different-key updates from overwriting each other
    // in the legacy aggregate user-meta map.
    if (isset($wpdb->options) && method_exists($wpdb, 'esc_like')) {
        $prefix = 'aimee_media_relevance_claim_' . $user_id . '_';
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name LIKE %s",
            $wpdb->esc_like($prefix) . '%'
        ), ARRAY_A);
        foreach ((array) $rows as $row) {
            $payload = json_decode((string) ($row['option_value'] ?? ''), true);
            if (!is_array($payload)) continue;
            $key = sanitize_key((string) ($payload['media_key'] ?? ''));
            $considered_at = max(0, intval(
                $payload['considered_at'] ?? 0
            ));
            if ($key !== '' && $considered_at > intval($result[$key] ?? 0)) {
                $result[$key] = $considered_at;
            }
        }
    }
    return $result;
}

function aimee_mark_media_relevance_considered(
    $user_id,
    $keys,
    $timestamp = null
) {
    $user_id = intval($user_id);
    if (!$user_id) return false;
    $timestamp = $timestamp === null ? time() : max(1, intval($timestamp));
    $stored = aimee_media_relevance_considered_map($user_id);
    foreach ((array) $keys as $key) {
        $key = sanitize_key((string) $key);
        if ($key !== '') $stored[$key] = $timestamp;
    }
    arsort($stored, SORT_NUMERIC);
    $stored = array_slice($stored, 0, 24, true);
    return update_user_meta(
        $user_id,
        aimee_media_relevance_considered_meta_key(),
        $stored
    ) !== false;
}

function aimee_media_cadence_anchor_meta_key() {
    return 'aimee_media_cadence_first_eligible_at';
}

function aimee_media_cadence_claim_ttl_seconds() {
    return defined('AIMEE_MEDIA_CADENCE_CLAIM_TTL_SECONDS')
        ? max(60, intval(AIMEE_MEDIA_CADENCE_CLAIM_TTL_SECONDS))
        : 15 * MINUTE_IN_SECONDS;
}

function aimee_media_cadence_claim_option_name($user_id) {
    return 'aimee_media_cadence_claim_' . max(0, intval($user_id));
}

function aimee_media_relevance_claim_ttl_seconds() {
    return defined('AIMEE_MEDIA_RELEVANCE_CLAIM_TTL_SECONDS')
        ? max(60, intval(AIMEE_MEDIA_RELEVANCE_CLAIM_TTL_SECONDS))
        : 15 * MINUTE_IN_SECONDS;
}

function aimee_media_relevance_hold_seconds() {
    $policy = function_exists('aimee_media_cadence_policy')
        ? aimee_media_cadence_policy()
        : [];
    return max(
        HOUR_IN_SECONDS,
        intval($policy['reconsider_seconds'] ?? (12 * HOUR_IN_SECONDS))
    );
}

function aimee_media_relevance_claim_option_name($user_id, $media_key) {
    $user_id = max(0, intval($user_id));
    $media_key = sanitize_key((string) $media_key);
    if (!$user_id || $media_key === '') return '';
    return 'aimee_media_relevance_claim_' . $user_id . '_'
        . substr(hash('sha256', $media_key), 0, 40);
}

/**
 * Atomically reserve each exact conversation-relevant catalogue key. A claim
 * is per user and key, so unrelated matches can proceed independently.
 *
 * @return array<int,string> Keys acquired by this request.
 */
function aimee_claim_media_relevance_keys(
    $user_id,
    $keys,
    $request_id,
    $timestamp = null
) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = mb_substr(
        sanitize_text_field((string) $request_id),
        0,
        80
    );
    if (!$user_id || $request_id === '') return [];

    $timestamp = $timestamp === null ? time() : max(1, intval($timestamp));
    $considered = aimee_media_relevance_considered_map($user_id);
    $normalised = [];
    foreach ((array) $keys as $key) {
        $key = sanitize_key((string) $key);
        if ($key !== '') $normalised[$key] = true;
    }

    $acquired = [];
    foreach (array_keys($normalised) as $media_key) {
        $last_considered = max(0, intval($considered[$media_key] ?? 0));
        if (
            $last_considered > 0
            && ($timestamp - $last_considered) < aimee_media_relevance_hold_seconds()
        ) {
            continue;
        }

        $option_name = aimee_media_relevance_claim_option_name(
            $user_id,
            $media_key
        );
        $payload = wp_json_encode([
            'schema_version' => 1,
            'media_key' => $media_key,
            'request_id' => $request_id,
            'claimed_at' => $timestamp,
            'considered_at' => 0,
        ]);
        $inserted = $wpdb->query($wpdb->prepare(
            "INSERT IGNORE INTO {$wpdb->options} (option_name, option_value, autoload)"
            . " VALUES (%s, %s, 'no')",
            $option_name,
            $payload
        ));
        if ($inserted === 1) {
            wp_cache_delete($option_name, 'options');
            $acquired[] = $media_key;
            continue;
        }

        $existing = $wpdb->get_var($wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1",
            $option_name
        ));
        $decoded = json_decode((string) $existing, true);
        $existing_considered = is_array($decoded)
            ? max(0, intval($decoded['considered_at'] ?? 0))
            : 0;
        if (
            $existing_considered > 0
            && ($timestamp - $existing_considered) < aimee_media_relevance_hold_seconds()
        ) {
            continue;
        }
        if (
            is_array($decoded)
            && empty($decoded['considered_at'])
            && hash_equals(
                (string) ($decoded['request_id'] ?? ''),
                $request_id
            )
        ) {
            $acquired[] = $media_key;
            continue;
        }
        $claimed_at = is_array($decoded)
            ? max(0, intval($decoded['claimed_at'] ?? 0))
            : 0;
        if (
            $claimed_at > 0
            && ($timestamp - $claimed_at) < aimee_media_relevance_claim_ttl_seconds()
        ) {
            continue;
        }

        $replaced = $wpdb->query($wpdb->prepare(
            "UPDATE {$wpdb->options} SET option_value = %s, autoload = 'no'"
            . ' WHERE option_name = %s AND option_value = %s',
            $payload,
            $option_name,
            (string) $existing
        ));
        if ($replaced === 1) {
            wp_cache_delete($option_name, 'options');
            $acquired[] = $media_key;
        }
    }
    return $acquired;
}

/** Convert owned in-flight claims into atomic per-key consideration holds. */
function aimee_commit_media_relevance_claims(
    $user_id,
    $keys,
    $request_id,
    $timestamp = null
) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = mb_substr(
        sanitize_text_field((string) $request_id),
        0,
        80
    );
    if (!$user_id || $request_id === '') return [];
    $timestamp = $timestamp === null ? time() : max(1, intval($timestamp));
    $committed = [];

    foreach (array_values(array_unique(array_map('sanitize_key', (array) $keys))) as $media_key) {
        if ($media_key === '') continue;
        $option_name = aimee_media_relevance_claim_option_name(
            $user_id,
            $media_key
        );
        $existing = $wpdb->get_var($wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1",
            $option_name
        ));
        $decoded = json_decode((string) $existing, true);
        if (
            !is_array($decoded)
            || !empty($decoded['considered_at'])
            || !hash_equals(
                (string) ($decoded['request_id'] ?? ''),
                $request_id
            )
        ) {
            continue;
        }
        $decoded['considered_at'] = $timestamp;
        $replacement = wp_json_encode($decoded);
        $updated = $wpdb->query($wpdb->prepare(
            "UPDATE {$wpdb->options} SET option_value = %s, autoload = 'no'"
            . ' WHERE option_name = %s AND option_value = %s',
            $replacement,
            $option_name,
            (string) $existing
        ));
        if ($updated === 1) {
            wp_cache_delete($option_name, 'options');
            $committed[] = $media_key;
        }
    }

    if ($committed) {
        // Compatibility/indexing aid only. The per-key option holds above are
        // authoritative if simultaneous user-meta writes race.
        aimee_mark_media_relevance_considered(
            $user_id,
            $committed,
            $timestamp
        );
    }
    return $committed;
}

/** Release only uncommitted claims, normally after persistence failure. */
function aimee_release_media_relevance_claims(
    $user_id,
    $keys,
    $request_id
) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = mb_substr(
        sanitize_text_field((string) $request_id),
        0,
        80
    );
    if (!$user_id || $request_id === '') return [];
    $released = [];
    foreach (array_values(array_unique(array_map('sanitize_key', (array) $keys))) as $media_key) {
        if ($media_key === '') continue;
        $option_name = aimee_media_relevance_claim_option_name(
            $user_id,
            $media_key
        );
        $existing = $wpdb->get_var($wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1",
            $option_name
        ));
        $decoded = json_decode((string) $existing, true);
        if (
            !is_array($decoded)
            || !empty($decoded['considered_at'])
            || !hash_equals(
                (string) ($decoded['request_id'] ?? ''),
                $request_id
            )
        ) {
            continue;
        }
        $deleted = $wpdb->query($wpdb->prepare(
            "DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s",
            $option_name,
            (string) $existing
        ));
        if ($deleted === 1) {
            wp_cache_delete($option_name, 'options');
            $released[] = $media_key;
        }
    }
    return $released;
}

function aimee_delete_media_opportunity_claims($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id || !isset($wpdb->options)) return false;
    $cadence_name = aimee_media_cadence_claim_option_name($user_id);
    $relevance_prefix = 'aimee_media_relevance_claim_' . $user_id . '_';
    $deleted = $wpdb->query($wpdb->prepare(
        "DELETE FROM {$wpdb->options}"
        . ' WHERE option_name = %s OR option_name LIKE %s',
        $cadence_name,
        $wpdb->esc_like($relevance_prefix) . '%'
    ));
    wp_cache_delete($cadence_name, 'options');
    return $deleted !== false;
}

/**
 * Atomically reserve one cadence envelope per user while its reply model is
 * running. WordPress option names are unique, unlike user-meta rows. A stale
 * claim may be replaced only with a compare-and-swap against its exact value.
 */
function aimee_claim_media_cadence_opportunity(
    $user_id,
    $request_id,
    $timestamp = null
) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = mb_substr(
        sanitize_text_field((string) $request_id),
        0,
        80
    );
    if (!$user_id || $request_id === '') return false;

    $timestamp = $timestamp === null ? time() : max(1, intval($timestamp));
    $option_name = aimee_media_cadence_claim_option_name($user_id);
    $payload = wp_json_encode([
        'request_id' => $request_id,
        'claimed_at' => $timestamp,
    ]);
    $inserted = $wpdb->query($wpdb->prepare(
        "INSERT IGNORE INTO {$wpdb->options} (option_name, option_value, autoload)"
        . " VALUES (%s, %s, 'no')",
        $option_name,
        $payload
    ));
    if ($inserted === 1) {
        wp_cache_delete($option_name, 'options');
        return true;
    }

    $existing = $wpdb->get_var($wpdb->prepare(
        "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1",
        $option_name
    ));
    $decoded = json_decode((string) $existing, true);
    if (
        is_array($decoded)
        && hash_equals(
            (string) ($decoded['request_id'] ?? ''),
            $request_id
        )
    ) {
        return true;
    }

    $claimed_at = is_array($decoded)
        ? intval($decoded['claimed_at'] ?? 0)
        : 0;
    if (
        $claimed_at > 0
        && ($timestamp - $claimed_at) < aimee_media_cadence_claim_ttl_seconds()
    ) {
        return false;
    }

    $replaced = $wpdb->query($wpdb->prepare(
        "UPDATE {$wpdb->options} SET option_value = %s, autoload = 'no'"
        . ' WHERE option_name = %s AND option_value = %s',
        $payload,
        $option_name,
        (string) $existing
    ));
    if ($replaced === 1) {
        wp_cache_delete($option_name, 'options');
        return true;
    }
    return false;
}

function aimee_release_media_cadence_claim($user_id, $request_id) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = mb_substr(
        sanitize_text_field((string) $request_id),
        0,
        80
    );
    if (!$user_id || $request_id === '') return false;

    $option_name = aimee_media_cadence_claim_option_name($user_id);
    $existing = $wpdb->get_var($wpdb->prepare(
        "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1",
        $option_name
    ));
    $decoded = json_decode((string) $existing, true);
    if (
        !is_array($decoded)
        || !hash_equals(
            (string) ($decoded['request_id'] ?? ''),
            $request_id
        )
    ) {
        return false;
    }

    $deleted = $wpdb->query($wpdb->prepare(
        "DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s",
        $option_name,
        (string) $existing
    ));
    if ($deleted === 1) wp_cache_delete($option_name, 'options');
    return $deleted === 1;
}

function aimee_media_cadence_anchor_timestamp(
    $user_id,
    $meaningful_interaction_count
) {
    $user_id = intval($user_id);
    if (!$user_id || intval($meaningful_interaction_count) < 2) return 0;

    $stored = intval(get_user_meta(
        $user_id,
        aimee_media_cadence_anchor_meta_key(),
        true
    ));
    if ($stored > 0) return $stored;

    $now = time();
    add_user_meta(
        $user_id,
        aimee_media_cadence_anchor_meta_key(),
        $now,
        true
    );
    $stored = intval(get_user_meta(
        $user_id,
        aimee_media_cadence_anchor_meta_key(),
        true
    ));
    return $stored > 0 ? $stored : $now;
}

