function aimee_media_decision_is_discretionary_opportunity(
    $decision_id,
    $user_id = 0
) {
    global $wpdb;

    $decision_id = sanitize_text_field((string) $decision_id);
    if ($decision_id === '') return false;
    $where = 'decision_id = %s';
    $args = [$decision_id];
    if ($user_id) {
        $where .= ' AND user_id = %d';
        $args[] = intval($user_id);
    }
    $row = $wpdb->get_row($wpdb->prepare(
        'SELECT source, reason_code FROM ' . aimee_media_decisions_table()
        . " WHERE {$where} LIMIT 1",
        $args
    ), ARRAY_A);
    return is_array($row)
        && (string) ($row['source'] ?? '') === 'proactive'
        && in_array(
            sanitize_key((string) ($row['reason_code'] ?? '')),
            [
                'eligible_conversation_relevance',
                'eligible_cadence_due',
                'eligible_indirect_opportunity',
                'eligible_respectful_restraint',
                'eligible_intimate_route_consideration',
            ],
            true
        );
}

function aimee_mark_media_cadence_returned_for_delivery(
    $decision_id,
    $user_id,
    $timestamp = null
) {
    $user_id = intval($user_id);
    if (
        !$user_id
        || !aimee_media_decision_is_discretionary_opportunity(
            $decision_id,
            $user_id
        )
    ) {
        return false;
    }
    $timestamp = $timestamp === null ? time() : max(1, intval($timestamp));
    update_user_meta(
        $user_id,
        aimee_media_cadence_considered_meta_key(),
        $timestamp
    );
    return update_user_meta(
        $user_id,
        aimee_media_cadence_returned_meta_key(),
        $timestamp
    ) !== false;
}

