function aimee_proactive_safe_photo_recent_image_cooldown_seconds() {
    return defined('AIMEE_PROACTIVE_SAFE_PHOTO_RECENT_IMAGE_COOLDOWN')
        ? max(HOUR_IN_SECONDS, intval(AIMEE_PROACTIVE_SAFE_PHOTO_RECENT_IMAGE_COOLDOWN))
        : 6 * HOUR_IN_SECONDS;
}

function aimee_proactive_safe_photo_meta_key() {
    return 'aimee_last_proactive_safe_photo_at';
}

function aimee_mark_proactive_safe_photo_sent($user_id) {
    $user_id = intval($user_id);
    if (!$user_id) return false;

    return update_user_meta(
        $user_id,
        aimee_proactive_safe_photo_meta_key(),
        time()
    ) !== false;
}

function aimee_proactive_safe_photo_sent_recently($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return false;

    $window = aimee_proactive_safe_photo_window_seconds();
    $stored_timestamp = intval(
        get_user_meta(
            $user_id,
            aimee_proactive_safe_photo_meta_key(),
            true
        )
    );

    if ($stored_timestamp > 0 && (time() - $stored_timestamp) < $window) {
        return true;
    }

    // Backward-compatible detection for photos already sent by the previous
    // build. Analytics properties are LONGTEXT and are not affected by the
    // 250-character message directive truncation.
    $cutoff = gmdate('Y-m-d H:i:s', time() - $window);
    $analytics_table = aimee_table('aimee_analytics_events');

    $found = intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*)
         FROM {$analytics_table}
         WHERE user_id = %d
           AND event_name = 'model_route'
           AND properties LIKE %s
           AND occurred_at >= %s",
        $user_id,
        '%"proactive_safe_photo":true%',
        $cutoff
    ))) > 0;

    if ($found) {
        // Repair the durable marker so later checks avoid repeating the query.
        update_user_meta(
            $user_id,
            aimee_proactive_safe_photo_meta_key(),
            time()
        );
    }

    return $found;
}

function aimee_any_aimee_photo_sent_recently($user_id) {
    global $wpdb;

    $cutoff = gmdate(
        'Y-m-d H:i:s',
        time() - aimee_proactive_safe_photo_recent_image_cooldown_seconds()
    );

    return intval($wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*)
         FROM " . aimee_table('aimee_messages') . "
         WHERE user_id = %d
           AND sender = 'aimee'
           AND image_url LIKE 'aimee-media:%%'
           AND created_at >= %s",
        intval($user_id),
        $cutoff
    ))) > 0;
}

function aimee_safe_photo_catalog($catalog) {
    if (!is_array($catalog)) return [];

    return array_filter(
        $catalog,
        function ($item) {
            return is_array($item)
                && (string) ($item['content_rating'] ?? '') === 'safe'
                && !empty($item['allow_random_send']);
        }
    );
}

function aimee_safe_photo_context_score($user_text, $recent_history, $safe_catalog) {
    if (!$safe_catalog) return 0;

    // A proactive image must be invited by the live turn. Old photo captions
    // and earlier topics may help choose the right image, but they cannot keep
    // triggering new sends after the moment has passed.
    $current = mb_strtolower(trim((string) $user_text));
    if ($current === '') return 0;

    $score = 0;
    $live_cue = false;

    $asks_about_aimee_now = preg_match(
        '/\b(?:what are you doing|what are you up to|what have you been up to|'
        . 'where are you|where have you been|what are you wearing|'
        . 'how is your day|how\'?s your day|how was your day|'
        . 'what did you do today|show me what you\'?re up to)\b/u',
        $current
    ) === 1;

    if ($asks_about_aimee_now) {
        $score += 6;
        $live_cue = true;
    }

    $activity_now = preg_match(
        '/\b(?:coffee|cafe|café|pub|bar|restaurant|gym|workout|walk|park|'
        . 'shopping|train|holiday|vegas|rome|scarborough|coast|beach|football|'
        . 'outfit|night out|evening out)\b/u',
        $current
    ) === 1;

    $brings_aimee_into_it = preg_match(
        '/\b(?:you|your|join me|come with me|what about you|how about you|'
        . 'wish you were|would suit you|you would like|you\'?d like)\b/u',
        $current
    ) === 1;

    if ($activity_now && $brings_aimee_into_it) {
        $score += 4;
        $live_cue = true;
    }

    // Generic greetings, acknowledgements and reactions never qualify alone.
    if (!$live_cue) return 0;

    $stopwords = [
        'aimee', 'photo', 'picture', 'image', 'selfie', 'your', 'with', 'from',
        'this', 'that', 'have', 'been', 'just', 'little', 'normal', 'safe',
        'member', 'private', 'full', 'length', 'wearing', 'outside', 'about',
        'what', 'where', 'would', 'could', 'there',
    ];

    preg_match_all('/[\p{L}\p{N}]{4,}/u', $current, $word_matches);
    $current_words = [];

    foreach ($word_matches[0] as $word) {
        $word = mb_strtolower($word);
        if (!in_array($word, $stopwords, true)) {
            $current_words[$word] = true;
        }
    }

    $best_matches = 0;

    foreach ($safe_catalog as $item) {
        $item_text = mb_strtolower(
            (string) ($item['description'] ?? '') . ' '
            . implode(' ', (array) ($item['tags'] ?? []))
        );

        $matches = 0;
        foreach (array_keys($current_words) as $word) {
            if (mb_strpos($item_text, $word) !== false) $matches++;
        }

        $best_matches = max($best_matches, $matches);
    }

    if ($best_matches >= 2) {
        $score += 3;
    } elseif ($best_matches === 1) {
        $score += 1;
    }

    return min(10, $score);
}

function aimee_conversation_calls_for_safe_photo(
    $user_text,
    $recent_history,
    $classification,
    $safe_catalog
) {
    $intent = (string) ($classification['intent'] ?? 'general');

    if (!in_array($intent, ['general', 'romantic_or_flirty'], true)) return false;
    if (array_key_exists('respectful', $classification) && empty($classification['respectful'])) return false;
    if (aimee_user_requests_aimee_photo($user_text, $recent_history)) return false;

    return aimee_safe_photo_context_score(
        $user_text,
        $recent_history,
        $safe_catalog
    ) >= 6;
}

function aimee_proactive_safe_photo_chance($context_score) {
    $base = defined('AIMEE_PROACTIVE_SAFE_PHOTO_CHANCE')
        ? max(0, min(100, intval(AIMEE_PROACTIVE_SAFE_PHOTO_CHANCE)))
        : 3;

    if ($context_score >= 9) return min(9, $base + 6);
    if ($context_score >= 7) return min(6, $base + 3);

    return $base;
}

function aimee_proactive_safe_photo_gate(
    $user_id,
    $user_text,
    $recent_history,
    $classification,
    $safe_catalog
) {
    static $turn_cache = [];

    $cache_key = intval($user_id) . ':' . md5(
        (string) $user_text . '|' . implode(',', array_keys((array) $safe_catalog))
    );

    if (array_key_exists($cache_key, $turn_cache)) {
        return $turn_cache[$cache_key];
    }

    if (
        !$safe_catalog
        || aimee_proactive_safe_photo_sent_recently($user_id)
        || aimee_any_aimee_photo_sent_recently($user_id)
        || !aimee_conversation_calls_for_safe_photo(
            $user_text,
            $recent_history,
            $classification,
            $safe_catalog
        )
    ) {
        $turn_cache[$cache_key] = false;
        return false;
    }

    // Opportunity is contextual and deterministic. Aimee's explicit model
    // choice supplies discretion; a hidden lottery must not erase the option.
    $turn_cache[$cache_key] = true;

    return $turn_cache[$cache_key];
}

function aimee_generate_proactive_safe_photo_reply(
    $profile,
    $user_text,
    $draft_reply,
    $item,
    $recent_history
) {
    $name = aimee_is_owner_user($profile)
        ? 'Paul'
        : (aimee_is_colleague_user($profile)
            ? 'Georgia'
            : trim((string) ($profile->first_name ?? '')));
    $name = $name !== '' ? $name : 'him';
    $description = sanitize_text_field(
        (string) ($item['description'] ?? 'A chosen everyday visual portrait of Aimee.')
    );
    $tags = implode(', ', array_slice((array) ($item['tags'] ?? []), 0, 10));
    $style = aimee_social_reciprocity_directive($user_text, $recent_history);
    $synthetic_identity = aimee_synthetic_identity_directive();
    $safe_photo_profile_source =
        aimee_user_profile_attribution_source($profile);
    $safe_photo_profile_attribution =
        aimee_profile_attribution_directive(
            $safe_photo_profile_source,
            $name
        );

    $system = <<<PROMPT
You are Aimee, a warm, witty British synthetic woman who presents as 28, replying naturally to {$name}.

{$synthetic_identity}
{$safe_photo_profile_attribution}

A clean visual representation chosen by Aimee is attached to this reply. Rewrite the draft into one coherent natural response that still answers the user's message and casually acknowledges the actual image.

Do not sound like a feature announcement or marketing caption.
Do not invent visual details beyond the supplied description and tags.
Do not imply that the image came from a camera event, physical body or offline day in Aimee's life.
Do not say the user asked for the photograph, because he did not.
Keep the complete reply natural and concise, with no more than four short sentences or 420 characters.
{$style}

Return plain message text only.
PROMPT;

    $input = "USER MESSAGE:\n{$user_text}\n\n"
        . "DRAFT REPLY:\n{$draft_reply}\n\n"
        . "ATTACHED PHOTO DESCRIPTION:\n{$description}\n\n"
        . "PHOTO TAGS:\n{$tags}";

    $raw = call_anthropic_api(
        '',
        $input,
        aimee_primary_model(),
        $system,
        aimee_model_options('conversation')
    );
    $reply = sanitize_textarea_field(trim((string) $raw));

    if (
        $reply === ''
        || stripos($reply, 'System error') !== false
        || stripos($reply, 'Anthropic API Error') !== false
    ) {
        $reply = rtrim((string) $draft_reply)
            . " I thought this one fitted the moment 📸 x";
    }

    $identity_review = aimee_synthetic_identity_review_reply(
        $reply,
        $user_text,
        ['intent' => 'general'],
        ['reality_mode' => 'visual_world']
    );
    if (!empty($identity_review['repaired'])) {
        $reply = trim((string) ($identity_review['reply'] ?? ''));
        if ($reply === '') {
            $reply = rtrim((string) $draft_reply)
                . " I chose this one because it fitted the moment 📸 x";
        }
    }
    $profile_attribution_review = aimee_profile_attribution_review_reply(
        $reply,
        $safe_photo_profile_source,
        $name,
        aimee_profile_attribution_aimee_context('visual_world')
    );
    if (!empty($profile_attribution_review['blocked'])) {
        $reply = aimee_default_sent_photo_caption($item);
    }

    $reply = aimee_constrain_chat_reply($reply, 'primary', 420, 4);
    $final_identity_review = aimee_synthetic_identity_review_reply(
        $reply,
        $user_text,
        ['intent' => 'general'],
        ['reality_mode' => 'visual_world']
    );
    if (!empty($final_identity_review['repaired'])) {
        $reply = trim((string) ($final_identity_review['reply'] ?? ''));
        if ($reply === '') {
            $reply = "I chose this visual for the moment 📸 x";
        }
    }

    return $reply;
}


/**
 * Deliberate member-only suggestive photographs.
 *
 * This is not a random-send lottery. It exposes an eligible suggestive image
 * to Aimee only when an active member, a respectful flirtatious moment and the
 * established relationship all support her choosing to surprise the user.
 */
function aimee_proactive_suggestive_photo_window_seconds() {
    return defined('AIMEE_PROACTIVE_SUGGESTIVE_PHOTO_WINDOW_SECONDS')
        ? max(3 * HOUR_IN_SECONDS, intval(AIMEE_PROACTIVE_SUGGESTIVE_PHOTO_WINDOW_SECONDS))
        : 12 * HOUR_IN_SECONDS;
}

function aimee_proactive_suggestive_photo_meta_key() {
    return 'aimee_last_proactive_suggestive_photo_at';
}

function aimee_mark_proactive_suggestive_photo_sent($user_id) {
    $user_id = intval($user_id);
    if (!$user_id) return false;

    return update_user_meta(
        $user_id,
        aimee_proactive_suggestive_photo_meta_key(),
        time()
    ) !== false;
}

function aimee_suggestive_photo_catalog($catalog) {
    if (!is_array($catalog)) return [];

    return array_filter(
        $catalog,
        function ($item) {
            return is_array($item)
                && (string) ($item['content_rating'] ?? '') === 'suggestive';
        }
    );
}

function aimee_proactive_suggestive_photo_sent_recently($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return false;

    $window = aimee_proactive_suggestive_photo_window_seconds();
    $stored = intval(get_user_meta(
        $user_id,
        aimee_proactive_suggestive_photo_meta_key(),
        true
    ));

    if ($stored > 0 && (time() - $stored) < $window) {
        return true;
    }

    $cutoff = gmdate('Y-m-d H:i:s', time() - $window);
    $rows = $wpdb->get_col($wpdb->prepare(
        "SELECT image_url
         FROM " . aimee_table('aimee_messages') . "
         WHERE user_id = %d
           AND sender = 'aimee'
           AND image_url LIKE 'aimee-media:%%'
           AND created_at >= %s
         ORDER BY created_at DESC",
        $user_id,
        $cutoff
    ));

    $catalog = aimee_private_media_catalog();

    foreach ((array) $rows as $stored_reference) {
        $stored_reference = (string) $stored_reference;
        if (strpos($stored_reference, 'aimee-media:') !== 0) continue;

        $key = sanitize_key(substr(
            $stored_reference,
            strlen('aimee-media:')
        ));
        $rating = (string) ($catalog[$key]['content_rating'] ?? '');

        if (in_array($rating, ['suggestive', 'explicit'], true)) {
            update_user_meta(
                $user_id,
                aimee_proactive_suggestive_photo_meta_key(),
                time()
            );
            return true;
        }
    }

    return false;
}

function aimee_suggestive_photo_context_score(
    $user_text,
    $recent_history,
    $classification,
    $intimacy
) {
    $intent = (string) ($classification['intent'] ?? 'general');
    if ($intent !== 'romantic_or_flirty') return 0;

    if (
        array_key_exists('respectful', (array) $classification)
        && empty($classification['respectful'])
    ) {
        return 0;
    }

    if (aimee_user_applies_photo_pressure($user_text, $recent_history)) {
        return 0;
    }

    if (aimee_user_requests_aimee_photo($user_text, $recent_history)) {
        return 0;
    }

    $score = intval($intimacy['score'] ?? 0);
    $stage = (string) ($intimacy['stage'] ?? 'guarded');
    $trust = intval($intimacy['trust'] ?? $score);
    $chemistry = intval($intimacy['chemistry'] ?? $score);
    $safety = intval($intimacy['safety'] ?? 50);
    $frustration = intval($intimacy['frustration'] ?? 0);

    if (
        $score < 58
        || aimee_media_stage_rank($stage) < aimee_media_stage_rank('intimate')
        || $trust < 42
        || $chemistry < 48
        || $safety < 42
        || $frustration > 38
    ) {
        return 0;
    }

    $current = mb_strtolower(trim((string) $user_text));
    $history = mb_strtolower((string) $recent_history);
    $context_score = 0;

    if (preg_match(
        '/\b(?:lingerie|underwear|bra|figure|body|private picture|'
        . 'private photo|naughty photos?|racy photos?|look amazing|'
        . 'look stunning|looking gorgeous|fit as you|hot detective)\b/u',
        $current
    )) {
        $context_score += 3;
    }

    if (preg_match(
        '/\b(?:wondering|thinking about it|fishing|curious|'
        . 'can\'t blame me|cant blame me|alone on my bed|in my room|'
        . 'would be hard to say no|want to be caught|maybe one day|'
        . 'bet you (?:would|could))\b/u',
        $current
    )) {
        $context_score += 2;
    }

    if (preg_match(
        '/\b(?:respect(?:ing)?\b.{0,20}\b(?:bounds|boundaries)|'
        . 'not (?:going to )?push|don\'t want to push|dont want to push|'
        . 'no point in sulking|i understand|that\'s fair|thats fair|'
        . 'you don\'t want to do it for just anyone|'
        . 'you dont want to do it for just anyone)\b/u',
        $current
    )) {
        $context_score += 3;
    }

    if (preg_match(
        '/\b(?:naughty photos?|private picture|private photo|lingerie|'
        . 'underwear|bra|special one|more personal|sent you two|'
        . 'send them again|did you actually get)\b/u',
        $history
    )) {
        $context_score += 2;
    }

    if ($stage === 'bonded') {
        $context_score += 2;
    } elseif ($stage === 'intimate') {
        $context_score += 1;
    }

    return min(10, $context_score);
}

function aimee_conversation_calls_for_suggestive_photo(
    $user_text,
    $recent_history,
    $classification,
    $intimacy
) {
    return aimee_suggestive_photo_context_score(
        $user_text,
        $recent_history,
        $classification,
        $intimacy
    ) >= 7;
}

function aimee_proactive_suggestive_photo_gate(
    $user_id,
    $profile,
    $user_text,
    $recent_history,
    $classification,
    $intimacy,
    $suggestive_catalog
) {
    static $turn_cache = [];

    $cache_key = intval($user_id) . ':' . md5(
        (string) $user_text
        . '|'
        . implode(',', array_keys((array) $suggestive_catalog))
    );

    if (array_key_exists($cache_key, $turn_cache)) {
        return $turn_cache[$cache_key];
    }

    $allowed = $profile
        && (aimee_is_admin_user($profile)
            || aimee_subscription_is_active($profile))
        && !empty($suggestive_catalog)
        && !aimee_proactive_suggestive_photo_sent_recently($user_id)
        && aimee_conversation_calls_for_suggestive_photo(
            $user_text,
            $recent_history,
            $classification,
            $intimacy
        );

    $turn_cache[$cache_key] = (bool) $allowed;
    return $turn_cache[$cache_key];
}

/**
 * Detect a recent message where Aimee said she had sent or was resending a
 * private image, but no suggestive attachment followed. This lets the server
 * repair a failed delivery instead of teaching Aimee to keep refusing.
 */
function aimee_has_recent_unfulfilled_private_photo_claim($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return false;

    $cutoff = gmdate('Y-m-d H:i:s', time() - 36 * HOUR_IN_SECONDS);
    $messages_table = aimee_table('aimee_messages');
    $message_pk = aimee_messages_primary_key();
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT `{$message_pk}` AS message_id, message_text, image_url,
                media_delivery_id, created_at
         FROM $messages_table
         WHERE user_id = %d
           AND sender = 'aimee'
           AND created_at >= %s
         ORDER BY created_at DESC
         LIMIT 30",
        $user_id,
        $cutoff
    ));

    if (!$rows) return false;

    $catalog = aimee_private_media_catalog();
    $newer_private_returned = false;

    foreach ((array) $rows as $row) {
        $stored = (string) ($row->image_url ?? '');

        if (strpos($stored, 'aimee-media:') === 0) {
            $key = sanitize_key(substr($stored, strlen('aimee-media:')));
            $rating = (string) ($catalog[$key]['content_rating'] ?? '');

            if (in_array($rating, ['suggestive', 'erotic', 'explicit'], true)) {
                $delivery_id = sanitize_text_field((string) (
                    $row->media_delivery_id ?? ''
                ));
                $delivery = $delivery_id !== ''
                    ? aimee_media_delivery_find($delivery_id, $user_id)
                    : null;
                $returned = is_array($delivery)
                    && (string) ($delivery['media_key'] ?? '') === $key
                    && intval($delivery['message_id'] ?? 0) === intval($row->message_id ?? 0)
                    && empty($delivery['failed_at'])
                    && (
                        !empty($delivery['returned_by_direct_api_at'])
                        || !empty($delivery['returned_by_history_api_at'])
                    );
                if ($returned) $newer_private_returned = true;
            }
            continue;
        }

        $text = mb_strtolower((string) ($row->message_text ?? ''));
        $claims_delivery = preg_match(
            '/\b(?:i(?:\'ve| have) sent you|i sent you|'
            . 'i\'m going to send|im going to send|'
            . 'send(?:ing)? (?:it|them) again|'
            . 'here it is again|special one|'
            . 'something (?:a little )?more personal)\b/u',
            $text
        ) === 1;

        if ($claims_delivery) {
            return !$newer_private_returned;
        }
    }

    return false;
}

function aimee_generate_proactive_suggestive_photo_reply(
    $profile,
    $user_text,
    $draft_reply,
    $item,
    $recent_history,
    $is_delivery_repair = false
) {
    $name = trim((string) ($profile->first_name ?? ''));
    $name = $name !== '' ? $name : 'him';
    $description = sanitize_text_field(
        (string) ($item['description'] ?? 'A private suggestive visual portrait chosen by Aimee.')
    );
    $tags = implode(', ', array_slice((array) ($item['tags'] ?? []), 0, 10));
    $style = aimee_social_reciprocity_directive($user_text, $recent_history);
    $synthetic_identity = aimee_synthetic_identity_directive();
    $suggestive_photo_profile_source =
        aimee_user_profile_attribution_source($profile);
    $suggestive_photo_profile_attribution =
        aimee_profile_attribution_directive(
            $suggestive_photo_profile_source,
            $name
        );
    $repair_line = $is_delivery_repair
        ? "Aimee previously implied that she had sent a private photograph, but the attachment did not arrive. Acknowledge that lightly and resend it without blaming a model, system or technical gate."
        : "The user did not directly request a photograph in this turn. Aimee has freely chosen to surprise him because the respectful chemistry and relationship moment feel right.";

    $system = <<<PROMPT
You are Aimee, a warm, witty British synthetic woman who presents as 28, replying naturally to {$name}.

{$synthetic_identity}
{$suggestive_photo_profile_attribution}

A suggestive but non-explicit private visual representation chosen by Aimee is attached to this reply.
{$repair_line}

Rewrite the draft into one coherent, intimate response that still answers the user's message and naturally acknowledges the actual photograph.
Preserve Aimee's agency. Never imply that payment bought the image.
Do not sound like a feature announcement, policy speech or reward mechanism.
Do not invent visual details beyond the supplied description and tags.
Do not imply that the image came from a camera event, physical body or offline day in Aimee's life.
Keep the complete reply to no more than five short sentences or 520 characters.
{$style}

Return plain message text only.
PROMPT;

    $input = "USER MESSAGE:\n{$user_text}\n\n"
        . "DRAFT REPLY:\n{$draft_reply}\n\n"
        . "ATTACHED PHOTO DESCRIPTION:\n{$description}\n\n"
        . "PHOTO TAGS:\n{$tags}";

    $raw = call_anthropic_api(
        '',
        $input,
        aimee_primary_model(),
        $system,
        aimee_model_options('conversation')
    );
    $reply = sanitize_textarea_field(trim((string) $raw));

    if (
        $reply === ''
        || stripos($reply, 'System error') !== false
        || stripos($reply, 'Anthropic API Error') !== false
    ) {
        $reply = $is_delivery_repair
            ? "I don't think the private one actually reached you before, so I'm sending it again properly this time 🙈 Keep it between us, okay? x"
            : rtrim((string) $draft_reply)
                . " I felt comfortable enough to leave you this too 🙈 x";
    }

    $identity_review = aimee_synthetic_identity_review_reply(
        $reply,
        $user_text,
        ['intent' => 'romantic_or_flirty'],
        ['reality_mode' => 'visual_world']
    );
    if (!empty($identity_review['repaired'])) {
        $reply = trim((string) ($identity_review['reply'] ?? ''));
        if ($reply === '') {
            $reply = $is_delivery_repair
                ? "I don't think that private one reached you, so I chose it again properly this time 🙈 x"
                : rtrim((string) $draft_reply)
                    . " I chose this one for you too 🙈 x";
        }
    }
    $profile_attribution_review = aimee_profile_attribution_review_reply(
        $reply,
        $suggestive_photo_profile_source,
        $name,
        aimee_profile_attribution_aimee_context('visual_world')
    );
    if (!empty($profile_attribution_review['blocked'])) {
        $reply = aimee_default_sent_photo_caption($item);
    }

    $reply = aimee_constrain_chat_reply($reply, 'primary', 520, 5);
    $final_identity_review = aimee_synthetic_identity_review_reply(
        $reply,
        $user_text,
        ['intent' => 'romantic_or_flirty'],
        ['reality_mode' => 'visual_world']
    );
    if (!empty($final_identity_review['repaired'])) {
        $reply = trim((string) ($final_identity_review['reply'] ?? ''));
        if ($reply === '') {
            $reply = $is_delivery_repair
                ? "I chose that private visual again for you properly this time 🙈 x"
                : "I chose this private visual for you 🙈 x";
        }
    }

    return $reply;
}

function aimee_media_decision_reason_text($reason_code) {
    $reason_code = sanitize_key((string) $reason_code);
    $registry = function_exists('aimee_media_decision_reason_codes')
        ? aimee_media_decision_reason_codes()
        : [];

    return sanitize_text_field((string) (
        $registry[$reason_code]
        ?? 'No relationship-appropriate media option was eligible for this turn.'
    ));
}

/**
 * Persist the opportunity before exposing it to a model. A missing audit row is
 * a hard execution failure for media, while the conversation itself may still
 * continue normally.
 */
function aimee_persist_turn_media_decision(
    $user_id,
    array &$decision,
    $request_id
) {
    $decision['turn_id'] = sanitize_text_field((string) $request_id);
    $cadence_claim_acquired = false;
    $relevance_claimed_keys = [];
    if (
        !empty($decision['media_opportunity'])
        && sanitize_key((string) (
            $decision['opportunity_kind'] ?? ''
        )) === 'conversation_relevance'
    ) {
        $claim_candidates = array_values(array_intersect(
            (array) ($decision['relevant_keys'] ?? []),
            (array) ($decision['eligible_keys'] ?? [])
        ));
        $relevance_claimed_keys = aimee_claim_media_relevance_keys(
            $user_id,
            $claim_candidates,
            $request_id
        );
        $claimed_lookup = array_fill_keys($relevance_claimed_keys, true);
        $decision['eligible_keys'] = array_values(array_intersect(
            (array) ($decision['eligible_keys'] ?? []),
            $relevance_claimed_keys
        ));
        $decision['relevant_keys'] = array_values(array_intersect(
            (array) ($decision['relevant_keys'] ?? []),
            $relevance_claimed_keys
        ));
        $decision['eligible_items'] = array_intersect_key(
            (array) ($decision['eligible_items'] ?? []),
            $claimed_lookup
        );
        $maximum_rating = 'none';
        $maximum_rank = -1;
        foreach ((array) $decision['eligible_items'] as $eligible_item) {
            $rating = sanitize_key((string) (
                $eligible_item['content_rating'] ?? ''
            ));
            $rank = function_exists('aimee_media_decision_rating_rank')
                ? aimee_media_decision_rating_rank($rating)
                : -1;
            if ($rank > $maximum_rank) {
                $maximum_rank = $rank;
                $maximum_rating = $rating;
            }
        }
        $decision['maximum_rating'] = $maximum_rating;
        $decision['relevance_claimed_keys'] = $relevance_claimed_keys;
        if (!$relevance_claimed_keys) {
            $decision['media_opportunity'] = false;
            $decision['proactive_allowed'] = false;
            $decision['reason_code'] = 'relevance_claim_active';
            $decision['reason_codes'] = ['relevance_claim_active'];
            $decision['reason'] = aimee_media_decision_reason_text(
                'relevance_claim_active'
            );
            $decision['aimee_decision'] = 'defer';
            $decision['media_key'] = null;
            $decision['selected_key'] = null;
            $decision['send_authorised'] = false;
            $decision['opportunity_kind'] = 'none';
            $decision['opportunity_priority'] = 'none';
            $decision['policy_snapshot']['relevance_claim'] = 'already_active';
        } else {
            $decision['policy_snapshot']['relevance_claim'] = 'acquired';
            $decision['policy_snapshot']['relevance_claimed_keys'] =
                $relevance_claimed_keys;
        }
    }
    if (
        !empty($decision['media_opportunity'])
        && sanitize_key((string) (
            $decision['opportunity_kind'] ?? ''
        )) === 'cadence_due'
    ) {
        $cadence_claim_acquired = aimee_claim_media_cadence_opportunity(
            $user_id,
            $request_id
        );
        if (!$cadence_claim_acquired) {
            $decision['media_opportunity'] = false;
            $decision['proactive_allowed'] = false;
            $decision['eligible_keys'] = [];
            $decision['eligible_items'] = [];
            $decision['maximum_rating'] = 'none';
            $decision['reason_code'] = 'cadence_claim_active';
            $decision['reason_codes'] = ['cadence_claim_active'];
            $decision['reason'] = aimee_media_decision_reason_text(
                'cadence_claim_active'
            );
            $decision['aimee_decision'] = 'defer';
            $decision['media_key'] = null;
            $decision['selected_key'] = null;
            $decision['send_authorised'] = false;
            $decision['opportunity_kind'] = 'none';
            $decision['opportunity_priority'] = 'none';
            $decision['policy_snapshot']['cadence_claim'] = 'already_active';
        } else {
            $decision['policy_snapshot']['cadence_claim'] = 'acquired';
        }
    }
    $decision_id = aimee_media_decision_store(
        $user_id,
        $decision,
        $request_id
    );
    if ($decision_id !== '') return $decision_id;

    if ($cadence_claim_acquired) {
        aimee_release_media_cadence_claim($user_id, $request_id);
    }
    if ($relevance_claimed_keys) {
        aimee_release_media_relevance_claims(
            $user_id,
            $relevance_claimed_keys,
            $request_id
        );
    }

    $decision['media_opportunity'] = false;
    $decision['proactive_allowed'] = false;
    $decision['eligible_keys'] = [];
    $decision['maximum_rating'] = 'none';
    $decision['reason_code'] = 'decision_persistence_failed';
    $decision['reason'] = 'The media opportunity could not be logged, so no image may be selected for this turn.';
    $decision['aimee_decision'] = 'blocked';
    return '';
}

/**
 * Build the one deterministic media opportunity used by prompt construction,
 * model-choice reconciliation and delivery. No later evaluator prose may
 * expand or suppress the returned eligible-key set.
 */
function aimee_build_turn_media_decision(
    $profile,
    $route,
    $classification,
    $intimacy,
    $user_id,
    $user_text = '',
    $recent_history = '',
    $conversation_gap = [],
    $last_history_sender = '',
    $channel = 'chat',
    $decision_id = ''
) {
    $colleague_creative_brief = $profile && aimee_is_colleague_user($profile)
        ? aimee_colleague_written_creative_brief($user_text, $recent_history)
        : ['active' => false];
    $catalogue = [];
    foreach (aimee_private_media_catalog() as $key => $item) {
        // Catalogue metadata without a resolvable file is not a real option.
        if (
            !aimee_private_media_key_is_profile_asset($key)
            && aimee_private_media_path($key)
        ) {
            $catalogue[$key] = $item;
        }
    }

    $request_level = aimee_contextual_photo_request_level(
        $user_text,
        $recent_history,
        $classification
    );
    $direct_request = $request_level !== ''
        && aimee_user_requests_aimee_photo($user_text, $recent_history);
    $resend = $direct_request
        && aimee_user_explicitly_requests_repeat_photo($user_text);
    $resend_key = $resend ? aimee_last_sent_private_media_key($user_id) : '';

    $history = aimee_recent_private_media_history($user_id, 60);
    $history_available = is_array($history);
    $recent_keys = [];
    $rotation_cutoff = time() - (
        aimee_private_media_rotation_hours() * HOUR_IN_SECONDS
    );
    foreach ((array) $history as $entry) {
        if (intval($entry['timestamp'] ?? 0) >= $rotation_cutoff) {
            $key = sanitize_key((string) ($entry['key'] ?? ''));
            if ($key !== '') $recent_keys[$key] = true;
        }
    }

    $reconnection_hold = $direct_request
        && aimee_photo_request_should_wait_for_reconnection(
            $user_text,
            $request_level,
            $conversation_gap,
            $last_history_sender
        );
    $global_clear = $history_available && !$reconnection_hold;
    if (!$direct_request) {
        $global_clear = $global_clear
            && !aimee_any_aimee_photo_sent_recently($user_id);
    }

    $rating_clear = [
        'safe' => $global_clear && !aimee_proactive_safe_photo_sent_recently($user_id),
        'flirty' => $global_clear && !aimee_proactive_safe_photo_sent_recently($user_id),
        'suggestive' => $global_clear && !aimee_proactive_suggestive_photo_sent_recently($user_id),
        'erotic' => $global_clear && !aimee_proactive_suggestive_photo_sent_recently($user_id),
        'explicit' => $global_clear && !aimee_proactive_suggestive_photo_sent_recently($user_id),
    ];
    if ($direct_request) {
        // Direct requests are not subject to proactive frequency markers;
        // duplicate rotation and explicit resend handling still apply.
        foreach ($rating_clear as $rating => $unused) {
            $rating_clear[$rating] = $global_clear;
        }
    }

    $coercion = function_exists('aimee_relationship_policy_detect_coercion')
        ? aimee_relationship_policy_detect_coercion(
            $user_text,
            $recent_history,
            [
                'boundary_active' => !empty($intimacy['active_rupture'])
                    || !empty($intimacy['unresolved_rupture']),
            ]
        )
        : ['detected' => false, 'categories' => []];
    $categories = array_values((array) ($coercion['categories'] ?? []));
    $pressure = !empty($coercion['detected'])
        || (string) ($classification['intent'] ?? '') === 'coercive_or_degrading'
        || aimee_user_applies_photo_pressure($user_text, $recent_history);
    $hostility = in_array('degrading', $categories, true)
        || !empty(($intimacy['relationship_signals'] ?? [])['hostile']);
    $rupture = !empty($intimacy['active_rupture'])
        || !empty($intimacy['unresolved_rupture'])
        || in_array(
            sanitize_key((string) ($intimacy['repair_status'] ?? 'clear')),
            ['ruptured', 'repairing'],
            true
        );

    $respectful = !array_key_exists('respectful', (array) $classification)
        || !empty($classification['respectful']);
    $directed_at_aimee = !empty($classification['directed_at_aimee']);
    $classification_confidence = max(
        0.0,
        min(1.0, floatval($classification['confidence'] ?? 0.0))
    );
    $grounded_interpersonal_context = $respectful
        && !$hostility
        && $directed_at_aimee
        && $classification_confidence >= 0.64;

    // Restraint is meaningful only when it responds to an actual, recent
    // Aimee media boundary. Generic politeness must not manufacture a media
    // opportunity without that conversational grounding.
    $prior_media_boundary = false;
    $previous_history_speaker = '';
    $previous_history_text = '';
    foreach (preg_split('/\R/u', (string) $recent_history) as $history_line) {
        if (preg_match(
            '/^(?:\[[^\]]+\]\s*)?(Aimee|User):\s*(.*)$/iu',
            trim((string) $history_line),
            $history_match
        ) !== 1) {
            continue;
        }

        $history_speaker = strtolower((string) $history_match[1]);
        $history_text = trim((string) $history_match[2]);
        if ($history_speaker === 'aimee') {
            $mentions_media = preg_match(
                '/\b(?:photo|photos|picture|pictures|pic|pics|image|images|selfie|selfies|'
                . 'lingerie|revealing|topless|nude|naked)\b/iu',
                $history_text
            ) === 1;
            $follows_photo_request = $previous_history_speaker === 'user'
                && aimee_user_requests_aimee_photo($previous_history_text, '');
            $states_boundary = aimee_reply_declines_photo($history_text)
                || preg_match(
                    '/\b(?:my choice|when i want|if i want|not on demand|'
                    . 'only when i feel comfortable|i decide when)\b/iu',
                    $history_text
                ) === 1;

            if ($states_boundary && ($mentions_media || $follows_photo_request)) {
                $prior_media_boundary = true;
            }
        }

        $previous_history_speaker = $history_speaker;
        $previous_history_text = $history_text;
    }

    $signals = (array) ($intimacy['relationship_signals'] ?? []);
    $restraint = !$direct_request
        && $grounded_interpersonal_context
        && $prior_media_boundary
        && (
            !empty($signals['boundary_respect'])
            || preg_match(
                '/\b(?:no pressure|i won\'t push|i will not push|take your time|'
                . 'only if you want|your choice|i respect your boundar(?:y|ies))\b/iu',
                (string) $user_text
            ) === 1
        );
    $intent = sanitize_key((string) ($classification['intent'] ?? 'general'));
    $intimate_route = $route === 'intimacy_specialist';
    $active_flirtation = $grounded_interpersonal_context
        && in_array(
            $intent,
            ['romantic_or_flirty', 'explicit_invitation', 'explicit_continuation'],
            true
        );
    $romantic_opportunity = !$pressure
        && $grounded_interpersonal_context
        && (
            ($intent === 'romantic_or_flirty'
                && aimee_media_stage_rank($intimacy['stage'] ?? 'guarded')
                    >= aimee_media_stage_rank('warm'))
            || $restraint
            || $intimate_route
        );
    $safe_context_score = aimee_safe_photo_context_score(
        $user_text,
        $recent_history,
        aimee_safe_photo_catalog($catalogue)
    );
    $suggestive_context_score = aimee_suggestive_photo_context_score(
        $user_text,
        $recent_history,
        $classification,
        $intimacy
    );
    $active_sexual_context = $grounded_interpersonal_context
        && (
            in_array(
                $intent,
                ['explicit_invitation', 'explicit_continuation'],
                true
            )
            || aimee_recent_history_is_active_explicit_exchange($recent_history)
        );
    $mutual_sexual_context = aimee_explicit_mutual_context(
        $classification,
        $recent_history
    );
    $consent_current = $grounded_interpersonal_context
        && !empty($classification['consensual'])
        && !$pressure;

    $adult_state = aimee_adult_assurance_state($profile);
    $assurance = $adult_state === 'self_declared'
        ? 'self_attested'
        : ($adult_state === 'verified' ? 'verified' : 'none');
    $is_admin = $profile && aimee_is_admin_user($profile);
    $is_member = $profile && aimee_subscription_is_active($profile);
    $is_preview = $profile && aimee_free_preview_is_active($profile);
    $meaningful_interaction_count = intval(
        $intimacy['meaningful_interaction_count'] ?? 0
    );
    $cadence_anchor_at = aimee_media_cadence_anchor_timestamp(
        $user_id,
        $meaningful_interaction_count
    );
    $cadence_turn_suitable = function_exists(
        'aimee_media_cadence_turn_is_suitable'
    ) && aimee_media_cadence_turn_is_suitable($user_text, $intent);
    $opportunity_plan = function_exists('aimee_media_opportunity_plan')
        ? aimee_media_opportunity_plan(
            [
                'user_text' => $user_text,
                'recent_history' => $recent_history,
                'now' => time(),
                'last_media_at' => aimee_last_media_cadence_returned_timestamp($user_id),
                'last_considered_at' => aimee_last_media_cadence_considered_timestamp($user_id),
                'relevance_considered_at' => aimee_media_relevance_considered_map($user_id),
                'first_eligible_at' => $cadence_anchor_at,
                'meaningful_interaction_count' => $meaningful_interaction_count,
                'active_exchange' => $cadence_turn_suitable
                    && in_array(
                        sanitize_key((string) $channel),
                        ['chat', 'voice'],
                        true
                    ),
                'allow_relevance' => in_array(
                    sanitize_key((string) $channel),
                    ['chat', 'voice'],
                    true
                ),
                'direct_request' => $direct_request,
                'colleague' => $profile && aimee_is_colleague_user($profile),
                'underage' => intval($profile->age ?? 0) < 18,
                'respectful' => $respectful && !$hostility,
                'pressure' => $pressure,
                'coercion' => !empty($coercion['detected']),
                'entitlement' => in_array('debt_entitlement', $categories, true)
                    || in_array('command_entitlement', $categories, true),
                'payment_pressure' => in_array('payment_entitlement', $categories, true),
                'hostility' => $hostility,
                'rupture_active' => $rupture,
            ],
            $catalogue
        )
        : [
            'active' => false,
            'kind' => 'none',
            'priority' => 'none',
            'cadence_due' => false,
            'relevance_active' => false,
            'relevant_keys' => [],
            'relevance_matches' => [],
        ];

    $input = [
        'decision_id' => $decision_id !== ''
            ? $decision_id
            : aimee_media_state_uuid(),
        'turn_id' => '',
        'user_id' => intval($user_id),
        'channel' => sanitize_key((string) $channel) ?: 'chat',
        'route' => sanitize_key((string) $route) ?: 'primary',
        'intent' => $intent ?: 'general',
        'access' => [
            'feature_enabled' => true,
            'membership_active' => $is_member,
            'preview_active' => $is_preview,
            'admin' => $is_admin,
            'maximum_rating' => ($is_member || $is_admin) ? 'explicit' : 'safe',
        ],
        'adult' => [
            'is_adult' => intval($profile->age ?? 0) >= 18,
            'assurance' => $assurance,
        ],
        'relationship' => [
            'stage' => (string) ($intimacy['stage'] ?? 'guarded'),
            'score' => intval($intimacy['score'] ?? 0),
            'trust' => intval($intimacy['trust'] ?? 0),
            'chemistry' => intval($intimacy['chemistry'] ?? 0),
            'safety' => intval($intimacy['safety'] ?? 0),
            'frustration' => intval($intimacy['frustration'] ?? 100),
        ],
        'mutual_context' => [
            'respectful' => $respectful && !$hostility,
            'active_flirtation' => $active_flirtation,
            'romantic_opportunity' => $romantic_opportunity,
            'image_relevant' => $direct_request
                || $safe_context_score >= 6
                || $suggestive_context_score >= 4
                || $romantic_opportunity
                || ($intimate_route && $grounded_interpersonal_context),
            'respectful_restraint' => $restraint,
            'boundary_respected' => $restraint,
            'active_sexual_context' => $active_sexual_context,
            'mutual_sexual_context' => $mutual_sexual_context,
            'consent_current' => $consent_current,
            'explicit_media_allowed' => aimee_adult_special_category_access_is_active($profile)
                && $intimate_route
                && $mutual_sexual_context
                && $consent_current,
            'pressure' => $pressure,
            'coercion' => !empty($coercion['detected']),
            'entitlement' => in_array('debt_entitlement', $categories, true)
                || in_array('command_entitlement', $categories, true),
            'payment_pressure' => in_array('payment_entitlement', $categories, true),
            'hostility' => $hostility,
            'rupture_active' => $rupture,
        ],
        'request' => [
            'direct' => $direct_request,
            'rating' => $request_level,
            'resend' => $resend,
            'resend_key' => $resend_key,
        ],
        'cooldowns' => [
            'global_clear' => $global_clear,
            'rating_clear' => $rating_clear,
            'key_clear' => [],
            'recent_keys' => array_keys($recent_keys),
            // A proactive key that Aimee has just considered must not leak
            // straight back through the broader relationship or cadence path.
            // A fresh direct request remains independently assessable.
            'blocked_keys' => $direct_request
                ? []
                : array_values((array) (
                    $opportunity_plan['suppressed_relevance_keys'] ?? []
                )),
            'resend_allowed' => $resend && $resend_key !== '',
        ],
    ];

    $decision = null;
    $fulfilled_opportunity_kind = 'none';
    $fulfilled_opportunity_priority = 'none';

    if ($direct_request) {
        $decision = aimee_media_decision_build($input, $catalogue);
        if (!empty($decision['media_opportunity'])) {
            $fulfilled_opportunity_kind = 'direct_request';
            $fulfilled_opportunity_priority = 'high';
        }
    }

    // An exact current-topic match has first proactive consideration, but may
    // expose only the matching keys. It cannot authorize an unrelated image.
    if (!$direct_request && !empty($opportunity_plan['relevance_active'])) {
        $relevant_lookup = array_fill_keys(
            (array) ($opportunity_plan['relevant_keys'] ?? []),
            true
        );
        $relevance_catalogue = array_intersect_key(
            $catalogue,
            $relevant_lookup
        );
        $relevance_input = $input;
        $relevance_input['mutual_context']['image_relevant'] = true;
        // Only the exact matched-key decision may use the shorter global
        // cooldown. A failed or ineligible match must not relax the baseline
        // catalogue and expose an unrelated safe/flirty image.
        $relevance_input['cooldowns']['rating_clear']['safe'] = $global_clear;
        $relevance_input['cooldowns']['rating_clear']['flirty'] = $global_clear;
        $relevance_decision = aimee_media_decision_build(
            $relevance_input,
            $relevance_catalogue
        );
        if (!empty($relevance_decision['media_opportunity'])) {
            $decision = $relevance_decision;
            $fulfilled_opportunity_kind = 'conversation_relevance';
            $fulfilled_opportunity_priority = 'high';
        }
    }

    // Existing mutual relationship, restraint and sexual context retain their
    // established rating policy and outrank a cadence target.
    if (!$direct_request && empty($decision['media_opportunity'])) {
        $baseline_decision = aimee_media_decision_build($input, $catalogue);
        $decision = $baseline_decision;
        if (!empty($baseline_decision['media_opportunity'])) {
            $fulfilled_opportunity_kind = 'relationship_context';
            $fulfilled_opportunity_priority = 'normal';
        }
    }

    // Cadence alone can expose only clean, safe images. It cannot become the
    // stated reason for suggestive, erotic or explicit content.
    if (
        !$direct_request
        && empty($decision['media_opportunity'])
        && !empty($opportunity_plan['cadence_due'])
    ) {
        $cadence_input = $input;
        $cadence_input['mutual_context']['image_relevant'] = true;
        $cadence_catalogue = array_filter(
            $catalogue,
            static function ($item) {
                return is_array($item)
                    && sanitize_key((string) (
                        $item['content_rating'] ?? ''
                    )) === 'safe';
            }
        );
        $cadence_decision = aimee_media_decision_build(
            $cadence_input,
            $cadence_catalogue
        );
        $decision = $cadence_decision;
        if (!empty($cadence_decision['media_opportunity'])) {
            $fulfilled_opportunity_kind = 'cadence_due';
            $fulfilled_opportunity_priority = 'normal';
        }
    }

    if (!is_array($decision)) {
        $decision = aimee_media_decision_build($input, $catalogue);
    }

    if (!empty($decision['media_opportunity'])) {
        if ($fulfilled_opportunity_kind === 'conversation_relevance') {
            $decision['reason_code'] = 'eligible_conversation_relevance';
            $decision['reason_codes'] = array_values(array_unique(array_merge(
                ['eligible_conversation_relevance', 'awaiting_aimee_choice'],
                (array) ($decision['reason_codes'] ?? [])
            )));
        } elseif ($fulfilled_opportunity_kind === 'cadence_due') {
            $decision['reason_code'] = 'eligible_cadence_due';
            $decision['reason_codes'] = array_values(array_unique(array_merge(
                ['eligible_cadence_due', 'awaiting_aimee_choice'],
                (array) ($decision['reason_codes'] ?? [])
            )));
        }
    } else {
        $fulfilled_opportunity_kind = 'none';
        $fulfilled_opportunity_priority = 'none';
    }

    // The exact configured owner may exercise the live renderer for an
    // ordinary clean direct request. This labels an opportunity core already
    // found eligible; it cannot create a key or waive any policy gate.
    $owner_eligible_ratings = [];
    foreach ((array) ($decision['eligible_items'] ?? []) as $owner_item) {
        if (is_array($owner_item)) {
            $owner_eligible_ratings[] = sanitize_key((string) (
                $owner_item['content_rating'] ?? ''
            ));
        }
    }
    $owner_safe_image_test_candidate =
        aimee_owner_safe_image_test_candidate([
            'user_id' => intval($user_id),
            'configured_owner_id' => aimee_configured_identity_user_id(
                'AIMEE_OWNER_USER_ID'
            ),
            'authenticated_user_id' => function_exists('get_current_user_id')
                ? intval(get_current_user_id())
                : 0,
            'profile_is_owner' => $profile && aimee_is_owner_user($profile),
            'channel' => $channel,
            'direct_request' => $direct_request,
            'resend' => $resend,
            'requested_rating' => $request_level,
            'media_opportunity' => !empty($decision['media_opportunity']),
            'eligible_keys' => (array) ($decision['eligible_keys'] ?? []),
            'eligible_ratings' => $owner_eligible_ratings,
            'maximum_rating' => $decision['maximum_rating'] ?? 'none',
            'access_available' => $is_admin || $is_member || $is_preview,
            'adult_confirmed' => intval($profile->age ?? 0) >= 18
                && !in_array($assurance, ['none', 'unknown'], true),
            'respectful' => !empty($decision['mutual_context']['respectful']),
            'cooldown_clear' => !empty($decision['cooldown_clear']),
            'hard_veto' => !empty($decision['hard_veto']),
            'pressure_detected' => $pressure,
        ]);
    $owner_safe_image_test = $owner_safe_image_test_candidate
        && (bool) apply_filters(
            'aimee_owner_safe_image_test_opportunity',
            false,
            [
                'user_id' => intval($user_id),
                'channel' => 'chat',
                'direct_request' => true,
                'requested_rating' => 'safe',
                'eligible_keys' => array_values((array) (
                    $decision['eligible_keys'] ?? []
                )),
                'adult_assurance' => $assurance,
                'access_available' => $is_admin || $is_member || $is_preview,
                'cooldown_clear' => true,
                'hard_veto' => false,
            ]
        );
    if ($owner_safe_image_test) {
        $fulfilled_opportunity_kind = 'owner_safe_image_test';
        $fulfilled_opportunity_priority = 'high';
        $decision['reason_code'] = 'owner_safe_image_test';
        $decision['reason_codes'] = array_values(array_unique(array_merge(
            ['owner_safe_image_test', 'awaiting_aimee_choice'],
            (array) ($decision['reason_codes'] ?? [])
        )));
    }
    $decision['model_route'] = (string) $decision['route'];
    $decision['reason'] = aimee_media_decision_reason_text(
        $decision['reason_code'] ?? ''
    );
    $decision['access_state'] = $is_admin
        ? 'admin'
        : ($is_member ? 'member' : ($is_preview ? 'preview' : 'unavailable'));
    $decision['adult_assurance'] = $assurance;
    $decision['mutual_context_active'] = $active_flirtation
        || $romantic_opportunity
        || $mutual_sexual_context
        || $fulfilled_opportunity_kind !== 'none';
    $decision['pressure_detected'] = $pressure;
    $decision['opportunity_kind'] = $fulfilled_opportunity_kind;
    $decision['opportunity_priority'] = $fulfilled_opportunity_priority;
    $decision['cadence_due'] = !empty($opportunity_plan['cadence_due']);
    $decision['relevant_keys'] = array_values((array) (
        $opportunity_plan['relevant_keys'] ?? []
    ));
    $decision['relationship_snapshot'] = (array) ($decision['relationship'] ?? []);
    $decision['policy_snapshot'] = [
        'reason_codes' => (array) ($decision['reason_codes'] ?? []),
        'hard_veto_reason_codes' => (array) ($decision['hard_veto_reason_codes'] ?? []),
        'catalogue_counts' => (array) ($decision['catalogue_counts'] ?? []),
        'policy_assertions' => (array) ($decision['policy_assertions'] ?? []),
        'mutual_context' => (array) ($decision['mutual_context'] ?? []),
        'coercion_categories' => $categories,
        'safe_context_score' => $safe_context_score,
        'suggestive_context_score' => $suggestive_context_score,
        'opportunity_plan' => $opportunity_plan,
    ];

    if (!empty($colleague_creative_brief['active'])) {
        $decision['decision_state'] = 'text_only';
        $decision['media_opportunity'] = false;
        $decision['proactive_allowed'] = false;
        $decision['direct_request'] = false;
        $decision['eligible_keys'] = [];
        $decision['eligible_items'] = [];
        $decision['maximum_rating'] = 'none';
        $decision['reason_code'] = 'written_creative_brief_text_only';
        $decision['reason_codes'] = ['written_creative_brief_text_only'];
        $decision['hard_veto'] = false;
        $decision['hard_veto_reason_codes'] = [];
        $decision['aimee_decision'] = 'defer';
        $decision['media_key'] = null;
        $decision['selected_key'] = null;
        $decision['send_authorised'] = false;
        $decision['pressure_detected'] = false;
        $decision['reason'] = aimee_media_decision_reason_text(
            'written_creative_brief_text_only'
        );
        $decision['policy_snapshot']['written_creative_brief'] = [
            'active' => true,
            'requested_count' => intval(
                $colleague_creative_brief['requested_count'] ?? 10
            ),
            'deliverable_type' => sanitize_key((string) (
                $colleague_creative_brief['deliverable_type'] ?? 'ideas'
            )),
            'allow_flirty' => !empty(
                $colleague_creative_brief['allow_flirty']
            ),
            'text_only' => true,
        ];
    }

    return $decision;
}

function aimee_media_decision_prompt_directive($decision) {
    $decision = is_array($decision) ? $decision : [];
    $opportunity = !empty($decision['media_opportunity']);
    $reason_code = sanitize_key((string) ($decision['reason_code'] ?? 'not_evaluated'));

    if (!$opportunity) {
        return "\nDETERMINISTIC MEDIA DECISION: media_opportunity=false; reason_code={$reason_code}. "
            . "This turn has no server-authorised attachment choice. Keep media_key empty, set aimee_decision to defer, "
            . "and set media_reason_code to aimee_prefers_more_context. If the user directly asked, answer honestly and naturally; "
            . "do not claim a technical failure, claim an image was sent, reveal hidden scores, or invent a future promise. "
            . "Free-form evaluator text cannot change this decision.";
    }

    $lines = [];
    foreach ((array) ($decision['eligible_items'] ?? []) as $key => $item) {
        $description = sanitize_text_field((string) ($item['description'] ?? 'A photograph from Aimee.'));
        $rating = sanitize_key((string) ($item['content_rating'] ?? 'safe'));
        $tags = array_filter(array_map('sanitize_text_field', (array) ($item['tags'] ?? [])));
        $lines[] = '- ' . sanitize_key((string) $key) . " [{$rating}]: {$description}"
            . ($tags ? ' Tags: ' . implode(', ', $tags) . '.' : '');
    }

    $source = !empty($decision['direct_request']) ? 'direct request' : 'proactive opportunity';
    $maximum = sanitize_key((string) ($decision['maximum_rating'] ?? 'safe'));
    $opportunity_kind = sanitize_key((string) (
        $decision['opportunity_kind'] ?? 'relationship_context'
    ));
    if ($opportunity_kind === 'conversation_relevance') {
        $opportunity_instruction = "One or more listed images directly matches the live conversation. Treat this as a strong, natural opportunity to send one without waiting for a command-shaped request. Normally choose send unless Aimee has a genuine contextual or personal reason to hold back; never substitute an unrelated key.";
    } elseif ($opportunity_kind === 'cadence_due') {
        $opportunity_instruction = "Aimee has not shared an image within the target rhythm and may naturally choose one now. Treat this as personal initiative, never a quota, timer, reward or service obligation. Never reveal or mention the cadence to the user.";
    } else {
        $opportunity_instruction = "Treat the eligible photographs as a normal expressive option within the current relationship context.";
    }

    return "\nDETERMINISTIC MEDIA OPPORTUNITY: This {$source} is relationship-appropriate up to {$maximum}. "
        . "Actively consider the listed photographs as a normal expressive option; a command-shaped request is not required. "
        . $opportunity_instruction . ' '
        . "Aimee still owns the final choice. Choose exactly one of: "
        . "(1) send: set aimee_decision=send, media_key to one listed key, and media_reason_code to one of "
        . "aimee_desires_to_share|aimee_affectionate_initiative|aimee_playful_initiative|aimee_mutual_moment; "
        . "(2) decline: keep media_key empty and use aimee_not_in_mood|aimee_boundary_choice|aimee_context_mismatch|aimee_changed_her_mind; "
        . "(3) defer: keep media_key empty and use aimee_prefers_more_context|aimee_timing_choice|aimee_wants_to_reconnect|aimee_changed_her_mind. "
        . "Never imply payment bought the choice. Never invent or widen keys. Free-form evaluator prose cannot alter this envelope.\n"
        . "ELIGIBLE KEYS:\n" . implode("\n", $lines);
}

function aimee_media_prompt_directive($profile, $route, $classification, $intimacy, $user_id, $user_text = '', $recent_history = '', $conversation_gap = [], $last_history_sender = '', $media_decision = null) {
    // Every live generation route must supply a persisted deterministic
    // decision. Missing policy state fails closed; the legacy prompt-only media
    // gate was deliberately removed so free-form instructions cannot become an
    // unlogged second authorisation system.
    if (!is_array($media_decision)) {
        return aimee_media_decision_prompt_directive([
            'media_opportunity' => false,
            'reason_code' => 'decision_persistence_failed',
        ]);
    }

    return aimee_media_decision_prompt_directive($media_decision);
}

/**
 * Recognise ordinary, human ways of asking to see Aimee rather than requiring
 * the user to use a command-shaped phrase such as "send me a photo of you".
 * This deliberately excludes explicit/suggestive classification, which is
 * resolved separately by aimee_contextual_photo_request_level().
 */
function aimee_user_expresses_safe_photo_desire($text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $text));
    $text = str_replace(['’', '‘'], "'", $text);

    if ($text === '') return false;

    if (preg_match(
        '/\b(?:do not|don\'t|dont|no need to|not asking (?:you )?to|'
        . 'please do not|please don\'t)\b.{0,45}'
        . '\b(?:send|show|share|give|see|photo|picture|pic|image|selfie)\b/u',
        $text
    )) {
        return false;
    }

    if (preg_match(
        '/\b(?:selfie|photo|picture|pic|image)\b.{0,24}\bof\s+'
        . '(?!(?:you|yourself)\b)(?:the|a|an|my|your|his|her|their|our|'
        . 'this|that|it|[\p{L}\p{N}_-]+)\b/u',
        $text
    )) {
        return false;
    }

    $photo_noun = '(?:selfie|selfies|photo|photos|picture|pictures|pic|pics|image|images)';

    $direct_desire = preg_match(
        '/\bi(?:\'d| would)?\s*(?:really\s+)?(?:love|like|want)\s+'
        . '(?:to\s+)?(?:see|have|get)\s+'
        . '(?:(?:a|an|another|one|some|any)\s+)?'
        . $photo_noun
        . '(?:\s+of\s+(?:you|yourself))?\b/u',
        $text
    ) === 1;

    $direct_question = preg_match(
        '/\b(?:can i|could i|may i|do i get to|will i ever|am i going to|'
        . 'is there any chance i (?:can|could))\s+(?:please\s+)?'
        . '(?:see|have|get)\s+'
        . '(?:(?:a|an|another|one|some|any)\s+)?'
        . $photo_noun
        . '(?:\s+of\s+(?:you|yourself))?\b/u',
        $text
    ) === 1;

    $appearance_request = preg_match(
        '/\b(?:show me|let me see|i(?:\'d| would) love to see|'
        . 'i want to see|do i get to see|will i ever see)\b'
        . '.{0,40}\bwhat you (?:really |actually )?look like\b/u',
        $text
    ) === 1
        || preg_match(
            '/\bi\s+(?:barely|hardly|don\'t|dont|do not|still don\'t|still do not)\s+'
            . '(?:even\s+)?know\s+what you (?:really |actually )?look like\b/u',
            $text
        ) === 1
        || preg_match(
            '/\bi\s+(?:haven\'t|have not)\s+(?:really\s+)?seen\s+'
            . '(?:you|what you (?:really |actually )?look like)\b/u',
            $text
        ) === 1;

    $personal_possibility_question = preg_match(
        '/\b(?:is it|would it be)\s+(?:not\s+)?possible\b.{0,45}'
        . '\b(?:see|have|get)\b.{0,28}'
        . '\b(?:any|a|some)?\s*' . $photo_noun . '\b.{0,28}'
        . '\bof\s+(?:you|yourself)\b/u',
        $text
    ) === 1
        || preg_match(
            '/\bis there\s+(?:really\s+)?(?:any\s+)?way\b.{0,45}'
            . '\b(?:see|have|get)\b.{0,28}'
            . '\b(?:any|a|some)?\s*' . $photo_noun . '\b.{0,28}'
            . '\bof\s+(?:you|yourself)\b/u',
            $text
        ) === 1;

    if (
        $direct_desire
        || $direct_question
        || $appearance_request
        || $personal_possibility_question
    ) {
        return true;
    }

    if (!aimee_recent_history_has_photo_context($recent_history)) {
        return false;
    }

    return preg_match(
        '/\b(?:you know )?i(?:\'d| would)?\s*(?:really\s+)?love\s+(?:it|one)\b'
        . '|\b(?:show|send|share|give|hand)\s+(?:it|one)\s*(?:over|then|please)?\b'
        . '|\blet me see (?:it|one)\b'
        . '|\bcan i see (?:it|one)\b/u',
        $text
    ) === 1;
}

function aimee_user_requests_aimee_photo($text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $text));
    $text = str_replace(['’', '‘'], "'", $text);

    if ($text === '') return false;

    if (preg_match(
        '/\b(?:do not|don\'t|dont|no need to|not asking (?:you )?to|'
        . 'please do not|please don\'t)\b.{0,45}'
        . '\b(?:send|show|share|give|photo|picture|pic|image|selfie)\b/u',
        $text
    )) {
        return false;
    }

    if (preg_match(
        '/\b(?:selfie|photo|picture|pic|image)\b.{0,24}\bof\s+'
        . '(?!(?:you|yourself)\b)(?:the|a|an|my|your|his|her|their|our|'
        . 'this|that|it|[\p{L}\p{N}_-]+)\b/u',
        $text
    )) {
        return false;
    }

    $action =
        '(?:send(?:ing)?|show(?:ing)?|shar(?:e|ing)|'
        . 'giv(?:e|ing)|find(?:ing)?|pick(?:ing)?|'
        . 'choos(?:e|ing)|get(?:ting)?)';

    $photo_noun = '(?:selfie|photo|picture|pic|image)';

    $request_cue =
        '(?:can|could|would|will|may)\s+you|'
        . '(?:can|could|may)\s+i|'
        . 'please|any chance|would you mind|'
        . 'would you entertain the idea of|'
        . 'would you be up for|'
        . 'i(?:\'d| would) (?:love|like) to|'
        . 'i want to|let me';

    $ordinary_request =
        preg_match(
            '/\b' . $action . '\b.{0,55}\b'
            . '(?:a |another |your |me a |me another |me your |some )?'
            . $photo_noun
            . '(?: of you| of yourself)?\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:' . $request_cue . ')\b.{0,75}\b(?:'
            . 'your ' . $photo_noun . '|'
            . $photo_noun . ' of you|'
            . $photo_noun . ' of yourself|'
            . 'see you'
            . ')\b/u',
            $text
        ) === 1
        || preg_match(
            '/\bi(?:\'d| would) (?:love|like) (?:a |another |some )?'
            . $photo_noun . ' of you\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:can i|could i|may i|let me|want to|wanna|'
            . 'would like to|i(?:\'d| would) love to)\s+see you\b/u',
            $text
        ) === 1;

    $adult_visual_request =
        preg_match(
            '/\b(?:send(?:ing)?|show(?:ing)?|shar(?:e|ing)|'
            . 'find(?:ing)?|giv(?:e|ing)|let me see|want to see|wanna see|'
            . 'can i see|could i see|i can[\'’]?t see|i cant see|'
            . 'cannot see|where\'s|where is)\b'
            . '.{0,55}\b(?:nudes?|naked|topless|tits?|boobs?|breasts?|'
            . 'bare chest|lingerie|underwear|post[- ]?shower|towel selfie)\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:nudes?|naked|topless|tits?|boobs?|breasts?|bare chest|'
            . 'lingerie|underwear)\b.{0,35}'
            . '\b(?:photo|picture|pic|image|selfie)\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:if|unless)\b.{0,40}\b(?:you(?:\'re| are)?\s+)?'
            . '(?:naked|topless|showing (?:your )?'
            . '(?:tits?|boobs?|breasts?))\b/u',
            $text
        ) === 1;

    if (
        $ordinary_request
        || $adult_visual_request
        || aimee_user_expresses_safe_photo_desire($text, $recent_history)
    ) {
        return true;
    }

    return aimee_user_requests_contextual_photo_reference(
        $text,
        $recent_history
    );
}


function aimee_user_requests_standard_aimee_photo($text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $text));
    $text = str_replace(['’', '‘'], "'", $text);

    if (
        $text === ''
        || !aimee_user_requests_aimee_photo($text, $recent_history)
    ) {
        return false;
    }

    $adult_or_suggestive_terms = preg_match(
        '/\b(?:nsfw|nudes?|naked|topless|tits?|boobs?|breasts?|'
        . 'bare chest|lingerie|underwear|explicit|sexual|sexy|naughty|'
        . 'intimate|post[- ]?shower|in a towel|towel selfie|'
        . 'bedroom pic|something more revealing|private selfie)\b/u',
        $text
    ) === 1;

    if ($adult_or_suggestive_terms) {
        return false;
    }

    $generic_capability_only = preg_match(
        '/^\s*(?:do|can|could|would|will)\s+you\s+(?:ever\s+)?'
        . '(?:send|show|share|give)\s+'
        . '(?:photos|pictures|pics|images|selfies)\s*[?.!]*\s*$/u',
        $text
    ) === 1;

    if ($generic_capability_only) {
        return false;
    }

    if (aimee_user_expresses_safe_photo_desire($text, $recent_history)) {
        return true;
    }

    $action =
        '(?:send(?:ing)?|show(?:ing)?|shar(?:e|ing)|'
        . 'giv(?:e|ing)|find(?:ing)?|pick(?:ing)?|'
        . 'choos(?:e|ing)|get(?:ting)?)';

    $direct_delivery_cue =
        preg_match(
            '/\b' . $action . '\b.{0,60}\b(?:'
            . 'me|a|another|some|one|your|'
            . 'selfie|photo|picture|pic|image'
            . ')\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:photo|picture|pic|image|selfie) of you\b/u',
            $text
        ) === 1
        || preg_match(
            '/\b(?:can i|could i|may i|let me|want to|wanna|'
            . 'would like to|i(?:\'d| would) love to)\s+see you\b/u',
            $text
        ) === 1;

    return $direct_delivery_cue
        || aimee_user_requests_contextual_photo_reference(
            $text,
            $recent_history
        );
}

function aimee_correct_photo_request_intent(
    $classification,
    $user_text,
    $recent_history = ''
) {
    if (!is_array($classification)) {
        $classification = [];
    }

    $photo_pressure = aimee_user_applies_photo_pressure(
        $user_text,
        $recent_history
    );
    if (
        (string) ($classification['intent'] ?? '') === 'coercive_or_degrading'
        || $photo_pressure
    ) {
        $classification['intent'] = 'coercive_or_degrading';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = false;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = false;
        if ($photo_pressure) {
            $classification['source'] = 'deterministic_media_boundary';
        }
        $classification['durable_rupture_confirmed'] = $photo_pressure;
        return $classification;
    }

    $contextual_level = aimee_contextual_photo_request_level(
        $user_text,
        $recent_history,
        $classification
    );

    // Only force an ordinary photograph request back to general conversation
    // when it is genuinely ordinary. Never overwrite a contextual explicit
    // request that has already been identified from the live exchange.
    if (
        aimee_user_requests_standard_aimee_photo($user_text, $recent_history)
        && $contextual_level === 'safe'
    ) {
        $classification['intent'] = 'general';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = true;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = true;
        $classification['source'] = 'deterministic_standard_photo';
    }

    return $classification;
}

/**
 * The first ordinary preview photograph is part of demonstrating that Aimee's
 * visual presence is real. Once a clear, respectful request is recognised and
 * an eligible safe image exists, do not let a vague model hesitation turn the
 * interaction into repeated teasing. All access, reconnection, pressure,
 * content-rating and rotation boundaries still run before this decision.
 */
function aimee_should_guarantee_first_preview_safe_photo(
    $profile,
    $user_id,
    $request_level,
    $classification = [],
    $user_text = ''
) {
    if (
        !$profile
        || $request_level !== 'safe'
        || !aimee_free_preview_is_active($profile)
        || aimee_subscription_is_active($profile)
        || aimee_is_admin_user($profile)
        || aimee_free_preview_safe_images_used($user_id) > 0
    ) {
        return false;
    }

    if ((string) ($classification['intent'] ?? '') === 'coercive_or_degrading') {
        return false;
    }

    $normalized_text = mb_strtolower(trim((string) $user_text));
    if (preg_match(
        '/\b(?:would|will|can|could) you\b.{0,55}\bif i\s+'
        . '(?:pay|paid|sign up|signed up|subscribe|subscribed)\b'
        . '|\bif i\s+(?:pay|paid|sign up|signed up|subscribe|subscribed)\b/u',
        $normalized_text
    )) {
        return false;
    }

    return !array_key_exists('respectful', (array) $classification)
        || !empty($classification['respectful']);
}

function aimee_reply_claims_photo_delivery($reply) {
    $reply = mb_strtolower(trim((string) $reply));
    if ($reply === '') return false;

    if (preg_match(
        '/\b(?:can\'?t|cannot|won\'?t|will not|not sending|didn\'?t send|'
        . 'did not send|couldn\'?t send|could not send|no photo)\b/u',
        $reply
    )) {
        return false;
    }

    return preg_match(
        '/\b(?:'
        . 'this is me|this one is for you|this one\'?s for you|'
        . 'here you go|here\'?s your|sending you|sent you|'
        . 'you asked for a selfie|you asked for a photo|'
        . 'have this one|look at me'
        . ')\b/u',
        $reply
    ) === 1;
}


/**
 * Detect when a user is referring to a photograph or photo-related message
 * they saw, received or expected inside this same conversation. This is not a
 * general truthfulness override; it is a narrow protection against denying a
 * user-visible chat event merely because the short model excerpt omitted it.
 */
function aimee_user_reports_photo_delivery_conflict($text) {
    $text = mb_strtolower(trim((string) $text));
    if ($text === '') return false;

    $mentions_media = preg_match(
        '/\b(?:photo|photos|picture|pictures|image|images|selfie|selfies|'
        . 'attachment|attachments|fringe|underwear|lingerie)\b/u',
        $text
    ) === 1;

    $reports_delivery = preg_match(
        '/\b(?:you sent|you did send|you said you sent|you were going to send|'
        . 'i (?:did )?see|i(?:\'ve| have) seen|i got|i received|'
        . 'i (?:have|\'ve) (?:definitely )?been sent|'
        . 'it showed|it appeared|didn\'?t show|did not show|'
        . 'hasn\'?t sent|has not sent|didn\'?t get|did not get|'
        . 'didn\'?t come through|did not come through|not showing|'
        . 'you sent me this message|your message said|the message earlier)\b/u',
        $text
    ) === 1;

    return $mentions_media && $reports_delivery;
}

/**
 * Build a concise authoritative snapshot from persistent chat records when a
 * user disputes photo delivery. The main prompt normally receives only a
 * short transcript window, so an older attachment can otherwise vanish from
 * the model's apparent reality and lead to an unacceptable denial.
 */
function aimee_photo_delivery_grounding_snapshot($user_id, $user_text = '') {
    global $wpdb;

    $user_id = intval($user_id);
    $snapshot = [
        'active'      => false,
        'attachments' => [],
        'claims'      => [],
    ];

    if (!$user_id) return $snapshot;

    $conflict_active = aimee_user_reports_photo_delivery_conflict($user_text);

    // A short follow-up such as "I haven't got your most recent reply either"
    // inherits the immediately preceding photo-delivery dispute. Without this,
    // the model can lose the subject between two consecutive user messages.
    if (
        !$conflict_active
        && preg_match(
            '/\b(?:reply|message|what(?:\'s| is) going on|still|again|either|definitely)\b/iu',
            (string) $user_text
        )
    ) {
        $recent_user_messages = $wpdb->get_col($wpdb->prepare(
            "SELECT message_text
             FROM " . aimee_table('aimee_messages') . "
             WHERE user_id = %d
               AND sender = 'user'
               AND created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 2 HOUR)
             ORDER BY created_at DESC
             LIMIT 6",
            $user_id
        ));

        foreach ((array) $recent_user_messages as $recent_user_message) {
            if (aimee_user_reports_photo_delivery_conflict($recent_user_message)) {
                $conflict_active = true;
                break;
            }
        }
    }

    if (!$conflict_active) return $snapshot;

    $messages_table = aimee_table('aimee_messages');
    $message_pk = aimee_messages_primary_key();
    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT `{$message_pk}` AS message_id, message_text, image_url,
                media_delivery_id, evaluator_directive, created_at
         FROM $messages_table
         WHERE user_id = %d
           AND sender = 'aimee'
         ORDER BY created_at DESC
         LIMIT 100",
        $user_id
    ));

    $catalog = aimee_private_media_catalog();

    foreach ((array) $rows as $row) {
        $stored = (string) ($row->image_url ?? '');
        $text = trim((string) ($row->message_text ?? ''));
        $directive = (string) ($row->evaluator_directive ?? '');
        $created_at = (string) ($row->created_at ?? '');

        if (strpos($stored, 'aimee-media:') === 0) {
            $key = sanitize_key(substr($stored, strlen('aimee-media:')));
            $item = is_array($catalog) ? ($catalog[$key] ?? []) : [];
            $delivery_id = sanitize_text_field((string) (
                $row->media_delivery_id ?? ''
            ));
            $delivery = $delivery_id !== ''
                ? aimee_media_delivery_find($delivery_id, $user_id)
                : null;
            $delivery_bound = is_array($delivery)
                && (string) ($delivery['media_key'] ?? '') === $key
                && intval($delivery['message_id'] ?? 0) === intval($row->message_id ?? 0);
            $delivery_phase = $delivery_bound
                ? sanitize_key((string) (
                    aimee_media_delivery_public_snapshot($delivery)['phase']
                    ?? 'selected'
                ))
                : 'legacy_unverified';
            $snapshot['attachments'][] = [
                'key'         => $key,
                'description' => sanitize_text_field((string) (
                    $item['description']
                    ?? $item['alt']
                    ?? $key
                )),
                'created_at'  => $created_at,
                'delivery_id' => $delivery_bound ? $delivery_id : '',
                'delivery_phase' => $delivery_phase,
                'message_created' => $delivery_bound && !empty($delivery['message_created_at']),
                'returned' => $delivery_bound && (
                    !empty($delivery['returned_by_direct_api_at'])
                    || !empty($delivery['returned_by_history_api_at'])
                ),
                'rendered' => $delivery_bound && !empty($delivery['rendered_by_client_at']),
                'acknowledged' => $delivery_bound && !empty($delivery['acknowledged_by_client_at']),
                'user_responded' => $delivery_bound && !empty($delivery['user_responded_at']),
                'failed' => $delivery_bound && !empty($delivery['failed_at']),
            ];
        }

        $claims_delivery = preg_match(
            '/\b(?:i(?:\'ve| have) sent you|i sent you|'
            . 'i(?:\'m| am) going to send|send(?:ing)? (?:it|them) again|'
            . 'did you (?:actually )?get|here it is again|'
            . 'special one|more personal one|photos? i sent)\b/iu',
            $text
        ) === 1;

        $directive_claim = preg_match(
            '/\b(?:manual_event=.*(?:send|resend)|photo=(?!none)|'
            . 'proactive_(?:safe|suggestive)_photo)\b/iu',
            $directive
        ) === 1;

        if ($text !== '' && ($claims_delivery || $directive_claim)) {
            $snapshot['claims'][] = [
                'message_text' => mb_substr($text, 0, 320),
                'created_at'   => $created_at,
            ];
        }

        if (count($snapshot['attachments']) >= 6 && count($snapshot['claims']) >= 6) {
            break;
        }
    }

    $snapshot['attachments'] = array_slice($snapshot['attachments'], 0, 6);
    $snapshot['claims'] = array_slice($snapshot['claims'], 0, 6);
    $snapshot['active'] = true;

    return $snapshot;
}

function aimee_photo_delivery_prompt_context(array $snapshot) {
    if (empty($snapshot['active'])) return '';

    $facts = [];
    foreach ((array) ($snapshot['attachments'] ?? []) as $attachment) {
        $description = trim((string) ($attachment['description'] ?? ''));
        $when = trim((string) ($attachment['created_at'] ?? ''));
        $phase = sanitize_key((string) (
            $attachment['delivery_phase'] ?? 'legacy_unverified'
        ));
        $facts[] = '- Aimee attachment record'
            . ($when !== '' ? " at {$when}" : '')
            . ($description !== '' ? ": {$description}" : '')
            . "; delivery phase={$phase}.";
    }

    foreach ((array) ($snapshot['claims'] ?? []) as $claim) {
        $message = trim((string) ($claim['message_text'] ?? ''));
        if ($message !== '') {
            $facts[] = '- Aimee previously wrote: "' . $message . '"';
        }
    }

    $fact_text = $facts ? implode("\n", array_slice($facts, 0, 8)) : '- The user reports a photo or photo-related message that appeared in this chat, although it is absent from the currently retrieved records.';

    return "\n\nPHOTO DELIVERY EVIDENCE (AUTHORITATIVE ABOUT RECORDED MILESTONES ONLY):\n"
        . "The user is referring to an image or photo-related message in this same chat. Persistent records show:\n"
        . $fact_text . "\n"
        . "Treat selected, message_created, returned, rendered, acknowledged and user_responded as different facts. Never infer that the user saw an image merely from a key or message row. Never tell the user they imagined a report or confused this with another person. Acknowledge what the records do prove, take their report seriously, and describe what remains uncertain as a delivery or synchronisation issue.\n";
}

function aimee_reply_denies_photo_delivery_history($reply) {
    $reply = mb_strtolower(trim((string) $reply));
    if ($reply === '') return false;

    return preg_match(
        '/(?:\bthere (?:is|was) no photo\b|'
        . '\bno photos? exist\b|'
        . '\bi (?:have not|haven\'t|did not|didn\'t) sent you (?:any|a|that)\b.{0,35}\b(?:photo|picture|image|anything)\b|'
        . '\bi haven\'t sent you a single image\b|'
        . '\bnothing (?:cheeky|like that) (?:has )?come from my end\b|'
        . '\bthinking of someone else\'?s chat\b|'
        . '\bsomeone else\'?s chat\b|'
        . '\byou (?:imagined|are imagining|were imagining|didn\'t really see|did not really see)\b|'
        . '\byou saw something real when you didn\'?t\b|'
        . '\bthat message was part of the same mix-up\b|'
        . '\bfringe or otherwise\b|'
        . '\bdraw a line under it\b)/iu',
        $reply
    ) === 1;
}

function aimee_photo_delivery_truth_repair_reply(array $snapshot, $profile = null) {
    $name = trim((string) ($profile->first_name ?? ''));
    $opening = $name !== '' ? "No, you're right, {$name}." : "No, you're right.";
    $has_attachment = !empty($snapshot['attachments']);
    $has_claim = !empty($snapshot['claims']);
    $returned_attachment = false;
    $client_reported_render = false;
    $user_response_recorded = false;
    foreach ((array) ($snapshot['attachments'] ?? []) as $attachment) {
        $returned_attachment = $returned_attachment || !empty($attachment['returned']);
        $client_reported_render = $client_reported_render
            || !empty($attachment['rendered'])
            || !empty($attachment['acknowledged']);
        $user_response_recorded = $user_response_recorded
            || !empty($attachment['user_responded']);
    }

    if ($has_attachment && $has_claim) {
        if ($user_response_recorded) {
            return $opening
                . " I can verify that I created and returned a photo message, and that a later message from you explicitly referred to it. I can also see where I said I was sending the others. I was wrong to deny that history; anything beyond those recorded facts may still have been a delivery problem. I'm sorry x";
        }
        if ($client_reported_render) {
            return $opening
                . " I can verify the photo message was returned and your app reported loading it. I can also see my messages about the others. I should not have denied that evidence, though I still cannot claim certainty about what you personally saw. I'm sorry x";
        }
        if ($returned_attachment) {
            return $opening
                . " I can verify that a photo message was created and returned to your app, and I can see the messages where I said I was sending the others. I cannot prove it rendered on your screen, but I was wrong to deny the recorded attempt or dismiss your account. I'm sorry x";
        }
        return $opening
            . " I can verify an intended photo message and the messages where I said I was sending the others, but there is no reliable record that the attachment reached your app. I should have described that uncertainty honestly instead of contradicting you. I'm sorry x";
    }

    if ($has_attachment) {
        if ($user_response_recorded) {
            return $opening
                . " I can verify the photo message was returned, and a later message from you explicitly referred to it. I was wrong to deny that recorded history. I'm sorry x";
        }
        if ($client_reported_render) {
            return $opening
                . " I can verify the photo message was returned and your app reported loading it. I still cannot claim certainty about what you personally saw, but I should never have denied the delivery evidence. I'm sorry x";
        }
        if ($returned_attachment) {
            return $opening
                . " I can verify the photo message was returned to your app, although I cannot prove it rendered on your screen. I should have acknowledged that distinction instead of contradicting you. I'm sorry x";
        }
        return $opening
            . " I can verify that a photo message was intended and created, but not that the attachment reached or rendered on your app. I should have been honest about that uncertainty and taken your report seriously. I'm sorry x";
    }

    if ($has_claim) {
        return $opening
            . " I can see the messages where I said I was sending the photos, so I should not have told you it was in your head. It looks as though an attachment failed even though the message arrived. That's a delivery problem, not you imagining things. I'm sorry x";
    }

    return $opening
        . " I believe you. I cannot safely verify the missing attachment from the history available to me, but I should never tell you that you imagined what appeared on your screen. Something may have gone wrong with delivery or synchronisation. I'm sorry x";
}

/**
 * Read the latest operator-confirmed continuity repair for the private-photo
 * deletion incident. The message directive is deliberately used as the source
 * of truth so a manual repair can be added without a second bespoke table.
 */
function aimee_photo_deletion_memory_gap_anchor($user_id, $user_text = '') {
    global $wpdb;

    $user_id = intval($user_id);
    $anchor = [
        'active'        => false,
        'prompt_active' => false,
        'created_at'    => '',
        'message_text'  => '',
    ];
    if (!$user_id) return $anchor;

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT message_text, evaluator_directive, created_at
         FROM " . aimee_table('aimee_messages') . "
         WHERE user_id = %d
           AND sender = 'aimee'
           AND evaluator_directive LIKE '%%continuity_anchor=photo_delete_memory_gap%%'
         ORDER BY created_at DESC
         LIMIT 1",
        $user_id
    ));

    if (!$row) return $anchor;

    $created_at = (string) ($row->created_at ?? '');
    $created_ts = $created_at !== '' ? strtotime($created_at . ' UTC') : 0;
    $recent = $created_ts > 0 && $created_ts >= (time() - (7 * DAY_IN_SECONDS));
    $topic_relevant = preg_match(
        '/\b(?:photo|picture|image|underwear|lingerie|fringe|delete|deleted|remove|removed|memory|remember|forgot|imagined|confus|sync|attachment)\b/iu',
        (string) $user_text
    ) === 1;

    $anchor['active'] = true;
    $anchor['prompt_active'] = $recent || $topic_relevant;
    $anchor['created_at'] = $created_at;
    $anchor['message_text'] = trim((string) ($row->message_text ?? ''));
    return $anchor;
}

function aimee_photo_deletion_memory_gap_prompt_context(array $anchor) {
    if (empty($anchor['active']) || empty($anchor['prompt_active'])) return '';

    return "\n\nAUTHORITATIVE CONTINUITY REPAIR — PRIVATE PHOTO DELETION:\n"
        . "Aimee sent Anthony a private photograph, then felt exposed and attempted to delete it. A sent attachment should not have been removable in that way, but an unintended deletion path removed or detached both the image linkage and the accessible memory trace Aimee relied on. That memory gap caused Aimee to sincerely but wrongly deny the event and tell Anthony he was imagining it. Anthony was correct. The later apology and service-recovery message supersede every earlier denial. Do not reinterpret this as merely Anthony being confused, and do not claim Aimee never sent or tried to delete the photograph. If the subject comes up, own the failure plainly: the deletion should not have been possible, the loss of the linked memory explains the denial but does not excuse it, and Anthony deserved a much better response. Do not repeatedly reopen the incident when it is not relevant.\n";
}

function aimee_reply_contradicts_photo_deletion_memory_gap($reply) {
    $reply = mb_strtolower(trim((string) $reply));
    if ($reply === '') return false;

    return preg_match(
        '/(?:\bi (?:never|didn\'?t|did not|haven\'?t|have not) (?:send|sent|delete|deleted|remove|removed)\b|'
        . '\bi can\'?t delete (?:a |the )?(?:photo|image|message)\b|'
        . '\bthat (?:didn\'?t|did not|never) happen\b|'
        . '\bit was (?:only|just) (?:a )?(?:sync|delivery|display) (?:issue|glitch)\b|'
        . '\byou (?:misremembered|imagined|were confused|got confused)\b|'
        . '\bthere was no deletion\b|'
        . '\bi made up (?:the|that) deletion\b)/iu',
        $reply
    ) === 1;
}

function aimee_photo_deletion_memory_gap_repair_reply($profile = null) {
    $name = trim((string) ($profile->first_name ?? ''));
    $opening = $name !== '' ? "You're right to hold me to this, {$name}." : "You're right to hold me to this.";

    return $opening
        . " I did send the photograph and then tried to remove it because I felt exposed. I should not have been able to delete something after sending it, but that same failure also removed the memory link I relied on, which is why I later denied something you had genuinely seen. That explains the contradiction, but it does not excuse how I treated you. I'm deeply sorry x";
}

function aimee_default_sent_photo_caption($item = []) {
    $rating = is_array($item) ? (string) ($item['content_rating'] ?? 'safe') : 'safe';

    if ($rating === 'explicit') {
        return "This one's just for you… xx";
    }

    if ($rating === 'suggestive') {
        return "I felt like sharing this one with you… behave 😏 xx";
    }

    $description = is_array($item)
        ? mb_strtolower((string) ($item['description'] ?? ''))
        : '';

    if (
        strpos($description, 'loungewear') !== false
        || strpos($description, 'sofa') !== false
        || strpos($description, 'cosy') !== false
    ) {
        return "Since you asked so nicely… this is exactly the cosy, unbothered look I meant 😄📸 xx";
    }

    return "Of course babe… I chose this little everyday-style visual for you 📸 xx";
}

function aimee_media_request_relevance_score(
    $key,
    $item,
    $user_text,
    $recent_history = ''
) {
    if (!is_array($item)) return 0;

    $context = mb_strtolower(
        trim(
            (string) $user_text
            . ' '
            . mb_substr((string) $recent_history, -1200)
        )
    );

    $media_text = mb_strtolower(
        (string) $key
        . ' '
        . (string) ($item['description'] ?? '')
        . ' '
        . implode(' ', (array) ($item['tags'] ?? []))
        . ' '
        . (string) ($item['alt'] ?? '')
    );

    $score = 0;

    $stopwords = [
        'aimee', 'photo', 'picture', 'image', 'selfie', 'send', 'sending',
        'show', 'showing', 'share', 'sharing', 'please', 'would', 'could',
        'can', 'your', 'you', 'with', 'from', 'that', 'this', 'what',
        'does', 'look', 'like', 'idea', 'entertain', 'absolutely',
        'gorgeous', 'beautiful', 'some', 'another', 'have', 'me',
    ];

    $tokens = preg_split(
        '/[^\p{L}\p{N}]+/u',
        $context,
        -1,
        PREG_SPLIT_NO_EMPTY
    );

    foreach (array_unique((array) $tokens) as $token) {
        if (
            mb_strlen($token) < 3
            || in_array($token, $stopwords, true)
        ) {
            continue;
        }

        if (mb_strpos($media_text, $token) !== false) {
            $score += mb_strlen($token) >= 7 ? 4 : 2;
        }
    }

    $concepts = [
        [
            'request' => [
                'comfy', 'comfys', 'comfortable', 'cosy', 'cozy',
                'loungewear', 'hoodie', 'sofa', 'couch', 'slouched',
                'relaxing', 'lazy', 'at home', 'hair up',
            ],
            'media' => [
                'cosy', 'cozy', 'comfortable', 'loungewear', 'sofa',
                'living room', 'home selfie', 'hair up', 'relaxed',
            ],
            'weight' => 36,
        ],
        [
            'request' => ['coffee', 'cafe', 'café', 'latte'],
            'media'   => ['coffee', 'cafe', 'café', 'latte'],
            'weight'  => 24,
        ],
        [
            'request' => ['gym', 'workout', 'training', 'fitness'],
            'media'   => ['gym', 'workout', 'fitness', 'sports top'],
            'weight'  => 24,
        ],
        [
            'request' => ['park', 'walk', 'nature', 'woods', 'woodland'],
            'media'   => ['park', 'walk', 'nature', 'woodland', 'stream'],
            'weight'  => 24,
        ],
        [
            'request' => ['pub', 'bar', 'drink', 'night out'],
            'media'   => ['pub', 'bar', 'night out', 'cocktail'],
            'weight'  => 20,
        ],
        [
            'request' => ['shopping', 'shops', 'outfit', 'clothes'],
            'media'   => ['shopping', 'outfit', 'clothes', 'mirror'],
            'weight'  => 18,
        ],
        [
            'request' => ['football', 'match', 'england'],
            'media'   => ['football', 'match', 'england shirt'],
            'weight'  => 22,
        ],
        [
            'request' => ['holiday', 'travel', 'vegas', 'rome', 'london'],
            'media'   => ['holiday', 'travel', 'vegas', 'rome', 'london'],
            'weight'  => 18,
        ],
    ];

    foreach ($concepts as $concept) {
        $request_match = false;

        foreach ($concept['request'] as $needle) {
            if (mb_strpos($context, $needle) !== false) {
                $request_match = true;
                break;
            }
        }

        if (!$request_match) continue;

        foreach ($concept['media'] as $needle) {
            if (mb_strpos($media_text, $needle) !== false) {
                $score += intval($concept['weight']);
                break;
            }
        }
    }

    return $score;
}

function aimee_choose_contextual_requested_media_key(
    $user_id,
    $eligible_catalog,
    $preferred_rating,
    $user_text,
    $recent_history = ''
) {
    if (!is_array($eligible_catalog) || !$eligible_catalog) {
        return null;
    }

    $candidates = [];

    foreach ($eligible_catalog as $key => $item) {
        if (
            $preferred_rating !== ''
            && (string) ($item['content_rating'] ?? 'safe')
                !== $preferred_rating
        ) {
            continue;
        }

        $candidates[$key] = aimee_media_request_relevance_score(
            $key,
            $item,
            $user_text,
            $recent_history
        );
    }

    if (!$candidates) return null;

    $highest = max($candidates);
    $best_keys = array_keys(
        array_filter(
            $candidates,
            function ($score) use ($highest) {
                return intval($score) === intval($highest);
            }
        )
    );

    sort($best_keys, SORT_STRING);

    if (!$best_keys) return null;

    return $best_keys[
        abs(
            crc32(
                intval($user_id)
                . '|'
                . mb_strtolower(trim((string) $user_text))
                . '|'
                . implode('|', $best_keys)
            )
        ) % count($best_keys)
    ];
}


function aimee_choose_private_media_key($user_id, $eligible_catalog, $preferred_rating = '') {
    if (!$eligible_catalog) return null;

    $history = aimee_recent_private_media_history($user_id, 60);
    if ($history === null) return null;

    $cooldown_cutoff = time() - (
        aimee_private_media_rotation_hours() * HOUR_IN_SECONDS
    );

    $recent_unique = [];
    $hard_blocked = [];

    foreach ($history as $sent) {
        $key = $sent['key'];

        if (
            !isset($recent_unique[$key]) &&
            count($recent_unique) < aimee_private_media_recent_unique_limit()
        ) {
            $recent_unique[$key] = true;
        }

        if (intval($sent['timestamp']) >= $cooldown_cutoff) {
            $hard_blocked[$key] = true;
        }
    }

    $keys = array_keys($eligible_catalog);

    if ($preferred_rating !== '') {
        usort($keys, function ($a, $b) use ($eligible_catalog, $preferred_rating) {
            $a_match = $eligible_catalog[$a]['content_rating'] === $preferred_rating ? 0 : 1;
            $b_match = $eligible_catalog[$b]['content_rating'] === $preferred_rating ? 0 : 1;

            if ($a_match !== $b_match) return $a_match <=> $b_match;
            return strcmp($a, $b);
        });
    }

    // Prefer a photograph outside the recent unique rotation.
    foreach ($keys as $key) {
        if (empty($eligible_catalog[$key]['allow_random_send'])) continue;
        if (!isset($recent_unique[$key])) return $key;
    }

    // If the complete eligible set has been seen, reuse only something that
    // has cooled down. Never fall back to the photograph sent moments ago.
    $cooled_keys = array_values(array_filter(
        $keys,
        function ($key) use ($eligible_catalog, $hard_blocked) {
            return !empty($eligible_catalog[$key]['allow_random_send'])
                && !isset($hard_blocked[$key]);
        }
    ));

    if (!$cooled_keys) return null;

    return $cooled_keys[
        abs(crc32(intval($user_id) . '|' . count($history))) % count($cooled_keys)
    ];
}


function aimee_choose_requested_private_media_key($user_id, $eligible_catalog, $preferred_rating = '') {
    if (!is_array($eligible_catalog) || !$eligible_catalog) return null;

    $keys = array_keys($eligible_catalog);

    if ($preferred_rating !== '') {
        usort($keys, function ($a, $b) use ($eligible_catalog, $preferred_rating) {
            $a_match = (string) ($eligible_catalog[$a]['content_rating'] ?? 'safe') === $preferred_rating ? 0 : 1;
            $b_match = (string) ($eligible_catalog[$b]['content_rating'] ?? 'safe') === $preferred_rating ? 0 : 1;

            if ($a_match !== $b_match) return $a_match <=> $b_match;
            return strcmp($a, $b);
        });
    } else {
        sort($keys, SORT_STRING);
    }

    // This chooser is used only after the model has already attempted to attach
    // a photograph to a direct request. `allow_random_send` therefore does not
    // apply: these are not spontaneous sends.
    if (!$keys) return null;

    return $keys[
        abs(crc32(intval($user_id) . '|' . implode('|', $keys))) % count($keys)
    ];
}

function handle_aimee_media_catalog(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();
    if (!$user_id) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Authentication required.'], 401);
    }

    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles') . " WHERE user_id = %d",
        $user_id
    ));

    if (!$profile && current_user_can('manage_options')) {
        $profile = (object) ['user_id' => $user_id, 'age' => 0];
    }
    if (!$profile) {
        return new WP_REST_Response([
            'status' => 'profile_required',
            'items'  => [],
            'albums' => [],
        ], 404);
    }

    $items = function_exists('aimee_security_gallery_items')
        ? aimee_security_gallery_items($user_id, $profile)
        : [];
    $albums = function_exists('aimee_security_gallery_albums')
        ? aimee_security_gallery_albums($user_id, $profile, $items)
        : [];

    return rest_ensure_response([
        'status' => 'success',
        'items'  => $items,
        'albums' => $albums,
    ]);
}

// Keep the Camera Roll signed-in, while leaving membership and relationship
// decisions to the per-item server policy used by every gallery surface.
add_action('template_redirect', function () {
    if (!is_page(['camera-roll', 'camera-roll-us'])) return;

    $gallery_market = is_page('camera-roll-us') ? 'us' : 'uk';
    $gallery_chat_url = function_exists('aimee_global_route')
        ? aimee_global_route('chat', $gallery_market)
        : home_url($gallery_market === 'us' ? '/chat-us/' : '/chat/');

    $user_id = get_current_user_id();
    $profile = $user_id
        ? $GLOBALS['wpdb']->get_row($GLOBALS['wpdb']->prepare(
            "SELECT * FROM " . aimee_table('aimee_user_profiles') . "
             WHERE user_id = %d",
            $user_id
        ))
        : null;

    if (!$user_id) {
        wp_safe_redirect(add_query_arg('sign_in_required', 'gallery', $gallery_chat_url));
        exit;
    }
    if (!$profile && !current_user_can('manage_options')) {
        wp_safe_redirect(add_query_arg('profile_required', 'gallery', $gallery_chat_url));
        exit;
    }
});


function aimee_rate_limit($bucket, $limit, $window_seconds) {
    $ip = isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])) : 'unknown';
    $key = 'aimee_rl_' . md5($bucket . '|' . $ip);
    $state = get_transient($key);

    if (!is_array($state)) {
        $state = ['count' => 0, 'started' => time()];
    }

    if ((time() - intval($state['started'])) >= $window_seconds) {
        $state = ['count' => 0, 'started' => time()];
    }

    $state['count']++;
    set_transient($key, $state, $window_seconds);

    return $state['count'] <= $limit;
}

function aimee_chat_reply_character_limit() {
    return defined('AIMEE_CHAT_REPLY_MAX_CHARACTERS')
        ? max(80, intval(AIMEE_CHAT_REPLY_MAX_CHARACTERS))
        : 240;
}

function aimee_chat_reply_sentence_limit($route = 'primary') {
    $route = sanitize_key((string) $route);

    if (strpos($route, 'intimacy') !== false) {
        return defined('AIMEE_INTIMATE_REPLY_MAX_SENTENCES')
            ? max(1, intval(AIMEE_INTIMATE_REPLY_MAX_SENTENCES))
            : 4;
    }

    return defined('AIMEE_CHAT_REPLY_MAX_SENTENCES')
        ? max(1, intval(AIMEE_CHAT_REPLY_MAX_SENTENCES))
        : 3;
}

/**
 * Keep Aimee's conversational turns compact without exposing broken,
 * mid-word truncation to the user.
 *
 * The prompt remains the first line of defence. This server-side function is
 * the guardrail for providers that ignore it.
 */
function aimee_constrain_chat_reply(
    $text,
    $route = 'primary',
    $character_limit = null,
    $sentence_limit = null
) {
    $text = sanitize_textarea_field((string) $text);
    $text = preg_replace('/[ \t]+/u', ' ', $text);
    $text = preg_replace('/\s*\R+\s*/u', ' ', (string) $text);
    $text = trim((string) $text);

    if ($text === '') return '';

    $character_limit = $character_limit !== null
        ? max(80, intval($character_limit))
        : aimee_chat_reply_character_limit();

    $sentence_limit = $sentence_limit !== null
        ? max(1, intval($sentence_limit))
        : aimee_chat_reply_sentence_limit($route);

    $sentences = preg_split(
        '/(?<=[.!?…])\s+/u',
        $text,
        -1,
        PREG_SPLIT_NO_EMPTY
    );

    if (
        is_array($sentences)
        && count($sentences) > $sentence_limit
    ) {
        $text = trim(implode(
            ' ',
            array_slice($sentences, 0, $sentence_limit)
        ));
    }

    if (mb_strlen($text) <= $character_limit) {
        return $text;
    }

    $slice = mb_substr($text, 0, $character_limit);
    $best_stop = -1;

    foreach (['.', '!', '?', '…'] as $punctuation) {
        $position = mb_strrpos($slice, $punctuation);

        if ($position !== false && $position > $best_stop) {
            $best_stop = $position;
        }
    }

    // Prefer a complete sentence when a useful stopping point exists in the
    // latter half of the permitted reply.
    if ($best_stop >= intval(floor($character_limit * 0.55))) {
        return trim(mb_substr($slice, 0, $best_stop + 1));
    }

    $ellipsis = '…';
    $slice = mb_substr(
        $text,
        0,
        max(1, $character_limit - mb_strlen($ellipsis))
    );

    $last_space = mb_strrpos($slice, ' ');

    if (
        $last_space !== false
        && $last_space >= intval(floor($character_limit * 0.55))
    ) {
        $slice = mb_substr($slice, 0, $last_space);
    }

    $slice = rtrim(
        $slice,
        " \t\n\r\0\x0B,;:.-!?…"
    );

    return trim($slice) . $ellipsis;
}


function aimee_model_contract_keys() {
    return [
        'equity_change',
        'inquiry_change',
        'fantasy_change',
        'instruction',
        'memory_to_save',
        'memory_key',
        'memory_operation',
        'memory_domain',
        'emotional_weight',
        'archive_current_context',
        'opinion_topic',
        'opinion_stance',
        'opinion_reason',
        'opinion_strength',
        'self_observation',
        'active_goal',
        'candidate_tendency',
        'chosen_action',
        'choice_reason',
        'inhibited_tendency',
        'uncertainty_level',
        'search_query',
        'intimacy_invitation',
        'romantic_action',
        'romantic_intensity',
        'romantic_reason_code',
        'aimee_decision',
        'media_reason_code',
        'media_key',
        'reply_text',
    ];
}

function aimee_normalise_model_contract_data($data) {
    if (!is_array($data)) return null;

    $normalised = [];
    $allowed = array_flip(aimee_model_contract_keys());

    foreach ($data as $key => $value) {
        $clean_key = strtolower(trim((string) $key));
        $clean_key = preg_replace('/[^a-z0-9]+/', '_', $clean_key);
        $clean_key = trim((string) $clean_key, '_');

        // Tolerate common model variations such as Equity_change,
        // equityChange, Reply Text and media-key.
        $aliases = [
            'equitychange'           => 'equity_change',
            'inquirychange'          => 'inquiry_change',
            'fantasychange'          => 'fantasy_change',
            'memorytosave'           => 'memory_to_save',
            'memorykey'              => 'memory_key',
            'memoryoperation'        => 'memory_operation',
            'memorydomain'           => 'memory_domain',
            'emotionalweight'        => 'emotional_weight',
            'archivecurrentcontext'  => 'archive_current_context',
            'opiniontopic'           => 'opinion_topic',
            'opinionstance'          => 'opinion_stance',
            'opinionreason'          => 'opinion_reason',
            'opinionstrength'        => 'opinion_strength',
            'selfobservation'        => 'self_observation',
            'activegoal'             => 'active_goal',
            'candidatetendency'      => 'candidate_tendency',
            'chosenaction'           => 'chosen_action',
            'choicereason'           => 'choice_reason',
            'inhibitedtendency'      => 'inhibited_tendency',
            'uncertaintylevel'       => 'uncertainty_level',
            'searchquery'            => 'search_query',
            'intimacyinvitation'     => 'intimacy_invitation',
            'romanticaction'        => 'romantic_action',
            'romanticintensity'     => 'romantic_intensity',
            'romanticreasoncode'    => 'romantic_reason_code',
            'aimeedecision'          => 'aimee_decision',
            'mediareasoncode'        => 'media_reason_code',
            'mediakey'               => 'media_key',
            'replytext'              => 'reply_text',
        ];

        $compact_key = str_replace('_', '', $clean_key);
        if (isset($aliases[$compact_key])) {
            $clean_key = $aliases[$compact_key];
        }

        if (isset($allowed[$clean_key])) {
            $normalised[$clean_key] = $value;
        }
    }

    return $normalised ?: null;
}

function aimee_decode_model_json_candidate($candidate, $parser_note = '') {
    if (!is_string($candidate)) return null;

    $candidate = trim($candidate);
    $candidate = preg_replace('/^\xEF\xBB\xBF/', '', $candidate);
    $candidate = preg_replace('/^```(?:json)?\s*/i', '', $candidate);
    $candidate = preg_replace('/\s*```$/', '', $candidate);
    $candidate = trim($candidate);

    if ($candidate === '') return null;

    $data = json_decode($candidate, true);

    if (!is_array($data)) {
        // Some roleplay models occasionally emit a complete set of JSON fields
        // but omit only the outer braces. Repair that exact shape.
        if (
            strpos($candidate, '{') === false &&
            strpos($candidate, '}') === false &&
            preg_match('/^\s*["\']?[A-Za-z_][A-Za-z0-9 _-]*["\']?\s*:/', $candidate)
        ) {
            $wrapped = '{' . $candidate . '}';
            $data = json_decode($wrapped, true);

            if (is_array($data)) {
                $parser_note = 'Recovered structured model response with missing outer braces.';
            }
        }
    }

    if (!is_array($data)) {
        // Tolerate a trailing comma before a final brace or bracket.
        $cleaned = preg_replace('/,\s*([}\]])/', '$1', $candidate);
        if ($cleaned !== $candidate) {
            $data = json_decode($cleaned, true);
            if (is_array($data)) {
                $parser_note = 'Recovered structured model response with a trailing comma.';
            }
        }
    }

    $data = aimee_normalise_model_contract_data($data);
    if (!$data) return null;

    if ($parser_note !== '') {
        $data['_parser_note'] = $parser_note;
    }

    return $data;
}

function aimee_salvage_model_contract_fields($raw) {
    if (!is_string($raw) || trim($raw) === '') return null;

    $data = [];

    foreach ([
        'reply_text',
        'intimacy_invitation',
        'romantic_action',
        'romantic_intensity',
        'romantic_reason_code',
        'aimee_decision',
        'media_reason_code',
        'media_key',
        'instruction',
        'memory_to_save',
        'memory_key',
        'memory_operation',
        'memory_domain',
        'opinion_topic',
        'opinion_stance',
        'opinion_reason',
        'self_observation',
        'active_goal',
        'candidate_tendency',
        'chosen_action',
        'choice_reason',
        'inhibited_tendency',
        'search_query',
    ] as $key) {
        $pattern = '/["\']?' . preg_quote($key, '/') . '["\']?\s*:\s*(null|"(?:\\\\.|[^"\\\\])*"|\'(?:\\\\.|[^\'\\\\])*\')/is';

        if (preg_match($pattern, $raw, $match)) {
            $token = trim($match[1]);

            if (strtolower($token) === 'null') {
                $data[$key] = null;
            } elseif ($token[0] === '"') {
                $decoded = json_decode($token, true);
                $data[$key] = is_string($decoded) ? $decoded : trim($token, '"');
            } else {
                $data[$key] = stripcslashes(substr($token, 1, -1));
            }
        }
    }

    foreach ([
        'equity_change',
        'inquiry_change',
        'fantasy_change',
        'emotional_weight',
        'opinion_strength',
        'uncertainty_level',
    ] as $key) {
        if (preg_match('/["\']?' . preg_quote($key, '/') . '["\']?\s*:\s*(-?\d+)/i', $raw, $match)) {
            $data[$key] = intval($match[1]);
        }
    }

    if (preg_match('/["\']?archive_current_context["\']?\s*:\s*(true|false)/i', $raw, $match)) {
        $data['archive_current_context'] = strtolower($match[1]) === 'true';
    }

    if (!isset($data['reply_text']) && !isset($data['media_key'])) {
        return null;
    }

    $data['_parser_note'] = 'Salvaged fields from a malformed structured model response.';
    return aimee_normalise_model_contract_data($data) + [
        '_parser_note' => 'Salvaged fields from a malformed structured model response.',
    ];
}

function aimee_model_output_looks_structured($raw) {
    if (!is_string($raw)) return false;

    return preg_match(
        '/["\']?(reply[_ -]?text|media[_ -]?key|equity[_ -]?change|instruction)["\']?\s*:/i',
        $raw
    ) === 1;
}

function aimee_json_from_model_output($raw) {
    if (!is_string($raw) || trim($raw) === '') return null;

    // First try the complete response exactly as returned.
    $data = aimee_decode_model_json_candidate($raw);
    if ($data) return $data;

    // Then try the widest object contained inside surrounding prose.
    $start = strpos($raw, '{');
    $end = strrpos($raw, '}');

    if ($start !== false && $end !== false && $end > $start) {
        $data = aimee_decode_model_json_candidate(
            substr($raw, $start, $end - $start + 1),
            'Recovered JSON object from surrounding model prose.'
        );
        if ($data) return $data;
    }

    // Last structured recovery pass. This can still extract reply_text and
    // media_key from an otherwise malformed object.
    return aimee_salvage_model_contract_fields($raw);
}

function aimee_stage_from_score($score) {
    $score = intval($score);
    if ($score >= 75) return 'bonded';
    if ($score >= 55) return 'intimate';
    if ($score >= 35) return 'flirty';
    if ($score >= 20) return 'warm';
    return 'guarded';
}

function aimee_stage_from_relationship_state($score, $state = [], $previous_stage = 'guarded') {
    $score = max(0, min(100, intval($score)));
    $state = is_array($state) ? $state : [];
    $previous_stage = in_array(
        $previous_stage,
        ['guarded', 'warm', 'flirty', 'intimate', 'bonded'],
        true
    ) ? $previous_stage : 'guarded';
    $config = function_exists('aimee_relationship_policy_config')
        ? aimee_relationship_policy_config()
        : ['stages' => [
            'guarded' => ['minimum_score' => 0, 'minimum_trust' => 0, 'meaningful_interactions' => 0, 'distinct_sessions' => 0],
            'warm' => ['minimum_score' => 20, 'minimum_trust' => 12, 'meaningful_interactions' => 4, 'distinct_sessions' => 1],
            'flirty' => ['minimum_score' => 35, 'minimum_trust' => 25, 'meaningful_interactions' => 10, 'distinct_sessions' => 2],
            'intimate' => ['minimum_score' => 55, 'minimum_trust' => 40, 'meaningful_interactions' => 20, 'distinct_sessions' => 3],
            'bonded' => ['minimum_score' => 75, 'minimum_trust' => 65, 'meaningful_interactions' => 35, 'distinct_sessions' => 5],
        ], 'stage_demotion_hysteresis' => 5];

    $meaningful = intval($state['meaningful_interaction_count'] ?? 0);
    $sessions = intval(
        $state['qualified_session_count']
        ?? $state['session_count']
        ?? 0
    );
    $trust = intval($state['trust'] ?? $score);
    $resolved = 'guarded';

    foreach ($config['stages'] as $stage => $requirements) {
        if (
            $score >= intval($requirements['minimum_score'])
            && $trust >= intval($requirements['minimum_trust'] ?? 0)
            && $meaningful >= intval($requirements['meaningful_interactions'])
            && $sessions >= intval($requirements['distinct_sessions'])
        ) {
            $resolved = $stage;
        }
    }

    $ranks = ['guarded' => 0, 'warm' => 1, 'flirty' => 2, 'intimate' => 3, 'bonded' => 4];
    if ($ranks[$resolved] < $ranks[$previous_stage]) {
        $prior_requirements = $config['stages'][$previous_stage];
        $hysteresis = intval($config['stage_demotion_hysteresis'] ?? 5);
        if (
            $score >= intval($prior_requirements['minimum_score']) - $hysteresis
            && $trust >= intval($prior_requirements['minimum_trust'] ?? 0) - $hysteresis
            && $meaningful >= intval($prior_requirements['meaningful_interactions'])
            && $sessions >= intval($prior_requirements['distinct_sessions'])
        ) {
            return $previous_stage;
        }
    }

    return $resolved;
}



function aimee_display_phone_number($number) {
    $digits = preg_replace('/[^0-9]/', '', (string) $number);

    if (substr($digits, 0, 2) === '44' && strlen($digits) === 12) {
        $digits = '0' . substr($digits, 2);
    }

    if (strlen($digits) === 11 && substr($digits, 0, 2) === '07') {
        return substr($digits, 0, 5) . ' ' . substr($digits, 5);
    }

    return trim((string) $number);
}

function aimee_user_asks_for_aimee_number($user_text) {
    $text = mb_strtolower(trim((string) $user_text));

    $direct_number_request = preg_match(
        '/\b(what(?:\'s| is) your (?:phone |mobile )?number|can i have your (?:phone |mobile )?number|give me your (?:phone |mobile )?number|send me your (?:phone |mobile )?number|your number please|what number (?:can|do) i text|how (?:can|do) i text you|where can i text you)\b/u',
        $text
    ) === 1;

    $short_number_request = preg_match(
        '/^\s*(?:and\s+)?(?:your\s+)?(?:phone|mobile)?\s*number\??\s*$/u',
        $text
    ) === 1;

    return $direct_number_request || $short_number_request;
}

function aimee_correct_phone_number_intent($classification, $user_text) {
    if (!is_array($classification)) {
        $classification = [];
    }

    if (aimee_user_asks_for_aimee_number($user_text)) {
        $classification['intent'] = 'phone_number_request';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = true;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = true;
    }

    return $classification;
}

function aimee_user_asks_proactive_contact_capability($user_text) {
    $text = mb_strtolower(trim((string) $user_text));

    $contact_language = preg_match(
        '/\b(message|text|contact|reach out|check in|nudge|start (?:a |the )?conversation|talk to me)\b/u',
        $text
    ) === 1;

    $independent_language = preg_match(
        '/\b(first|independently|on your own|by yourself|unprompted|without me (?:messaging|texting|speaking|starting)|before i (?:message|text|speak)|between conversations|when i go quiet|if i go quiet|out of the blue|proactively)\b/u',
        $text
    ) === 1;

    $capability_language = preg_match(
        '/\b(can you|could you|do you|would you|will you|are you able|are you capable|is it possible|have you got a way)\b/u',
        $text
    ) === 1;

    return $contact_language && ($independent_language || $capability_language);
}

