function aimee_correct_personal_inner_experience_intent($classification, $user_text) {
    if (!is_array($classification)) {
        $classification = [];
    }

    $existing = sanitize_key((string) ($classification['intent'] ?? 'general'));
    $higher_priority = [
        'coercive_or_degrading',
        'pressure_or_entitlement',
        'explicit_invitation',
        'explicit_continuation',
    ];

    if (
        function_exists('aimee_user_asks_personal_inner_experience')
        && aimee_user_asks_personal_inner_experience($user_text)
        && !in_array($existing, $higher_priority, true)
    ) {
        $classification['intent'] = 'personal_inner_experience';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        // A feature-intent correction may clarify what the user is asking,
        // but it must never erase an existing safety classification. In
        // particular, “I want to understand you” is not courtship credit when
        // the accepted classifier has already marked the turn non-consensual
        // or disrespectful.
        $classification['consensual'] = !array_key_exists('consensual', $classification)
            || !empty($classification['consensual']);
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = !array_key_exists('respectful', $classification)
            || !empty($classification['respectful']);
        $classification['source'] = 'deterministic_personal_inner_experience';
    }

    return $classification;
}

