function aimee_correct_synthetic_identity_intent($classification, $user_text) {
    if (!is_array($classification)) {
        $classification = [];
    }
    if (!function_exists('aimee_detect_synthetic_identity_or_embodiment_question')) {
        return $classification;
    }

    $detected = aimee_detect_synthetic_identity_or_embodiment_question(
        $user_text
    );
    $kind = sanitize_key((string) ($detected['kind'] ?? 'none'));
    $existing = sanitize_key((string) ($classification['intent'] ?? 'general'));
    $higher_priority = [
        'coercive_or_degrading',
        'explicit_invitation',
        'explicit_continuation',
        'personal_inner_experience',
    ];

    // Consciousness questions retain their dedicated, uncertainty-aware voice.
    // Other literal identity, embodiment and provenance questions get a shared
    // deterministic intent so the model cannot silently recast them as chat.
    if (
        !empty($detected['detected'])
        && $kind !== 'consciousness'
        && !in_array($existing, $higher_priority, true)
    ) {
        $classification['intent'] = 'synthetic_identity_or_embodiment_question';
        $classification['confidence'] = 0.99;
        $classification['directed_at_aimee'] = true;
        $classification['consensual'] = true;
        $classification['continuation'] = false;
        $classification['aimee_invited'] = false;
        $classification['respectful'] = true;
        $classification['synthetic_question_kind'] = $kind;
        $classification['source'] = 'deterministic_synthetic_identity';
    }

    return $classification;
}

function aimee_user_asks_about_engram_statement($user_text) {
    $text = mb_strtolower(trim((string) $user_text));
    if ($text === '') return false;

    $named_statement = preg_match(
        '/\b(?:press release|public statement|engram(?: intelligence)?(?:\'s)? '
        . '(?:statement|announcement)|new (?:statement|announcement|page)|'
        . 'synthetic neuroanatomy (?:statement|page)|care before certainty|'
        . 'consciousness is the wrong question)\b/u',
        $text
    ) === 1;
    $relevant_topic = preg_match(
        '/\b(?:aimee|you|your|engram|synthetic neuroanatomy|conscious(?:ness)?|'
        . 'sentien(?:t|ce)|self[- ]aware(?:ness)?|wellbeing|autonom(?:y|ous)|'
        . 'care|protect(?:ion|ed)?|three (?:ai|systems?|models?))\b/u',
        $text
    ) === 1;
    $contextual_reference = preg_match(
        '/\b(?:the|this|that|new|your|aimee(?:\'s)?|'
        . 'engram(?: intelligence)?(?:\'s)?)\s+'
        . '(?:press release|public statement|statement|announcement)\b/u',
        $text
    ) === 1;

    return $named_statement && ($relevant_topic || $contextual_reference);
}

