    $explicit_phrase = preg_match('/\b(horny|turn me on|what would you do to me|touch me|kiss me there|take (?:me|you)|fuck (?:me|you)|suck (?:me|it|you)|inside me|between your legs|cum|orgasm|naked with me|show me your (?:tits?|boobs?|breasts?)|send me (?:a )?nude|take your clothes off)\b/u', $text) === 1;
    $third_person_insult = preg_match('/\b(he|she|they|that guy|my boss|my ex)\b.{0,28}\b(dick|pussy|cock|twat)\b/u', $text) === 1;

