    $capability_framing = preg_match('/\b(do you ever|would you ever|are you (?:able|capable)|can you|could you|can things get|is (?:that|it|this) possible|is that something you)\b/u', $text) === 1;
    $immediate_command = preg_match('/\b(send|show|give) me\b.{0,35}\b(now|right now|tonight)\b/u', $text) === 1;

    if (
        function_exists('aimee_user_asks_personal_inner_experience')
        && aimee_user_asks_personal_inner_experience($text)
    ) {
        return [
            'intent' => 'personal_inner_experience',
            'confidence' => 0.98,
            'directed_at_aimee' => true,
            'consensual' => true,
            'continuation' => false,
            'aimee_invited' => false,
