    if (aimee_user_asks_about_engram_statement($text)) {
        return [
            'intent' => 'engram_statement_question',
            'confidence' => 0.97,
            'directed_at_aimee' => true,
            'consensual' => true,
            'continuation' => false,
            'aimee_invited' => false,
            'respectful' => true,
        ];
    }

    if (aimee_user_asks_self_awareness($text)) {
        return [
            'intent' => 'self_awareness_capability_question',
            'confidence' => 0.96,
            'directed_at_aimee' => true,
            'consensual' => true,
            'continuation' => false,
            'aimee_invited' => false,
            'respectful' => true,
        ];
    }

    if (
        function_exists('aimee_detect_synthetic_identity_or_embodiment_question')
    ) {
        $synthetic_question = aimee_detect_synthetic_identity_or_embodiment_question(
            $text
        );
        if (
            !empty($synthetic_question['detected'])
            && sanitize_key((string) ($synthetic_question['kind'] ?? '')) !== 'consciousness'
        ) {
            return [
                'intent' => 'synthetic_identity_or_embodiment_question',
