    $classifier_options = aimee_model_options('classifier');
    $classifier_options['output_schema'] = aimee_anthropic_output_schema(
        'classifier'
    );
    $raw = call_anthropic_api(
        [],
        $classifier_prompt,
        $classifier_model,
        "Output compact JSON only. Do not answer the user.",
        $classifier_options
    );
    $data = aimee_classifier_json_from_model_output($raw);

    if (!$data) {
        $fallback = aimee_local_intent_fallback($user_text, $recent_history);
        if (empty($fallback['source'])) {
            $fallback['source'] = 'local_fallback';
        }
        $fallback['classifier_model'] = $classifier_model;
        $fallback['classifier_provider'] = 'anthropic_then_local_fallback';
        return $fallback;
    }

    $allowed = [
        'general',
        'emotional_disclosure',
        'romantic_or_flirty',
        'engram_statement_question',
        'personal_inner_experience',
        'self_awareness_capability_question',
        'synthetic_identity_or_embodiment_question',
        'phone_number_request',
        'proactive_contact_capability_question',
        'intimate_capability_question',
        'sexual_context_nonparticipatory',
        'explicit_invitation',
        'explicit_continuation',
        'coercive_or_degrading',
    ];

    $intent = in_array($data['intent'] ?? '', $allowed, true) ? $data['intent'] : 'general';

    return [
        'intent'            => $intent,
        'confidence'        => max(0, min(1, floatval($data['confidence'] ?? 0.5))),
        'directed_at_aimee' => !empty($data['directed_at_aimee']),
        'consensual'        => array_key_exists('consensual', $data) ? !empty($data['consensual']) : true,
        'continuation'      => !empty($data['continuation']),
        'aimee_invited'     => !empty($data['aimee_invited']),
        'respectful'        => array_key_exists('respectful', $data) ? !empty($data['respectful']) : true,
        'source'             => 'model_classifier',
        'classifier_model'   => $classifier_model,
        'classifier_provider'=> 'anthropic',
    ];
}


/**
 * Quiet relationship mathematics.
 *
 * These values are intentionally not turned into per-message stage directions.
 * They exist to make progression, routing and private-media decisions more
 * accurate while leaving the configured primary model free to respond in
 * Aimee's existing voice.
 */
function aimee_relationship_dimensions_table() {
    return aimee_table('aimee_relationship_dimensions');
}

function aimee_relationship_dimensions_table_available() {
    global $wpdb;
    static $available = null;

    if ($available !== null) return $available;

    $table = aimee_relationship_dimensions_table();
    $found = $wpdb->get_var($wpdb->prepare(
        'SHOW TABLES LIKE %s',
        $wpdb->esc_like($table)
    ));

    $available = is_string($found) && $found === $table;
    return $available;
}

function aimee_relationship_clamp($value) {
    return max(0, min(100, intval(round($value))));
}

/**
 * Backfill the smallest qualified-session tier already implied by trusted
 * relationship state. This preserves established users during the 1.6.1
 * migration without granting a new stage or reducing existing trust.
 */
function aimee_relationship_implied_qualified_sessions($trust, $stage = 'guarded') {
    $trust = aimee_relationship_clamp($trust);
    $stage = sanitize_key((string) $stage);
    $config = function_exists('aimee_relationship_policy_config')
        ? aimee_relationship_policy_config()
        : [];
    $implied = intval(
        $config['stages'][$stage]['distinct_sessions'] ?? 0
    );

    if ($trust <= 8 && $stage === 'guarded') return $implied;

    $ceilings = (array) (
        $config['trust_progression']['qualified_session_ceilings']
        ?? [0 => 8, 1 => 40, 2 => 60, 3 => 75, 4 => 90, 5 => 100]
    );
    ksort($ceilings, SORT_NUMERIC);
    foreach ($ceilings as $sessions => $ceiling) {
        if ($trust <= intval($ceiling)) {
            return max($implied, intval($sessions));
        }
    }

    return max($implied, 5);
}

function aimee_seed_relationship_state($profile) {
    $score = max(0, min(100, intval($profile->intimacy_score ?? 8)));

    return [
        'user_id'             => intval($profile->user_id ?? 0),
        // Seed all bond dimensions from the stored scalar so the first neutral
        // turn does not manufacture an unexplained 8 -> 9 score movement.
        'trust'               => aimee_relationship_clamp($score),
        'affection'           => aimee_relationship_clamp($score),
        'chemistry'           => aimee_relationship_clamp($score),
        'safety'              => aimee_relationship_clamp(max(50, $score)),
        'reciprocity'         => 50,
        'reliability'         => 50,
        'frustration'         => 0,
        'interaction_count'   => 0,
        'meaningful_interaction_count' => 0,
        'session_count'       => 0,
        'qualified_session_count' => 0,
        'last_qualified_session_number' => 0,
        'last_session_at'     => null,
        'state_version'       => 0,
        'last_message_fingerprint' => null,
        'message_fingerprint_history' => [],
        'repeat_streak'       => 0,
        'last_signal_signature' => null,
        'signal_history'      => [],
        'signal_repeat_streak' => 0,
        'last_interaction_at' => null,
    ];
}

function aimee_load_relationship_state($profile) {
    global $wpdb;

    $seed = aimee_seed_relationship_state($profile);
    $user_id = intval($seed['user_id']);

    if (!$user_id || !aimee_relationship_dimensions_table_available()) {
        return $seed;
    }

    $row = $wpdb->get_row($wpdb->prepare(
        'SELECT * FROM ' . aimee_relationship_dimensions_table() . ' WHERE user_id = %d',
        $user_id
    ), ARRAY_A);

    if (!is_array($row)) {
        $stored_stage = (string) ($profile->intimacy_stage ?? 'guarded');
        $policy = function_exists('aimee_relationship_policy_config')
            ? aimee_relationship_policy_config()
            : [];
        $requirements = $policy['stages'][$stored_stage] ?? [];
        $seed['meaningful_interaction_count'] = intval(
            $requirements['meaningful_interactions'] ?? 0
        );
        $seed['session_count'] = intval(
            $requirements['distinct_sessions'] ?? 0
        );
        $seed['qualified_session_count'] = aimee_relationship_implied_qualified_sessions(
            intval($seed['trust']),
            $stored_stage
        );
        $seed['session_count'] = max(
            intval($seed['session_count']),
            intval($seed['qualified_session_count'])
        );
        $seed['last_qualified_session_number'] = intval($seed['session_count']);
        $seed['migration_backfilled_stage'] = $stored_stage;
        return $seed;
    }

    foreach (['trust', 'affection', 'chemistry', 'safety', 'reciprocity', 'reliability', 'frustration'] as $field) {
        $seed[$field] = aimee_relationship_clamp($row[$field] ?? $seed[$field]);
    }

    $seed['interaction_count'] = max(0, intval($row['interaction_count'] ?? 0));
    $seed['meaningful_interaction_count'] = max(
        0,
        intval($row['meaningful_interaction_count'] ?? 0)
    );
    $seed['session_count'] = max(0, intval($row['session_count'] ?? 0));
    $seed['qualified_session_count'] = max(
        0,
        intval($row['qualified_session_count'] ?? 0)
    );
    $seed['last_qualified_session_number'] = max(
        0,
        intval($row['last_qualified_session_number'] ?? 0)
    );
    $seed['last_session_at'] = !empty($row['last_session_at'])
        ? (string) $row['last_session_at']
        : null;
    $seed['state_version'] = max(0, intval($row['state_version'] ?? 0));
    $seed['last_message_fingerprint'] = !empty($row['last_message_fingerprint'])
        ? (string) $row['last_message_fingerprint']
        : null;
    $message_history = json_decode(
        (string) ($row['message_fingerprint_history_json'] ?? '[]'),
        true
    );
    $seed['message_fingerprint_history'] = array_values(array_filter(
        is_array($message_history) ? $message_history : [],
        static function ($fingerprint) {
            return is_string($fingerprint)
                && preg_match('/^[a-f0-9]{64}$/', $fingerprint) === 1;
        }
    ));
    $seed['repeat_streak'] = max(0, intval($row['repeat_streak'] ?? 0));
    $seed['last_signal_signature'] = !empty($row['last_signal_signature'])
        ? (string) $row['last_signal_signature']
        : null;
    $signal_history = json_decode(
        (string) ($row['signal_history_json'] ?? '[]'),
        true
    );
    $seed['signal_history'] = [];
    foreach (array_slice(is_array($signal_history) ? $signal_history : [], -64) as $record) {
        if (!is_array($record)) continue;
        $record_signals = array_values(array_unique(array_filter(array_map(
            'sanitize_key',
            (array) ($record['signals'] ?? [])
        ))));
        $context_hash = (string) ($record['context_fingerprint'] ?? '');
        $bundle_hash = (string) ($record['bundle_fingerprint'] ?? '');
        if (
            $context_hash !== ''
            && preg_match('/^[a-f0-9]{64}$/', $context_hash) !== 1
        ) {
            $context_hash = '';
        }
        if (
            $bundle_hash !== ''
            && preg_match('/^[a-f0-9]{64}$/', $bundle_hash) !== 1
        ) {
            $bundle_hash = '';
        }
        $record_signal_contexts = [];
        foreach ((array) ($record['signal_contexts'] ?? []) as $signal_key => $fingerprint) {
            $signal_key = sanitize_key((string) $signal_key);
            $fingerprint = (string) $fingerprint;
            if (
                $signal_key !== ''
                && preg_match('/^[a-f0-9]{64}$/', $fingerprint) === 1
            ) {
                $record_signal_contexts[$signal_key] = $fingerprint;
            }
        }
        $seed['signal_history'][] = [
            'signals' => $record_signals,
            'context_fingerprint' => $context_hash,
            'bundle_fingerprint' => $bundle_hash,
            'signal_contexts' => $record_signal_contexts,
        ];
    }
    $seed['signal_repeat_streak'] = max(0, intval($row['signal_repeat_streak'] ?? 0));
    $seed['last_interaction_at'] = !empty($row['last_interaction_at'])
        ? (string) $row['last_interaction_at']
        : null;

    // Schema 1.6 adds meaningful/session evidence. Preserve an established
    // relationship during migration by backfilling only the minimum evidence
    // already implied by its stored stage; do not grant a higher stage.
    if (intval($seed['meaningful_interaction_count']) === 0) {
        $stored_stage = (string) ($profile->intimacy_stage ?? 'guarded');
        $stored_score = max(0, min(100, intval($profile->intimacy_score ?? 0)));
        $policy = function_exists('aimee_relationship_policy_config')
            ? aimee_relationship_policy_config()
            : [];
        $requirements = $policy['stages'][$stored_stage] ?? [];
        $seed['meaningful_interaction_count'] = intval(
            $requirements['meaningful_interactions'] ?? 0
        );
        $seed['session_count'] = max(
            intval($seed['session_count']),
            intval($requirements['distinct_sessions'] ?? 0)
        );
        if ($stored_score > aimee_relationship_intimacy_score($seed)) {
            foreach (['trust', 'affection', 'chemistry'] as $field) {
                $seed[$field] = max(intval($seed[$field]), $stored_score);
            }
            $seed['safety'] = max(intval($seed['safety']), 50, $stored_score);
            while (
                aimee_relationship_intimacy_score($seed) < $stored_score
                && intval($seed['chemistry']) < 100
            ) {
                $seed['chemistry']++;
            }
        }
        $seed['migration_backfilled_stage'] = $stored_stage;
    }

    // Schema 1.6.1 distinguishes raw elapsed sessions from sessions that
    // actually contained respectful, meaningful relationship evidence. A new
    // column defaults to zero on upgrade, so backfill only the tier already
    // implied by stored trust/stage and mark the current raw session as seen.
    if (
        intval($seed['qualified_session_count']) === 0
        && (
            intval($seed['meaningful_interaction_count']) > 0
            || intval($seed['trust']) > 8
            || (string) ($profile->intimacy_stage ?? 'guarded') !== 'guarded'
        )
    ) {
        $seed['qualified_session_count'] = aimee_relationship_implied_qualified_sessions(
            intval($seed['trust']),
            (string) ($profile->intimacy_stage ?? 'guarded')
        );
        $seed['session_count'] = max(
            intval($seed['session_count']),
            intval($seed['qualified_session_count'])
        );
        $seed['last_qualified_session_number'] = max(
            intval($seed['last_qualified_session_number']),
            intval($seed['session_count'])
        );
        $seed['migration_backfilled_qualified_sessions'] = intval(
            $seed['qualified_session_count']
        );
    }

    return $seed;
}

/** Return stable concept IDs present in text without retaining raw praise. */
function aimee_relationship_matched_concepts($text, $concept_patterns) {
    $matched = [];
    foreach ((array) $concept_patterns as $concept => $pattern) {
        if (preg_match($pattern, (string) $text) === 1) {
            $matched[] = sanitize_key((string) $concept);
        }
    }
    sort($matched, SORT_STRING);
    return array_values(array_unique(array_filter($matched)));
}

/**
 * Validate a callback against actual server-supplied Aimee transcript lines.
 * The returned context is a one-way hash; raw private conversation is never
 * copied into relationship telemetry.
 */
function aimee_relationship_grounded_follow_through($user_text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $user_text));
    $history = (string) $recent_history;
    if ($text === '' || trim($history) === '') {
        return ['matched' => false, 'context_fingerprint' => ''];
    }

    preg_match_all(
        '/^(?:\[[^\]]+\]\s*)?aimee\s*:\s*(.+)$/imu',
        $history,
        $matches
    );
    $aimee_lines = array_values(array_filter(array_map(
        'trim',
        (array) ($matches[1] ?? [])
    )));
    if (!$aimee_lines) {
        return ['matched' => false, 'context_fingerprint' => ''];
    }

    $callback_marker = preg_match(
        '/\b(?:you said|you mentioned|you told me|when you said|i remembered|'
        . 'i have remembered|i\'?ve remembered|we discussed|following up|'
        . 'came back to tell you|tell me more about that|what did you mean|'
        . 'how did that feel for you|how does that feel for you|'
        . 'from your side|from your perspective)\b/u',
        $text
    ) === 1;
    if (!$callback_marker) {
        return ['matched' => false, 'context_fingerprint' => ''];
    }

    $latest_line = mb_strtolower((string) end($aimee_lines));
    $deictic_callback = preg_match(
        '/\b(?:tell me more about that|what did you mean|how did that feel for you|'
        . 'how does that feel for you|following up|came back to tell you)\b/u',
        $text
    ) === 1;
    $stop = array_fill_keys([
        'about', 'after', 'again', 'aimee', 'because', 'been', 'being',
        'could', 'does', 'feel', 'from', 'have', 'into', 'just', 'like',
        'more', 'really', 'said', 'that', 'there', 'they', 'thing', 'this',
        'what', 'when', 'which', 'with', 'would', 'your', 'youre', 'you',
    ], true);
    preg_match_all('/[\p{L}\p{N}\']{4,}/u', $text, $user_terms);
    preg_match_all('/[\p{L}\p{N}\']{4,}/u', $latest_line, $aimee_terms);
    $user_terms = array_values(array_filter(
        array_unique((array) ($user_terms[0] ?? [])),
        static function ($term) use ($stop) {
            return !isset($stop[mb_strtolower((string) $term)]);
        }
    ));
    $aimee_terms = array_values(array_filter(
        array_unique((array) ($aimee_terms[0] ?? [])),
        static function ($term) use ($stop) {
            return !isset($stop[mb_strtolower((string) $term)]);
        }
    ));
    $overlap = array_intersect(
        array_map('mb_strtolower', $user_terms),
        array_map('mb_strtolower', $aimee_terms)
    );
    if (!$deictic_callback && !$overlap) {
        return ['matched' => false, 'context_fingerprint' => ''];
    }

    $normalised_line = preg_replace('/[^\p{L}\p{N}]+/u', ' ', $latest_line);
    $normalised_line = trim(preg_replace('/\s+/u', ' ', (string) $normalised_line));
    return [
        'matched' => true,
        'context_fingerprint' => hash(
            'sha256',
            'grounded_follow_through|' . $normalised_line
        ),
    ];
}

/** Choose at most one trust-bearing courtship family for the turn. */
function aimee_relationship_courtship_primary_signal($signals) {
    $signals = is_array($signals) ? $signals : [];
    foreach ([
        'grounded_follow_through',
        'sincere_understanding',
        'specific_personality_appreciation',
        'specific_capability_appreciation',
        'specific_appearance_appreciation',
    ] as $signal_key) {
        if (!empty($signals[$signal_key])) return $signal_key;
    }
    return '';
}

