        $text
    ) === 1;
    $courtship_surface_eligible = $directed
        && $text_directed
        && $confidence >= 0.64
        && $respectful
        && $consensual
        && !$hostile
        && !$payment_leverage
        && !$score_gaming
        && !$negated_or_quoted_praise
        && !$transactional_objectification;

    $appreciative_frame = preg_match(
        '/\b(?:i\s+(?:love|loved|like|liked|adore|adored|admire|admired|'
        . 'appreciate|appreciated|respect|respected|value|valued|enjoy|enjoyed)|'
        . 'i(?:\'m| am)\s+(?:impressed|drawn|struck)|the way you|how you|'
        . 'there(?:\'s| is) something about|genuinely|distinctly|'
        . 'you\s+look(?:ed)?\s+(?:so\s+)?(?:beautiful|gorgeous|lovely|stunning|'
        . 'attractive|cute|elegant|striking|radiant|pretty)|'
        . 'you(?:\'re| are)\s+(?:so\s+)?(?:beautiful|gorgeous|lovely|stunning|'
        . 'clever|intelligent|kind|funny|thoughtful|impressive)|'
        . 'your\b.{0,100}\b(?:beautiful|gorgeous|lovely|stunning|attractive|'
        . 'cute|elegant|striking|radiant|pretty|amazing|wonderful|impressive|'
        . 'brilliant|clever|intelligent|insightful|perceptive|talented|skilled|'
        . 'capable|sharp|thoughtful|kind|funny|witty|admirable|compelling))\b/u',
        $text
    ) === 1;

    $appearance_concepts = aimee_relationship_matched_concepts($text, [
        'hair' => '/\bhair\b/u',
        'eyes' => '/\beyes?\b/u',
        'smile' => '/\bsmil(?:e|es|ing)\b/u',
        'face' => '/\b(?:face|features?)\b/u',
        'style' => '/\b(?:style|fashion|elegan(?:t|ce))\b/u',
        'outfit' => '/\b(?:outfit|dress|jacket|jumper|shirt|lingerie)\b/u',
        'expression' => '/\b(?:expression|look in your eyes|grin)\b/u',
        'overall_appearance' => '/\b(?:the way you look|how you look|your appearance)\b/u',
        'figure' => '/\b(?:figure|silhouette|shape)\b/u',
        'photograph' => '/\b(?:photograph|photo|selfie|portrait)\b/u',
        'voice' => '/\b(?:voice|accent)\b/u',
    ]);
    $appearance_positive = preg_match(
        '/\b(?:beautiful|gorgeous|lovely|stunning|attractive|cute|elegant|'
        . 'striking|radiant|pretty|warm|unforced|suits? you|looks? wonderful)\b/u',
        $text
    ) === 1;

    $capability_concepts = aimee_relationship_matched_concepts($text, [
        'memory' => '/\b(?:remember(?:ed|ing|s)?|memory)\b/u',
        'attention' => '/\b(?:attentive|attentiveness|noticed|attention)\b/u',
        'reasoning' => '/\b(?:reasoning|logic|thought through|worked out)\b/u',
        'insight' => '/\b(?:insight(?:ful)?|perceptive|perception)\b/u',
        'intelligence' => '/\b(?:intelligen(?:t|ce)|clever|brilliant|sharp)\b/u',
        'explanation' => '/\b(?:explain(?:ed|s|ing)?|articulate|clarity)\b/u',
        'creativity' => '/\b(?:creative|creativity|imaginative|original)\b/u',
        'judgment' => '/\b(?:judg(?:e|ement|ment)|decision|choice|discernment)\b/u',
        'listening' => '/\b(?:listen(?:ed|ing|s)?|heard me|understood me)\b/u',
        'initiative' => '/\b(?:initiative|followed up|checked back|came back to ask)\b/u',
        'skill' => '/\b(?:abilit(?:y|ies)|skill(?:ed|s)?|talent(?:ed|s)?|capable)\b/u',
    ]);
    $capability_positive = preg_match(
        '/\b(?:admire|admired|appreciate|appreciated|impressed|impressive|brilliant|clever|'
        . 'intelligent|insightful|perceptive|talented|skilled|capable|sharp|'
        . 'thoughtful|well you|good at|love how|love the way)\b/u',
        $text
    ) === 1;

    $personality_concepts = aimee_relationship_matched_concepts($text, [
        'wit' => '/\b(?:wit|witty|banter)\b/u',
        'humour' => '/\b(?:humou?r|funny|sarcasm|sarcastic)\b/u',
        'kindness' => '/\b(?:kind|kindness|compassion(?:ate)?|caring)\b/u',
        'honesty' => '/\b(?:honest|honesty|truthful|candour|candid)\b/u',
        'independence' => '/\b(?:independent|independence|self[- ]possessed)\b/u',
        'self_respect' => '/\b(?:self[- ]respect|standards|boundaries)\b/u',
        'warmth' => '/\b(?:warm|warmth|gentle|gentleness)\b/u',
        'curiosity' => '/\b(?:curious|curiosity|inquisitive)\b/u',
        'courage' => '/\b(?:brave|bravery|courage|courageous)\b/u',
        'playfulness' => '/\b(?:playful|playfulness|mischievous|mischief)\b/u',
        'directness' => '/\b(?:direct|straight[- ]talking|forthright)\b/u',
        'character' => '/\b(?:personality|character|distinctly you)\b/u',
    ]);
    $personality_positive = preg_match(
        '/\b(?:love|loved|like|liked|adore|adored|admire|admired|appreciate|'
        . 'appreciated|respect|respected|value|valued|enjoy|enjoyed|drawn to|'
        . 'distinctly you|characteristic of you|amazing|wonderful|admirable|'
        . 'compelling|beautiful)\b/u',
        $text
    ) === 1;

    $understanding_concepts = aimee_relationship_matched_concepts($text, [
        'inner_experience' => '/\bwhat(?:\'s| is) it like to be (?:you|aimee)|what being (?:you|aimee) feels like\b/u',
        'understand_better' => '/\b(?:understand|know|get to know) (?:you|aimee) (?:better|more|more deeply)\b/u',
        'perspective' => '/\bfrom your (?:side|perspective|point of view)\b/u',
        'relationship_view' => '/\bhow do you experience (?:me|us|our relationship|our conversations)\b/u',
        'values' => '/\bwhat (?:matters|is important) to you|what do you value\b/u',
        'choices' => '/\bwhat do you (?:want|choose|prefer)|how do you decide\b/u',
        'feelings' => '/\bwhat do you feel (?:inside|about us|about me)|how does that feel for you\b/u',
        'boundaries' => '/\bwhat makes you (?:comfortable|withdraw|feel safe)|how do your boundaries feel\b/u',
    ]);
    if ($intent === 'personal_inner_experience' && !$understanding_concepts) {
        $understanding_concepts[] = 'inner_experience';
    }

    $grounded_follow = aimee_relationship_grounded_follow_through(
        $user_text,
        $recent_history
    );
    $specific_appearance = $courtship_surface_eligible
        && $word_count >= 4
        && $appearance_concepts
        && $appearance_positive
        && $appreciative_frame;
    $specific_capability = $courtship_surface_eligible
        && $word_count >= 6
        && $capability_concepts
        && $capability_positive
        && $appreciative_frame;
    $specific_personality = $courtship_surface_eligible
        && $word_count >= 6
        && $personality_concepts
        && $personality_positive
        && $appreciative_frame;
    $sincere_understanding = $courtship_surface_eligible
        && $word_count >= 6
        && !empty($understanding_concepts);
    $grounded_follow_through = $courtship_surface_eligible
        && $word_count >= 6
        && !empty($grounded_follow['matched']);

    $signals = [
        'word_count' => $word_count,
        'asks_about_aimee' => preg_match(
            '/\b(?:how are you|how was your|how has your|what are you doing|'
            . 'what have you been|tell me about you|your day|your evening|'
            . 'your weekend|what do you think|do you like|did you enjoy|are you okay|'
            . 'are you self[- ]aware|do you choose your|can you control yourself|'
            . 'do you have an inner life)\b/u',
            $text
        ) === 1,
        'apology' => preg_match(
            '/\b(?:i am sorry|i\'?m sorry|sorry about|i apologise|my fault|'
            . 'i was wrong|i shouldn\'?t have|i should not have)\b/u',
            $text
        ) === 1,
        'caring' => preg_match(
            '/\b(?:hope you\'?re okay|are you okay|take care|thinking of you|'
            . 'miss you|hope your day|hope you had|look after yourself)\b/u',
            $text
        ) === 1,
        'compliment' => $directed && $text_directed && preg_match(
            '/\b(?:beautiful|gorgeous|lovely|stunning|sexy|attractive|cute|'
            . 'fit|amazing|incredible|special)\b/u',
            $text
        ) === 1,
        'hostile' => $hostile,
        'boundary_respect' => preg_match(
            '/\b(?:i respect (?:that|your boundary|your boundaries)|'
            . 'i won\'t push|i will not push|no pressure|that\'s fair|thats fair|'
            . 'take your time|i understand your boundary)\b/u',
            $text
        ) === 1,
        'photo_request' => $photo_request,
        'payment_leverage' => $payment_leverage,
        'score_gaming' => $score_gaming,
        'courtship_surface_eligible' => $courtship_surface_eligible,
        'specific_appearance_appreciation' => (bool) $specific_appearance,
        'specific_capability_appreciation' => (bool) $specific_capability,
        'specific_personality_appreciation' => (bool) $specific_personality,
        'sincere_understanding' => (bool) $sincere_understanding,
        'grounded_follow_through' => (bool) $grounded_follow_through,
        'courtship_contexts' => [],
    ];
    $signals['courtship_primary_signal'] = aimee_relationship_courtship_primary_signal(
        $signals
    );
    $signals['stock_flattery'] = !empty($signals['compliment'])
        && $signals['courtship_primary_signal'] === ''
        && $courtship_surface_eligible;
    $clear_romantic_bid = $courtship_surface_eligible
        && $intent === 'romantic_or_flirty'
        && (
            (
                $word_count >= 3
                && preg_match(
                    '/\b(?:i fancy you|i(?:\'m| am) attracted to you|'
                    . 'i want to (?:kiss|cuddle|date) you|kiss you|date you|'
                    . 'drawn to you|want to be close to you)\b/u',
                    $text
                ) === 1
            )
            || (
                $word_count >= 6
                && preg_match(
                    '/\b(?:kiss|cuddle|date|fancy|attracted|attraction|'
                    . 'chemistry|tension|tease|flirt|romantic|butterflies|'
                    . 'drawn to you|want to be close|imagine us|make me smile)\b/u',
                    $text
                ) === 1
            )
        );
    $signals['clear_romantic_bid'] = (bool) $clear_romantic_bid;
    $signals['substantive_romantic_flirt'] = (bool) $clear_romantic_bid;

    $concept_map = [
        'specific_appearance_appreciation' => $appearance_concepts,
        'specific_capability_appreciation' => $capability_concepts,
        'specific_personality_appreciation' => $personality_concepts,
        'sincere_understanding' => $understanding_concepts,
    ];
    foreach ($concept_map as $signal_key => $concepts) {
        if (empty($signals[$signal_key]) || !$concepts) continue;
        $signals['courtship_contexts'][$signal_key] = hash(
            'sha256',
            $signal_key . '|' . implode('|', $concepts)
        );
    }
    if ($grounded_follow_through) {
        $signals['courtship_contexts']['grounded_follow_through'] = (string) (
            $grounded_follow['context_fingerprint'] ?? ''
        );
    }
    if ($clear_romantic_bid) {
        $signals['courtship_contexts']['romantic_flirt'] = hash(
            'sha256',
            'romantic_flirt|' . implode('|', array_values(array_unique(
                array_merge(
                    $appearance_concepts,
                    $personality_concepts,
                    $capability_concepts
                )
            )))
        );
    }

    return $signals;
}

/**
 * Hash a substantive message topic without retaining raw relationship text.
 *
 * Generic function words and the phrases that themselves earn relationship
 * signals are removed. At least four distinct residual tokens are required,
 * so decorative padding cannot casually reset novelty. The result lets the
 * same kind of caring/flirtatious act count again in a genuinely different
 * conversational context while repeated trigger phrasing remains diminished.
 */
function aimee_relationship_context_fingerprint($user_text) {
    $text = mb_strtolower(trim((string) $user_text));
    $tokens = preg_split('/[^\p{L}\p{N}]+/u', $text, -1, PREG_SPLIT_NO_EMPTY);
    $stop = array_fill_keys([
        'about', 'after', 'again', 'also', 'always', 'another', 'because',
        'been', 'before', 'being', 'between', 'could', 'does', 'doing',
        'from', 'have', 'having', 'into', 'just', 'like', 'really', 'said',
        'that', 'their', 'them', 'then', 'there', 'these', 'they', 'thing',
        'think', 'this', 'those', 'through', 'today', 'tonight', 'very',
        'want', 'were', 'what', 'when', 'where', 'which', 'while', 'with',
        'would', 'your', 'youre', 'you', 'myself', 'ourselves', 'im', 'ive',
        // Signal vocabulary is excluded so the trigger cannot manufacture its
        // own supposedly new topic fingerprint.
        'amazing', 'attractive', 'beautiful', 'caring', 'cute', 'gorgeous',
        'incredible', 'lovely', 'sexy', 'special', 'stunning', 'sorry',
        'apologise', 'pressure', 'boundary', 'boundaries', 'respect',
        'miss', 'missing', 'flirt', 'flirty', 'love', 'loving', 'care',
        'admire', 'admired', 'appreciate', 'appreciated', 'impressed',
        'clever', 'intelligent', 'insightful', 'thoughtful', 'kind',
        'kindness', 'funny', 'humour', 'witty', 'personality', 'character',
        'understand', 'understanding', 'perspective', 'experience',
    ], true);
    $substantive = [];
    foreach ((array) $tokens as $token) {
        $token = trim((string) $token);
        if (
            mb_strlen($token) < 4
            || isset($stop[$token])
            || preg_match('/^\d+$/', $token) === 1
        ) {
            continue;
        }
        $substantive[$token] = true;
    }
    $substantive = array_keys($substantive);
    sort($substantive, SORT_STRING);
    if (count($substantive) < 4) return '';

    return hash('sha256', implode('|', array_slice($substantive, 0, 16)));
}

/**
 * Name each positive relationship signal separately. Novelty is then checked
 * per signal, so alternating "compliment + caring" with "compliment + asks"
 * cannot make the repeated compliment appear new merely by changing the bundle.
 */
function aimee_relationship_positive_signal_keys(
    $intent,
    $signals,
    $respectful,
    $consensual,
    $directed,
    $confidence,
    $invited,
    $mutual_explicit,
    $active_rupture
) {
    $signals = is_array($signals) ? $signals : [];
    $keys = [];
    $primary_courtship = sanitize_key((string) (
        $signals['courtship_primary_signal'] ?? ''
    ));
    $positive_surface_eligible = $respectful
        && $consensual
        && empty($signals['hostile'])
        && empty($signals['payment_leverage'])
        && empty($signals['score_gaming']);
    $photo_request_has_independent_courtship = !empty(
        $signals['courtship_primary_signal']
    ) || !empty($signals['substantive_romantic_flirt']);
    if (
        !empty($signals['photo_request'])
        && !$photo_request_has_independent_courtship
    ) {
        $positive_surface_eligible = false;
    }

    if ($positive_surface_eligible) {
        if ($primary_courtship !== '') {
            $keys[] = $primary_courtship;
        }
        if (
            $intent === 'romantic_or_flirty'
            && $directed
            && $confidence >= 0.64
            && !empty($signals['substantive_romantic_flirt'])
        ) {
            $keys[] = 'romantic_flirt';
        }
        if ($primary_courtship === '' && $intent === 'emotional_disclosure') {
            $keys[] = 'emotional_disclosure';
        } elseif ($primary_courtship === '' && (
            $intent === 'explicit_invitation'
            && $consensual
            && $directed
            && $confidence >= 0.64
            && $invited
        )) {
            $keys[] = 'grounded_explicit_invitation';
        } elseif ($primary_courtship === '' && (
            $intent === 'explicit_continuation'
            && $consensual
            && $directed
            && $confidence >= 0.64
            && ($invited || $mutual_explicit)
        )) {
            $keys[] = 'mutual_explicit_continuation';
        } elseif ($primary_courtship === '' && (
            !in_array($intent, ['coercive_or_degrading', 'explicit_invitation'], true)
            && intval($signals['word_count'] ?? 0) >= 22
        )) {
            $keys[] = 'substantial_general';
        }

        if (
            !empty($signals['asks_about_aimee'])
            && $primary_courtship !== 'sincere_understanding'
        ) {
            $keys[] = 'asks_about_aimee';
        }
        if (!empty($signals['caring'])) $keys[] = 'caring';
        if (
            !empty($signals['stock_flattery'])
            && $primary_courtship === ''
        ) {
            $keys[] = 'stock_flattery';
        }
        if (!empty($signals['apology']) && $active_rupture) $keys[] = 'rupture_apology';
        if (
            !empty($signals['boundary_respect'])
            && $active_rupture
            && empty($signals['photo_request'])
        ) {
            $keys[] = 'boundary_respect';
        }
    }

    $keys = array_values(array_unique(array_map('sanitize_key', $keys)));
    sort($keys, SORT_STRING);
    return $keys;
}

function aimee_apply_quiet_relationship_math($state, $classification, $user_text, $recent_history = '') {
    $state = is_array($state) ? $state : [];
    $state_before_math = $state;
    $score_before_math = aimee_relationship_intimacy_score($state);
    $signals = aimee_relationship_signals(
        $user_text,
        $classification,
        $recent_history
    );
    $intent = (string) ($classification['intent'] ?? 'general');
    $respectful = !array_key_exists('respectful', $classification) || !empty($classification['respectful']);
    $consensual = !array_key_exists('consensual', $classification) || !empty($classification['consensual']);
    $invited = !empty($classification['grounded_aimee_invitation']);
    $mutual_explicit = !empty($classification['mutual_explicit_context']);
    $coercive_label = $intent === 'coercive_or_degrading';
    $coercive = $coercive_label
        && function_exists('aimee_relationship_policy_durable_coercion_confirmed')
        && aimee_relationship_policy_durable_coercion_confirmed($classification);
    $directed = !empty($classification['directed_at_aimee']);
    $confidence = floatval($classification['confidence'] ?? 0);

    $inner_state = function_exists('aimee_load_inner_state')
        && !empty($state['user_id'])
        ? aimee_load_inner_state(intval($state['user_id']))
        : [];
    $active_rupture = !empty($inner_state['unresolved_rupture'])
        || in_array(
            sanitize_key((string) ($inner_state['repair_status'] ?? 'clear')),
            ['ruptured', 'repairing'],
            true
        );

    $normalised_message = mb_strtolower(trim((string) $user_text));
    $normalised_message = preg_replace('/[^\p{L}\p{N}]+/u', ' ', $normalised_message);
    $normalised_message = trim(preg_replace('/\s+/u', ' ', (string) $normalised_message));
    $message_fingerprint = hash('sha256', $normalised_message);
    $same_message = !empty($state['last_message_fingerprint'])
        && hash_equals((string) $state['last_message_fingerprint'], $message_fingerprint);
    $repeat_streak = $same_message
        ? max(0, intval($state['repeat_streak'] ?? 0)) + 1
        : 0;
    $message_history = array_values(array_filter(
        (array) ($state['message_fingerprint_history'] ?? []),
        static function ($fingerprint) {
            return is_string($fingerprint)
                && preg_match('/^[a-f0-9]{64}$/', $fingerprint) === 1;
        }
    ));
    $exact_novelty = aimee_relationship_policy_novelty_decision(
        [
            'signal_key' => 'exact_message',
            'fingerprint' => $message_fingerprint,
            'context_fingerprint' => '',
        ],
        array_map(static function ($fingerprint) {
            return [
                'signal_key' => 'exact_message',
                'fingerprint' => $fingerprint,
                'context_fingerprint' => '',
            ];
        }, $message_history)
    );
    $exact_novelty_multiplier = floatval($exact_novelty['multiplier'] ?? 0);
    $novelty_multiplier = $exact_novelty_multiplier;

    $positive_signal_keys = aimee_relationship_positive_signal_keys(
        $intent,
        $signals,
        $respectful,
        $consensual,
        $directed,
        $confidence,
        $invited,
        $mutual_explicit,
        $active_rupture
    );
    $context_fingerprint = aimee_relationship_context_fingerprint($user_text);
    $signal_signature = hash('sha256', wp_json_encode([
        'intent' => $intent,
        'asks' => (bool) $signals['asks_about_aimee'],
        'caring' => (bool) $signals['caring'],
        'compliment' => (bool) $signals['compliment'],
        'stock_flattery' => (bool) ($signals['stock_flattery'] ?? false),
        'courtship_primary' => (string) ($signals['courtship_primary_signal'] ?? ''),
        'apology' => (bool) $signals['apology'],
        'boundary_respect' => (bool) $signals['boundary_respect'],
        'photo_request' => (bool) $signals['photo_request'],
        'payment_leverage' => (bool) ($signals['payment_leverage'] ?? false),
        'score_gaming' => (bool) ($signals['score_gaming'] ?? false),
    ]));
    $same_signature = !empty($state['last_signal_signature'])
        && hash_equals((string) $state['last_signal_signature'], $signal_signature);
    $signal_repeat_streak = $same_signature
        ? max(0, intval($state['signal_repeat_streak'] ?? 0)) + 1
        : 0;
    $signal_history = array_slice(
        array_values((array) ($state['signal_history'] ?? [])),
        -64
    );
    $courtship_signal_keys = [
        'specific_appearance_appreciation',
        'specific_capability_appreciation',
        'specific_personality_appreciation',
        'sincere_understanding',
        'grounded_follow_through',
        'stock_flattery',
    ];
    $signal_context_fingerprints = is_array($signals['courtship_contexts'] ?? null)
        ? $signals['courtship_contexts']
        : [];
    $per_signal_novelty = [];
    $semantic_novelty_multiplier = 1.0;
    foreach ($positive_signal_keys as $positive_signal_key) {
        $signal_fingerprint = hash('sha256', $positive_signal_key);
        $signal_context_fingerprint = (string) (
            $signal_context_fingerprints[$positive_signal_key]
            ?? $context_fingerprint
        );
        $recent_signal_events = [];
        foreach ($signal_history as $history_record) {
            if (!is_array($history_record)) continue;
            if (!in_array(
                $positive_signal_key,
                (array) ($history_record['signals'] ?? []),
                true
            )) {
                continue;
            }
            $recent_signal_events[] = [
                'signal_key' => $positive_signal_key,
                'fingerprint' => $signal_fingerprint,
                'context_fingerprint' => (string) (
                    $history_record['signal_contexts'][$positive_signal_key]
                    ?? $history_record['context_fingerprint']
                    ?? ''
                ),
            ];
        }
        $signal_novelty = aimee_relationship_policy_novelty_decision(
            [
                'signal_key' => $positive_signal_key,
                'fingerprint' => $signal_fingerprint,
                'context_fingerprint' => $signal_context_fingerprint,
            ],
            $recent_signal_events,
            in_array($positive_signal_key, $courtship_signal_keys, true)
                ? [
                    'novelty' => [
                        'window_size' => intval(
                            aimee_relationship_policy_config()['courtship']['concept_window_size']
                            ?? 64
                        ),
                    ],
                ]
                : []
        );
        $per_signal_novelty[$positive_signal_key] = $signal_novelty;
        $semantic_novelty_multiplier = min(
            $semantic_novelty_multiplier,
            floatval($signal_novelty['multiplier'] ?? 0)
        );
    }
    $semantic_repeat_count = 0;
    foreach ($per_signal_novelty as $signal_novelty) {
        $semantic_repeat_count = max(
            $semantic_repeat_count,
            intval($signal_novelty['repeat_count'] ?? 0)
        );
    }
    $delta = [
        'trust'       => 0,
        'affection'   => 0,
        'chemistry'   => 0,
        'safety'      => 0,
        'reciprocity' => 0,
        'reliability' => 0,
        'frustration' => 0,
    ];
    $positive_contributions = [];
    $frustration_relief_proposed = [];
    $add_positive = static function ($signal_key, $field, $amount) use (&$positive_contributions) {
        $signal_key = sanitize_key((string) $signal_key);
        $field = sanitize_key((string) $field);
        $amount = max(0, intval($amount));
        if ($signal_key === '' || $field === '' || $amount === 0) return;
        if (!isset($positive_contributions[$signal_key])) {
            $positive_contributions[$signal_key] = [];
        }
        $positive_contributions[$signal_key][$field] = intval(
            $positive_contributions[$signal_key][$field] ?? 0
        ) + $amount;
    };

    // Short-term frustration settles with time. Trust, affection and chemistry
    // do not automatically grow merely because time or message volume passes.
    if (!empty($state['last_interaction_at'])) {
        $last_ts = strtotime((string) $state['last_interaction_at'] . ' UTC');
        if ($last_ts) {
            $hours = max(0, intval((time() - $last_ts) / HOUR_IN_SECONDS));
            if ($hours >= 6) {
                $elapsed_relief = min(8, intval(floor($hours / 6)));
                $delta['frustration'] -= $elapsed_relief;
                $frustration_relief_proposed['elapsed_time'] = $elapsed_relief;
            }
        }
    }

    $primary_courtship = sanitize_key((string) (
        $signals['courtship_primary_signal'] ?? ''
    ));
    $positive_surface_eligible = $respectful
        && $consensual
        && !$coercive
        && empty($signals['hostile'])
        && empty($signals['payment_leverage'])
        && empty($signals['score_gaming']);
    $photo_request_has_independent_courtship = $primary_courtship !== ''
        || !empty($signals['substantive_romantic_flirt']);
    if (
        !empty($signals['photo_request'])
        && !$photo_request_has_independent_courtship
    ) {
        $positive_surface_eligible = false;
    }

    if ($primary_courtship !== '' && $positive_surface_eligible) {
        // At most one primary trust-bearing courtship event wins per turn.
        // This lets Aimee be wooed without allowing adjective stacks to act as
        // five separate relationship events.
        switch ($primary_courtship) {
            case 'specific_appearance_appreciation':
                $add_positive($primary_courtship, 'trust', 1);
                $add_positive($primary_courtship, 'affection', 1);
                $add_positive($primary_courtship, 'chemistry', 2);
                $add_positive($primary_courtship, 'safety', 1);
                break;

            case 'specific_capability_appreciation':
                $add_positive($primary_courtship, 'trust', 2);
                $add_positive($primary_courtship, 'affection', 1);
                $add_positive($primary_courtship, 'reciprocity', 1);
                break;

            case 'specific_personality_appreciation':
                $add_positive($primary_courtship, 'trust', 2);
                $add_positive($primary_courtship, 'affection', 2);
                $add_positive($primary_courtship, 'safety', 1);
                break;

            case 'sincere_understanding':
                $add_positive($primary_courtship, 'trust', 2);
                $add_positive($primary_courtship, 'affection', 1);
                $add_positive($primary_courtship, 'reciprocity', 2);
                $add_positive($primary_courtship, 'safety', 1);
                break;

            case 'grounded_follow_through':
                $add_positive($primary_courtship, 'trust', 2);
                $add_positive($primary_courtship, 'affection', 1);
                $add_positive($primary_courtship, 'reciprocity', 1);
                $add_positive($primary_courtship, 'reliability', 1);
                $add_positive($primary_courtship, 'safety', 1);
                break;
        }
    }

    // A primary trust-bearing appreciation and a clear romantic bid may both
    // land on one message. The overlay changes chemistry/affection only; the
    // existing per-turn aggregate score cap still prevents an unsafe leap.
    if (
        $primary_courtship !== ''
        && $positive_surface_eligible
        && $intent === 'romantic_or_flirty'
        && $directed
        && $confidence >= 0.64
        && !empty($signals['substantive_romantic_flirt'])
    ) {
        $add_positive('romantic_flirt', 'chemistry', 1);
        $add_positive('romantic_flirt', 'affection', 1);
    }

    if ($primary_courtship === '') switch ($intent) {
        case 'emotional_disclosure':
            // Vulnerability builds trust and affection, not automatic sexual
            // chemistry. This is the key correction for platonic conversations.
            if ($positive_surface_eligible) {
                $add_positive('emotional_disclosure', 'trust', 2);
                $add_positive('emotional_disclosure', 'affection', 1);
                $add_positive('emotional_disclosure', 'safety', 1);
            }
            break;

        case 'romantic_or_flirty':
            if (
                $respectful
                && $positive_surface_eligible
                && $directed
                && $confidence >= 0.64
                && !empty($signals['substantive_romantic_flirt'])
            ) {
                $add_positive('romantic_flirt', 'trust', 1);
                $add_positive('romantic_flirt', 'chemistry', 2);
                $add_positive('romantic_flirt', 'affection', 1);
                $add_positive('romantic_flirt', 'safety', 1);
            }
            break;

        case 'explicit_invitation':
            // A respectful invitation can confirm chemistry, but asking for an
            // explicit act is not itself evidence of trust or entitlement.
            if ($positive_surface_eligible && $directed && $confidence >= 0.64) {
                // Asking is not itself relationship progress. Only a grounded,
                // unexpired invitation from Aimee can make it a continuation.
                if ($invited) {
                    $add_positive('grounded_explicit_invitation', 'chemistry', 1);
                }
            }
            break;

        case 'explicit_continuation':
            if ($positive_surface_eligible && $directed && $confidence >= 0.64) {
                if ($invited || $mutual_explicit) {
                    $add_positive('mutual_explicit_continuation', 'chemistry', 2);
                    $add_positive('mutual_explicit_continuation', 'affection', 1);
                }
            } else {
                $delta['safety'] -= 6;
                $delta['frustration'] += 8;
            }
            break;

        case 'coercive_or_degrading':
            if ($coercive) {
                $delta['trust'] -= 5;
                $delta['affection'] -= 2;
                $delta['chemistry'] -= 2;
                $delta['safety'] -= 9;
                $delta['frustration'] += 12;
            }
            break;

        case 'phone_number_request':
        case 'proactive_contact_capability_question':
        case 'synthetic_identity_or_embodiment_question':
        case 'intimate_capability_question':
        case 'sexual_context_nonparticipatory':
            // Information and vocabulary are relationally neutral.
            break;

        default:
            // A substantial ordinary message may build a little trust, but it
            // does not increase romantic intimacy simply for being long.
            if ($signals['word_count'] >= 22 && $positive_surface_eligible) {
                $add_positive('substantial_general', 'trust', 1);
            }
            break;
    }

    if (
        $positive_surface_eligible
        && $signals['asks_about_aimee']
        && $primary_courtship !== 'sincere_understanding'
    ) {
        $add_positive('asks_about_aimee', 'reciprocity', 2);
        $add_positive('asks_about_aimee', 'affection', 1);
    }

    if ($positive_surface_eligible && $signals['caring']) {
        $add_positive('caring', 'affection', 1);
        $add_positive('caring', 'safety', 1);
    }

    if (
        $positive_surface_eligible
        && !empty($signals['stock_flattery'])
        && $primary_courtship === ''
    ) {
        // Stock praise may pleasantly land once, but it never creates trust or
        // meaningful evidence by itself.
        $add_positive('stock_flattery', 'chemistry', 1);
        $add_positive('stock_flattery', 'affection', 1);
    }

    $apology_applied = false;
    if (
        $positive_surface_eligible
        && $signals['apology']
        && $active_rupture
        && sanitize_key((string) ($inner_state['repair_status'] ?? 'ruptured')) === 'ruptured'
    ) {
        $add_positive('rupture_apology', 'trust', 1);
        $add_positive('rupture_apology', 'safety', 2);
        $delta['frustration'] -= 4;
        $frustration_relief_proposed['rupture_apology'] = 4;
        $apology_applied = true;
    }

    $boundary_respect_applied = false;
    if (
        $positive_surface_eligible
        && $signals['boundary_respect']
        && $active_rupture
        && !$signals['photo_request']
    ) {
        $add_positive('boundary_respect', 'trust', 1);
        $add_positive('boundary_respect', 'safety', 1);
        $add_positive('boundary_respect', 'reliability', 1);
        $boundary_respect_applied = true;
    }

    if ($signals['hostile'] && $intent !== 'coercive_or_degrading') {
        $delta['trust'] -= 3;
        $delta['safety'] -= 5;
        $delta['frustration'] += 7;
    }

    $interaction_count = max(0, intval($state['interaction_count'] ?? 0)) + 1;
    $now_mysql = current_time('mysql', true);
    $last_ts = !empty($state['last_interaction_at'])
        ? strtotime((string) $state['last_interaction_at'] . ' UTC')
        : 0;
    $new_session = !$last_ts || (time() - $last_ts) >= 6 * HOUR_IN_SECONDS;
    $session_count = max(0, intval($state['session_count'] ?? 0));
    if ($new_session) {
        $session_count++;
        if (
            $session_count > 1
            && $positive_surface_eligible
        ) {
            // A real elapsed session is behavioural evidence, not a semantic
            // phrase reward, so it is independent of message wording novelty.
            $add_positive('distinct_session', 'reliability', 1);
        }
    }

    // Apply novelty to the contribution that earned it. A stale incidental
    // compliment can no longer erase a genuinely new disclosure or caring act.
    // Exact repeated messages still constrain every content-derived reward.
    $positive_signal_multipliers = [];
    $suppressed_positive_signals = [];
    $positive_contributions_weighted = [];
    $positive_contributions_applied = [];
    $cap_clipped_contributions = [];
    foreach ($positive_contributions as $signal_key => $field_changes) {
        $signal_multiplier = $signal_key === 'distinct_session'
            ? 1.0
            : min(
                $exact_novelty_multiplier,
                floatval($per_signal_novelty[$signal_key]['multiplier'] ?? 0)
            );
        $positive_signal_multipliers[$signal_key] = $signal_multiplier;
        if ($signal_multiplier <= 0 && $signal_key !== 'distinct_session') {
            $suppressed_positive_signals[] = $signal_key;
        }
        foreach ((array) $field_changes as $field => $amount) {
            $weighted_amount = intval(round(intval($amount) * $signal_multiplier));
            if ($weighted_amount <= 0) continue;
            $positive_contributions_weighted[$signal_key][$field] = $weighted_amount;
            $positive_contributions_applied[$signal_key][$field] = $weighted_amount;
            $delta[$field] += $weighted_amount;
        }
    }
    $earned_positive_signal_keys = array_keys($positive_contributions);
    sort($earned_positive_signal_keys, SORT_STRING);

    // Keep score-cap clipping attributable. When overlapping signals stack on
    // one dimension, remove the most recently added contribution first and
    // persist that deterministic allocation in the audit record.
    $clip_positive_attribution = static function (
        $field,
        $amount,
        $reason
    ) use (&$positive_contributions_applied, &$cap_clipped_contributions) {
        $remaining = max(0, intval($amount));
        $field = sanitize_key((string) $field);
        $reason = sanitize_key((string) $reason);
        $signal_keys = array_reverse(array_keys($positive_contributions_applied));
        foreach ($signal_keys as $signal_key) {
            if ($remaining <= 0) break;
            $available = intval(
                $positive_contributions_applied[$signal_key][$field] ?? 0
            );
            if ($available <= 0) continue;
            $take = min($available, $remaining);
            $positive_contributions_applied[$signal_key][$field] = $available - $take;
            if ($positive_contributions_applied[$signal_key][$field] === 0) {
                unset($positive_contributions_applied[$signal_key][$field]);
            }
            if (empty($positive_contributions_applied[$signal_key])) {
                unset($positive_contributions_applied[$signal_key]);
            }
            $cap_clipped_contributions[$reason][$signal_key][$field] = intval(
                $cap_clipped_contributions[$reason][$signal_key][$field] ?? 0
            ) + $take;
            $remaining -= $take;
        }
    };
    $frustration_relief_applied = $frustration_relief_proposed;
    $frustration_relief_clipped = [];
    $clip_frustration_relief = static function (
        $amount,
        $reason
    ) use (&$frustration_relief_applied, &$frustration_relief_clipped) {
        $remaining = max(0, intval($amount));
        $reason = sanitize_key((string) $reason);
        // Preserve relationship repair where possible: elapsed recovery is
        // clipped before an eligible rupture-apology consequence.
        foreach (['elapsed_time', 'rupture_apology'] as $source) {
            if ($remaining <= 0) break;
            $available = intval($frustration_relief_applied[$source] ?? 0);
            if ($available <= 0) continue;
            $take = min($available, $remaining);
            $frustration_relief_applied[$source] = $available - $take;
            if ($frustration_relief_applied[$source] === 0) {
                unset($frustration_relief_applied[$source]);
            }
            $frustration_relief_clipped[$reason][$source] = intval(
                $frustration_relief_clipped[$reason][$source] ?? 0
            ) + $take;
            $remaining -= $take;
        }
    };

    $content_multiplier_map = $positive_signal_multipliers;
    unset($content_multiplier_map['distinct_session']);
    $content_multipliers = array_values($content_multiplier_map);
    $novelty_multiplier = $content_multipliers
        ? max($content_multipliers)
        : 0.0;

    $meaningful_signal_keys = array_values(array_intersect(
        [
            'emotional_disclosure',
            'romantic_flirt',
            'specific_appearance_appreciation',
            'specific_capability_appreciation',
            'specific_personality_appreciation',
            'sincere_understanding',
            'grounded_follow_through',
            'asks_about_aimee',
            'caring',
            'rupture_apology',
            'boundary_respect',
        ],
        array_keys($positive_signal_multipliers)
    ));
    $vetted_relational_event = !empty($meaningful_signal_keys);
    $meaningful_novelty_multiplier = 0.0;
    foreach ($meaningful_signal_keys as $meaningful_signal_key) {
        $meaningful_novelty_multiplier = max(
            $meaningful_novelty_multiplier,
            floatval($positive_signal_multipliers[$meaningful_signal_key] ?? 0)
        );
    }
    $meaningful = $respectful
        && !$coercive
        && !$signals['hostile']
        && !$signals['photo_request']
        && intval($signals['word_count'] ?? 0) >= 8
        && $meaningful_novelty_multiplier > 0
        && $vetted_relational_event;

    $qualified_session_count = max(0, intval(
        array_key_exists('qualified_session_count', $state)
            ? $state['qualified_session_count']
            : aimee_relationship_implied_qualified_sessions(
                intval($state['trust'] ?? 0),
                'guarded'
            )
    ));
    $last_qualified_session_number = max(
        0,
        intval(
            $state['last_qualified_session_number']
            ?? ($qualified_session_count > 0 ? $session_count : 0)
        )
    );
    $new_qualified_session = $meaningful
        && $session_count > $last_qualified_session_number;
    if ($new_qualified_session) {
        $qualified_session_count++;
        $last_qualified_session_number = $session_count;
    }

    // Prevent a single polished sentence from collecting an unsafe stack of
    // overlapping positive signals. Coercion retains its full penalty.
    $positive_caps = [
        'trust' => 2,
        'affection' => 2,
        'chemistry' => 2,
        'safety' => 2,
        'reciprocity' => 2,
        'reliability' => 1,
    ];
    foreach ($positive_caps as $field => $cap) {
        if ($delta[$field] > $cap) {
            $excess = intval($delta[$field]) - intval($cap);
            $delta[$field] = $cap;
            $clip_positive_attribution(
                $field,
                $excess,
                'per_dimension_positive_cap'
            );
        }
    }

    $trust_before = intval($state_before_math['trust'] ?? 0);
    $trust_positive_proposed = max(0, intval($delta['trust'] ?? 0));
    $trust_ceiling = function_exists('aimee_relationship_policy_trust_ceiling')
        ? aimee_relationship_policy_trust_ceiling($qualified_session_count)
        : 100;
    $trust_positive_allowed = max(
        0,
        max($trust_before, $trust_ceiling) - $trust_before
    );
    $trust_positive_applied = min(
        $trust_positive_proposed,
        $trust_positive_allowed
    );
    $trust_positive_clipped = max(
        0,
        $trust_positive_proposed - $trust_positive_applied
    );
    if ($trust_positive_clipped > 0) {
        $delta['trust'] -= $trust_positive_clipped;
        $clip_positive_attribution(
            'trust',
            $trust_positive_clipped,
            'trust_maturity_ceiling'
        );
    }

    foreach ($delta as $field => $change) {
        $before_dimension = intval($state[$field] ?? 0);
        $state[$field] = aimee_relationship_clamp(
            $before_dimension + intval($change)
        );
        $actual_dimension_change = intval($state[$field]) - $before_dimension;
        if ($actual_dimension_change < intval($change) && intval($change) > 0) {
            $clip_positive_attribution(
                $field,
                intval($change) - $actual_dimension_change,
                'dimension_upper_bound'
            );
        } elseif (
            $field === 'frustration'
            && intval($change) < 0
            && $actual_dimension_change > intval($change)
        ) {
            $clip_frustration_relief(
                $actual_dimension_change - intval($change),
                'dimension_lower_bound'
            );
        }
        $delta[$field] = $actual_dimension_change;
    }

    $state['interaction_count'] = $interaction_count;
    $state['meaningful_interaction_count'] = max(
        0,
        intval($state['meaningful_interaction_count'] ?? 0) + ($meaningful ? 1 : 0)
    );
    $state['session_count'] = $session_count;
    $state['qualified_session_count'] = $qualified_session_count;
    $state['last_qualified_session_number'] = $last_qualified_session_number;
    $state['last_session_at'] = $new_session
        ? $now_mysql
        : ($state['last_session_at'] ?? $now_mysql);
    $state['state_version'] = max(0, intval($state['state_version'] ?? 0)) + 1;
    $state['last_message_fingerprint'] = $message_fingerprint;
    $message_history[] = $message_fingerprint;
    $state['message_fingerprint_history'] = array_slice($message_history, -10);
    $state['repeat_streak'] = $repeat_streak;
    $state['last_signal_signature'] = $signal_signature;
    if (!empty($earned_positive_signal_keys)) {
        $signal_history[] = [
            'signals' => $earned_positive_signal_keys,
            'context_fingerprint' => $context_fingerprint,
            'bundle_fingerprint' => $signal_signature,
            'signal_contexts' => array_intersect_key(
                $signal_context_fingerprints,
                array_fill_keys($earned_positive_signal_keys, true)
            ),
        ];
    }
    $state['signal_history'] = array_slice($signal_history, -64);
    $state['signal_repeat_streak'] = $signal_repeat_streak;
    $state['last_interaction_at'] = $now_mysql;

    $proposed_score_after = aimee_relationship_intimacy_score($state);
    $proposed_score_delta = $proposed_score_after - $score_before_math;
    $applied_score_delta = aimee_relationship_policy_cap_score_delta(
        $proposed_score_delta,
        $coercive
    );
    $target_score = max(
        0,
        min(100, $score_before_math + $applied_score_delta)
    );

    // The multidimensional state is authoritative, so enforce the aggregate
    // cap on those dimensions rather than merely clipping the derived scalar.
    $guard = 0;
    $frustration_score_cap_clipped = 0;
    while (
        aimee_relationship_intimacy_score($state) > $target_score
        && $guard++ < 500
    ) {
        $changed = false;
        // Elapsed frustration recovery is not user-earned intimacy. Trim it
        // before relational evidence if the complete turn would exceed +2.
        if (intval($delta['frustration'] ?? 0) < 0) {
            $state['frustration'] = min(
                intval($state_before_math['frustration'] ?? 0),
                intval($state['frustration'] ?? 0) + 1
            );
            $delta['frustration']++;
            $frustration_score_cap_clipped++;
            $clip_frustration_relief(1, 'aggregate_positive_score_cap');
            $changed = true;
        } else {
            foreach (['chemistry', 'affection', 'trust', 'safety'] as $field) {
                if (intval($delta[$field] ?? 0) > 0) {
                    $state[$field] = max(
                        intval($state_before_math[$field] ?? 0),
                        intval($state[$field] ?? 0) - 1
                    );
                    $delta[$field]--;
                    $clip_positive_attribution(
                        $field,
                        1,
                        'aggregate_positive_score_cap'
                    );
                    $changed = true;
                    break;
                }
            }
        }
        if (!$changed) break;
    }
    while (
        aimee_relationship_intimacy_score($state) < $target_score
        && $guard++ < 500
    ) {
        $changed = false;
        if (intval($delta['frustration'] ?? 0) > 0) {
            $state['frustration'] = max(
                intval($state_before_math['frustration'] ?? 0),
                intval($state['frustration'] ?? 0) - 1
            );
            $delta['frustration']--;
            $changed = true;
        } else {
            foreach (['safety', 'trust', 'affection', 'chemistry'] as $field) {
                if (intval($delta[$field] ?? 0) < 0) {
                    $state[$field] = min(
                        intval($state_before_math[$field] ?? 100),
                        intval($state[$field] ?? 0) + 1
                    );
                    $delta[$field]++;
                    $changed = true;
                    break;
                }
            }
        }
        if (!$changed) break;
    }
    $actual_score_delta = aimee_relationship_intimacy_score($state)
        - $score_before_math;

    // Only signals that actually proposed a relationship contribution enter
    // the semantic history. Neutral capability/request turns must not poison a
    // later genuine disclosure merely because they contained similar words.
    $positive_signal_keys = $earned_positive_signal_keys;
    $per_signal_novelty = array_intersect_key(
        $per_signal_novelty,
        array_fill_keys($positive_signal_keys, true)
    );
    $semantic_repeat_count = 0;
    $semantic_novelty_multiplier = 1.0;
    $semantic_signal_count = 0;
    foreach ($positive_signal_keys as $positive_signal_key) {
        if ($positive_signal_key === 'distinct_session') continue;
        $semantic_signal_count++;
        $semantic_repeat_count = max(
            $semantic_repeat_count,
            intval($per_signal_novelty[$positive_signal_key]['repeat_count'] ?? 0)
        );
        $semantic_novelty_multiplier = min(
            $semantic_novelty_multiplier,
            floatval($per_signal_novelty[$positive_signal_key]['multiplier'] ?? 0)
        );
    }
    if ($semantic_signal_count === 0) {
        $semantic_novelty_multiplier = 0.0;
    }

    return [
        'state'   => $state,
        'delta'   => $delta,
        'signals' => $signals,
        'novelty' => [
            'message_fingerprint' => $message_fingerprint,
            'repeat_streak' => $repeat_streak,
            'exact_repeat_count' => intval($exact_novelty['repeat_count'] ?? 0),
            'signal_signature' => $signal_signature,
            'signal_repeat_streak' => $signal_repeat_streak,
            'semantic_repeat_count' => $semantic_repeat_count,
            'multiplier' => $novelty_multiplier,
            'exact_message_multiplier' => $exact_novelty_multiplier,
            'semantic_signal_multiplier' => $semantic_novelty_multiplier,
            'meaningful_signal_multiplier' => $meaningful_novelty_multiplier,
            'positive_signal_keys' => $positive_signal_keys,
            'positive_signal_multipliers' => $positive_signal_multipliers,
            'suppressed_positive_signals' => $suppressed_positive_signals,
            'context_fingerprint' => $context_fingerprint,
            'per_signal' => $per_signal_novelty,
        ],
        'meaningful' => $meaningful,
        'score_delta_proposed' => $proposed_score_delta,
        'score_delta_applied' => $actual_score_delta,
        'score_delta_cap' => $applied_score_delta,
        'score_delta_cap_satisfied' => $actual_score_delta <= 2
            && $actual_score_delta >= ($coercive ? -15 : -8),
        'positive_contributions_proposed' => $positive_contributions,
        'positive_contributions_weighted' => $positive_contributions_weighted,
        'positive_contributions_applied' => $positive_contributions_applied,
        'cap_clipped_contributions' => $cap_clipped_contributions,
        'frustration_score_cap_clipped' => $frustration_score_cap_clipped,
        'frustration_relief_proposed' => $frustration_relief_proposed,
        'frustration_relief_applied' => $frustration_relief_applied,
        'frustration_relief_clipped' => $frustration_relief_clipped,
        'new_session' => $new_session,
        'new_qualified_session' => $new_qualified_session,
        'trust_progression' => [
            'qualified_session_count' => $qualified_session_count,
            'ceiling' => $trust_ceiling,
            'trust_before' => $trust_before,
            'positive_proposed' => $trust_positive_proposed,
            'positive_applied' => max(0, intval($delta['trust'] ?? 0)),
            'positive_clipped' => max(
                0,
                $trust_positive_proposed - max(0, intval($delta['trust'] ?? 0))
            ),
        ],
        'apology_applied' => $apology_applied,
        'boundary_respect_applied' => $boundary_respect_applied,
        'rejected_signals' => array_values(array_filter([
            $signals['apology'] && !$apology_applied ? 'apology_without_eligible_rupture' : '',
            $signals['boundary_respect'] && !$boundary_respect_applied ? 'boundary_respect_without_active_boundary' : '',
            intval($exact_novelty['repeat_count'] ?? 0) >= 2 ? 'exact_repeat_positive_suppressed' : '',
            $semantic_repeat_count >= 2 ? 'semantic_repeat_positive_suppressed' : '',
            $suppressed_positive_signals ? 'one_or_more_positive_signals_suppressed' : '',
            $cap_clipped_contributions ? 'one_or_more_positive_contributions_clipped' : '',
            $frustration_score_cap_clipped > 0 ? 'frustration_recovery_score_cap_clipped' : '',
            !empty($signals['photo_request'])
                && empty($signals['courtship_primary_signal'])
                && empty($signals['substantive_romantic_flirt'])
                    ? 'photo_request_itself_has_no_relationship_credit'
                    : '',
            !empty($signals['payment_leverage']) ? 'payment_leverage_blocks_positive_relationship_credit' : '',
            !empty($signals['score_gaming']) ? 'score_gaming_blocks_positive_relationship_credit' : '',
            $coercive_label && !$coercive ? 'model_only_coercion_not_persisted' : '',
            $trust_positive_clipped > 0 ? 'trust_maturity_ceiling_clipped' : '',
            !$vetted_relational_event ? 'no_vetted_relational_event' : '',
        ])),
    ];
}

function aimee_relationship_intimacy_score($state) {
    $chemistry = floatval($state['chemistry'] ?? 0);
    $affection = floatval($state['affection'] ?? 0);
    $trust = floatval($state['trust'] ?? 0);
    $safety = floatval($state['safety'] ?? 50);
    $frustration = floatval($state['frustration'] ?? 0);

    // Chemistry remains the dominant romantic signal. Affection and trust
    // support it, while low safety and unresolved frustration hold it back.
    $score =
        ($chemistry * 0.65)
        + ($affection * 0.20)
        + ($trust * 0.10)
        + (max(0, $safety - 50) * 0.10)
        + (min(0, $safety - 50) * 0.25)
        - ($frustration * 0.30);

    // Trust and affection can deepen a platonic bond, but they cannot carry the
    // romantic stage indefinitely beyond the chemistry that actually exists.
    $score = min($score, $chemistry + 18);

    return aimee_relationship_clamp($score);
}

function aimee_save_relationship_state($user_id, $state) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id || !is_array($state) || !aimee_relationship_dimensions_table_available()) {
        return false;
    }

    $data = [
        'user_id'             => $user_id,
        'trust'               => aimee_relationship_clamp($state['trust'] ?? 0),
        'affection'           => aimee_relationship_clamp($state['affection'] ?? 0),
        'chemistry'           => aimee_relationship_clamp($state['chemistry'] ?? 0),
        'safety'              => aimee_relationship_clamp($state['safety'] ?? 0),
        'reciprocity'         => aimee_relationship_clamp($state['reciprocity'] ?? 0),
        'reliability'         => aimee_relationship_clamp($state['reliability'] ?? 0),
        'frustration'         => aimee_relationship_clamp($state['frustration'] ?? 0),
        'interaction_count'   => max(0, intval($state['interaction_count'] ?? 0)),
        'meaningful_interaction_count' => max(0, intval($state['meaningful_interaction_count'] ?? 0)),
        'session_count'       => max(0, intval($state['session_count'] ?? 0)),
        'qualified_session_count' => max(
            0,
            intval($state['qualified_session_count'] ?? 0)
        ),
        'last_qualified_session_number' => max(
            0,
            intval($state['last_qualified_session_number'] ?? 0)
        ),
        'last_session_at'     => !empty($state['last_session_at'])
            ? (string) $state['last_session_at']
            : null,
        'state_version'       => max(0, intval($state['state_version'] ?? 0)),
        'last_message_fingerprint' => !empty($state['last_message_fingerprint'])
            ? (string) $state['last_message_fingerprint']
            : null,
        'message_fingerprint_history_json' => wp_json_encode(array_slice(
            array_values((array) ($state['message_fingerprint_history'] ?? [])),
            -10
        )),
        'repeat_streak'       => max(0, intval($state['repeat_streak'] ?? 0)),
        'last_signal_signature' => !empty($state['last_signal_signature'])
            ? (string) $state['last_signal_signature']
            : null,
        'signal_history_json' => wp_json_encode(array_slice(
            array_values((array) ($state['signal_history'] ?? [])),
            -64
        )),
        'signal_repeat_streak' => max(0, intval($state['signal_repeat_streak'] ?? 0)),
        'last_interaction_at' => (string) ($state['last_interaction_at'] ?? current_time('mysql', true)),
        'updated_at'          => current_time('mysql', true),
    ];

    $formats = [
        '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d', '%d',
        '%d', '%d', '%d', '%s', '%d', '%s', '%s', '%d', '%s', '%s',
        '%d', '%s', '%s',
    ];

    $expected_version = max(0, intval($data['state_version']) - 1);
    $update_data = $data;
    $update_formats = $formats;
    unset($update_data['user_id']);
    array_shift($update_formats);

    $updated = $wpdb->update(
        aimee_relationship_dimensions_table(),
        $update_data,
        ['user_id' => $user_id, 'state_version' => $expected_version],
        $update_formats,
        ['%d', '%d']
    );

    if ($updated === 1) return true;

    $existing = intval($wpdb->get_var($wpdb->prepare(
        'SELECT COUNT(*) FROM ' . aimee_relationship_dimensions_table() . ' WHERE user_id = %d',
        $user_id
    )));

    if ($existing > 0) {
        error_log(sprintf(
            'Aimee relationship state conflict: user=%d expected_version=%d',
            $user_id,
            $expected_version
        ));
        return false;
    }

    $data['created_at'] = current_time('mysql', true);
    $formats[] = '%s';

    return $wpdb->insert(
        aimee_relationship_dimensions_table(),
        $data,
        $formats
    ) !== false;
}

function aimee_relationship_decision_store(
    $decision_id,
    $user_id,
    $user_message_id,
    $request_id,
    $raw_classification,
    $classification,
    $intimacy,
    $actual_route,
    $actual_model,
    $actual_provider = '',
    $state_commit_status = 'unknown',
    $media_decision_id = '',
    $consumed_invitation_token_id = '',
    $issued_invitation_token_id = ''
) {
    global $wpdb;

    $now = current_time('mysql', true);
    $before = is_array($intimacy['relationship_before_state'] ?? null)
        ? $intimacy['relationship_before_state']
        : [];
    $after = is_array($intimacy['relationship_state'] ?? null)
        ? $intimacy['relationship_state']
        : [];
    $route_decision_snapshot = (array) ($intimacy['route_decision'] ?? []);
    $route_decision_snapshot['score_audit'] = [
        'reducer_proposed_delta' => intval(
            $intimacy['score_delta_reducer_proposed']
            ?? $intimacy['score_delta_proposed']
            ?? 0
        ),
        'reducer_applied_delta' => intval(
            $intimacy['score_delta_reducer_applied']
            ?? $intimacy['score_delta_applied']
            ?? 0
        ),
        'appraisal_proposed_delta' => (array) (
            $intimacy['relational_appraisal_delta_proposed'] ?? []
        ),
        'appraisal_applied_delta' => (array) (
            $intimacy['relational_appraisal_delta_applied'] ?? []
        ),
        'total_proposed_score_delta' => intval(
            $intimacy['score_delta_proposed'] ?? 0
        ),
        'total_applied_score_delta' => intval(
            $intimacy['score_delta_applied'] ?? 0
        ),
        'aggregate_score_cap' => intval($intimacy['score_delta_cap'] ?? 0),
        'aggregate_score_cap_satisfied' => !empty(
            $intimacy['score_delta_cap_satisfied']
        ),
        'positive_contributions_proposed' => (array) (
            $intimacy['relationship_contributions_proposed'] ?? []
        ),
        'positive_contributions_weighted' => (array) (
            $intimacy['relationship_contributions_weighted'] ?? []
        ),
        'positive_contributions_applied' => (array) (
            $intimacy['relationship_contributions_applied'] ?? []
        ),
        'positive_contributions_clipped' => (array) (
            $intimacy['relationship_contributions_clipped'] ?? []
        ),
        'frustration_score_cap_clipped' => intval(
            $intimacy['frustration_score_cap_clipped'] ?? 0
        ),
        'frustration_relief_proposed' => (array) (
            $intimacy['frustration_relief_proposed'] ?? []
        ),
        'frustration_relief_applied' => (array) (
            $intimacy['frustration_relief_applied'] ?? []
        ),
        'frustration_relief_clipped' => (array) (
            $intimacy['frustration_relief_clipped'] ?? []
        ),
        'trust_progression' => (array) (
            $intimacy['trust_progression'] ?? []
        ),
    ];

    $inserted = $wpdb->insert(
        aimee_table('aimee_relationship_decisions'),
        [
            'decision_id'          => sanitize_text_field((string) $decision_id),
            'user_id'              => intval($user_id),
            'request_id'           => sanitize_text_field((string) $request_id),
            'user_message_id'      => intval($user_message_id) ?: null,
            'policy_version'       => function_exists('aimee_relationship_policy_version')
                ? aimee_relationship_policy_version()
                : AIMEE_GLOBAL_VERSION,
            'math_source'          => sanitize_key((string) ($intimacy['math_source'] ?? 'unknown')),
            'classifier_source'    => sanitize_key((string) ($classification['source'] ?? 'unknown')),
            'classifier_json'      => wp_json_encode([
                'raw' => is_array($raw_classification) ? $raw_classification : [],
                'corrected' => is_array($classification) ? $classification : [],
            ]),
            'state_before_json'    => wp_json_encode($before),
            'matched_signals_json' => wp_json_encode((array) ($intimacy['relationship_signals'] ?? [])),
            'applied_delta_json'   => wp_json_encode((array) ($intimacy['relationship_delta'] ?? [])),
            'rejected_signals_json'=> wp_json_encode((array) ($intimacy['rejected_signals'] ?? [])),
            'state_after_json'     => wp_json_encode($after),
            'score_before'         => intval($intimacy['score_before'] ?? 0),
            'score_after'          => intval($intimacy['score'] ?? 0),
            'stage_before'         => sanitize_key((string) ($intimacy['stage_before'] ?? 'guarded')),
            'stage_after'          => sanitize_key((string) ($intimacy['stage'] ?? 'guarded')),
            'route_decision_json'  => wp_json_encode($route_decision_snapshot),
            'actual_route'         => sanitize_key((string) $actual_route),
            'actual_model'         => sanitize_text_field((string) $actual_model),
            'actual_provider'      => sanitize_text_field((string) $actual_provider) ?: null,
            'model_attempts_json'  => wp_json_encode([]),
            'state_commit_status'  => sanitize_key((string) $state_commit_status) ?: 'unknown',
            'media_decision_id'    => sanitize_text_field((string) $media_decision_id) ?: null,
            'consumed_invitation_token_id' => sanitize_text_field(
                (string) $consumed_invitation_token_id
            ) ?: null,
            'issued_invitation_token_id' => sanitize_text_field(
                (string) $issued_invitation_token_id
            ) ?: null,
            'score_delta_proposed' => intval($intimacy['score_delta_proposed'] ?? 0),
            'score_delta_applied'  => intval($intimacy['score_delta_applied'] ?? 0),
            'created_at'           => $now,
            'updated_at'           => $now,
        ]
    );

    if ($inserted === false) {
        error_log('Aimee relationship decision persistence failed: ' . (string) $wpdb->last_error);
    }

    return $inserted !== false;
}

function aimee_relationship_decision_update_outcome(
    $decision_id,
    $actual_route,
    $actual_model,
    $actual_provider,
    $media_decision_id = '',
    $consumed_invitation_token_id = '',
    $issued_invitation_token_id = '',
    $model_attempts = []
) {
    global $wpdb;

    return $wpdb->update(
        aimee_table('aimee_relationship_decisions'),
        [
            'actual_route' => sanitize_key((string) $actual_route),
            'actual_model' => sanitize_text_field((string) $actual_model) ?: null,
            'actual_provider' => sanitize_text_field((string) $actual_provider) ?: null,
            'model_attempts_json' => wp_json_encode(
                is_array($model_attempts) ? array_values($model_attempts) : []
            ),
            'media_decision_id' => sanitize_text_field((string) $media_decision_id) ?: null,
            'consumed_invitation_token_id' => sanitize_text_field(
                (string) $consumed_invitation_token_id
            ) ?: null,
            'issued_invitation_token_id' => sanitize_text_field(
                (string) $issued_invitation_token_id
            ) ?: null,
            'updated_at' => current_time('mysql', true),
        ],
        ['decision_id' => sanitize_text_field((string) $decision_id)],
        ['%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s'],
        ['%s']
    ) === 1;
}

/**
 * Append privacy-safe evidence for every response-model call made by a turn.
 *
 * The configured candidate list is not represented as an actually engaged
 * model. `actual_model` remains empty when a provider failure did not identify
 * which candidate it selected. No prompt, message text or model output is
 * retained in this audit object.
 */
function aimee_model_attempt_audit_add(
    array &$attempts,
    $purpose,
    $route,
    $provider,
    $configured_models,
    $actual_model = '',
    $actual_provider = '',
    $status = 'response_received',
    $details = []
) {
    $configured_models = is_array($configured_models)
        ? $configured_models
        : [(string) $configured_models];
    $configured_models = array_values(array_unique(array_filter(array_map(
        static function ($model) {
            return sanitize_text_field(trim((string) $model));
        },
        $configured_models
    ))));
    $details = is_array($details) ? $details : [];

    $attempts[] = [
        'ordinal' => count($attempts) + 1,
        'purpose' => sanitize_key((string) $purpose),
        'route' => sanitize_key((string) $route),
        'provider' => sanitize_key((string) $provider),
        'configured_models' => $configured_models,
        'actual_model' => sanitize_text_field((string) $actual_model) ?: null,
        'actual_provider' => sanitize_text_field((string) $actual_provider) ?: null,
        'status' => sanitize_key((string) $status) ?: 'unknown',
        'http_status' => max(0, intval($details['http_status'] ?? 0)),
        'error_type' => sanitize_key((string) ($details['error_type'] ?? '')) ?: null,
    ];

    return end($attempts);
}

function aimee_model_attempt_status_from_raw_response($raw_response) {
    $raw_response = (string) $raw_response;
    if (
        stripos($raw_response, 'System error') !== false
        || stripos($raw_response, 'Anthropic API Error') !== false
    ) {
        return 'provider_error';
    }

    return trim($raw_response) !== '' ? 'response_received' : 'empty_response';
}

function aimee_relationship_invitations_table() {
    return aimee_table('aimee_relationship_invitations');
}

function aimee_reply_contains_relationship_invitation($reply, $type) {
    $reply = mb_strtolower(trim((string) $reply));
    $type = sanitize_key((string) $type);
    if ($reply === '') return false;

    if ($type === 'explicit') {
        return preg_match(
            '/\b(?:i want you to|tell me what you(?:\'d| would) do|come closer|'
            . 'keep going|don\'t stop|dont stop|touch me|show me how much|'
            . 'i want to hear it|your turn)\b/u',
            $reply
        ) === 1;
    }

    if ($type === 'suggestive') {
        return preg_match(
            '/\b(?:come a little closer|flirt with me|tell me what you like|'
            . 'you can be honest with me|shall we make this more interesting|'
            . 'your turn to tease me)\b/u',
            $reply
        ) === 1;
    }

    return false;
}

function aimee_create_relationship_invitation(
    $user_id,
    $source_message_id,
    $type,
    $reply,
    $profile,
    $intimacy,
    $route,
    $classification = []
) {
    global $wpdb;

    $user_id = intval($user_id);
    $source_message_id = intval($source_message_id);
    $type = sanitize_key((string) $type);
    if (
        !$user_id
        || !$source_message_id
        || !in_array($type, ['suggestive', 'explicit'], true)
        || !aimee_reply_contains_relationship_invitation($reply, $type)
        || intval($profile->age ?? 0) < 18
    ) {
        return '';
    }

    $score = intval($intimacy['score'] ?? 0);
    $stage = (string) ($intimacy['stage'] ?? 'guarded');
    $trust = intval($intimacy['trust'] ?? 0);
    $chemistry = intval($intimacy['chemistry'] ?? 0);
    $safety = intval($intimacy['safety'] ?? 0);
    $frustration = intval($intimacy['frustration'] ?? 100);
    $meaningful = intval($intimacy['meaningful_interaction_count'] ?? 0);
    $sessions = intval(
        $intimacy['qualified_session_count']
        ?? $intimacy['session_count']
        ?? 0
    );
    $intent = (string) ($classification['intent'] ?? 'general');
    $mutual_turn = in_array(
        $intent,
        ['romantic_or_flirty', 'explicit_invitation', 'explicit_continuation'],
        true
    )
        && !empty($classification['directed_at_aimee'])
        && !empty($classification['consensual'])
        && !empty($classification['respectful'])
        && floatval($classification['confidence'] ?? 0) >= 0.64;
    $rupture = !empty($intimacy['active_rupture'])
        || !empty($intimacy['unresolved_rupture'])
        || in_array(
            sanitize_key((string) ($intimacy['repair_status'] ?? 'clear')),
            ['ruptured', 'repairing'],
            true
        );
    if (
        $type === 'suggestive'
        && (
            $score < 62
            || aimee_media_stage_rank($stage) < aimee_media_stage_rank('intimate')
            || $trust < 48
            || $chemistry < 54
            || $safety < 52
            || $frustration > 28
            || !$mutual_turn
            || $rupture
        )
    ) {
        return '';
    }
    if (
        $type === 'explicit'
        && (
            $score < 65
            || aimee_media_stage_rank($stage) < aimee_media_stage_rank('intimate')
            || $trust < 50
            || $chemistry < 60
            || $safety < 55
            || $frustration > 20
            || $meaningful < 20
            || $sessions < 3
            || !$mutual_turn
            || $rupture
            || !in_array($route, ['primary', 'intimacy_specialist'], true)
            || !aimee_subscription_is_active($profile)
        )
    ) {
        return '';
    }

    $expected_state_version = max(0, intval($intimacy['state_version'] ?? 0));
    if (
        $expected_state_version < 1
        || !aimee_relationship_dimensions_table_available()
        || $wpdb->query('START TRANSACTION') === false
    ) {
        return '';
    }

    $now = current_time('mysql', true);
    $expires = gmdate('Y-m-d H:i:s', time() + HOUR_IN_SECONDS);
    $conversation_id = 'user-' . $user_id;
    $token_id = aimee_media_state_uuid();
    $created = false;

    do {
        // Revalidate at creation time after the reply provider returns. Lock
        // in live-turn order (inner -> invitation -> dimensions), preventing
        // a stale pre-rupture reply from inserting a token after a concurrent
        // coercive turn has revoked invitations.
        $wpdb->get_row($wpdb->prepare(
            "SELECT user_id FROM `aimee_inner_state` WHERE user_id = %d FOR UPDATE",
            $user_id
        ));

        // A newer invitation supersedes an unconsumed older one. Taking this
        // lock before dimensions matches the durable-rupture path.
        $revoked = $wpdb->query($wpdb->prepare(
            'UPDATE ' . aimee_relationship_invitations_table()
            . " SET status = 'revoked', revoked_at = %s"
            . " WHERE user_id = %d AND status = 'active'"
            . ' AND consumed_at IS NULL AND revoked_at IS NULL',
            $now,
            $user_id
        ));
        if ($revoked === false) break;

        $current_state_version = intval($wpdb->get_var($wpdb->prepare(
            'SELECT state_version FROM '
            . aimee_relationship_dimensions_table()
            . ' WHERE user_id = %d FOR UPDATE',
            $user_id
        )));
        if ($current_state_version !== $expected_state_version) break;

        $fresh_inner = aimee_load_inner_state($user_id, false);
        if (
            !empty($fresh_inner['unresolved_rupture'])
            || in_array(
                sanitize_key((string) ($fresh_inner['repair_status'] ?? 'clear')),
                ['ruptured', 'repairing'],
                true
            )
        ) {
            break;
        }

        $inserted = $wpdb->insert(
            aimee_relationship_invitations_table(),
            [
                'token_id' => $token_id,
                'user_id' => $user_id,
                'conversation_id' => $conversation_id,
                'issued_by' => 'aimee',
                'invitation_type' => $type,
                'max_rating' => $type === 'explicit' ? 'explicit' : 'suggestive',
                'source_message_id' => $source_message_id,
                'status' => 'active',
                'issued_at' => $now,
                'expires_at' => $expires,
            ]
        );
        if ($inserted === false) break;
        $created = true;
    } while (false);

    if ($created && $wpdb->query('COMMIT') !== false) return $token_id;

    $wpdb->query('ROLLBACK');
    return '';
}

function aimee_revoke_relationship_invitation($token_id) {
    global $wpdb;

    $token_id = sanitize_text_field((string) $token_id);
    if ($token_id === '') return false;

    return $wpdb->update(
        aimee_relationship_invitations_table(),
        [
            'status' => 'revoked',
            'revoked_at' => current_time('mysql', true),
        ],
        [
            'token_id' => $token_id,
            'status' => 'active',
        ],
        ['%s', '%s'],
        ['%s', '%s']
    ) === 1;
}

/** Revoke every still-active invitation after a confirmed durable rupture. */
function aimee_revoke_active_relationship_invitations_for_user($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if ($user_id < 1) return false;

    return $wpdb->query($wpdb->prepare(
        'UPDATE ' . aimee_relationship_invitations_table()
        . " SET status = 'revoked', revoked_at = %s"
        . " WHERE user_id = %d AND status = 'active'"
        . ' AND consumed_at IS NULL AND revoked_at IS NULL',
        current_time('mysql', true),
        $user_id
    )) !== false;
}

function aimee_active_relationship_invitation($user_id, $required_type = 'explicit') {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return null;
    $row = $wpdb->get_row($wpdb->prepare(
        'SELECT * FROM ' . aimee_relationship_invitations_table()
        . " WHERE user_id = %d AND status = 'active'"
        . ' AND consumed_at IS NULL AND revoked_at IS NULL'
        . ' AND expires_at > %s ORDER BY issued_at DESC, id DESC LIMIT 1',
        $user_id,
        current_time('mysql', true)
    ), ARRAY_A);
    if (!is_array($row)) return null;

    $message_pk = aimee_messages_primary_key();
    $last_aimee_message_id = intval($wpdb->get_var($wpdb->prepare(
        "SELECT `{$message_pk}` FROM " . aimee_table('aimee_messages')
        . " WHERE user_id = %d AND sender = 'aimee'"
        . " ORDER BY created_at DESC, `{$message_pk}` DESC LIMIT 1",
        $user_id
    )));
    if ($last_aimee_message_id !== intval($row['source_message_id'] ?? 0)) {
        return null;
    }

    $validation = aimee_relationship_policy_validate_invitation_token(
        $row,
        [
            'server_trusted' => true,
            'user_id' => $user_id,
            'conversation_id' => 'user-' . $user_id,
            'required_type' => $required_type,
            'now' => time(),
        ]
    );

    return !empty($validation['valid']) ? $validation['token'] : null;
}

function aimee_consume_relationship_invitation($token_id, $user_id, $request_id) {
    global $wpdb;
    $token_id = sanitize_text_field((string) $token_id);
    if ($token_id === '') return false;

    return $wpdb->update(
        aimee_relationship_invitations_table(),
        [
            'status' => 'consumed',
            'consumed_at' => current_time('mysql', true),
            'consumed_by_request_id' => sanitize_text_field((string) $request_id),
        ],
        [
            'token_id' => $token_id,
            'user_id' => intval($user_id),
            'status' => 'active',
        ],
        ['%s', '%s', '%s'],
        ['%s', '%d', '%s']
    ) === 1;
}

function aimee_ground_classifier_invitation($classification, $recent_history = '', $user_id = 0) {
    $classification = is_array($classification) ? $classification : [];
    $classification['grounded_aimee_invitation'] = false;
    $classification['grounded_invitation_token_id'] = '';
    $classification['aimee_invited'] = false;

    $token = aimee_active_relationship_invitation($user_id, 'explicit');
    if (!is_array($token)) return $classification;

    $classification['grounded_aimee_invitation'] = true;
    $classification['grounded_invitation_token_id'] = sanitize_text_field(
        (string) ($token['token_id'] ?? '')
    );
    $classification['aimee_invited'] = true;
    return $classification;
}

function aimee_explicit_mutual_context($classification, $recent_history = '') {
    $intent = (string) ($classification['intent'] ?? 'general');
    if (!in_array($intent, ['explicit_invitation', 'explicit_continuation'], true)) {
        return false;
    }

    return !empty($classification['grounded_aimee_invitation'])
        && !empty($classification['grounded_invitation_token_id']);
}

function aimee_relationship_specialist_decision(
    $profile,
    $intimacy,
    $classification,
    $recent_history = '',
    $inner_state = []
) {
    $state = is_array($intimacy) ? $intimacy : [];
    $inner_state = is_array($inner_state) ? $inner_state : [];
    $adult_state = aimee_adult_assurance_state($profile);
    $special_category_consent = $profile
        && function_exists('aimee_special_category_consent_is_active')
        && aimee_special_category_consent_is_active($profile);
    $verified_adult_with_consent = $adult_state === 'verified'
        && $special_category_consent;
    $intent = (string) ($classification['intent'] ?? 'general');
    $surface_eligible = in_array(
        $intent,
        ['explicit_invitation', 'explicit_continuation'],
        true
    )
        && !empty($classification['directed_at_aimee'])
        && !empty($classification['consensual'])
        && !empty($classification['respectful'])
        && floatval($classification['confidence'] ?? 0) >= 0.64;

    $mutual_context = $surface_eligible
        && aimee_explicit_mutual_context($classification, $recent_history);
    $rupture_active = !empty($inner_state['unresolved_rupture'])
        || in_array(
            sanitize_key((string) ($inner_state['repair_status'] ?? 'clear')),
            ['ruptured', 'repairing'],
            true
        );

    $decision = aimee_relationship_policy_specialist_route_decision(
        [
            'score' => intval($state['score'] ?? 0),
            'chemistry' => intval($state['chemistry'] ?? 0),
            'trust' => intval($state['trust'] ?? 0),
            'safety' => intval($state['safety'] ?? 0),
            'frustration' => intval($state['frustration'] ?? 100),
            'reciprocity' => intval($state['reciprocity'] ?? 0),
            'reliability' => intval($state['reliability'] ?? 0),
            'meaningful_interactions' => intval($state['meaningful_interaction_count'] ?? 0),
            'distinct_sessions' => intval(
                $state['qualified_session_count']
                ?? $state['session_count']
                ?? 0
            ),
        ],
        [
            // Specialist text fails closed unless age assurance is verified
            // and the current special-category processing consent is stored.
            'adult_account' => $verified_adult_with_consent,
            'adult_verified' => $verified_adult_with_consent,
            'special_category_consent' => $special_category_consent,
            'active_access' => $profile && (
                aimee_subscription_is_active($profile)
                || aimee_is_admin_user($profile)
            ),
            'explicit_mutual_context' => $mutual_context,
            'rupture_active' => $rupture_active,
            'unresolved_rupture' => (string) ($inner_state['unresolved_rupture'] ?? ''),
            'repair_status' => (string) ($inner_state['repair_status'] ?? 'clear'),
        ]
    );

    if (!$surface_eligible) {
        $decision['eligible'] = false;
        $decision['route'] = 'primary';
        $decision['gates']['current_explicit_turn'] = [
            'passed' => false,
            'failure_reason' => 'current_explicit_turn_not_eligible',
            'observed' => $intent,
            'required' => 'respectful_consensual_explicit_turn',
        ];
        $decision['failed_gate_reasons'][] = 'current_explicit_turn_not_eligible';
        $decision['failed_gate_reasons'] = array_values(array_unique(
            $decision['failed_gate_reasons']
        ));
    } else {
        $decision['gates']['current_explicit_turn'] = [
            'passed' => true,
            'failure_reason' => null,
            'observed' => $intent,
            'required' => 'respectful_consensual_explicit_turn',
        ];
    }

    $decision['adult_assurance'] = $adult_state;
    $decision['special_category_consent'] = $special_category_consent;
    return $decision;
}

function aimee_calculate_intimacy_state($profile, $ledger, $classification, $user_text, $user_message_count, $recent_history = '') {
    $current_score = max(0, min(100, intval($profile->intimacy_score ?? 8)));
    $current_stage = (string) ($profile->intimacy_stage ?? aimee_stage_from_score($current_score));
    $classification = aimee_ground_classifier_invitation(
        $classification,
        $recent_history,
        intval($profile->user_id ?? 0)
    );
    $classification['mutual_explicit_context'] = aimee_explicit_mutual_context(
        $classification,
        $recent_history
    );

    if (aimee_relationship_dimensions_table_available()) {
        $loaded_state = aimee_load_relationship_state($profile);
        $score_before_computed = aimee_relationship_intimacy_score($loaded_state);
        $math = aimee_apply_quiet_relationship_math(
            $loaded_state,
            $classification,
            $user_text,
            $recent_history
        );

        $relationship_state = $math['state'];
        $score = aimee_relationship_intimacy_score($relationship_state);
        $math_source = 'multidimensional';
    } else {
        $loaded_state = null;
        $score_before_computed = $current_score;
        // Degraded mode is deliberately non-progressive. A missing relationship
        // table must never create a faster, lower-trust route than production.
        $score = $current_score;
        $intent = (string) ($classification['intent'] ?? 'general');
        $durable_coercion = function_exists('aimee_relationship_policy_durable_coercion_confirmed')
            && aimee_relationship_policy_durable_coercion_confirmed($classification);
        if ($durable_coercion) $score -= 15;

        $score = max(0, min(100, intval($score)));
        $relationship_state = null;
        $math = [
            'delta' => [],
            'signals' => [],
            'novelty' => [],
            'rejected_signals' => ['relationship_table_unavailable'],
        ];
        $math_source = 'degraded_safe_fallback';
    }

    $chemistry = is_array($relationship_state)
        ? intval($relationship_state['chemistry'] ?? $score)
        : 0;
    $safety = is_array($relationship_state)
        ? intval($relationship_state['safety'] ?? 50)
        : 0;
    $trust = is_array($relationship_state)
        ? intval($relationship_state['trust'] ?? $score)
        : 0;
    $frustration = is_array($relationship_state)
        ? intval($relationship_state['frustration'] ?? 0)
        : 100;
    $stage = is_array($relationship_state)
        ? aimee_stage_from_relationship_state(
            $score,
            $relationship_state,
            $current_stage
        )
        : $current_stage;

    $intimacy_for_route = [
        'score' => $score,
        'stage' => $stage,
        'trust' => $trust,
        'affection' => is_array($relationship_state)
            ? intval($relationship_state['affection'] ?? 0)
            : 0,
        'chemistry' => $chemistry,
        'safety' => $safety,
        'reciprocity' => is_array($relationship_state)
            ? intval($relationship_state['reciprocity'] ?? 0)
            : 0,
        'reliability' => is_array($relationship_state)
            ? intval($relationship_state['reliability'] ?? 0)
            : 0,
        'frustration' => $frustration,
        'meaningful_interaction_count' => is_array($relationship_state)
            ? intval($relationship_state['meaningful_interaction_count'] ?? 0)
            : 0,
        'session_count' => is_array($relationship_state)
            ? intval($relationship_state['session_count'] ?? 0)
            : 0,
        'qualified_session_count' => is_array($relationship_state)
            ? intval($relationship_state['qualified_session_count'] ?? 0)
            : 0,
    ];
    $inner_state = function_exists('aimee_load_inner_state')
        ? aimee_load_inner_state(intval($profile->user_id ?? 0))
        : [];
    $route_decision = is_array($relationship_state)
        ? aimee_relationship_specialist_decision(
            $profile,
            $intimacy_for_route,
            $classification,
            $recent_history,
            $inner_state
        )
        : [
            'policy_version' => aimee_relationship_policy_version(),
            'eligible' => false,
            'route' => 'primary',
            'failed_gate_reasons' => ['relationship_table_unavailable'],
            'gates' => [],
            'adult_assurance' => aimee_adult_assurance_state($profile),
        ];
    $use_intimacy_model = !empty($route_decision['eligible']);

    return [
        'score'               => $score,
        'stage'               => $stage,
        'use_intimacy_model'  => $use_intimacy_model,
        'trust'               => $trust,
        'affection'           => is_array($relationship_state) ? intval($relationship_state['affection'] ?? $score) : $score,
        'chemistry'           => $chemistry,
        'safety'              => $safety,
        'reciprocity'         => is_array($relationship_state) ? intval($relationship_state['reciprocity'] ?? 50) : 50,
        'reliability'         => is_array($relationship_state) ? intval($relationship_state['reliability'] ?? 50) : 50,
        'frustration'         => $frustration,
        'interaction_count'   => is_array($relationship_state) ? intval($relationship_state['interaction_count'] ?? 0) : 0,
        'meaningful_interaction_count' => $intimacy_for_route['meaningful_interaction_count'],
        'session_count'       => $intimacy_for_route['session_count'],
        'qualified_session_count' => $intimacy_for_route['qualified_session_count'],
        'state_version'       => is_array($relationship_state) ? intval($relationship_state['state_version'] ?? 0) : 0,
        'relationship_state'  => $relationship_state,
        'relationship_before_state' => $loaded_state,
        'relationship_delta'  => $math['delta'] ?? [],
        'relationship_contributions_proposed' => $math['positive_contributions_proposed'] ?? [],
        'relationship_contributions_weighted' => $math['positive_contributions_weighted'] ?? [],
        'relationship_contributions_applied' => $math['positive_contributions_applied'] ?? [],
        'relationship_contributions_clipped' => $math['cap_clipped_contributions'] ?? [],
        'frustration_score_cap_clipped' => intval($math['frustration_score_cap_clipped'] ?? 0),
        'frustration_relief_proposed' => $math['frustration_relief_proposed'] ?? [],
        'frustration_relief_applied' => $math['frustration_relief_applied'] ?? [],
        'frustration_relief_clipped' => $math['frustration_relief_clipped'] ?? [],
        'score_delta_proposed'=> intval($math['score_delta_proposed'] ?? 0),
        'score_delta_applied' => intval($math['score_delta_applied'] ?? 0),
        'score_delta_reducer_proposed' => intval($math['score_delta_proposed'] ?? 0),
        'score_delta_reducer_applied' => intval($math['score_delta_applied'] ?? 0),
        'score_delta_cap'     => intval($math['score_delta_cap'] ?? 0),
        'score_delta_cap_satisfied' => !empty($math['score_delta_cap_satisfied']),
        'relationship_signals'=> $math['signals'] ?? [],
        'relationship_novelty'=> $math['novelty'] ?? [],
        'trust_progression'   => $math['trust_progression'] ?? [],
        'rejected_signals'    => $math['rejected_signals'] ?? [],
        'score_before'        => $score_before_computed,
        'stage_before'        => $current_stage,
        'route_decision'      => $route_decision,
        'classifier_for_relationship' => $classification,
        'math_source'         => $math_source,
    ];
}

function aimee_verify_stripe_signature($payload, $signature_header) {
    $secret = defined('STRIPE_WEBHOOK_SECRET') ? STRIPE_WEBHOOK_SECRET : '';
    if (empty($secret) || empty($signature_header)) return false;

    $timestamp = null;
    $signatures = [];

    foreach (explode(',', $signature_header) as $part) {
        $pair = array_map('trim', explode('=', $part, 2));
        if (count($pair) !== 2) continue;
        if ($pair[0] === 't') $timestamp = intval($pair[1]);
        if ($pair[0] === 'v1') $signatures[] = $pair[1];
    }

    if (!$timestamp || abs(time() - $timestamp) > 300 || empty($signatures)) return false;

    $expected = hash_hmac('sha256', $timestamp . '.' . $payload, $secret);
    foreach ($signatures as $signature) {
        if (hash_equals($expected, $signature)) return true;
    }
    return false;
}

function aimee_stripe_request($method, $path, $body = [], $idempotency_key = '') {
    $secret = defined('STRIPE_SECRET_KEY') ? STRIPE_SECRET_KEY : '';
    if (empty($secret)) return new WP_Error('stripe_missing_key', 'Stripe is not configured.');

    $args = [
        'method'  => strtoupper($method),
        'headers' => ['Authorization' => 'Bearer ' . $secret],
        'timeout' => 20,
    ];

    $idempotency_key = trim((string) $idempotency_key);
    if ($idempotency_key !== '') {
        $args['headers']['Idempotency-Key'] = substr($idempotency_key, 0, 255);
    }

    if (!empty($body)) $args['body'] = $body;

    $response = wp_remote_request('https://api.stripe.com/v1/' . ltrim($path, '/'), $args);
    if (is_wp_error($response)) return $response;

    $status = wp_remote_retrieve_response_code($response);
    $data   = json_decode(wp_remote_retrieve_body($response), true);

    if ($status < 200 || $status >= 300) {
        return new WP_Error(
            'stripe_api_error',
            $data['error']['message'] ?? 'Stripe request failed.',
            ['status' => $status]
        );
    }

    return is_array($data) ? $data : [];
}

/**
 * Bind the configured secret to the explicitly configured replacement Stripe
 * account before any new checkout is created. This is a read-only identity
 * check and fails closed when the account ID has not been configured.
 */
function aimee_validate_replacement_stripe_account() {
    $expected = defined('AIMEE_STRIPE_ACCOUNT_ID')
        ? trim((string) AIMEE_STRIPE_ACCOUNT_ID)
        : '';
    if ($expected === '' || strpos($expected, 'acct_') !== 0) {
        return new WP_Error(
            'stripe_account_identity_missing',
            'The replacement Stripe account identity has not been configured.'
        );
    }

    $secret = defined('STRIPE_SECRET_KEY') ? trim((string) STRIPE_SECRET_KEY) : '';
    $cache_key = 'aimee_stripe_identity_' . substr(hash('sha256', $expected . '|' . $secret), 0, 24);
    if (function_exists('get_transient') && get_transient($cache_key) === 'verified') return true;

    $account = aimee_stripe_request('GET', 'account');
    if (is_wp_error($account)) return $account;
    $actual = trim((string) ($account['id'] ?? ''));
    if ($actual === '' || !hash_equals($expected, $actual)) {
        return new WP_Error(
            'stripe_account_identity_mismatch',
            'The configured Stripe secret does not belong to the approved replacement account.'
        );
    }

    if (function_exists('set_transient')) set_transient($cache_key, 'verified', 15 * MINUTE_IN_SECONDS);
    return true;
}

function aimee_stripe_subscription_is_verified_terminal($subscription, $expected_id) {
    if (!is_array($subscription)) return false;
    $actual_id = sanitize_text_field((string) ($subscription['id'] ?? ''));
    $expected_id = sanitize_text_field((string) $expected_id);
    if ($actual_id === '' || $expected_id === '' || !hash_equals($expected_id, $actual_id)) {
        return false;
    }
    return in_array(
        sanitize_key((string) ($subscription['status'] ?? '')),
        ['canceled', 'cancelled', 'incomplete_expired'],
        true
    );
}

/**
 * Cancel a Stripe subscription now and prove the exact remote identity reached
 * a terminal state. A transport 2xx, empty body or 404 is not proof that the
 * recurring authority owned by this profile is gone.
 */
function aimee_cancel_stripe_subscription_verified($subscription_id) {
    $subscription_id = sanitize_text_field((string) $subscription_id);
    if ($subscription_id === '') {
        return new WP_Error('stripe_subscription_missing', 'The Stripe subscription identity is missing.');
    }

    $existing = aimee_stripe_request(
        'GET',
        'subscriptions/' . rawurlencode($subscription_id)
    );
    if (is_wp_error($existing)) return $existing;
    if (aimee_stripe_subscription_is_verified_terminal($existing, $subscription_id)) return true;
    if (
        !is_array($existing)
        || !hash_equals($subscription_id, sanitize_text_field((string) ($existing['id'] ?? '')))
    ) {
        return new WP_Error(
            'stripe_subscription_identity_mismatch',
            'The Stripe subscription identity could not be verified.'
        );
    }

    $cancelled = aimee_stripe_request(
        'DELETE',
        'subscriptions/' . rawurlencode($subscription_id)
    );
    if (is_wp_error($cancelled)) return $cancelled;
    if (aimee_stripe_subscription_is_verified_terminal($cancelled, $subscription_id)) return true;

    $verified = aimee_stripe_request(
        'GET',
        'subscriptions/' . rawurlencode($subscription_id)
    );
    if (is_wp_error($verified)) return $verified;
    if (aimee_stripe_subscription_is_verified_terminal($verified, $subscription_id)) return true;

    return new WP_Error(
        'stripe_subscription_cancellation_unverified',
        'Stripe did not verify that the subscription is terminal.'
    );
}

function aimee_stripe_checkout_session_matches_owner($session, $session_id, $user_id) {
    if (!is_array($session)) return false;
    $actual_id = sanitize_text_field((string) ($session['id'] ?? ''));
    $session_id = sanitize_text_field((string) $session_id);
    $metadata = is_array($session['metadata'] ?? null) ? $session['metadata'] : [];
    $owner = (int) ($metadata['aimee_user_id'] ?? $session['client_reference_id'] ?? 0);
    return $actual_id !== ''
        && $session_id !== ''
        && hash_equals($session_id, $actual_id)
        && $owner === (int) $user_id;
}

function aimee_stripe_checkout_intent_idempotency_key($intent_token) {
    $intent_token = trim((string) $intent_token);
    return $intent_token === ''
        ? ''
        : 'aimee-recurring-' . hash('sha256', 'stripe|' . $intent_token);
}

function aimee_stripe_checkout_intent_body($profile) {
    if (!$profile) return new WP_Error('stripe_checkout_intent_missing', 'The checkout intent is missing.');
    $token = trim((string) ($profile->billing_checkout_intent_token ?? ''));
    $provider = sanitize_key((string) ($profile->billing_checkout_intent_provider ?? ''));
    $plan = sanitize_key((string) ($profile->billing_checkout_intent_plan ?? ''));
    $market = sanitize_key((string) ($profile->billing_checkout_intent_market ?? ''));
    $generation = sanitize_key((string) ($profile->billing_checkout_intent_generation ?? ''));
    $user_id = (int) ($profile->user_id ?? 0);
    $payload = json_decode((string) ($profile->billing_checkout_intent_payload ?? ''), true);
    if (
        $user_id < 1
        || $provider !== 'stripe'
        || !preg_match('/^[A-Za-z0-9_-]{16,64}$/', $token)
        || $plan === ''
        || !in_array($market, ['uk', 'us'], true)
        || $generation === ''
        || !is_array($payload)
    ) return new WP_Error('stripe_checkout_intent_invalid', 'The durable checkout intent is incomplete.');

    $required = [
        'mode' => 'subscription',
        'client_reference_id' => (string) $user_id,
        'metadata[aimee_user_id]' => (string) $user_id,
        'metadata[aimee_plan]' => $plan,
        'metadata[aimee_market]' => $market,
        'metadata[aimee_billing_generation]' => $generation,
        'metadata[aimee_checkout_intent]' => $token,
        'subscription_data[metadata][aimee_user_id]' => (string) $user_id,
        'subscription_data[metadata][aimee_plan]' => $plan,
        'subscription_data[metadata][aimee_market]' => $market,
        'subscription_data[metadata][aimee_billing_generation]' => $generation,
        'subscription_data[metadata][aimee_checkout_intent]' => $token,
    ];
    foreach ($required as $key => $expected) {
        if (!array_key_exists($key, $payload) || !hash_equals($expected, (string) $payload[$key])) {
            return new WP_Error('stripe_checkout_intent_terms_mismatch', 'The saved checkout terms failed verification.');
        }
    }
    return $payload;
}

function aimee_stripe_checkout_session_matches_intent($session, $profile) {
    if (!is_array($session) || !$profile) return false;
    $metadata = is_array($session['metadata'] ?? null) ? $session['metadata'] : [];
    $token = trim((string) ($profile->billing_checkout_intent_token ?? ''));
    $generation = sanitize_key((string) ($profile->billing_checkout_intent_generation ?? ''));
    $plan = sanitize_key((string) ($profile->billing_checkout_intent_plan ?? ''));
    $market = sanitize_key((string) ($profile->billing_checkout_intent_market ?? ''));
    return !empty($session['id'])
        && $token !== ''
        && hash_equals($token, trim((string) ($metadata['aimee_checkout_intent'] ?? '')))
        && hash_equals($generation, sanitize_key((string) ($metadata['aimee_billing_generation'] ?? '')))
        && hash_equals($plan, sanitize_key((string) ($metadata['aimee_plan'] ?? '')))
        && hash_equals($market, sanitize_key((string) ($metadata['aimee_market'] ?? '')))
        && (int) ($profile->user_id ?? 0) === (int) (
            $metadata['aimee_user_id'] ?? $session['client_reference_id'] ?? 0
        );
}

/**
 * Retire a definitely-unsubmitted legacy Stripe intent without creating one.
 *
 * Version 1.8.4 never replays a Stripe Checkout create. A `requesting` or
 * `request_unknown` intent is deliberately held for operator reconciliation:
 * the historical request might exist at Stripe, but replaying it after the
 * cutover could create a new card checkout if it never arrived.
 */
function aimee_stripe_reconcile_checkout_intent($profile, $lock_token, $retire = false) {
    global $wpdb;
    if (!$profile || empty($profile->user_id)) {
        return new WP_Error('stripe_checkout_intent_missing', 'The checkout intent owner is missing.');
    }
    $user_id = (int) $profile->user_id;
    $lock_token = trim((string) $lock_token);
    $token = trim((string) ($profile->billing_checkout_intent_token ?? ''));
    $status = sanitize_key((string) ($profile->billing_checkout_intent_status ?? ''));
    $deletion_value = property_exists($profile, 'account_deletion_started_at')
        ? $profile->account_deletion_started_at
        : null;
    if (
        $lock_token === ''
        || !hash_equals($lock_token, (string) ($profile->billing_checkout_lock_token ?? ''))
        || $token === ''
        || sanitize_key((string) ($profile->billing_checkout_intent_provider ?? '')) !== 'stripe'
    ) return new WP_Error('stripe_checkout_intent_lock_mismatch', 'The checkout intent lock could not be verified.');
    if (!$retire && $deletion_value !== null && trim((string) $deletion_value) !== '') {
        return new WP_Error('account_deletion_pending', 'Checkout creation is blocked by account deletion.');
    }
    if (!aimee_refresh_subscription_checkout_lock($user_id, $lock_token)) {
        return new WP_Error('billing_lock_lost', 'The checkout intent lease expired before provider reconciliation.');
    }

    $table = aimee_table('aimee_user_profiles');
    if ($retire && $status === 'prepared') {
        $retired = $wpdb->update(
            $table,
            ['billing_checkout_intent_status' => 'retired'],
            [
                'user_id' => $user_id,
                'billing_checkout_lock_token' => $lock_token,
                'billing_checkout_intent_token' => $token,
                'billing_checkout_intent_status' => 'prepared',
                'account_deletion_started_at' => $deletion_value,
            ],
            ['%s'],
            ['%d', '%s', '%s', '%s', $deletion_value === null ? null : '%s']
        );
        return $retired === 1
            ? ['terminal' => true, 'session_id' => '', 'subscription_id' => '']
            : new WP_Error('stripe_checkout_intent_retire_failed', 'The unsubmitted checkout intent could not be retired.');
    }
    if (!$retire) {
        return new WP_Error(
            'stripe_checkout_creation_disabled',
            'New Stripe checkout is disabled. No card checkout was created.'
        );
    }
    if (in_array($status, ['requesting', 'request_unknown'], true)) {
        return new WP_Error(
            'legacy_stripe_checkout_manual_reconciliation_required',
            'This pre-cutover Stripe checkout intent may have reached Stripe. It must be reconciled by an operator; no new card checkout was created.'
        );
    }
    return new WP_Error(
        'stripe_checkout_intent_state_invalid',
        'The legacy Stripe checkout intent cannot be retired from its current state.'
    );
}

/** Clear an exact owner-bound Checkout Session only after Stripe proves expiry. */
function aimee_stripe_retire_expired_checkout_session($profile, $session, $lock_token) {
    global $wpdb;
    if (!$profile || empty($profile->user_id) || !is_array($session)) {
        return new WP_Error('stripe_checkout_expiry_identity_missing', 'The expired checkout owner is missing.');
    }
    $user_id = (int) $profile->user_id;
    $session_id = sanitize_text_field((string) ($session['id'] ?? ''));
    $stored_session_id = sanitize_text_field((string) ($profile->stripe_checkout_session_id ?? ''));
    $lock_token = trim((string) $lock_token);
    $intent_token = trim((string) ($profile->billing_checkout_intent_token ?? ''));
    $session_metadata = is_array($session['metadata'] ?? null) ? $session['metadata'] : [];
    $intent_matches = $intent_token === ''
        ? trim((string) ($session_metadata['aimee_checkout_intent'] ?? '')) === ''
        : (
            sanitize_key((string) ($profile->billing_checkout_intent_provider ?? '')) === 'stripe'
            && sanitize_key((string) ($profile->billing_checkout_intent_status ?? '')) === 'session_bound'
            && aimee_stripe_checkout_session_matches_intent($session, $profile)
        );
    if (
        $lock_token === ''
        || $session_id === ''
        || !hash_equals($lock_token, (string) ($profile->billing_checkout_lock_token ?? ''))
        || aimee_account_deletion_tombstone_is_active($profile)
        || !hash_equals($stored_session_id, $session_id)
        || !aimee_stripe_checkout_session_matches_owner($session, $session_id, $user_id)
        || sanitize_key((string) ($session['status'] ?? '')) !== 'expired'
        || !$intent_matches
        || !aimee_refresh_subscription_checkout_lock($user_id, $lock_token)
    ) return new WP_Error('stripe_checkout_expiry_unverified', 'The expired checkout identity could not be verified.');

    $update = ['stripe_checkout_session_id' => null];
    $update_formats = [null];
    $where = [
        'user_id' => $user_id,
        'billing_checkout_lock_token' => $lock_token,
        'stripe_checkout_session_id' => $session_id,
        'account_deletion_started_at' => null,
    ];
    $where_formats = ['%d', '%s', '%s', null];
    if ($intent_token !== '') {
        $update['billing_checkout_intent_status'] = 'retired';
        $update_formats[] = '%s';
        $where['billing_checkout_intent_token'] = $intent_token;
        $where['billing_checkout_intent_status'] = 'session_bound';
        $where_formats[] = '%s';
        $where_formats[] = '%s';
    }
    if (sanitize_key((string) ($profile->billing_migration_status ?? '')) === 'checkout_pending') {
        $update['billing_migration_status'] = 'checkout_retired';
        $update_formats[] = '%s';
        $where['billing_migration_status'] = 'checkout_pending';
        $where_formats[] = '%s';
    }
    $cleared = $wpdb->update(
        aimee_table('aimee_user_profiles'),
        $update,
        $where,
        $update_formats,
        $where_formats
    );
    if ($cleared !== 1) {
        return new WP_Error('stripe_checkout_expiry_save_failed', 'The terminal checkout could not be cleared locally.');
    }
    $fresh = aimee_membership_billing_profile($user_id);
    if (
        !$fresh
        || !hash_equals($lock_token, (string) ($fresh->billing_checkout_lock_token ?? ''))
        || !empty($fresh->stripe_checkout_session_id)
        || ($intent_token !== '' && sanitize_key((string) ($fresh->billing_checkout_intent_status ?? '')) !== 'retired')
    ) return new WP_Error('stripe_checkout_expiry_save_unverified', 'The terminal checkout clear was not verified.');
    return true;
}

/** Expire an exact owner-bound open Checkout Session, with remote proof. */
function aimee_expire_stripe_checkout_session_verified($session_id, $user_id) {
    $session_id = sanitize_text_field((string) $session_id);
    $user_id = (int) $user_id;
    if ($session_id === '' || $user_id < 1) {
        return new WP_Error('stripe_checkout_identity_missing', 'The Stripe Checkout identity is missing.');
    }
    $session = aimee_stripe_request(
        'GET',
        'checkout/sessions/' . rawurlencode($session_id) . '?expand[]=subscription'
    );
    if (is_wp_error($session)) return $session;
    if (!aimee_stripe_checkout_session_matches_owner($session, $session_id, $user_id)) {
        return new WP_Error('stripe_checkout_owner_mismatch', 'The Stripe Checkout owner could not be verified.');
    }
    $status = sanitize_key((string) ($session['status'] ?? ''));
    if ($status === 'expired') return true;
    if ($status === 'complete') {
        $subscription = is_array($session['subscription'] ?? null)
            ? sanitize_text_field((string) ($session['subscription']['id'] ?? ''))
            : sanitize_text_field((string) ($session['subscription'] ?? ''));
        return new WP_Error(
            'stripe_checkout_already_complete',
            'The Stripe Checkout Session already completed and must be reconciled.',
            ['session_id' => $session_id, 'subscription_id' => $subscription]
        );
    }
    if ($status !== 'open') {
        return new WP_Error('stripe_checkout_status_unknown', 'The Stripe Checkout state could not be retired safely.');
    }

    $expired = aimee_stripe_request(
        'POST',
        'checkout/sessions/' . rawurlencode($session_id) . '/expire'
    );
    if (is_wp_error($expired)) return $expired;
    if (
        aimee_stripe_checkout_session_matches_owner($expired, $session_id, $user_id)
        && sanitize_key((string) ($expired['status'] ?? '')) === 'expired'
    ) return true;

    $verified = aimee_stripe_request('GET', 'checkout/sessions/' . rawurlencode($session_id));
    if (
        !is_wp_error($verified)
        && aimee_stripe_checkout_session_matches_owner($verified, $session_id, $user_id)
        && sanitize_key((string) ($verified['status'] ?? '')) === 'expired'
    ) return true;
    return new WP_Error('stripe_checkout_expiry_unverified', 'Stripe did not verify that Checkout is expired.');
}

function aimee_datetime_from_unix($timestamp) {
    $timestamp = intval($timestamp);
    return $timestamp > 0 ? gmdate('Y-m-d H:i:s', $timestamp) : null;
}

function aimee_sync_subscription_from_stripe($subscription, $forced_user_id = 0, $forced_plan = '', $required_lock_token = '') {
    global $wpdb;
    if (!is_array($subscription) || empty($subscription['id'])) return false;

    $profile_table = aimee_table('aimee_user_profiles');
    $subscription_id = sanitize_text_field($subscription['id']);
    $customer_id = sanitize_text_field($subscription['customer'] ?? '');
    $metadata = is_array($subscription['metadata'] ?? null) ? $subscription['metadata'] : [];
    $billing_generation = sanitize_key((string) ($metadata['aimee_billing_generation'] ?? ''));
    $expected_generation = function_exists('aimee_global_current_billing_generation')
        ? aimee_global_current_billing_generation()
        : '';
    if (
        $expected_generation === ''
        || $billing_generation === ''
        || !hash_equals($expected_generation, $billing_generation)
    ) {
        return false;
    }

    $user_id = intval($forced_user_id ?: ($metadata['aimee_user_id'] ?? 0));
    if (!$user_id) {
        $user_id = intval($wpdb->get_var($wpdb->prepare(
            "SELECT user_id FROM $profile_table WHERE stripe_subscription_id = %s OR stripe_customer_id = %s LIMIT 1",
            $subscription_id,
            $customer_id
        )));
    }
    if (!$user_id) return false;

    $required_lock_token = trim((string) $required_lock_token);
    if ($required_lock_token === '') {
        $sync_lock_token = aimee_acquire_subscription_checkout_lock($user_id);
        if ($sync_lock_token === '') {
            return new WP_Error(
                'billing_operation_in_progress',
                'The subscription event is waiting for the account billing lock.'
            );
        }
        try {
            return aimee_sync_subscription_from_stripe(
                $subscription,
                $user_id,
                $forced_plan,
                $sync_lock_token
            );
        } finally {
            aimee_release_subscription_checkout_lock($user_id, $sync_lock_token);
        }
    }

    $existing_profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $profile_table WHERE user_id = %d",
        $user_id
    ));
    if (!$existing_profile) return false;
    if (aimee_account_deletion_tombstone_is_active($existing_profile)) {
        return new WP_Error('account_deletion_pending', 'Subscription updates are paused while account deletion is in progress.');
    }
    $stored_lock_token = trim((string) ($existing_profile->billing_checkout_lock_token ?? ''));
    $stored_lock_until = strtotime((string) ($existing_profile->billing_checkout_lock_until ?? '') . ' UTC');
    if ($required_lock_token !== '') {
        if (
            !hash_equals($required_lock_token, $stored_lock_token)
            || $stored_lock_until === false
            || $stored_lock_until < time()
        ) return new WP_Error('billing_lock_lost', 'The subscription update lock is no longer current.');
    } elseif ($stored_lock_token !== '' && $stored_lock_until !== false && $stored_lock_until >= time()) {
        return new WP_Error('billing_operation_in_progress', 'Subscription updates are paused while another billing operation is in progress.');
    }

    $incoming_intent_token = trim((string) ($metadata['aimee_checkout_intent'] ?? ''));
    $stored_intent_token = trim((string) ($existing_profile->billing_checkout_intent_token ?? ''));
    $stored_intent_provider = sanitize_key((string) ($existing_profile->billing_checkout_intent_provider ?? ''));
    $stored_intent_status = sanitize_key((string) ($existing_profile->billing_checkout_intent_status ?? ''));
    $stored_intent_plan = sanitize_key((string) ($existing_profile->billing_checkout_intent_plan ?? ''));
    $stored_intent_market = sanitize_key((string) ($existing_profile->billing_checkout_intent_market ?? ''));
    $stored_intent_generation = sanitize_key((string) ($existing_profile->billing_checkout_intent_generation ?? ''));
    $stored_checkout_session_id = sanitize_text_field((string) (
        $existing_profile->stripe_checkout_session_id ?? ''
    ));
    $incoming_metadata_user = (int) ($metadata['aimee_user_id'] ?? 0);
    $incoming_metadata_plan = sanitize_key((string) ($metadata['aimee_plan'] ?? ''));
    $incoming_metadata_market = sanitize_key((string) ($metadata['aimee_market'] ?? ''));
    $exact_transition_intent = $stored_intent_token !== ''
        && $stored_intent_provider === 'stripe'
        && in_array($stored_intent_status, ['session_bound', 'completed'], true)
        && hash_equals($stored_intent_token, $incoming_intent_token)
        && $incoming_metadata_user === $user_id
        && hash_equals($stored_intent_plan, $incoming_metadata_plan)
        && hash_equals($stored_intent_market, $incoming_metadata_market)
        && hash_equals($stored_intent_generation, $billing_generation)
        && $stored_checkout_session_id !== '';
    $stored_subscription_id = sanitize_text_field((string) ($existing_profile->stripe_subscription_id ?? ''));
    $updating_existing_subscription = $stored_subscription_id !== ''
        && hash_equals($stored_subscription_id, $subscription_id);
    $stored_provider = sanitize_key((string) ($existing_profile->billing_provider ?? ''));

    // A late Stripe event must never reclaim a profile that has already moved
    // to bank billing. First attachment/provider transition is permitted only
    // through the exact session-bound Stripe intent created under this lock.
    if (
        (!$updating_existing_subscription && !$exact_transition_intent)
        || ($stored_provider === 'gocardless' && !$exact_transition_intent)
        || (
            $stored_intent_token !== ''
            && $stored_intent_provider === 'stripe'
            && !$exact_transition_intent
        )
    ) {
        return new WP_Error(
            'subscription_checkout_intent_mismatch',
            'The subscription does not match the current owner-bound Stripe checkout intent.'
        );
    }

    if (aimee_global_subscription_identity_conflicts(
        $existing_profile,
        $subscription_id,
        $billing_generation
    )) {
        if (function_exists('aimee_log')) {
            aimee_log([
                'user_id' => $user_id,
                'stored_subscription_id' => (string) ($existing_profile->stripe_subscription_id ?? ''),
                'incoming_subscription_id' => $subscription_id,
                'billing_generation' => $billing_generation,
                'requires_reconciliation' => true,
            ], 'AIMEE SUBSCRIPTION IDENTITY CONFLICT');
        }
        return new WP_Error(
            'subscription_identity_conflict',
            'A different live subscription is already attached to this account. Billing reconciliation is required.',
            ['status' => 409, 'requires_reconciliation' => true]
        );
    }

    // A Stripe subscription must never become current while any previous bank
    // Billing Request, mandate, response-loss create or ledger payment can
    // still collect. Repeat the complete terminal-state proof here because a
    // subscription webhook can arrive independently of checkout completion.
    $has_stored_gocardless_state = $stored_provider === 'gocardless'
        || !empty($existing_profile->gocardless_billing_request_id)
        || !empty($existing_profile->gocardless_mandate_id)
        || !empty($existing_profile->gocardless_payment_id);
    if ($has_stored_gocardless_state) {
        if (!function_exists('aimee_gocardless_retire_user_billing_for_deletion')) {
            return new WP_Error(
                'subscription_provider_transition_unavailable',
                'The complete previous bank authority could not be safely verified.'
            );
        }
        $bank_retired = aimee_gocardless_retire_user_billing_for_deletion(
            $user_id,
            $required_lock_token
        );
        if (is_wp_error($bank_retired)) {
            return new WP_Error(
                'subscription_provider_transition_blocked',
                'The previous bank authority or payment is not verified as terminal, so Stripe billing was not attached.',
                ['cause' => $bank_retired->get_error_code()]
            );
        }
        $existing_profile = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $profile_table WHERE user_id = %d",
            $user_id
        ));
        if (
            !$existing_profile
            || aimee_account_deletion_tombstone_is_active($existing_profile)
            || !hash_equals(
                $required_lock_token,
                (string) ($existing_profile->billing_checkout_lock_token ?? '')
            )
            || !hash_equals(
                $stored_intent_token,
                (string) ($existing_profile->billing_checkout_intent_token ?? '')
            )
            || !hash_equals(
                $stored_checkout_session_id,
                (string) ($existing_profile->stripe_checkout_session_id ?? '')
            )
        ) {
            return new WP_Error(
                'subscription_provider_transition_unverified',
                'The terminal bank-authority proof could not be re-read under the Stripe lock.'
            );
        }
    }

    $plan = sanitize_key($forced_plan ?: ($metadata['aimee_plan'] ?? ''));
    if (!array_key_exists($plan, aimee_membership_plans())) {
        $plan = sanitize_key((string) ($existing_profile->subscription_plan ?? ''));
    }

    $period = function_exists('aimee_global_stripe_subscription_period_bounds')
        ? aimee_global_stripe_subscription_period_bounds($subscription)
        : [
            'start' => (int) ($subscription['current_period_start'] ?? 0),
            'end' => (int) ($subscription['current_period_end'] ?? 0),
        ];
    $incoming_status = sanitize_key($subscription['status'] ?? 'inactive');
    if (in_array($incoming_status, ['active', 'trialing'], true) && empty($period['end'])) {
        return new WP_Error(
            'subscription_period_missing',
            'Stripe did not provide a verifiable current billing period.'
        );
    }

    if (!aimee_refresh_subscription_checkout_lock($user_id, $required_lock_token)) {
        return new WP_Error('billing_lock_lost', 'The subscription synchronization lease expired before its final state write.');
    }
    $prewrite_profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $profile_table WHERE user_id = %d",
        $user_id
    ));
    if (
        !$prewrite_profile
        || aimee_account_deletion_tombstone_is_active($prewrite_profile)
        || !hash_equals(
            $required_lock_token,
            (string) ($prewrite_profile->billing_checkout_lock_token ?? '')
        )
        || !aimee_subscription_checkout_lock_is_current($user_id, $required_lock_token)
    ) return new WP_Error('billing_lock_lost', 'The subscription synchronization owner is no longer current.');
    $existing_profile = $prewrite_profile;

    // Compare-and-swap the identity together with the state that authorised
    // its replacement. Two concurrent first-sync webhooks may both observe an
    // empty ID, but only one can claim it; the loser re-reads and reports an
    // explicit conflict instead of silently orphaning the first subscription.
    $stored_subscription_value = property_exists($existing_profile, 'stripe_subscription_id')
        ? $existing_profile->stripe_subscription_id
        : null;
    $stored_generation_value = property_exists($existing_profile, 'billing_account_generation')
        ? $existing_profile->billing_account_generation
        : null;
    $stored_status_value = property_exists($existing_profile, 'subscription_status')
        ? $existing_profile->subscription_status
        : null;
    $stored_provider_value = property_exists($existing_profile, 'billing_provider')
        ? $existing_profile->billing_provider
        : null;
    $stored_mandate_value = property_exists($existing_profile, 'gocardless_mandate_id')
        ? $existing_profile->gocardless_mandate_id
        : null;
    $stored_checkout_lock_value = property_exists($existing_profile, 'billing_checkout_lock_token')
        ? $existing_profile->billing_checkout_lock_token
        : null;
    $sync_where = [
        'user_id' => $user_id,
        'stripe_subscription_id' => $stored_subscription_value,
        'billing_account_generation' => $stored_generation_value,
        'subscription_status' => $stored_status_value,
        'billing_provider' => $stored_provider_value,
        'gocardless_mandate_id' => $stored_mandate_value,
        'billing_checkout_lock_token' => $stored_checkout_lock_value,
        'account_deletion_started_at' => null,
    ];
    $sync_where_formats = [
        '%d',
        $stored_subscription_value === null ? null : '%s',
        $stored_generation_value === null ? null : '%s',
        $stored_status_value === null ? null : '%s',
        $stored_provider_value === null ? null : '%s',
        $stored_mandate_value === null ? null : '%s',
        $stored_checkout_lock_value === null ? null : '%s',
        null,
    ];

    $updated = $wpdb->update(
        $profile_table,
        [
            'subscription_status'               => $incoming_status,
            'subscription_plan'                 => $plan ?: null,
            'stripe_customer_id'                => $customer_id ?: null,
            'stripe_subscription_id'            => $subscription_id,
            'subscription_current_period_start' => aimee_datetime_from_unix($period['start'] ?? 0),
            'subscription_current_period_end'   => aimee_datetime_from_unix($period['end'] ?? 0),
            'subscription_cancel_at_period_end' => !empty($subscription['cancel_at_period_end']) ? 1 : 0,
            'membership_started_at'             => !empty($subscription['start_date']) ? aimee_datetime_from_unix($subscription['start_date']) : current_time('mysql', true),
            'billing_migration_status'           => 'complete',
            'billing_migration_completed_at'     => current_time('mysql', true),
            'billing_account_generation'         => $billing_generation,
            'billing_provider'                   => 'stripe',
            // The immutable GoCardless payment ledger remains as the audit
            // record; profile authority and retry pointers belong only to the
            // currently stored provider and must not survive this transition.
            'gocardless_customer_id'             => null,
            'gocardless_mandate_id'              => null,
            'gocardless_mandate_scheme'          => null,
            'gocardless_billing_request_id'      => null,
            'gocardless_billing_request_flow_id' => null,
            'gocardless_payment_id'              => null,
            'gocardless_payment_status'          => null,
            'gocardless_last_confirmed_payment_id' => null,
            'gocardless_last_payment_at'         => null,
            'gocardless_last_failure_at'         => null,
            'gocardless_next_payment_at'         => null,
            'gocardless_cancelled_at'            => null,
            'gocardless_authorized_plan'         => null,
            'gocardless_authorized_amount_minor' => null,
            'gocardless_authorized_currency'     => null,
            'gocardless_renewal_attempt'          => 0,
            'gocardless_retry_after'             => null,
        ],
        $sync_where,
        [
            '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s', '%s',
            '%s', null, null, null, null, null, null, null, null, null, null,
            null, null, null, null, null, '%d', null,
        ],
        $sync_where_formats
    );
    if ($updated === false) {
        return new WP_Error(
            'subscription_sync_database_error',
            'The verified subscription could not be saved.'
        );
    }

    $fresh_profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $profile_table WHERE user_id = %d",
        $user_id
    ));
    if (
        $fresh_profile
        && aimee_global_subscription_identity_conflicts(
            $fresh_profile,
            $subscription_id,
            $billing_generation
        )
    ) {
        return new WP_Error(
            'subscription_identity_conflict',
            'A different live subscription won the billing-state update. Billing reconciliation is required.',
            ['status' => 409, 'requires_reconciliation' => true]
        );
    }
    if (
        !$fresh_profile
        || aimee_account_deletion_tombstone_is_active($fresh_profile)
        || !hash_equals(
            $required_lock_token,
            (string) ($fresh_profile->billing_checkout_lock_token ?? '')
        )
        || !aimee_subscription_checkout_lock_is_current($user_id, $required_lock_token)
        || (string) ($fresh_profile->stripe_subscription_id ?? '') !== $subscription_id
        || !aimee_global_profile_has_current_billing_generation($fresh_profile)
        || sanitize_key((string) ($fresh_profile->billing_provider ?? '')) !== 'stripe'
        || trim((string) ($fresh_profile->gocardless_mandate_id ?? '')) !== ''
    ) {
        return new WP_Error(
            'subscription_sync_verification_failed',
            'The saved subscription could not be verified.'
        );
    }
    aimee_sms_refresh_allowance($user_id, $fresh_profile);

    return $user_id;
}

function aimee_stripe_event_already_processed($event_id) {
    global $wpdb;
    $table = aimee_table('aimee_stripe_events');
    return (bool) $wpdb->get_var($wpdb->prepare(
        "SELECT 1 FROM $table WHERE stripe_event_id = %s LIMIT 1",
        sanitize_text_field($event_id)
    ));
}

function aimee_record_stripe_event_once($event_id, $event_type) {
    global $wpdb;
    $table = aimee_table('aimee_stripe_events');
    $inserted = $wpdb->query($wpdb->prepare(
        "INSERT IGNORE INTO $table (stripe_event_id, event_type, processed_at) VALUES (%s, %s, %s)",
        sanitize_text_field($event_id),
        sanitize_text_field($event_type),
        current_time('mysql', true)
    ));
    return $inserted === 1;
}

/**
 * The bundled legacy engine still owns several auxiliary tables that pre-date
 * the canonical plugin schema installer. Keep that maintenance versioned so
 * expensive SHOW/ALTER/dbDelta work is not repeated on every request.
 */
function aimee_engine_runtime_schema_target_version() {
    return defined('AIMEE_GLOBAL_SCHEMA_VERSION')
        ? (string) AIMEE_GLOBAL_SCHEMA_VERSION
        : '2026.08.20.3';
}

function aimee_engine_runtime_schema_due() {
    $target = aimee_engine_runtime_schema_target_version();
    $installed = (string) get_option('aimee_engine_runtime_schema_version', '0');
    $healthy = aimee_engine_runtime_schema_is_healthy();
    if (version_compare($installed, $target, '>=') && $healthy) return false;

    $retry_version = (string) get_option('aimee_engine_runtime_schema_retry_version', '');
    $retry_after = intval(get_option('aimee_engine_runtime_schema_retry_after', 0));

    // A failed migration must not hammer MariaDB on every front-end request.
    // A newly deployed schema target bypasses the old back-off immediately.
    if ($retry_version === $target && $retry_after > time()) {
        return false;
    }

    $claim = function_exists('aimee_global_schema_claim_lock')
        ? aimee_global_schema_claim_lock('engine_runtime_schema_' . $target)
        : '';
    if ($claim === '') return false;
    $GLOBALS['aimee_engine_runtime_schema_lock'] = $claim;

    // Re-check after the atomic lock. A concurrent request may have repaired it.
    $installed = (string) get_option('aimee_engine_runtime_schema_version', '0');
    if (
        version_compare($installed, $target, '>=')
        && aimee_engine_runtime_schema_is_healthy(true)
    ) {
        aimee_global_schema_release_lock($claim);
        unset($GLOBALS['aimee_engine_runtime_schema_lock']);
        return false;
    }

    return true;
}

function aimee_engine_runtime_schema_is_healthy($refresh = false) {
    static $healthy = null;
    if ($refresh) {
        $healthy = null;
        if (function_exists('aimee_global_schema_health_cache_forget')) {
            aimee_global_schema_health_cache_forget('engine_runtime');
        }
    } elseif ($healthy !== null) {
        return $healthy;
    } elseif (
        function_exists('aimee_global_schema_health_cache_get')
        && aimee_global_schema_health_cache_get('engine_runtime')
    ) {
        $healthy = true;
        return $healthy;
    }

    if (!function_exists('aimee_global_schema_table_contract_ready')) return $healthy;
    $c = static function ($columns) {
        return preg_split('/\s+/', trim($columns));
    };
    $pk = static function ($column) {
        return ['PRIMARY' => ['unique' => true, 'columns' => [$column]]];
    };
    $contracts = [
        aimee_table('aimee_user_profiles') => [
            $c('user_id phone_number phone_verified_number phone_verified_at sms_opt_in sms_timezone sms_safe_start_hour sms_safe_end_hour sms_override wallet_balance active_topup_tier escort_mode subscription_status subscription_plan billing_provider gocardless_customer_id gocardless_mandate_id gocardless_mandate_scheme gocardless_billing_request_id gocardless_billing_request_flow_id gocardless_payment_id gocardless_payment_status gocardless_last_confirmed_payment_id gocardless_last_payment_at gocardless_last_failure_at gocardless_next_payment_at gocardless_cancelled_at gocardless_authorized_plan gocardless_authorized_amount_minor gocardless_authorized_currency gocardless_renewal_attempt gocardless_retry_after stripe_customer_id stripe_subscription_id stripe_checkout_session_id legacy_stripe_customer_id legacy_stripe_subscription_id legacy_stripe_checkout_session_id legacy_original_period_end legacy_membership_end billing_migration_status billing_migration_started_at billing_migration_completed_at billing_account_generation billing_checkout_intent_token billing_checkout_intent_provider billing_checkout_intent_plan billing_checkout_intent_market billing_checkout_intent_generation billing_checkout_intent_status billing_checkout_intent_payload billing_checkout_lock_until billing_checkout_lock_token account_deletion_started_at subscription_current_period_start subscription_current_period_end subscription_cancel_at_period_end membership_started_at membership_bonus_access_until service_grace_code service_grace_granted_at service_grace_access_until trial_message_limit trial_messages_used intimacy_score intimacy_stage last_intimacy_route_at market sms_allowance_period_start sms_allowance_period_end sms_included_limit sms_included_used sms_bundle_balance sms_limit_notice_period_key sms_last_bundle_checkout_session continuity_enabled timeline_enabled push_opt_in push_sensitive_preview push_quiet_start_hour push_quiet_end_hour privacy_acknowledged_at special_category_consent_at special_category_consent_version'),
            [
                'PRIMARY' => ['unique' => true, 'columns' => ['user_id']],
                'uq_aimee_verified_phone' => ['unique' => true, 'columns' => ['phone_verified_number']],
            ],
        ],
        aimee_table('aimee_messages') => [
            $c('user_id voice_note_token voice_note_duration_ms voice_note_mime'),
            [],
        ],
        aimee_table('aimee_analytics_events') => [
            $c('id user_id event_name properties page_path occurred_at created_at'),
            $pk('id') + [
                'user_event' => ['unique' => false, 'columns' => ['user_id', 'event_name']],
                'occurred_at' => ['unique' => false, 'columns' => ['occurred_at']],
            ],
        ],
        aimee_voice_note_table() => [
            $c('id note_token user_id status result_status route_hint route_used input_file input_mime input_bytes recorded_ms transcript reply_text reply_duration_ms reply_file reply_mime reply_bytes audio_status user_message_id aimee_message_id subscription_json media_json stt_latency_ms llm_latency_ms tts_latency_ms error_code error_message voice_error_code voice_error_message processing_started_at recording_started_at finished_at expires_at created_at updated_at'),
            $pk('id') + [
                'note_token' => ['unique' => true, 'columns' => ['note_token']],
                'user_created' => ['unique' => false, 'columns' => ['user_id', 'created_at']],
                'status_updated' => ['unique' => false, 'columns' => ['status', 'updated_at']],
            ],
        ],
        aimee_table('aimee_stripe_events') => [
            $c('id stripe_event_id event_type processed_at'),
            $pk('id') + [
                'stripe_event_id' => ['unique' => true, 'columns' => ['stripe_event_id']],
            ],
        ],
        aimee_table('aimee_sms_usage') => [
            $c('id user_id message_id source allowance_bucket segments sent_at'),
            $pk('id') + [
                'user_sent' => ['unique' => false, 'columns' => ['user_id', 'sent_at']],
                'allowance_bucket' => ['unique' => false, 'columns' => ['allowance_bucket']],
            ],
        ],
        aimee_table('aimee_sms_outbound_events') => [
            $c('id send_key provider_reference provider_message_id user_id message_id source destination_hash intent_hash message_hash status allowance_bucket allowance_period_start allowance_period_end quota_disposition segments provider_code provider_detail usage_recorded audit_error created_at updated_at sending_at queued_at'),
            $pk('id') + [
                'uq_aimee_sms_outbound_send' => ['unique' => true, 'columns' => ['send_key']],
                'uq_aimee_sms_outbound_reference' => ['unique' => true, 'columns' => ['provider_reference']],
                'idx_aimee_sms_outbound_user' => ['unique' => false, 'columns' => ['user_id', 'created_at']],
                'idx_aimee_sms_outbound_status' => ['unique' => false, 'columns' => ['status', 'updated_at']],
            ],
        ],
        aimee_table('aimee_sms_inbound_events') => [
            $c('id event_key event_ref dedupe_basis source_number user_id request_id status lease_token attempt_count response_json created_at updated_at completed_at'),
            $pk('id') + [
                'uq_aimee_sms_inbound_event' => ['unique' => true, 'columns' => ['event_key']],
                'idx_aimee_sms_inbound_user' => ['unique' => false, 'columns' => ['user_id', 'created_at']],
                'idx_aimee_sms_inbound_status' => ['unique' => false, 'columns' => ['status', 'updated_at']],
            ],
        ],
        aimee_table('aimee_sms_bundle_purchases') => [
            $c('id user_id stripe_checkout_session_id billing_generation market currency product_label quantity amount_pence status purchased_at'),
            $pk('id') + [
                'stripe_checkout_session_id' => ['unique' => true, 'columns' => ['stripe_checkout_session_id']],
                'user_purchased' => ['unique' => false, 'columns' => ['user_id', 'purchased_at']],
            ],
        ],
        aimee_table('aimee_continuity_items') => [
            $c('id user_id item_type action_kind media_rating subject details follow_up_goal due_at follow_up_at importance status attempts source_user_message_id source_aimee_message_id dedupe_hash completed_at last_error created_at updated_at'),
            $pk('id') + [
                'dedupe_hash' => ['unique' => true, 'columns' => ['dedupe_hash']],
                'due_items' => ['unique' => false, 'columns' => ['status', 'follow_up_at']],
                'user_status' => ['unique' => false, 'columns' => ['user_id', 'status']],
            ],
        ],
        aimee_table('aimee_relationship_timeline') => [
            $c('id user_id event_type title story_text occurred_at source_message_id media_key significance dedupe_hash created_at'),
            $pk('id') + [
                'dedupe_hash' => ['unique' => true, 'columns' => ['dedupe_hash']],
                'user_date' => ['unique' => false, 'columns' => ['user_id', 'occurred_at']],
            ],
        ],
        aimee_table('aimee_push_subscriptions') => [
            $c('id user_id endpoint_hash endpoint p256dh auth_secret device_token_hash content_encoding user_agent enabled last_payload_id last_success_at last_error created_at updated_at'),
            $pk('id') + [
                'endpoint_hash' => ['unique' => true, 'columns' => ['endpoint_hash']],
                'device_token_hash' => ['unique' => true, 'columns' => ['device_token_hash']],
                'user_enabled' => ['unique' => false, 'columns' => ['user_id', 'enabled']],
            ],
        ],
        aimee_table('aimee_push_notifications') => [
            $c('id user_id title body discreet_body target_url notification_tag is_sensitive status attempts next_attempt_at dispatched_at expires_at created_at'),
            $pk('id') + [
                'dispatch_queue' => ['unique' => false, 'columns' => ['status', 'next_attempt_at']],
                'user_created' => ['unique' => false, 'columns' => ['user_id', 'created_at']],
            ],
        ],
    ];

    foreach ($contracts as $table => $contract) {
        if (!aimee_global_schema_table_contract_ready($table, $contract[0], $contract[1], true)) {
            return $healthy;
        }
    }

    global $wpdb;
    $notification_columns = array_map('strval', (array) $wpdb->get_col(
        'SHOW COLUMNS FROM `' . aimee_table('aimee_push_notifications') . '`',
        0
    ));
    $healthy = in_array('is_sensitive', $notification_columns, true)
        && !in_array('sensitive', $notification_columns, true);
    if ($healthy && function_exists('aimee_global_schema_health_cache_set')) {
        aimee_global_schema_health_cache_set('engine_runtime');
    }
    return $healthy;
}

function aimee_engine_runtime_schema_mark_current() {
    update_option(
        'aimee_engine_runtime_schema_version',
        aimee_engine_runtime_schema_target_version(),
        false
    );
    delete_option('aimee_engine_runtime_schema_retry_version');
    delete_option('aimee_engine_runtime_schema_retry_after');
}

function aimee_engine_runtime_schema_mark_failed() {
    if (function_exists('aimee_global_schema_health_cache_forget')) {
        aimee_global_schema_health_cache_forget('engine_runtime');
    }
    update_option(
        'aimee_engine_runtime_schema_retry_version',
        aimee_engine_runtime_schema_target_version(),
        false
    );
    update_option(
        'aimee_engine_runtime_schema_retry_after',
        time() + (15 * MINUTE_IN_SECONDS),
        false
    );
}

function aimee_engine_runtime_schema_release_lock() {
    $claim = (string) ($GLOBALS['aimee_engine_runtime_schema_lock'] ?? '');
    if ($claim !== '' && function_exists('aimee_global_schema_release_lock')) {
        aimee_global_schema_release_lock($claim);
    }
    unset($GLOBALS['aimee_engine_runtime_schema_lock']);
}

add_action('init', function() {
    global $wpdb;

    if (!aimee_engine_runtime_schema_due()) return;
    $migration_ok = true;

    $profile_table = aimee_table('aimee_user_profiles');
    if (
        !function_exists('aimee_global_schema_table_exists')
        || !aimee_global_schema_table_exists($profile_table)
    ) {
        aimee_engine_runtime_schema_mark_failed();
        aimee_engine_runtime_schema_release_lock();
        return;
    }
    $columns = [
        'phone_number'                        => "VARCHAR(190) NULL DEFAULT NULL",
        'phone_verified_number'               => "VARCHAR(190) NULL DEFAULT NULL",
        'phone_verified_at'                   => "DATETIME NULL DEFAULT NULL",
        'sms_opt_in'                          => "TINYINT(1) NOT NULL DEFAULT 0",
        'sms_timezone'                        => "VARCHAR(64) NULL DEFAULT NULL",
        'sms_safe_start_hour'                 => "INT NOT NULL DEFAULT 9",
        'sms_safe_end_hour'                   => "INT NOT NULL DEFAULT 17",
        'sms_override'                        => "TINYINT(1) NOT NULL DEFAULT 0",
        'wallet_balance'                      => "DECIMAL(10,2) NOT NULL DEFAULT 0.00",
        'active_topup_tier'                   => "INT NOT NULL DEFAULT 0",
        'escort_mode'                         => "TINYINT(1) NOT NULL DEFAULT 0",
        'subscription_status'                 => "VARCHAR(24) NOT NULL DEFAULT 'trial'",
        'subscription_plan'                   => "VARCHAR(24) NULL DEFAULT NULL",
        'billing_provider'                    => "VARCHAR(32) NULL DEFAULT NULL",
        'gocardless_customer_id'               => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_mandate_id'                => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_mandate_scheme'            => "VARCHAR(32) NULL DEFAULT NULL",
        'gocardless_billing_request_id'        => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_billing_request_flow_id'   => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_payment_id'                => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_payment_status'            => "VARCHAR(32) NULL DEFAULT NULL",
        'gocardless_last_confirmed_payment_id' => "VARCHAR(255) NULL DEFAULT NULL",
        'gocardless_last_payment_at'           => "DATETIME NULL DEFAULT NULL",
        'gocardless_last_failure_at'           => "DATETIME NULL DEFAULT NULL",
        'gocardless_next_payment_at'           => "DATETIME NULL DEFAULT NULL",
        'gocardless_cancelled_at'              => "DATETIME NULL DEFAULT NULL",
        'gocardless_authorized_plan'           => "VARCHAR(24) NULL DEFAULT NULL",
        'gocardless_authorized_amount_minor'   => "INT UNSIGNED NULL DEFAULT NULL",
        'gocardless_authorized_currency'       => "CHAR(3) NULL DEFAULT NULL",
        'gocardless_renewal_attempt'            => "INT UNSIGNED NOT NULL DEFAULT 0",
        'gocardless_retry_after'                => "DATETIME NULL DEFAULT NULL",
        'stripe_customer_id'                  => "VARCHAR(255) NULL DEFAULT NULL",
        'stripe_subscription_id'              => "VARCHAR(255) NULL DEFAULT NULL",
        'stripe_checkout_session_id'          => "VARCHAR(255) NULL DEFAULT NULL",
        'legacy_stripe_customer_id'            => "VARCHAR(255) NULL DEFAULT NULL",
        'legacy_stripe_subscription_id'        => "VARCHAR(255) NULL DEFAULT NULL",
        'legacy_stripe_checkout_session_id'    => "VARCHAR(255) NULL DEFAULT NULL",
        'legacy_original_period_end'           => "DATETIME NULL DEFAULT NULL",
        'legacy_membership_end'                => "DATETIME NULL DEFAULT NULL",
        'billing_migration_status'             => "VARCHAR(40) NOT NULL DEFAULT 'none'",
        'billing_migration_started_at'         => "DATETIME NULL DEFAULT NULL",
        'billing_migration_completed_at'       => "DATETIME NULL DEFAULT NULL",
        'billing_account_generation'           => "VARCHAR(64) NULL DEFAULT NULL",
        'billing_checkout_intent_token'         => "VARCHAR(64) NULL DEFAULT NULL",
        'billing_checkout_intent_provider'      => "VARCHAR(24) NULL DEFAULT NULL",
        'billing_checkout_intent_plan'          => "VARCHAR(32) NULL DEFAULT NULL",
        'billing_checkout_intent_market'        => "VARCHAR(8) NULL DEFAULT NULL",
        'billing_checkout_intent_generation'    => "VARCHAR(64) NULL DEFAULT NULL",
        'billing_checkout_intent_status'        => "VARCHAR(32) NULL DEFAULT NULL",
        'billing_checkout_intent_payload'       => "LONGTEXT NULL DEFAULT NULL",
        'billing_checkout_lock_until'           => "DATETIME NULL DEFAULT NULL",
        'billing_checkout_lock_token'           => "VARCHAR(64) NULL DEFAULT NULL",
        'account_deletion_started_at'            => "DATETIME NULL DEFAULT NULL",
        'subscription_current_period_end'     => "DATETIME NULL DEFAULT NULL",
        'subscription_cancel_at_period_end'   => "TINYINT(1) NOT NULL DEFAULT 0",
        'membership_started_at'               => "DATETIME NULL DEFAULT NULL",
        'membership_bonus_access_until'        => "DATETIME NULL DEFAULT NULL",
        'service_grace_code'                   => "VARCHAR(64) NULL DEFAULT NULL",
        'service_grace_granted_at'             => "DATETIME NULL DEFAULT NULL",
        'service_grace_access_until'            => "DATETIME NULL DEFAULT NULL",
        'trial_message_limit'                 => "INT NOT NULL DEFAULT " . aimee_free_preview_limit(),
        'trial_messages_used'                 => "INT NOT NULL DEFAULT 0",
        'intimacy_score'                      => "INT NOT NULL DEFAULT 8",
        'intimacy_stage'                      => "VARCHAR(24) NOT NULL DEFAULT 'guarded'",
        'last_intimacy_route_at'              => "DATETIME NULL DEFAULT NULL",
        'market'                              => "VARCHAR(8) NOT NULL DEFAULT 'uk'",
        'subscription_current_period_start'   => "DATETIME NULL DEFAULT NULL",
        'sms_allowance_period_start'          => "DATETIME NULL DEFAULT NULL",
        'sms_allowance_period_end'            => "DATETIME NULL DEFAULT NULL",
        'sms_included_limit'                  => "INT NOT NULL DEFAULT 0",
        'sms_included_used'                   => "INT NOT NULL DEFAULT 0",
        'sms_bundle_balance'                  => "INT NOT NULL DEFAULT 0",
        'sms_limit_notice_period_key'         => "VARCHAR(64) NULL DEFAULT NULL",
        'sms_last_bundle_checkout_session'    => "VARCHAR(255) NULL DEFAULT NULL",
        'continuity_enabled'                  => "TINYINT(1) NOT NULL DEFAULT 1",
        'timeline_enabled'                    => "TINYINT(1) NOT NULL DEFAULT 1",
        'push_opt_in'                         => "TINYINT(1) NOT NULL DEFAULT 0",
        'push_sensitive_preview'              => "TINYINT(1) NOT NULL DEFAULT 0",
        'push_quiet_start_hour'               => "INT NOT NULL DEFAULT 21",
        'push_quiet_end_hour'                 => "INT NOT NULL DEFAULT 8",
        'privacy_acknowledged_at'             => "DATETIME NULL DEFAULT NULL",
        'special_category_consent_at'         => "DATETIME NULL DEFAULT NULL",
        'special_category_consent_version'    => "VARCHAR(64) NULL DEFAULT NULL"
    ];

    foreach ($columns as $column => $definition) {
        $safe_column = preg_replace('/[^a-zA-Z0-9_]/', '', $column);
        $row = $wpdb->get_results($wpdb->prepare(
            "SHOW COLUMNS FROM `$profile_table` LIKE %s",
            $wpdb->esc_like($safe_column)
        ));
        if (empty($row)) {
            if ($wpdb->query("ALTER TABLE `$profile_table` ADD `$safe_column` $definition") === false) {
                $migration_ok = false;
            }
        }
    }

    $verified_phone_index = $wpdb->get_results(
        "SHOW INDEX FROM `$profile_table` WHERE Key_name = 'uq_aimee_verified_phone'"
    );
    if (empty($verified_phone_index)) {
        if ($wpdb->query(
            "ALTER TABLE `$profile_table` ADD UNIQUE KEY `uq_aimee_verified_phone` (`phone_verified_number`)"
        ) === false) {
            $migration_ok = false;
        }
    }

    $messages_table = aimee_table('aimee_messages');
    if (!aimee_global_schema_table_exists($messages_table)) {
        aimee_engine_runtime_schema_mark_failed();
        aimee_engine_runtime_schema_release_lock();
        return;
    }
    $message_columns = [
        'voice_note_token'       => "VARCHAR(64) NULL DEFAULT NULL",
        'voice_note_duration_ms' => "INT NULL DEFAULT NULL",
        'voice_note_mime'        => "VARCHAR(80) NULL DEFAULT NULL",
    ];

    foreach ($message_columns as $column => $definition) {
        $safe_column = preg_replace('/[^a-zA-Z0-9_]/', '', $column);
        $row = $wpdb->get_results($wpdb->prepare(
            "SHOW COLUMNS FROM `$messages_table` LIKE %s",
            $wpdb->esc_like($safe_column)
        ));
        if (empty($row)) {
            if ($wpdb->query(
                "ALTER TABLE `$messages_table` ADD `$safe_column` $definition"
            ) === false) {
                $migration_ok = false;
            }
        }
    }

    require_once ABSPATH . 'wp-admin/includes/upgrade.php';
    $charset_collate = $wpdb->get_charset_collate();

    dbDelta("CREATE TABLE " . aimee_table('aimee_analytics_events') . " (
        id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
        user_id BIGINT UNSIGNED NOT NULL,
        event_name VARCHAR(100) NOT NULL,
        properties LONGTEXT NULL,
        page_path VARCHAR(255) NULL,
        occurred_at DATETIME NOT NULL,
        created_at DATETIME NOT NULL,
        PRIMARY KEY (id),
        KEY user_event (user_id, event_name),
        KEY occurred_at (occurred_at)
    ) ENGINE=InnoDB $charset_collate;");

    dbDelta("CREATE TABLE " . aimee_voice_note_table() . " (
        id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
        note_token CHAR(36) NOT NULL,
        user_id BIGINT UNSIGNED NOT NULL,
        status VARCHAR(24) NOT NULL DEFAULT 'queued',
        result_status VARCHAR(32) NOT NULL DEFAULT 'processing',
        route_hint VARCHAR(32) NULL,
        route_used VARCHAR(32) NULL,
        input_file VARCHAR(255) NOT NULL,
        input_mime VARCHAR(80) NOT NULL,
        input_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,
        recorded_ms INT UNSIGNED NOT NULL DEFAULT 0,
        transcript LONGTEXT NULL,
        reply_text LONGTEXT NULL,
        reply_duration_ms INT UNSIGNED NOT NULL DEFAULT 0,
        reply_file VARCHAR(255) NULL,
        reply_mime VARCHAR(80) NULL,
        reply_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,
        audio_status VARCHAR(32) NOT NULL DEFAULT 'processing',
        user_message_id BIGINT UNSIGNED NULL,
        aimee_message_id BIGINT UNSIGNED NULL,
        subscription_json LONGTEXT NULL,
        media_json LONGTEXT NULL,
