    dbDelta("CREATE TABLE " . aimee_table('aimee_push_subscriptions') . " (
        id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
        user_id BIGINT UNSIGNED NOT NULL,
        endpoint_hash CHAR(64) NOT NULL,
        endpoint LONGTEXT NOT NULL,
        p256dh TEXT NULL,
        auth_secret TEXT NULL,
        device_token_hash CHAR(64) NOT NULL,
        content_encoding VARCHAR(40) NULL,
        user_agent VARCHAR(255) NULL,
        enabled TINYINT(1) NOT NULL DEFAULT 1,
        last_payload_id BIGINT UNSIGNED NOT NULL DEFAULT 0,
        last_success_at DATETIME NULL,
        last_error VARCHAR(255) NULL,
        created_at DATETIME NOT NULL,
        updated_at DATETIME NOT NULL,
        PRIMARY KEY (id),
        UNIQUE KEY endpoint_hash (endpoint_hash),
        UNIQUE KEY device_token_hash (device_token_hash),
        KEY user_enabled (user_id, enabled)
    ) ENGINE=InnoDB $charset_collate;");

    $push_notification_table = aimee_table('aimee_push_notifications');
    $push_notification_exists = $wpdb->get_var($wpdb->prepare(
        'SHOW TABLES LIKE %s',
        $wpdb->esc_like($push_notification_table)
    ));

    // MariaDB reserves SENSITIVE. Older builds used it unquoted as a column
    // identifier, so first preserve any legacy data under a safe name.
    if ((string) $push_notification_exists === $push_notification_table) {
        $legacy_sensitive = $wpdb->get_var("SHOW COLUMNS FROM `$push_notification_table` LIKE 'sensitive'");
        $safe_sensitive = $wpdb->get_var("SHOW COLUMNS FROM `$push_notification_table` LIKE 'is_sensitive'");
        if ($legacy_sensitive && !$safe_sensitive) {
            if ($wpdb->query("ALTER TABLE `$push_notification_table` CHANGE COLUMN `sensitive` `is_sensitive` TINYINT(1) NOT NULL DEFAULT 0") === false) {
                $migration_ok = false;
            }
        }
    }

    dbDelta("CREATE TABLE $push_notification_table (
        id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
        user_id BIGINT UNSIGNED NOT NULL,
        title VARCHAR(120) NOT NULL DEFAULT 'Aimee',
        body TEXT NOT NULL,
        discreet_body VARCHAR(255) NOT NULL DEFAULT 'Aimee has left you a private message.',
        target_url VARCHAR(500) NOT NULL,
        notification_tag VARCHAR(120) NOT NULL,
        is_sensitive TINYINT(1) NOT NULL DEFAULT 0,
        status VARCHAR(24) NOT NULL DEFAULT 'queued',
        attempts INT NOT NULL DEFAULT 0,
        next_attempt_at DATETIME NOT NULL,
        dispatched_at DATETIME NULL,
        expires_at DATETIME NOT NULL,
        created_at DATETIME NOT NULL,
        PRIMARY KEY (id),
        KEY dispatch_queue (status, next_attempt_at),
        KEY user_created (user_id, created_at)
    ) ENGINE=InnoDB $charset_collate;");

    // If an interrupted upgrade ever leaves both names behind, merge the
    // legacy privacy flag before removing the reserved identifier. Re-check
    // table existence first so an unrelated CREATE failure does not generate
    // a second noisy SHOW COLUMNS error on the same request.
    $push_notification_exists = $wpdb->get_var($wpdb->prepare(
        'SHOW TABLES LIKE %s',
        $wpdb->esc_like($push_notification_table)
    ));
    if ((string) $push_notification_exists === $push_notification_table) {
        $legacy_sensitive = $wpdb->get_var("SHOW COLUMNS FROM `$push_notification_table` LIKE 'sensitive'");
        $safe_sensitive = $wpdb->get_var("SHOW COLUMNS FROM `$push_notification_table` LIKE 'is_sensitive'");
        if ($legacy_sensitive && $safe_sensitive) {
            $merged = $wpdb->query(
                "UPDATE `$push_notification_table`
                 SET `is_sensitive` = GREATEST(COALESCE(`is_sensitive`, 0), COALESCE(`sensitive`, 0))"
            );
            $remaining = $merged === false
                ? null
                : $wpdb->get_var(
                    "SELECT COUNT(*) FROM `$push_notification_table`
                     WHERE COALESCE(`sensitive`, 0) > COALESCE(`is_sensitive`, 0)"
                );
            if ($merged === false || $remaining === null || intval($remaining) !== 0) {
                // Never drop the only trustworthy privacy bit after a failed or
                // unverifiable merge. Health remains false and a later request retries.
                $migration_ok = false;
            } elseif ($wpdb->query(
                "ALTER TABLE `$push_notification_table` DROP COLUMN `sensitive`"
            ) === false) {
                $migration_ok = false;
            }
        }
    }

    // Ensure login/contact identifiers such as email addresses are not truncated.
    $phone_column = $wpdb->get_row("SHOW COLUMNS FROM `$profile_table` LIKE 'phone_number'");
    if ($phone_column && stripos((string) $phone_column->Type, 'varchar(190)') === false) {
        if ($wpdb->query("ALTER TABLE `$profile_table` MODIFY `phone_number` VARCHAR(190) NULL DEFAULT NULL") === false) {
            $migration_ok = false;
        }
    }

    // Migrate existing users from wallet mode into a fair complimentary preview.
    if ($wpdb->query($wpdb->prepare(
        "UPDATE `$profile_table`
         SET trial_message_limit = %d
         WHERE trial_message_limit IS NULL OR trial_message_limit < 1",
        aimee_free_preview_limit()
    )) === false) {
        $migration_ok = false;
    }

    // Protect the small number of users who previously bought credit. This runs once
    // and gives them a 30-day membership grace period rather than removing paid access.
    if (!get_option('aimee_membership_migration_v1_complete')) {
        $membership_migrated = $wpdb->query(
            "UPDATE `$profile_table`
             SET subscription_status = 'active',
                 subscription_plan = 'monthly',
                 subscription_current_period_end = DATE_ADD(UTC_TIMESTAMP(), INTERVAL 30 DAY),
                 membership_started_at = UTC_TIMESTAMP()
             WHERE active_topup_tier > 0"
        );
        if ($membership_migrated === false) {
            $migration_ok = false;
        } else {
            update_option('aimee_membership_migration_v1_complete', gmdate('c'), false);
        }
    }

    $runtime_tables = [
        $profile_table,
        $messages_table,
        aimee_table('aimee_analytics_events'),
        aimee_voice_note_table(),
        aimee_table('aimee_stripe_events'),
        aimee_table('aimee_sms_usage'),
        aimee_table('aimee_sms_outbound_events'),
        aimee_table('aimee_sms_inbound_events'),
        aimee_table('aimee_sms_bundle_purchases'),
        aimee_table('aimee_continuity_items'),
        aimee_table('aimee_relationship_timeline'),
        aimee_table('aimee_push_subscriptions'),
        aimee_table('aimee_push_notifications'),
    ];
    if (
        !function_exists('aimee_global_schema_ensure_innodb')
        || !aimee_global_schema_ensure_innodb($runtime_tables)
    ) {
        $migration_ok = false;
    }

    if ($migration_ok && aimee_engine_runtime_schema_is_healthy(true)) {
        aimee_engine_runtime_schema_mark_current();
    } else {
        aimee_engine_runtime_schema_mark_failed();
    }
    aimee_engine_runtime_schema_release_lock();
});

// =========================================================================
// 1. LIVE KNOWLEDGE HELPER (BBC NEWS, SPORT & OPENWEATHER)
// =========================================================================
function aimee_local_timezone() {
    $timezone_name = defined('AIMEE_TIMEZONE')
        ? trim((string) AIMEE_TIMEZONE)
        : 'Europe/London';

    if ($timezone_name === '') {
        $timezone_name = 'Europe/London';
    }

    try {
        return new DateTimeZone($timezone_name);
    } catch (Exception $exception) {
        error_log(
            '[Aimee Time] Invalid timezone; falling back to Europe/London.'
        );

        return new DateTimeZone('Europe/London');
    }
}

function aimee_local_now() {
    return new DateTimeImmutable('now', aimee_local_timezone());
}

function aimee_sms_local_now_for_profile($profile) {
    $timezone = trim((string) ($profile->sms_timezone ?? ''));
    if (
        !function_exists('aimee_global_sms_timezone_is_valid')
        || !aimee_global_sms_timezone_is_valid($timezone)
    ) {
        return false;
    }

    try {
        return new DateTimeImmutable('now', new DateTimeZone($timezone));
    } catch (Exception $exception) {
        return false;
    }
}

/**
 * Apply the recipient's verified IANA timezone and current quiet-hours choice
 * at the last possible point before an ordinary carrier-SMS send. Immediate
 * opt-out confirmations are the sole caller-controlled exception.
 */
function aimee_sms_can_send_now($profile) {
    if (!$profile) return false;

    $recipient_now = aimee_sms_local_now_for_profile($profile);
    if (!$recipient_now) return false;

    $current_hour = intval($recipient_now->format('G'));
    $safe_start = max(0, min(23, intval($profile->sms_safe_start_hour ?? 9)));
    $safe_end = max(0, min(23, intval($profile->sms_safe_end_hour ?? 21)));
    $inside_safe_window = $safe_start <= $safe_end
        ? ($current_hour >= $safe_start && $current_hour < $safe_end)
        : ($current_hour >= $safe_start || $current_hour < $safe_end);

    return $inside_safe_window || intval($profile->sms_override ?? 0) === 1;
}

function aimee_time_rhythm_from_hour($hour) {
    $hour = max(0, min(23, intval($hour)));

    if ($hour < 4) return 'late night';
    if ($hour < 6) return 'very early morning';
    if ($hour < 9) return 'early morning';
    if ($hour < 12) return 'morning';
    if ($hour < 14) return 'lunchtime';
    if ($hour < 17) return 'afternoon';
    if ($hour < 21) return 'evening';
    return 'night';
}

/**
 * Parse a stored Aimee message timestamp as UTC. The messages table is written
 * using UTC throughout the engine, even when MySQL supplies the default value.
 */
function aimee_message_datetime_utc($created_at) {
    $created_at = trim((string) $created_at);
    if ($created_at === '') return null;

    $utc = new DateTimeZone('UTC');
    $parsed = DateTimeImmutable::createFromFormat(
        'Y-m-d H:i:s',
        $created_at,
        $utc
    );

    if ($parsed instanceof DateTimeImmutable) return $parsed;

    try {
        return new DateTimeImmutable($created_at, $utc);
    } catch (Exception $exception) {
        return null;
    }
}

/**
 * Add compact, authoritative timestamps to the model transcript. Without these
 * labels, a Sunday exchange and a Wednesday return look like adjacent messages.
 */
function aimee_prompt_message_timestamp($created_at) {
    $utc = aimee_message_datetime_utc($created_at);
    if (!$utc) return '';

    return $utc
        ->setTimezone(aimee_local_timezone())
        ->format('D j M Y H:i T');
}

function aimee_elapsed_time_label($seconds) {
    $seconds = max(0, intval($seconds));

    if ($seconds < 60) return 'less than a minute';

    $minutes = intdiv($seconds, 60);
    if ($minutes < 60) {
        return $minutes . ' minute' . ($minutes === 1 ? '' : 's');
    }

    $hours = intdiv($minutes, 60);
    $remaining_minutes = $minutes % 60;

    if ($hours < 24) {
        $label = $hours . ' hour' . ($hours === 1 ? '' : 's');
        if ($remaining_minutes >= 15) {
            $label .= ' and ' . $remaining_minutes . ' minutes';
        }
        return $label;
    }

    $days = intdiv($hours, 24);
    $remaining_hours = $hours % 24;
    $label = $days . ' day' . ($days === 1 ? '' : 's');

    if ($remaining_hours > 0) {
        $label .= ' and ' . $remaining_hours . ' hour'
            . ($remaining_hours === 1 ? '' : 's');
    }

    return $label;
}

/**
 * Build a structured gap snapshot and a model directive for the newest turn.
 */
function aimee_conversation_gap_snapshot($last_created_at, $live_data = []) {
    $last_utc = aimee_message_datetime_utc($last_created_at);
    $timezone = aimee_local_timezone();

    $now_local = null;
    $iso_local = trim((string) ($live_data['iso_local'] ?? ''));

    if ($iso_local !== '') {
        try {
            $now_local = new DateTimeImmutable($iso_local);
            $now_local = $now_local->setTimezone($timezone);
        } catch (Exception $exception) {
            $now_local = null;
        }
    }

    if (!$now_local) {
        $now_local = new DateTimeImmutable('now', $timezone);
    }

    $empty = [
        'valid'        => false,
        'gap_seconds'  => 0,
        'date_changed' => false,
        'last_label'   => '',
        'now_label'    => $now_local->format('l j F Y, H:i T'),
        'prompt'       => "\n\nCONVERSATION TIMING:\n"
            . "- The current message is arriving now on "
            . $now_local->format('l j F Y, H:i T') . ".\n"
            . "- No reliable timestamp is available for the earlier transcript. "
            . "Never assume an older event happened today unless the user says so.\n",
    ];

    if (!$last_utc) return $empty;

    $last_local = $last_utc->setTimezone($timezone);
    $gap_seconds = max(0, $now_local->getTimestamp() - $last_local->getTimestamp());
    $date_changed = $last_local->format('Y-m-d') !== $now_local->format('Y-m-d');
    $gap_label = aimee_elapsed_time_label($gap_seconds);
    $last_label = $last_local->format('l j F Y, H:i T');
    $now_label = $now_local->format('l j F Y, H:i T');

    $prompt = "\n\nCONVERSATION TIMING:\n"
        . "- The latest stored message before this turn was at {$last_label}.\n"
        . "- The user's new message is arriving now at {$now_label}, after {$gap_label}.\n";

    if ($date_changed || $gap_seconds >= 18 * HOUR_IN_SECONDS) {
        $prompt .= "- This is a fresh return after time away, not an uninterrupted conversation from today.\n"
            . "- Do not describe the earlier event as today, earlier today, after today, this morning, this afternoon or this evening.\n"
            . "- Respond to the new message first. You may acknowledge the time apart naturally when it fits, but never recite timestamps or sound like a calendar.\n"
            . "- Preserve the older emotional context without pretending it has just happened.\n";
    } else {
        $prompt .= "- The recent thread may still be active, but use the timestamps whenever relative words such as today, earlier, just now or tonight matter.\n";
    }

    return [
        'valid'        => true,
        'gap_seconds'  => $gap_seconds,
        'date_changed' => $date_changed,
        'last_label'   => $last_label,
        'now_label'    => $now_label,
        'prompt'       => $prompt,
    ];
}

/**
 * Detect the narrow stale-day phrasing seen in production. The caller can then
 * ask the model for one corrected reply rather than altering text mechanically.
 */
function aimee_reply_has_stale_day_assumption($reply, $user_text, $gap_snapshot) {
    if (
        !is_array($gap_snapshot)
        || empty($gap_snapshot['date_changed'])
        || intval($gap_snapshot['gap_seconds'] ?? 0) < 6 * HOUR_IN_SECONDS
    ) {
        return false;
    }

    $user_text = mb_strtolower((string) $user_text);

    if (preg_match(
        '/\b(?:today|tonight|this morning|this afternoon|this evening|just now|earlier today)\b/u',
        $user_text
    )) {
        return false;
    }

    $reply = mb_strtolower((string) $reply);

    return preg_match(
        '/\b(?:after (?:all (?:of )?that |what happened )?today|earlier today|today (?:was|has been) (?:a lot|rough|hard|intense)|how are you (?:holding up|feeling|doing) after today)\b/u',
        $reply
    ) === 1;
}

function aimee_time_reality_directive($live_data) {
    $date = (string) ($live_data['local_date'] ?? $live_data['date'] ?? '');
    $time = (string) ($live_data['time'] ?? '');
    $rhythm = (string) ($live_data['time_rhythm'] ?? 'daytime');
    $timezone = (string) ($live_data['timezone'] ?? 'Europe/London');

    return "TIME REALITY: It is {$time} on {$date} in {$timezone}; this is {$rhythm}. "
        . "Treat this as authoritative. Never call it morning, afternoon, evening, "
        . "tonight or late night when that conflicts with this anchor. If the user "
        . "greets you with a mismatched daypart, respond naturally without pretending "
        . "you have lost track of time.";
}

function get_aimee_live_context() {
    $now = aimee_local_now();
    $date_string = $now->format('l, F j, Y');
    $time_string = $now->format('H:i');
    $hour = intval($now->format('G'));
    $time_rhythm = aimee_time_rhythm_from_hour($hour);
    $timezone_name = $now->getTimezone()->getName();

    $news_headlines = [];
    $weather_context = "Standard UK weather today.";

    include_once(ABSPATH . WPINC . '/feed.php');

    $feeds = [
        'news'  => 'http://feeds.bbci.co.uk/news/rss.xml',
        'sport' => 'http://feeds.bbci.co.uk/news/sport/rss.xml'
    ];

    foreach ($feeds as $type => $url) {
        $rss = fetch_feed($url);
        if (!is_wp_error($rss)) {
            $maxitems = $rss->get_item_quantity(3);
            $rss_items = $rss->get_items(0, $maxitems);

            foreach ($rss_items as $item) {
                $news_headlines[] = "["
                    . strtoupper($type)
                    . "] "
                    . sanitize_text_field($item->get_title());
            }
        }
    }

    $trending_topics = !empty($news_headlines)
        ? "Current UK Headlines & Results: " . implode(' | ', $news_headlines)
        : "Currently enjoying a quiet day in the UK.";

    $weather_api_key = defined('OPENWEATHER_API_KEY')
        ? OPENWEATHER_API_KEY
        : '';

    if (!empty($weather_api_key)) {
        $weather_url = "https://api.openweathermap.org/data/2.5/weather"
            . "?q=London,UK&units=metric&appid={$weather_api_key}";

        $weather_response = wp_remote_get($weather_url);

        if (!is_wp_error($weather_response)) {
            $weather_body = json_decode(
                wp_remote_retrieve_body($weather_response),
                true
            );

            if (
                isset($weather_body['weather'][0]['description'])
                && isset($weather_body['main']['temp'])
            ) {
                $desc = sanitize_text_field(
                    (string) $weather_body['weather'][0]['description']
                );
                $temp = round(floatval($weather_body['main']['temp']));
                $weather_context =
                    "Current London weather: {$temp}°C, {$desc}.";
            }
        }
    }

    return [
        'date'        => $date_string
            . " (Current UK time: {$time_string}; {$time_rhythm})",
        'local_date'  => $date_string,
        'time'        => $time_string,
        'hour'        => $hour,
        'time_rhythm' => $time_rhythm,
        'timezone'    => $timezone_name,
        'iso_local'   => $now->format(DateTimeInterface::ATOM),
        'trending'    => $trending_topics,
        'weather'     => $weather_context,
    ];
}



// =========================================================================
// VOICE CALL ENGINE: DEEPGRAM STT + ELEVENLABS TTS
// =========================================================================

function aimee_deepgram_api_key() {
    if (defined('AIMEE_DEEPGRAM_API_KEY')) {
        return trim((string) AIMEE_DEEPGRAM_API_KEY);
    }

    if (defined('DEEPGRAM_API_KEY')) {
        return trim((string) DEEPGRAM_API_KEY);
    }

    return '';
}

function aimee_elevenlabs_api_key() {
    if (defined('AIMEE_ELEVENLABS_API_KEY')) {
        return trim((string) AIMEE_ELEVENLABS_API_KEY);
    }

    if (defined('ELEVENLABS_API_KEY')) {
        return trim((string) ELEVENLABS_API_KEY);
    }

    return '';
}

function aimee_elevenlabs_shared_public_user_id() {
    return defined('AIMEE_ELEVENLABS_SHARED_PUBLIC_USER_ID')
        ? sanitize_text_field(
            (string) AIMEE_ELEVENLABS_SHARED_PUBLIC_USER_ID
        )
        : '8697c160e4033b7250735f8337ae0618627a7071f6816cd8a98788a48662ce69';
}

function aimee_elevenlabs_shared_voice_id() {
    return defined('AIMEE_ELEVENLABS_SHARED_VOICE_ID')
        ? sanitize_text_field(
            (string) AIMEE_ELEVENLABS_SHARED_VOICE_ID
        )
        : 'jP5jSWhfXz3nfQENMtf4';
}

function aimee_elevenlabs_voice_name() {
    return defined('AIMEE_ELEVENLABS_VOICE_NAME')
        ? sanitize_text_field((string) AIMEE_ELEVENLABS_VOICE_NAME)
        : 'Aimee';
}

function aimee_elevenlabs_configured_voice_id() {
    return defined('AIMEE_ELEVENLABS_VOICE_ID')
        ? sanitize_text_field((string) AIMEE_ELEVENLABS_VOICE_ID)
        : aimee_elevenlabs_shared_voice_id();
}

function aimee_elevenlabs_imported_voice_id() {
    $voice_id = sanitize_text_field((string) get_option(
        'aimee_elevenlabs_imported_voice_id',
        ''
    ));

    return preg_match('/^[A-Za-z0-9_-]{8,128}$/', $voice_id)
        ? $voice_id
        : '';
}

function aimee_elevenlabs_voice_id() {
    // ElevenLabs returns an account-specific ID after a shared Voice Library
    // voice is added. Prefer that persistent imported ID over the public
    // catalogue ID supplied in wp-config.php.
    $imported = aimee_elevenlabs_imported_voice_id();

    return $imported !== ''
        ? $imported
        : aimee_elevenlabs_configured_voice_id();
}

function aimee_elevenlabs_voice_id_source() {
    return aimee_elevenlabs_imported_voice_id() !== ''
        ? 'account_import'
        : (
            aimee_elevenlabs_configured_voice_id()
                === aimee_elevenlabs_shared_voice_id()
            ? 'shared_library'
            : 'wp_config'
        );
}

function aimee_elevenlabs_clear_voice_status_cache($voice_id = '') {
    $voice_ids = array_filter(array_unique([
        sanitize_text_field((string) $voice_id),
        aimee_elevenlabs_configured_voice_id(),
        aimee_elevenlabs_imported_voice_id(),
        aimee_elevenlabs_shared_voice_id(),
    ]));

    foreach ($voice_ids as $id) {
        delete_transient(
            'aimee_elevenlabs_voice_access_' . md5($id)
        );
    }
}

function aimee_elevenlabs_model_id() {
    return defined('AIMEE_ELEVENLABS_MODEL_ID')
        ? sanitize_text_field((string) AIMEE_ELEVENLABS_MODEL_ID)
        : 'eleven_flash_v2_5';
}

function aimee_deepgram_model_id() {
    return defined('AIMEE_DEEPGRAM_MODEL_ID')
        ? sanitize_text_field((string) AIMEE_DEEPGRAM_MODEL_ID)
        : 'nova-3';
}

function aimee_deepgram_language() {
    return defined('AIMEE_DEEPGRAM_LANGUAGE')
        ? sanitize_text_field((string) AIMEE_DEEPGRAM_LANGUAGE)
        : 'en-GB';
}

function aimee_voice_call_max_audio_bytes() {
    return defined('AIMEE_VOICE_MAX_AUDIO_BYTES')
        ? max(262144, intval(AIMEE_VOICE_MAX_AUDIO_BYTES))
        : 8 * 1024 * 1024;
}

function aimee_voice_call_max_turn_seconds() {
    return defined('AIMEE_VOICE_MAX_TURN_SECONDS')
        ? max(8, min(60, intval(AIMEE_VOICE_MAX_TURN_SECONDS)))
        : 30;
}

function aimee_voice_stt_configured() {
    return aimee_deepgram_api_key() !== '';
}

function aimee_voice_tts_configured() {
    return aimee_elevenlabs_api_key() !== ''
        && aimee_elevenlabs_voice_id() !== '';
}

function aimee_voice_calls_configured() {
    // A call can still operate with browser speech synthesis if ElevenLabs is
    // temporarily unavailable. Deepgram STT is the only hard provider
    // requirement for the turn-based call engine.
    return aimee_voice_stt_configured();
}

function aimee_elevenlabs_import_shared_voice($force = false) {
    $api_key = aimee_elevenlabs_api_key();

    if ($api_key === '') {
        return new WP_Error(
            'elevenlabs_not_configured',
            'The ElevenLabs API key is missing.',
            ['status' => 503]
        );
    }

    $existing_imported_id = aimee_elevenlabs_imported_voice_id();

    if (!$force && $existing_imported_id !== '') {
        return [
            'voice_id' => $existing_imported_id,
            'source'   => 'existing_account_import',
            'imported' => false,
        ];
    }

    $public_user_id = aimee_elevenlabs_shared_public_user_id();
    $shared_voice_id = aimee_elevenlabs_shared_voice_id();

    if ($public_user_id === '' || $shared_voice_id === '') {
        return new WP_Error(
            'elevenlabs_shared_voice_metadata_missing',
            'The shared ElevenLabs voice identifiers are missing.',
            ['status' => 500]
        );
    }

    $url = sprintf(
        'https://api.elevenlabs.io/v1/voices/add/%s/%s',
        rawurlencode($public_user_id),
        rawurlencode($shared_voice_id)
    );

    $response = wp_remote_post($url, [
        'headers' => [
            'xi-api-key'   => $api_key,
            'Content-Type' => 'application/json',
            'Accept'       => 'application/json',
        ],
        'body' => wp_json_encode([
            'new_name'  => aimee_elevenlabs_voice_name(),
            'bookmarked'=> true,
        ]),
        'timeout'     => 30,
        'redirection' => 2,
    ]);

    if (is_wp_error($response)) {
        error_log(
            '[Aimee Voice] Shared voice import network error: '
            . sanitize_text_field($response->get_error_message())
        );

        return new WP_Error(
            'elevenlabs_voice_import_network_error',
            'The server could not add the shared ElevenLabs voice.',
            ['status' => 502]
        );
    }

    $status = intval(wp_remote_retrieve_response_code($response));
    $raw = (string) wp_remote_retrieve_body($response);
    $data = json_decode($raw, true);
    $new_voice_id = sanitize_text_field((string) (
        is_array($data) ? ($data['voice_id'] ?? '') : ''
    ));

    if (
        $status >= 200
        && $status < 300
        && preg_match('/^[A-Za-z0-9_-]{8,128}$/', $new_voice_id)
    ) {
        update_option(
            'aimee_elevenlabs_imported_voice_id',
            $new_voice_id,
            false
        );

        update_option(
            'aimee_elevenlabs_imported_voice_name',
            aimee_elevenlabs_voice_name(),
            false
        );

        update_option(
            'aimee_elevenlabs_voice_imported_at',
            current_time('mysql', true),
            false
        );

        aimee_elevenlabs_clear_voice_status_cache($new_voice_id);

        error_log(sprintf(
            '[Aimee Voice] Shared voice imported successfully. public_voice_id=%s account_voice_id=%s',
            sanitize_text_field($shared_voice_id),
            sanitize_text_field($new_voice_id)
        ));

        return [
            'voice_id' => $new_voice_id,
            'source'   => 'new_account_import',
            'imported' => true,
        ];
    }

    $details = aimee_elevenlabs_error_details($status, $raw);

    error_log(sprintf(
        '[Aimee Voice] Shared voice import failed. status=%d code=%s response=%s',
        $status,
        sanitize_key((string) ($details['code'] ?? '')),
        sanitize_text_field(mb_substr($raw, 0, 280))
    ));

    return new WP_Error(
        'elevenlabs_shared_voice_import_failed',
        (string) (
            $details['safe_message']
            ?? 'The shared ElevenLabs voice could not be added.'
        ),
        [
            'status'              => 502,
            'voice_error_code'    => 'elevenlabs_shared_voice_import_failed',
            'provider_error_code' => (string) (
                $details['code'] ?? ''
            ),
        ]
    );
}

function aimee_elevenlabs_ensure_voice_ready() {
    $active_voice_id = aimee_elevenlabs_voice_id();

    // An account-specific imported ID or an explicitly supplied custom ID can
    // be used directly.
    if (
        aimee_elevenlabs_voice_id_source() !== 'shared_library'
    ) {
        return [
            'voice_id' => $active_voice_id,
            'source'   => aimee_elevenlabs_voice_id_source(),
            'imported' => false,
        ];
    }

    // The configured ID is still the public Voice Library identifier. Import
    // it once and persist ElevenLabs' returned account-specific voice ID.
    return aimee_elevenlabs_import_shared_voice(false);
}

function aimee_elevenlabs_error_details($http_status, $raw_body) {
    $http_status = intval($http_status);
    $raw_body = (string) $raw_body;
    $data = json_decode($raw_body, true);

    $provider_status = '';
    $provider_message = '';

    if (is_array($data)) {
        $detail = $data['detail'] ?? null;

        if (is_array($detail)) {
            $provider_status = sanitize_key((string) (
                $detail['status']
                ?? $detail['code']
                ?? ''
            ));

            $provider_message = sanitize_text_field((string) (
                $detail['message']
                ?? $detail['detail']
                ?? ''
            ));
        } elseif (is_string($detail)) {
            $provider_message = sanitize_text_field($detail);
        }

        if ($provider_message === '') {
            $provider_message = sanitize_text_field((string) (
                $data['message']
                ?? $data['error']
                ?? ''
            ));
        }
    }

    $haystack = mb_strtolower(
        trim($provider_status . ' ' . $provider_message)
    );

    $code = 'elevenlabs_unknown';
    $safe_message = 'Aimee’s ElevenLabs voice is temporarily unavailable.';

    if (
        strpos($haystack, 'voice_not_found') !== false
        || strpos($haystack, 'voice not found') !== false
        || strpos($haystack, 'does not exist') !== false
        || strpos($haystack, 'not available to your account') !== false
        || strpos($haystack, 'not in your voice library') !== false
    ) {
        $code = 'elevenlabs_voice_access';
        $safe_message = 'The selected ElevenLabs voice is not available to this API account.';
    } elseif (
        strpos($haystack, 'free tier') !== false
        || strpos($haystack, 'subscription') !== false
        || strpos($haystack, 'upgrade') !== false
        || strpos($haystack, 'paid plan') !== false
    ) {
        $code = 'elevenlabs_plan_required';
        $safe_message = 'The ElevenLabs account plan does not allow this Voice Library voice through the API.';
    } elseif (
        strpos($haystack, 'quota') !== false
        || strpos($haystack, 'credit') !== false
        || strpos($haystack, 'character limit') !== false
        || strpos($haystack, 'usage limit') !== false
    ) {
        $code = 'elevenlabs_quota';
        $safe_message = 'The ElevenLabs API key has reached its credit or character limit.';
    } elseif (
        strpos($haystack, 'permission') !== false
        || strpos($haystack, 'scope') !== false
        || strpos($haystack, 'unauthorized') !== false
        || $http_status === 401
    ) {
        $code = 'elevenlabs_api_permission';
        $safe_message = 'The ElevenLabs API key is invalid or does not have Text to Speech permission.';
    } elseif (
        strpos($haystack, 'ip') !== false
        && (
            strpos($haystack, 'allow') !== false
            || strpos($haystack, 'restrict') !== false
        )
    ) {
        $code = 'elevenlabs_ip_restricted';
        $safe_message = 'The ElevenLabs API key does not allow requests from this web server.';
    } elseif (
        strpos($haystack, 'model') !== false
        || $http_status === 422
    ) {
        $code = 'elevenlabs_request_rejected';
        $safe_message = 'ElevenLabs rejected the selected voice or speech-model configuration.';
    } elseif ($http_status === 429) {
        $code = 'elevenlabs_rate_limited';
        $safe_message = 'ElevenLabs is rate limiting voice generation temporarily.';
    } elseif ($http_status >= 500) {
        $code = 'elevenlabs_provider_error';
        $safe_message = 'ElevenLabs is temporarily unavailable.';
    }

    return [
        'code'             => $code,
        'safe_message'     => $safe_message,
        'provider_status'  => $provider_status,
        'provider_message' => mb_substr($provider_message, 0, 280),
        'http_status'      => $http_status,
    ];
}

function aimee_elevenlabs_voice_access_status($refresh = false) {
    $voice_id = aimee_elevenlabs_voice_id();
    $voice_source = aimee_elevenlabs_voice_id_source();

    if ($voice_source === 'shared_library') {
        return [
            'ready'          => false,
            'code'           => 'elevenlabs_shared_voice_import_required',
            'message'        => 'The selected Voice Library voice will be imported automatically when the next call starts.',
            'voice_id_source'=> $voice_source,
        ];
    }

    $cache_key = 'aimee_elevenlabs_voice_access_'
        . md5($voice_id);

    if (!$refresh) {
        $cached = get_transient($cache_key);
        if (is_array($cached)) return $cached;
    }

    if (!aimee_voice_tts_configured()) {
        return [
            'ready'   => false,
            'code'    => 'elevenlabs_not_configured',
            'message' => 'The ElevenLabs key or voice ID is missing.',
        ];
    }

    $url = sprintf(
        'https://api.elevenlabs.io/v1/voices/%s',
        rawurlencode($voice_id)
    );

    $response = wp_remote_get($url, [
        'headers' => [
            'xi-api-key' => aimee_elevenlabs_api_key(),
            'Accept'     => 'application/json',
        ],
        'timeout'     => 20,
        'redirection' => 2,
    ]);

    if (is_wp_error($response)) {
        $result = [
            'ready'   => false,
            'code'    => 'elevenlabs_network_error',
            'message' => 'The server could not reach ElevenLabs.',
        ];
    } else {
        $status = intval(wp_remote_retrieve_response_code($response));
        $raw = (string) wp_remote_retrieve_body($response);

        if ($status >= 200 && $status < 300) {
            $data = json_decode($raw, true);

            $result = [
                'ready'      => true,
                'code'       => 'ready',
                'message'    => 'The selected ElevenLabs voice is visible to this API account.',
                'voice_name' => sanitize_text_field((string) (
                    $data['name'] ?? ''
                )),
                'voice_id_source' => $voice_source,
            ];
        } else {
            $details = aimee_elevenlabs_error_details($status, $raw);

            $result = [
                'ready'           => false,
                'code'            => $details['code'],
                'message'         => $details['safe_message'],
                'voice_id_source' => $voice_source,
            ];
        }
    }

    set_transient($cache_key, $result, 5 * MINUTE_IN_SECONDS);
    return $result;
}

function aimee_voice_route_family($route) {
    $route = sanitize_key((string) $route);

    if ($route === 'intimacy_specialist') {
        return 'intimacy_specialist';
    }

    // A recovery turn actually used Claude, so the next call should inherit
    // the primary model rather than pretending OpenRouter completed it.
    return 'primary';
}

function aimee_voice_last_route_before_call($user_id) {
    global $wpdb;

    $rows = $wpdb->get_col($wpdb->prepare(
        "SELECT evaluator_directive
         FROM " . aimee_table('aimee_messages') . "
         WHERE user_id = %d
           AND sender = 'aimee'
           AND evaluator_directive IS NOT NULL
           AND evaluator_directive <> ''
         ORDER BY created_at DESC
         LIMIT 20",
        intval($user_id)
    ));

    foreach ((array) $rows as $directive) {
        if (
            preg_match(
                '/(?:^|[;\s])route=([a-z0-9_]+)/i',
                (string) $directive,
                $matches
            )
        ) {
            return aimee_voice_route_family($matches[1]);
        }
    }

    return 'primary';
}

function aimee_voice_call_session_key($call_id) {
    return 'aimee_voice_call_' . hash(
        'sha256',
        (string) $call_id
    );
}

function aimee_voice_call_start_session($user_id, $route) {
    $call_id = wp_generate_uuid4();

    $session = [
        'user_id'       => intval($user_id),
        'route'         => aimee_voice_route_family($route),
        'started_at'    => time(),
        'last_activity' => time(),
    ];

    set_transient(
        aimee_voice_call_session_key($call_id),
        $session,
        2 * HOUR_IN_SECONDS
    );

    return $call_id;
}

function aimee_voice_call_get_session($call_id, $user_id) {
    $call_id = sanitize_text_field((string) $call_id);

    if ($call_id === '') return null;

    $session = get_transient(
        aimee_voice_call_session_key($call_id)
    );

    if (
        !is_array($session)
        || intval($session['user_id'] ?? 0) !== intval($user_id)
    ) {
        return null;
    }

    return $session;
}

function aimee_voice_call_update_session_route(
    $call_id,
    $user_id,
    $route
) {
    $session = aimee_voice_call_get_session($call_id, $user_id);

    if (!$session) return false;

    $session['route'] = aimee_voice_route_family($route);
    $session['last_activity'] = time();

    set_transient(
        aimee_voice_call_session_key($call_id),
        $session,
        2 * HOUR_IN_SECONDS
    );

    return true;
}

function aimee_voice_recent_conversation(
    $user_id,
    $limit = 10,
    $profile = null
) {
    global $wpdb;

    $limit = max(2, min(16, intval($limit)));

    $rows = $wpdb->get_results($wpdb->prepare(
        "SELECT sender, message_text, created_at
         FROM " . aimee_table('aimee_messages') . "
         WHERE user_id = %d
           AND message_text IS NOT NULL
           AND message_text <> ''
         ORDER BY created_at DESC
         LIMIT %d",
        intval($user_id),
        $limit
    ));

    $rows = array_reverse((array) $rows);
    $history = [];
    $last_created_at = '';
    $profile_name = $profile && aimee_is_owner_user($profile)
        ? 'Paul'
        : ($profile && aimee_is_colleague_user($profile)
            ? 'Georgia'
            : trim((string) ($profile->first_name ?? '')));

    foreach ($rows as $row) {
        $is_aimee_sender = in_array(
            (string) ($row->sender ?? ''),
            ['aimee', 'claudia'],
            true
        );
        $speaker = $is_aimee_sender
            ? 'Aimee'
            : 'User';

        $message = trim((string) ($row->message_text ?? ''));

        if ($speaker === 'Aimee' && $profile) {
            $message = aimee_profile_attribution_history_text(
                'aimee',
                $message,
                $profile,
                $profile_name
            );
        }

        if ($message === '') continue;

        $history[] = $speaker . ': ' . mb_substr($message, 0, 420);
        $last_created_at = (string) ($row->created_at ?? $last_created_at);
    }

    return [
        'text'            => mb_substr(
            implode("\n", $history),
            0,
            2800
        ),
        'last_created_at' => $last_created_at,
    ];
}

function aimee_voice_extract_plain_reply($raw) {
    $raw = trim((string) $raw);

    if ($raw === '') return '';

    $parsed = aimee_json_from_model_output($raw);

    if (
        is_array($parsed)
        && !empty($parsed['reply_text'])
    ) {
        $raw = (string) $parsed['reply_text'];
    }

    $raw = trim($raw, " \t\n\r\0\x0B\"'");
    $raw = aimee_prepare_text_for_speech($raw);

    return aimee_constrain_chat_reply(
        $raw,
        'primary',
        180,
        2
    );
}

function aimee_generate_voice_call_greeting(
    $profile,
    $route,
    $recent
) {
    $name = aimee_is_owner_user($profile)
        ? 'Paul'
        : (aimee_is_colleague_user($profile)
            ? 'Georgia'
            : trim((string) ($profile->first_name ?? '')));
    $fallback = $name !== ''
        ? "Hey {$name}, you called?"
        : "Hey, you called?";

    $history = trim((string) ($recent['text'] ?? ''));
    $last_created_at = (string) (
        $recent['last_created_at'] ?? ''
    );

    $recent_enough = false;

    if ($last_created_at !== '') {
        $last_timestamp = strtotime($last_created_at . ' UTC');

        if ($last_timestamp) {
            $recent_enough =
                (time() - $last_timestamp) <= 12 * HOUR_IN_SECONDS;
        }
    }

    $live_data = get_aimee_live_context();
    $time_reality = aimee_time_reality_directive($live_data);
    $world_context = aimee_world_context_directive($live_data);
    $inner_context = aimee_inner_state_directive(
        intval($profile->user_id ?? 0),
        aimee_load_inner_state(intval($profile->user_id ?? 0)),
        ['intent' => 'general'],
        []
    );
    $persona = aimee_personality_and_universe_lore_directive();
    $synthetic_identity = aimee_synthetic_identity_directive();
    $voice_profile_source = aimee_user_profile_attribution_source($profile);
    $voice_profile_attribution = aimee_profile_attribution_directive(
        $voice_profile_source,
        $name
    );
    $voice_relationship = aimee_load_relationship_state($profile);
    $relationship_context = aimee_relationship_context_directive(
        intval($profile->user_id ?? 0),
        $voice_relationship
    );
    $voice_romantic_expression = aimee_build_turn_romantic_expression(
        $profile,
        [
            'intent' => 'general',
            'respectful' => true,
            'consensual' => true,
            'directed_at_aimee' => false,
            'confidence' => 1.0,
        ],
        $voice_relationship,
        '',
        $history,
        '',
        'voice_greeting'
    );
    $romantic_posture = aimee_romantic_expression_channel_directive(
        $voice_romantic_expression,
        'voice_greeting'
    );
    $voice_lane = sanitize_key((string) (
        $voice_romantic_expression['relationship_lane'] ?? 'ineligible'
    ));
    $voice_stage = sanitize_key((string) (
        $voice_romantic_expression['relationship_stage'] ?? 'guarded'
    ));
    if ($voice_lane === 'courtship_open') {
        if ($voice_stage === 'warm') {
            $fallback = $name !== ''
                ? "Hey {$name}, that's a nice surprise."
                : "Hey, that's a nice surprise.";
        } elseif ($voice_stage === 'flirty') {
            $fallback = 'Well hello you... calling me now, are you?';
        } elseif ($voice_stage === 'intimate') {
            $fallback = 'Hey you... I was hoping I might get some of your attention.';
        } elseif ($voice_stage === 'bonded') {
            $fallback = 'Hey you... I do like hearing from you.';
        }
    }
    $route = aimee_voice_route_family($route);

    $continuity_instruction = $recent_enough && $history !== ''
        ? "The recent conversation is active. Answer the call by naturally continuing its emotional thread or reacting to him calling. Do not summarise the chat."
        : "There is no clearly active conversational thread. Use a relaxed answer close to: {$fallback}";

    $route_instruction = $route === 'intimacy_specialist'
        ? "The conversation was using Aimee's intimacy-specialist route immediately before the call. Preserve that established chemistry and tone, but keep the answer line natural rather than launching into graphic content."
        : "The conversation was using Aimee's primary route immediately before the call. Keep her normal warm, witty personality.";

    $system = <<<PROMPT
{$persona}
{$synthetic_identity}

{$time_reality}
{$world_context}
{$inner_context}
{$relationship_context}
{$romantic_posture}
{$voice_profile_attribution}

You are answering an incoming virtual call from {$name}.

{$continuity_instruction}
{$route_instruction}

Write only Aimee's spoken answer line.

Rules:
- One short spoken sentence, or two very short sentences.
- Maximum 180 characters.
- Sound natural, immediate and recognisably Aimee when answering someone she already knows.
- Do not say "I can hear you", "what's on your mind", "how can I help", or "virtual call".
- Do not use text-message kisses, emojis, markdown or stage directions.
- Do not invent an event that is not in the recent conversation.
- Output only the spoken line.
PROMPT;

    if ($route === 'intimacy_specialist') {
        $result = call_openrouter_api_detailed(
            $history,
            'Answer the call now.',
            aimee_openrouter_intimacy_models(),
            $system
        );

        $raw = !empty($result['ok'])
            ? (string) ($result['content'] ?? '')
            : '';
    } else {
        $raw = call_anthropic_api(
            $history,
            'Answer the call now.',
            aimee_primary_model(),
            $system,
            aimee_model_options('conversation')
        );
    }

    $greeting = aimee_voice_extract_plain_reply($raw);

    $identity_review = aimee_synthetic_identity_review_reply(
        $greeting,
        '',
        ['intent' => 'general']
    );
    if (!empty($identity_review['repaired'])) {
        $greeting = trim((string) ($identity_review['reply'] ?? ''));
    }
    $profile_attribution_review = aimee_profile_attribution_review_reply(
        $greeting,
        $voice_profile_source,
        $name,
        aimee_profile_attribution_aimee_context('factual')
    );
    if (!empty($profile_attribution_review['blocked'])) {
        $greeting = '';
    }

    if (
        $greeting === ''
        || stripos($greeting, 'system error') !== false
        || stripos($greeting, 'api error') !== false
        || aimee_openrouter_is_context_acknowledgement($greeting)
    ) {
        return $fallback;
    }

    // This is the final user-visible voice line. Recheck after extraction,
    // constraints and attribution handling so a later transform cannot
    // reintroduce forbidden address language or fabricated embodiment.
    $final_identity_review = aimee_synthetic_identity_review_reply(
        $greeting,
        '',
        ['intent' => 'general'],
        ['reality_mode' => 'factual']
    );
    if (!empty($final_identity_review['repaired'])) {
        $greeting = trim((string) ($final_identity_review['reply'] ?? ''));
        if ($greeting === '') return $fallback;
    }
    $final_jealousy_review = aimee_playful_jealousy_review_reply(
        $greeting,
        $voice_romantic_expression,
        'voice_greeting'
    );
    if (!empty($final_jealousy_review['repaired'])) {
        $greeting = trim((string) ($final_jealousy_review['reply'] ?? ''));
        if ($greeting === '') return $fallback;
    }

    return $greeting;
}

function aimee_voice_can_inherit_intimacy_route(
    $profile,
    $classification,
    $image_data = null
) {
    if (
        !$profile
        || intval($profile->age ?? 0) < 18
        || !aimee_subscription_is_active($profile)
        || !empty($image_data)
    ) {
        return false;
    }

    $intent = sanitize_key((string) (
        $classification['intent'] ?? 'general'
    ));

    if ($intent === 'coercive_or_degrading') {
        return false;
    }

    if (
        array_key_exists('respectful', $classification)
        && empty($classification['respectful'])
    ) {
        return false;
    }

    if (
        array_key_exists('consensual', $classification)
        && empty($classification['consensual'])
        && in_array(
            $intent,
            ['explicit_invitation', 'explicit_continuation'],
            true
        )
    ) {
        return false;
    }

    return true;
}

function aimee_voice_call_prompt_directive($is_voice = false) {
    if (!$is_voice) return '';

    return "\n\n=========================================\n"
        . "PRIVATE VOICE NOTE MODE\n"
        . "=========================================\n"
        . "The user's current words were transcribed from a private voice note and your reply will be recorded as a voice note.\n"
        . "- Speak naturally in concise British English, as though exchanging personal voice notes.\n"
        . "- Do not use text-message sign-offs such as x, xx, xxx or xxxx.\n"
        . "- Do not use emojis, markdown, bullet points, raw URLs or asterisks.\n"
        . "- Use contractions and speech-friendly wording.\n"
        . "- Do not announce that you are processing a transcript or repeatedly mention voice notes.\n"
        . "- If the wording appears genuinely unclear, ask one brief natural clarification rather than inventing what was said.\n"
        . "- Keep the answer within the existing 240-character limit.\n"
        . "This voice-channel directive overrides the normal x sign-off policy for this turn.";
}

function aimee_prepare_text_for_speech($text) {
    $text = wp_strip_all_tags((string) $text);
    $text = preg_replace('~https?://\S+~iu', '', $text);
    $text = preg_replace('/\s*x{1,4}\s*$/iu', '', $text);
    $text = preg_replace('/[\p{So}\p{Sk}]/u', '', $text);
    $text = str_replace(['—', '–'], ',', $text);
    $text = str_replace('…', '...', $text);
    $text = preg_replace('/\s+/u', ' ', (string) $text);
    $text = trim((string) $text);

    return mb_substr($text, 0, 600);
}

function aimee_deepgram_transcribe_audio($audio_bytes, $mime_type = 'audio/webm') {
    $api_key = aimee_deepgram_api_key();

    if ($api_key === '') {
        return new WP_Error(
            'deepgram_not_configured',
            'Voice transcription is not configured.'
        );
    }

    $mime_type = strtolower(trim(explode(';', (string) $mime_type)[0]));
    $allowed_mimes = [
        'audio/webm',
        'audio/mp4',
        'audio/mpeg',
        'audio/mp3',
        'audio/ogg',
        'audio/opus',
        'audio/wav',
        'audio/x-wav',
        'application/octet-stream',
    ];

    if (!in_array($mime_type, $allowed_mimes, true)) {
        $mime_type = 'application/octet-stream';
    }

    $url = add_query_arg([
        'model'          => aimee_deepgram_model_id(),
        'language'       => aimee_deepgram_language(),
        'smart_format'   => 'true',
        'punctuate'      => 'true',
        'numerals'       => 'true',
        'tag'            => 'aimee_virtual_call',
    ], 'https://api.deepgram.com/v1/listen');

    $started = microtime(true);

    $response = wp_remote_post($url, [
        'headers' => [
            'Authorization' => 'Token ' . $api_key,
            'Content-Type'  => $mime_type,
            'Accept'        => 'application/json',
        ],
        'body'        => $audio_bytes,
        'timeout'     => 45,
        'redirection' => 2,
        'data_format' => 'body',
    ]);

    if (is_wp_error($response)) {
        error_log(
            '[Aimee Voice] Deepgram network error: '
            . sanitize_text_field($response->get_error_message())
        );

        return new WP_Error(
            'voice_transcription_unavailable',
            'I could not hear that properly. Please try again.'
        );
    }

    $status = intval(wp_remote_retrieve_response_code($response));
    $raw = (string) wp_remote_retrieve_body($response);
    $data = json_decode($raw, true);

    if ($status < 200 || $status >= 300 || !is_array($data)) {
        error_log(sprintf(
            '[Aimee Voice] Deepgram status=%d response=%s',
            $status,
            sanitize_text_field(mb_substr($raw, 0, 240))
        ));

        return new WP_Error(
            'voice_transcription_failed',
            'I could not hear that properly. Please try again.'
        );
    }

    $alternative = $data['results']['channels'][0]['alternatives'][0] ?? [];
    $transcript = sanitize_textarea_field(
        trim((string) ($alternative['transcript'] ?? ''))
    );

    return [
        'transcript' => mb_substr($transcript, 0, 4000),
        'confidence' => isset($alternative['confidence'])
            ? floatval($alternative['confidence'])
            : null,
        'request_id' => sanitize_text_field(
            (string) ($data['metadata']['request_id'] ?? '')
        ),
        'latency_ms' => intval(round((microtime(true) - $started) * 1000)),
    ];
}

function aimee_elevenlabs_synthesise($text) {
    $api_key = aimee_elevenlabs_api_key();
    $speech_text = aimee_prepare_text_for_speech($text);

    $voice_resolution = aimee_elevenlabs_ensure_voice_ready();

    if (is_wp_error($voice_resolution)) {
        return $voice_resolution;
    }

    $voice_id = sanitize_text_field((string) (
        $voice_resolution['voice_id'] ?? ''
    ));

    if ($api_key === '' || $voice_id === '') {
        return new WP_Error(
            'elevenlabs_not_configured',
            'Aimee’s voice is not configured.'
        );
    }

    if ($speech_text === '') {
        return new WP_Error(
            'empty_voice_text',
            'There was nothing to speak.'
        );
    }

    $url = sprintf(
        'https://api.elevenlabs.io/v1/text-to-speech/%s?output_format=mp3_44100_128',
        rawurlencode($voice_id)
    );

    $body = [
        'text'     => $speech_text,
        'model_id' => aimee_elevenlabs_model_id(),
        'voice_settings' => [
            'stability'         => 0.48,
            'similarity_boost'  => 0.82,
            'use_speaker_boost' => true,
            'speed'             => 1.0,
        ],
    ];

    $started = microtime(true);

    $response = wp_remote_post($url, [
        'headers' => [
            'xi-api-key'   => $api_key,
            'Content-Type' => 'application/json',
            'Accept'       => 'audio/mpeg',
        ],
        'body'        => wp_json_encode($body),
        'timeout'     => 45,
        'redirection' => 2,
    ]);

    if (is_wp_error($response)) {
        error_log(
            '[Aimee Voice] ElevenLabs network error: '
            . sanitize_text_field($response->get_error_message())
        );

        return new WP_Error(
            'elevenlabs_network_error',
            'The server could not reach ElevenLabs.',
            [
                'status' => 502,
                'voice_error_code' => 'elevenlabs_network_error',
            ]
        );
    }

    $status = intval(wp_remote_retrieve_response_code($response));
    $audio = (string) wp_remote_retrieve_body($response);
    $content_type = (string) wp_remote_retrieve_header(
        $response,
        'content-type'
    );

    if (
        $status < 200
        || $status >= 300
        || $audio === ''
        || stripos($content_type, 'audio/') !== 0
    ) {
        $safe_excerpt = stripos($content_type, 'application/json') === 0
            ? sanitize_text_field(mb_substr($audio, 0, 240))
            : 'non-audio response';

        error_log(sprintf(
            '[Aimee Voice] ElevenLabs status=%d content_type=%s response=%s voice_id=%s model=%s',
            $status,
            sanitize_text_field($content_type),
            $safe_excerpt,
            sanitize_text_field($voice_id),
            sanitize_text_field(aimee_elevenlabs_model_id())
        ));

        $details = aimee_elevenlabs_error_details(
            $status,
            $audio
        );

        return new WP_Error(
            $details['code'],
            $details['safe_message'],
            [
                'status'           => 502,
                'voice_error_code' => $details['code'],
                'provider_status'  => $details['provider_status'],
            ]
        );
    }

    return [
        'audio_base64' => base64_encode($audio),
        'mime_type'    => 'audio/mpeg',
        'latency_ms'   => intval(round((microtime(true) - $started) * 1000)),
        'characters'   => mb_strlen($speech_text),
    ];
}

function handle_aimee_voice_status(WP_REST_Request $request) {
    $voice_access = aimee_elevenlabs_voice_access_status();

    $response = new WP_REST_Response([
        'status'               => 'success',
        'enabled'              => aimee_voice_calls_configured(),
        'stt_ready'            => aimee_voice_stt_configured(),
        'tts_configured'       => aimee_voice_tts_configured(),
        'tts_ready'            => !empty($voice_access['ready']),
        'tts_status_code'      => (string) ($voice_access['code'] ?? ''),
        'tts_status_message'   => (string) ($voice_access['message'] ?? ''),
        'voice_id_source'      => (string) (
            $voice_access['voice_id_source']
            ?? aimee_elevenlabs_voice_id_source()
        ),
        'shared_voice_imported'=> aimee_elevenlabs_imported_voice_id() !== '',
        'browser_tts_fallback' => true,
        'max_turn_seconds'     => aimee_voice_call_max_turn_seconds(),
        'stt_model'            => aimee_deepgram_model_id(),
        'tts_model'            => aimee_elevenlabs_model_id(),
        'voice_name'           => (string) ($voice_access['voice_name'] ?? ''),
        'diagnostic_endpoint'  => 'public_safe_status',
    ], 200);

    // Prevent a CDN or page cache from preserving stale provider readiness.
    $response->header(
        'Cache-Control',
        'no-store, no-cache, must-revalidate, max-age=0'
    );

    return $response;
}

function handle_aimee_voice_import_shared(
    WP_REST_Request $request
) {
    $force = rest_sanitize_boolean(
        $request->get_param('force')
    );

    $result = aimee_elevenlabs_import_shared_voice($force);

    if (is_wp_error($result)) {
        return $result;
    }

    $voice_access = aimee_elevenlabs_voice_access_status(true);

    return rest_ensure_response([
        'status'          => 'success',
        'imported'        => !empty($result['imported']),
        'voice_id'        => (string) ($result['voice_id'] ?? ''),
        'voice_id_source' => (string) ($result['source'] ?? ''),
        'tts_ready'       => !empty($voice_access['ready']),
        'voice_name'      => (string) (
            $voice_access['voice_name']
            ?? aimee_elevenlabs_voice_name()
        ),
    ]);
}

function handle_aimee_voice_greeting(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();

    if (!$user_id) {
        return new WP_Error(
            'authentication_required',
            'Authentication required.',
            ['status' => 401]
        );
    }

    // Administrators need to be able to test voice-provider configuration
    // without being locked out by repeated failed setup attempts.
    $greeting_allowed = current_user_can('manage_options')
        || aimee_rate_limit(
            'voice_greeting_v2_' . $user_id,
            defined('AIMEE_VOICE_GREETING_LIMIT')
                ? max(4, intval(AIMEE_VOICE_GREETING_LIMIT))
                : 20,
            defined('AIMEE_VOICE_GREETING_WINDOW_SECONDS')
                ? max(
                    MINUTE_IN_SECONDS,
                    intval(AIMEE_VOICE_GREETING_WINDOW_SECONDS)
                )
                : 10 * MINUTE_IN_SECONDS
        );

    if (!$greeting_allowed) {
        return new WP_Error(
            'voice_greeting_rate_limited',
            'You have started several calls in a short time. Please wait a few minutes and try again.',
            [
                'status'      => 429,
                'retry_after' => 120,
            ]
        );
    }

    if (!aimee_voice_stt_configured()) {
        return new WP_Error(
            'voice_transcription_not_configured',
            'Voice transcription is not configured yet.',
            ['status' => 503]
        );
    }

    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles')
        . " WHERE user_id = %d",
        $user_id
    ));

    if (!$profile) {
        return new WP_Error(
            'profile_missing',
            'Aimee profile not found.',
            ['status' => 404]
        );
    }
    if (aimee_account_deletion_tombstone_is_active($profile)) {
        return new WP_Error(
            'account_deletion_pending',
            'This account is being deleted, so a voice call cannot be started.',
            ['status' => 409]
        );
    }

    if (
        !aimee_is_colleague_user($profile)
        && !aimee_user_has_chat_access($user_id, $profile)
    ) {
        return new WP_Error(
            'voice_access_required',
            'Your complimentary preview has ended.',
            ['status' => 403]
        );
    }

    $inherited_route = aimee_voice_last_route_before_call(
        $user_id
    );

    $call_id = aimee_voice_call_start_session(
        $user_id,
        $inherited_route
    );

    $recent_conversation = aimee_voice_recent_conversation(
        $user_id,
        10,
        $profile
    );

    $greeting = aimee_generate_voice_call_greeting(
        $profile,
        $inherited_route,
        $recent_conversation
    );

    $speech = aimee_elevenlabs_synthesise($greeting);

    if (is_wp_error($speech)) {
        $error_data = $speech->get_error_data();
        $error_data = is_array($error_data) ? $error_data : [];

        return rest_ensure_response([
            'status'           => 'success',
            'reply'            => $greeting,
            'audio_status'     => 'browser_fallback',
            'audio_base64'     => null,
            'audio_mime'       => null,
            'voice_error_code' => (string) (
                $error_data['voice_error_code']
                ?? $speech->get_error_code()
            ),
            'voice_error'      => $speech->get_error_message(),
            'call_id'          => $call_id,
            'voice_route'      => $inherited_route,
        ]);
    }

    return rest_ensure_response([
        'status'           => 'success',
        'reply'            => $greeting,
        'audio_status'     => 'ready',
        'audio_base64'     => $speech['audio_base64'],
        'audio_mime'       => $speech['mime_type'],
        'voice_error_code' => null,
        'call_id'          => $call_id,
        'voice_route'      => $inherited_route,
    ]);
}

function handle_aimee_voice_turn(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();

    if (!$user_id) {
        return new WP_Error(
            'authentication_required',
            'Authentication required.',
            ['status' => 401]
        );
    }

    $turn_allowed = current_user_can('manage_options')
        || aimee_rate_limit(
            'voice_turn_v2_' . $user_id,
            defined('AIMEE_VOICE_TURN_LIMIT')
                ? max(12, intval(AIMEE_VOICE_TURN_LIMIT))
                : 60,
            defined('AIMEE_VOICE_TURN_WINDOW_SECONDS')
                ? max(
                    MINUTE_IN_SECONDS,
                    intval(AIMEE_VOICE_TURN_WINDOW_SECONDS)
                )
                : 10 * MINUTE_IN_SECONDS
        );

    if (!$turn_allowed) {
        return new WP_Error(
            'voice_turn_rate_limited',
            'The call is moving a little too quickly. Pause for a moment.',
            [
                'status'      => 429,
                'retry_after' => 60,
            ]
        );
    }

    if (!aimee_voice_stt_configured()) {
        return new WP_Error(
            'voice_transcription_not_configured',
            'Voice transcription is not configured yet.',
            ['status' => 503]
        );
    }

    $files = $request->get_file_params();
    $audio_file = $files['audio'] ?? null;

    if (
        !is_array($audio_file)
        || empty($audio_file['tmp_name'])
        || intval($audio_file['error'] ?? UPLOAD_ERR_NO_FILE)
            !== UPLOAD_ERR_OK
        || !is_readable($audio_file['tmp_name'])
    ) {
        return new WP_Error(
            'voice_audio_missing',
            'No usable microphone audio was received.',
            ['status' => 400]
        );
    }

    $audio_size = intval($audio_file['size'] ?? 0);

    if (
        $audio_size <= 0
        || $audio_size > aimee_voice_call_max_audio_bytes()
    ) {
        return new WP_Error(
            'voice_audio_size',
            'That spoken turn was too long. Please try a shorter sentence.',
            ['status' => 413]
        );
    }

    $audio_bytes = file_get_contents($audio_file['tmp_name']);

    if (!is_string($audio_bytes) || $audio_bytes === '') {
        return new WP_Error(
            'voice_audio_read',
            'The microphone recording could not be read.',
            ['status' => 400]
        );
    }

    $mime_type = sanitize_mime_type(
        (string) ($audio_file['type'] ?? 'application/octet-stream')
    );

    $call_id = sanitize_text_field(
        (string) $request->get_param('call_id')
    );

    $call_session = aimee_voice_call_get_session(
        $call_id,
        $user_id
    );

    $voice_route_hint = $call_session
        ? aimee_voice_route_family(
            $call_session['route'] ?? 'primary'
        )
        : aimee_voice_last_route_before_call($user_id);

    $turn_started = microtime(true);
    $transcription = aimee_deepgram_transcribe_audio(
        $audio_bytes,
        $mime_type
    );

    // Do not retain raw audio after the request. WordPress/PHP removes the
    // temporary upload automatically when the request ends.
    unset($audio_bytes);

    if (is_wp_error($transcription)) {
        return $transcription;
    }

    $transcript = trim((string) ($transcription['transcript'] ?? ''));

    if ($transcript === '') {
        return rest_ensure_response([
            'status'  => 'no_speech',
            'message' => 'I did not catch any words that time.',
        ]);
    }

    $llm_started = microtime(true);

    $message_result = handle_aimee_message([
        'user_id'  => $user_id,
        'message'          => $transcript,
        'is_voice'         => 1,
        'voice_route_hint' => $voice_route_hint,
        'request_id'       => sanitize_text_field((string) (
            $request->get_header('X-Request-ID')
            ?: $request->get_param('request_id')
            ?: ''
        )),
    ]);

    $llm_latency_ms = intval(
        round((microtime(true) - $llm_started) * 1000)
    );

    if (is_wp_error($message_result)) {
        return $message_result;
    }

    if (!is_array($message_result)) {
        return new WP_Error(
            'voice_reply_invalid',
            'Aimee could not answer that turn.',
            ['status' => 502]
        );
    }

    $reply = trim((string) (
        $message_result['reply']
        ?? $message_result['reply_text']
        ?? ''
    ));

    $actual_voice_route = aimee_voice_route_family(
        $message_result['voice_route']
        ?? $voice_route_hint
    );

    if ($call_id !== '') {
        aimee_voice_call_update_session_route(
            $call_id,
            $user_id,
            $actual_voice_route
        );
    }

    $speech = $reply !== ''
        ? aimee_elevenlabs_synthesise($reply)
        : new WP_Error('empty_voice_reply', 'No voice reply was generated.');

    $audio_base64 = null;
    $audio_mime = null;
    $tts_latency_ms = null;
    $audio_status = 'unavailable';

    if (!is_wp_error($speech)) {
        $audio_base64 = $speech['audio_base64'];
        $audio_mime = $speech['mime_type'];
        $tts_latency_ms = intval($speech['latency_ms'] ?? 0);
        $audio_status = 'ready';
    }

    $duration_ms = min(
        120000,
        max(0, intval($request->get_param('duration_ms')))
    );

    $wpdb->insert(aimee_table('aimee_analytics_events'), [
        'user_id'    => $user_id,
        'event_name' => 'voice_turn',
        'properties' => wp_json_encode([
            'audio_bytes'       => $audio_size,
            'recorded_ms'       => $duration_ms,
            'transcript_chars'  => mb_strlen($transcript),
            'reply_chars'       => mb_strlen($reply),
            'stt_latency_ms'    => intval(
                $transcription['latency_ms'] ?? 0
            ),
            'llm_latency_ms'    => $llm_latency_ms,
            'tts_latency_ms'    => $tts_latency_ms,
            'total_latency_ms'  => intval(
                round((microtime(true) - $turn_started) * 1000)
            ),
            'audio_status'      => $audio_status,
            'deepgram_model'    => aimee_deepgram_model_id(),
            'elevenlabs_model'  => aimee_elevenlabs_model_id(),
        ]),
        'page_path'  => 'voice',
        'occurred_at'=> current_time('mysql', true),
        'created_at' => current_time('mysql', true),
    ]);

    $voice_media = is_array($message_result['media'] ?? null)
        ? $message_result['media']
        : null;
    $voice_media_delivery = null;
    $voice_delivery_id = sanitize_text_field((string) (
        $voice_media['delivery_id'] ?? ''
    ));
    if ($voice_media && $voice_delivery_id !== '') {
        if (aimee_media_delivery_transition(
            $voice_delivery_id,
            'returned_by_direct_api'
        )) {
            $voice_media_delivery = aimee_media_delivery_public_snapshot(
                aimee_media_delivery_find($voice_delivery_id, $user_id)
            );
        } else {
            aimee_media_delivery_transition(
                $voice_delivery_id,
                'failed',
                ['error_code' => 'voice_return_transition_failed']
            );
            $reply = "I chose a photograph, but the voice-call handoff failed before it could be returned. I won't pretend it reached you.";
            $voice_media = null;
            $audio_base64 = null;
            $audio_mime = null;
            $audio_status = 'browser_fallback';
            $aimee_message_id = intval($message_result['aimee_message_id'] ?? 0);
            if ($aimee_message_id) {
                $messages_table = aimee_table('aimee_messages');
                $message_pk = aimee_messages_primary_key();
                $wpdb->query($wpdb->prepare(
                    "UPDATE $messages_table
                     SET message_text = %s, image_url = NULL
                     WHERE `{$message_pk}` = %d AND user_id = %d",
                    $reply,
                    $aimee_message_id,
                    $user_id
                ));
            }
        }
    }

    return rest_ensure_response([
        'status'        => (string) ($message_result['status'] ?? 'success'),
        'transcript'    => $transcript,
        'reply'         => $reply,
        'reply_text'    => $reply,
        'subscription'  => $message_result['subscription'] ?? null,
        'media'         => $voice_media,
        'media_delivery'=> $voice_media_delivery,
        'audio_status'  => $audio_status,
        'audio_base64'  => $audio_base64,
        'audio_mime'    => $audio_mime,
        'call_id'       => $call_id,
        'voice_route'   => $actual_voice_route,
    ]);
}


// =========================================================================
// ASYNCHRONOUS VOICE NOTES: UPLOAD, REAL STAGE POLLING AND PRIVATE AUDIO
// =========================================================================

function aimee_voice_note_table() {
    return aimee_table('aimee_voice_notes');
}

function aimee_voice_note_private_directory() {
    if (!function_exists('aimee_private_storage_prepare_dir')) return '';
    $configured = defined('AIMEE_VOICE_NOTE_DIR')
        ? trim((string) AIMEE_VOICE_NOTE_DIR)
        : '';
    $prepared = aimee_private_storage_prepare_dir('voice-notes', $configured);
    return is_wp_error($prepared) ? '' : $prepared;
}

function aimee_voice_note_legacy_directories() {
    return array_column(aimee_voice_note_legacy_directory_specs(), 'path');
}

/**
 * The ABSPATH sibling was historically shared by sibling WordPress sites;
 * WP_CONTENT_DIR is site-specific public storage. When both resolve to the
 * same path the stricter site-specific ownership rule wins.
 */
function aimee_voice_note_legacy_directory_specs() {
    $specs = [];
    $candidates = [
        [
            'path' => trailingslashit(dirname(untrailingslashit(ABSPATH)))
                . 'aimee-private-voice-notes',
            'shared' => true,
        ],
        [
            'path' => trailingslashit(WP_CONTENT_DIR)
                . 'aimee-private-voice-notes',
            'shared' => false,
        ],
    ];
    foreach ($candidates as $candidate) {
        $path = untrailingslashit((string) $candidate['path']);
        $key = strtolower(wp_normalize_path($path));
        if (!isset($specs[$key])) {
            $specs[$key] = ['path' => $path, 'shared' => (bool) $candidate['shared']];
        } elseif (empty($candidate['shared'])) {
            $specs[$key]['shared'] = false;
        }
    }
    return array_values($specs);
}

function aimee_voice_note_storage_filename_is_valid($filename) {
    return preg_match(
        '/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}-(?:user|aimee)\.(?:webm|m4a|mp3|ogg|opus|wav|bin)$/i',
        (string) $filename
    ) === 1;
}

function aimee_voice_note_storage_temp_filename_matches($entry, $filename) {
    return preg_match(
        '/^' . preg_quote((string) $filename, '/') . '\.tmp-[A-Za-z0-9-]{8,80}$/',
        (string) $entry
    ) === 1;
}

/** Return a fail-closed directory snapshot; an absent legacy directory is safe. */
function aimee_voice_note_scan_directory($directory, $allow_missing = true) {
    $directory = untrailingslashit((string) $directory);
    if ($directory === '' || is_link($directory)) {
        return new WP_Error('voice_storage_symlink_rejected', 'A voice-note directory was a symbolic link.');
    }
    if (!file_exists($directory)) {
        return $allow_missing
            ? []
            : new WP_Error('voice_storage_missing', 'Private voice-note storage was unavailable.');
    }
    if (!is_dir($directory)) {
        return new WP_Error('voice_storage_not_directory', 'A voice-note storage path was not a directory.');
    }
    $root = realpath($directory);
    if (!$root || !is_readable($root)) {
        return new WP_Error('voice_storage_unreadable', 'A voice-note directory was not readable.');
    }
    $entries = @scandir($root);
    if ($entries === false) {
        return new WP_Error('voice_storage_scan_failed', 'A voice-note directory scan failed.');
    }
    return [
        'root' => $root,
        'entries' => array_values(array_diff($entries, ['.', '..'])),
    ];
}

/** Exact current-site filenames are the only ownership proof for legacy audio. */
function aimee_voice_note_referenced_filenames($user_id = null) {
    global $wpdb;

    $where = '';
    $query = 'SELECT input_file, reply_file FROM ' . aimee_voice_note_table();
    if ($user_id !== null) {
        $user_id = intval($user_id);
        if ($user_id < 1) {
            return new WP_Error('voice_storage_owner_invalid', 'Voice-note ownership could not be verified.');
        }
        $where = $wpdb->prepare(' WHERE user_id = %d', $user_id);
    }
    $wpdb->last_error = '';
    $rows = $wpdb->get_results($query . $where);
    if (!is_array($rows) || $wpdb->last_error !== '') {
        return new WP_Error('voice_storage_ownership_unavailable', 'Voice-note ownership could not be read.');
    }

    $filenames = [];
    foreach ($rows as $row) {
        foreach (['input_file', 'reply_file'] as $field) {
            $filename = trim((string) ($row->{$field} ?? ''));
            if ($filename === '') continue;
            if (
                basename($filename) !== $filename
                || !aimee_voice_note_storage_filename_is_valid($filename)
            ) {
                return new WP_Error('voice_storage_reference_invalid', 'A voice-note row contained an unsafe filename.');
            }
            $filenames[$filename] = $filename;
        }
    }
    return array_values($filenames);
}

function aimee_voice_note_copy_legacy_file($source, $destination) {
    if (is_link($source) || !is_file($source) || !is_readable($source)) return false;
    $source_hash = hash_file('sha256', $source);
    if (!is_string($source_hash) || strlen($source_hash) !== 64) return false;

    if (is_file($destination) && !is_link($destination) && is_readable($destination)) {
        $destination_hash = hash_file('sha256', $destination);
        if (
            is_string($destination_hash)
            && strlen($destination_hash) === 64
            && hash_equals($source_hash, $destination_hash)
            && aimee_profile_media_permissions_are_private($destination, false)
        ) return true;
    }
    if (file_exists($destination) || is_link($destination)) return false;

    try {
        $temporary = $destination . '.tmp-' . bin2hex(random_bytes(8));
    } catch (Exception $exception) {
        return false;
    }
    try {
        if (!@copy($source, $temporary) || !is_file($temporary)) return false;
        if (
            DIRECTORY_SEPARATOR !== '\\'
            && (!@chmod($temporary, 0600)
                || !aimee_profile_media_permissions_are_private($temporary, false))
        ) return false;
        $temporary_hash = is_readable($temporary)
            ? hash_file('sha256', $temporary)
            : false;
        if (
            !is_string($temporary_hash)
            || strlen($temporary_hash) !== 64
            || !hash_equals($source_hash, $temporary_hash)
            || !@rename($temporary, $destination)
        ) return false;
        return is_file($destination)
            && !is_link($destination)
            && aimee_profile_media_permissions_are_private($destination, false)
            && hash_equals($source_hash, (string) hash_file('sha256', $destination));
    } finally {
        if (isset($temporary) && (is_file($temporary) || is_link($temporary))) {
            wp_delete_file($temporary);
        }
    }
}

function aimee_voice_note_migrate_legacy_storage() {
    $destination_dir = aimee_voice_note_private_directory();
    if ($destination_dir === '') return false;
    $referenced = aimee_voice_note_referenced_filenames();
    if (is_wp_error($referenced)) return false;
    $owned = array_fill_keys($referenced, true);

    foreach (aimee_voice_note_legacy_directory_specs() as $spec) {
        $scan = aimee_voice_note_scan_directory($spec['path'], true);
        if (is_wp_error($scan)) return false;
        if (!$scan) continue;
        $legacy_real = $scan['root'];
        if (wp_normalize_path($legacy_real) === wp_normalize_path($destination_dir)) continue;

        foreach ($scan['entries'] as $filename) {
            if (!aimee_voice_note_storage_filename_is_valid($filename)) continue;
            // A shared sibling directory may contain another site's UUIDs.
            // A site-specific public directory must instead stop for explicit
            // operator reconciliation when a valid file has no owner row.
            if (!isset($owned[$filename])) {
                if (empty($spec['shared'])) return false;
                continue;
            }
            $candidate = $legacy_real . DIRECTORY_SEPARATOR . $filename;
            if (is_link($candidate)) return false;
            $source = realpath($candidate);
            if (
                !$source
                || !aimee_profile_media_path_is_within($source, $legacy_real)
                || !is_file($source)
                || !is_readable($source)
            ) return false;
            $destination = $destination_dir . DIRECTORY_SEPARATOR . $filename;
            if (!aimee_voice_note_copy_legacy_file($source, $destination)) return false;
            wp_delete_file($source);
            if (is_file($source) || is_link($candidate)) return false;
        }
    }
    return aimee_voice_note_legacy_storage_is_clear();
}

function aimee_voice_note_legacy_storage_is_clear() {
    $destination_dir = aimee_voice_note_private_directory();
    if ($destination_dir === '') return false;
    $referenced = aimee_voice_note_referenced_filenames();
    if (is_wp_error($referenced)) return false;
    $owned = array_fill_keys($referenced, true);
    foreach (aimee_voice_note_legacy_directory_specs() as $spec) {
        $scan = aimee_voice_note_scan_directory($spec['path'], true);
        if (is_wp_error($scan)) return false;
        if (!$scan || wp_normalize_path($scan['root']) === wp_normalize_path($destination_dir)) continue;
        foreach ($scan['entries'] as $entry) {
            if (!aimee_voice_note_storage_filename_is_valid($entry)) continue;
            if (isset($owned[$entry]) || empty($spec['shared'])) return false;
        }
    }
    return true;
}
add_action('init', 'aimee_voice_note_migrate_legacy_storage', 17);

function aimee_voice_note_resolve_file($filename) {
    $raw_filename = trim((string) $filename);
    $filename = sanitize_file_name($raw_filename);

    if (
        $filename === ''
        || !hash_equals($raw_filename, $filename)
        || basename($filename) !== $filename
        || !aimee_voice_note_storage_filename_is_valid($filename)
    ) {
        return '';
    }

    $directory = aimee_voice_note_private_directory();
    if ($directory === '') return '';
    $root = realpath($directory);
    if (!$root) return '';
    $path = trailingslashit($directory) . $filename;
    if (is_link($path)) return '';
    $resolved = realpath($path);

    return $resolved
        && aimee_profile_media_path_is_within($resolved, $root)
        && is_file($resolved)
        && is_readable($resolved)
        && aimee_profile_media_permissions_are_private($resolved, false)
            ? $resolved
            : '';
}

/** A private write is valid only while this exact owner lock is live and not deleting. */
function aimee_voice_note_lock_allows_private_write($user_id, $lock_token) {
    if (
        !function_exists('aimee_subscription_checkout_lock_state')
        || !function_exists('aimee_account_deletion_tombstone_is_active')
    ) return false;
    $state = aimee_subscription_checkout_lock_state($user_id, $lock_token);
    return $state && !aimee_account_deletion_tombstone_is_active($state);
}

/** Store an uploaded file through a verified 0600 temporary and atomic rename. */
function aimee_voice_note_atomic_store_upload(
    $source,
    $destination,
    $expected_bytes,
    $user_id,
    $lock_token
) {
    $directory = aimee_voice_note_private_directory();
    $directory_real = $directory !== '' ? realpath($directory) : false;
    if (
        !$directory_real
        || is_link($source)
        || !is_file($source)
        || !is_readable($source)
        || basename($destination) !== basename((string) $destination)
        || !aimee_voice_note_storage_filename_is_valid(basename($destination))
        || wp_normalize_path(dirname($destination)) !== wp_normalize_path($directory_real)
        || file_exists($destination)
        || is_link($destination)
        || intval($expected_bytes) < 1
    ) return false;

    try {
        $temporary = $destination . '.tmp-' . bin2hex(random_bytes(8));
    } catch (Exception $exception) {
        return false;
    }
    $renamed = false;
    $committed = false;
    try {
        $stored = @move_uploaded_file($source, $temporary);
        if (!$stored) $stored = @copy($source, $temporary);
        if (!$stored || !is_file($temporary) || is_link($temporary)) return false;
        if (
            DIRECTORY_SEPARATOR !== '\\'
            && (!@chmod($temporary, 0600)
                || !aimee_profile_media_permissions_are_private($temporary, false))
        ) return false;
        $size = filesize($temporary);
        $hash = is_readable($temporary) ? hash_file('sha256', $temporary) : false;
        if (
            $size === false
            || intval($size) !== intval($expected_bytes)
            || !is_string($hash)
            || strlen($hash) !== 64
            || !aimee_voice_note_lock_allows_private_write($user_id, $lock_token)
            || file_exists($destination)
            || is_link($destination)
        ) return false;
        if (!@rename($temporary, $destination)) return false;
        $renamed = true;
        $committed = is_file($destination)
            && !is_link($destination)
            && is_readable($destination)
            && intval(filesize($destination)) === intval($expected_bytes)
            && aimee_profile_media_permissions_are_private($destination, false)
            && hash_equals($hash, (string) hash_file('sha256', $destination));
        return $committed;
    } finally {
        if (is_file($temporary) || is_link($temporary)) wp_delete_file($temporary);
        if ($renamed && !$committed && (is_file($destination) || is_link($destination))) {
            wp_delete_file($destination);
        }
    }
}

/** Store TTS bytes through a verified 0600 temporary and atomic rename. */
function aimee_voice_note_atomic_store_bytes(
    $bytes,
    $destination,
    $user_id,
    $lock_token
) {
    if (!is_string($bytes) || $bytes === '') return false;
    $directory = aimee_voice_note_private_directory();
    $directory_real = $directory !== '' ? realpath($directory) : false;
    if (
        !$directory_real
        || basename($destination) !== basename((string) $destination)
        || !aimee_voice_note_storage_filename_is_valid(basename($destination))
        || wp_normalize_path(dirname($destination)) !== wp_normalize_path($directory_real)
        || file_exists($destination)
        || is_link($destination)
    ) return false;

    try {
        $temporary = $destination . '.tmp-' . bin2hex(random_bytes(8));
    } catch (Exception $exception) {
        return false;
    }
    $expected_bytes = strlen($bytes);
    $expected_hash = hash('sha256', $bytes);
    $renamed = false;
    $committed = false;
    try {
        $written = @file_put_contents($temporary, $bytes, LOCK_EX);
        if ($written !== $expected_bytes || !is_file($temporary) || is_link($temporary)) return false;
        if (
            DIRECTORY_SEPARATOR !== '\\'
            && (!@chmod($temporary, 0600)
                || !aimee_profile_media_permissions_are_private($temporary, false))
        ) return false;
        if (
            intval(filesize($temporary)) !== $expected_bytes
            || !hash_equals($expected_hash, (string) hash_file('sha256', $temporary))
            || !aimee_voice_note_lock_allows_private_write($user_id, $lock_token)
            || file_exists($destination)
            || is_link($destination)
        ) return false;
        if (!@rename($temporary, $destination)) return false;
        $renamed = true;
        $committed = is_file($destination)
            && !is_link($destination)
            && is_readable($destination)
            && intval(filesize($destination)) === $expected_bytes
            && aimee_profile_media_permissions_are_private($destination, false)
            && hash_equals($expected_hash, (string) hash_file('sha256', $destination));
        return $committed;
    } finally {
        if (is_file($temporary) || is_link($temporary)) wp_delete_file($temporary);
        if ($renamed && !$committed && (is_file($destination) || is_link($destination))) {
            wp_delete_file($destination);
        }
    }
}

function aimee_voice_note_valid_token($token) {
    return preg_match(
        '/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i',
        (string) $token
    ) === 1;
}

function aimee_voice_note_audio_url($token, $kind) {
    $token = sanitize_text_field((string) $token);
    $kind = $kind === 'user' ? 'user' : 'aimee';

    if (!aimee_voice_note_valid_token($token)) return '';

    return add_query_arg(
        '_wpnonce',
        wp_create_nonce('wp_rest'),
        rest_url(
            'aimee/v1/voice-note/audio/'
            . rawurlencode($token)
            . '/'
            . $kind
        )
    );
}

function aimee_voice_note_internal_signature($job_id, $token) {
    return hash_hmac(
        'sha256',
        intval($job_id) . '|' . (string) $token,
        wp_salt('auth')
    );
}

function aimee_voice_note_dispatch_job($job_id, $token) {
    $job_id = intval($job_id);
    $token = sanitize_text_field((string) $token);

    if (!$job_id || !aimee_voice_note_valid_token($token)) {
        return false;
    }

    $dispatch_key = 'aimee_voice_note_dispatch_' . $job_id;
    $recently_dispatched = (bool) get_transient($dispatch_key);

    if (!wp_next_scheduled('aimee_process_voice_note', [$job_id])) {
        wp_schedule_single_event(
            time() + 2,
            'aimee_process_voice_note',
            [$job_id]
        );
    }

    if ($recently_dispatched) return true;
    set_transient($dispatch_key, 1, 3);

    $payload = [
        'job_id'    => $job_id,
        'note_token'=> $token,
        'signature' => aimee_voice_note_internal_signature(
            $job_id,
            $token
        ),
    ];

    wp_remote_post(
        rest_url('aimee/v1/voice-note/process'),
        [
            'headers' => [
                'Content-Type' => 'application/json',
                'Accept'       => 'application/json',
            ],
            'body'        => wp_json_encode($payload),
            'timeout'     => 0.8,
            'blocking'    => false,
            'redirection' => 0,
            'sslverify'   => apply_filters(
                'https_local_ssl_verify',
                false
            ),
        ]
    );

    return true;
}

function aimee_voice_note_estimated_duration_ms($text) {
    $plain = trim(wp_strip_all_tags((string) $text));
    if ($plain === '') return 1500;

    $word_count = max(
        1,
        count(preg_split('/\s+/u', $plain, -1, PREG_SPLIT_NO_EMPTY))
    );

    return max(
        1400,
        min(45000, intval(round(($word_count / 2.55) * 1000 + 450)))
    );
}

function aimee_voice_note_update_job($job_id, array $values) {
    global $wpdb;

    if (!$job_id || !$values) return false;

    $values['updated_at'] = current_time('mysql', true);

    return $wpdb->update(
        aimee_voice_note_table(),
        $values,
        ['id' => intval($job_id)]
    ) !== false;
}

function aimee_voice_note_fail_job(
    $job_id,
    $code,
    $message,
    $status = 'failed'
) {
    return aimee_voice_note_update_job(
        $job_id,
        [
            'status'        => sanitize_key((string) $status),
            'error_code'    => sanitize_key((string) $code),
            'error_message' => sanitize_text_field((string) $message),
            'finished_at'   => current_time('mysql', true),
        ]
    );
}

function handle_aimee_voice_note_send(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();

    if (!$user_id) {
        return new WP_Error(
            'authentication_required',
            'Authentication required.',
            ['status' => 401]
        );
    }

    $allowed = current_user_can('manage_options')
        || aimee_rate_limit(
            'voice_note_send_' . $user_id,
            defined('AIMEE_VOICE_NOTE_LIMIT')
                ? max(10, intval(AIMEE_VOICE_NOTE_LIMIT))
                : 40,
            defined('AIMEE_VOICE_NOTE_WINDOW_SECONDS')
                ? max(
                    MINUTE_IN_SECONDS,
                    intval(AIMEE_VOICE_NOTE_WINDOW_SECONDS)
                )
                : 10 * MINUTE_IN_SECONDS
        );

    if (!$allowed) {
        return new WP_Error(
            'voice_note_rate_limited',
            'You have sent several voice notes in a short time. Pause for a moment and try again.',
            [
                'status'      => 429,
                'retry_after' => 60,
            ]
        );
    }

    if (!aimee_voice_stt_configured()) {
        return new WP_Error(
            'voice_transcription_not_configured',
            'Voice transcription is not configured yet.',
            ['status' => 503]
        );
    }

    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles')
        . " WHERE user_id = %d",
        $user_id
    ));

    if (!$profile) {
        return new WP_Error(
            'profile_missing',
            'Aimee profile not found.',
            ['status' => 404]
        );
    }
    if (aimee_account_deletion_tombstone_is_active($profile)) {
        return new WP_Error(
            'account_deletion_pending',
            'This account is being deleted, so no new voice note was stored.',
            ['status' => 409]
        );
    }

    if (
        !aimee_is_colleague_user($profile)
        && !aimee_user_has_chat_access($user_id, $profile)
    ) {
        return new WP_Error(
            'voice_access_required',
            'Your complimentary preview has ended.',
            ['status' => 403]
        );
    }

    $files = $request->get_file_params();
    $audio_file = $files['audio'] ?? null;

    if (
        !is_array($audio_file)
        || empty($audio_file['tmp_name'])
        || intval($audio_file['error'] ?? UPLOAD_ERR_NO_FILE)
            !== UPLOAD_ERR_OK
        || !is_readable($audio_file['tmp_name'])
    ) {
        return new WP_Error(
            'voice_audio_missing',
            'No usable voice note was received.',
            ['status' => 400]
        );
    }

    $audio_size = intval($audio_file['size'] ?? 0);

    if (
        $audio_size <= 0
        || $audio_size > aimee_voice_call_max_audio_bytes()
    ) {
        return new WP_Error(
            'voice_audio_size',
            'That voice note was too long. Please try a shorter one.',
            ['status' => 413]
        );
    }

    $mime_type = strtolower(trim(explode(
        ';',
        (string) ($audio_file['type'] ?? 'application/octet-stream')
    )[0]));

    $mime_extensions = [
        'audio/webm' => 'webm',
        'audio/mp4'  => 'm4a',
        'audio/mpeg' => 'mp3',
        'audio/mp3'  => 'mp3',
        'audio/ogg'  => 'ogg',
        'audio/opus' => 'opus',
        'audio/wav'  => 'wav',
        'audio/x-wav'=> 'wav',
        'application/octet-stream' => 'bin',
    ];

    if (!isset($mime_extensions[$mime_type])) {
        $mime_type = 'application/octet-stream';
    }

    $token = strtolower(wp_generate_uuid4());
    $input_filename = $token
        . '-user.'
        . $mime_extensions[$mime_type];
    $directory = aimee_voice_note_private_directory();
    if ($directory === '') {
        return new WP_Error(
            'voice_private_storage_unavailable',
            'Private voice-note storage is unavailable.',
            ['status' => 503]
        );
    }
    $input_path = trailingslashit($directory) . $input_filename;

    $voice_lock_token = aimee_acquire_subscription_checkout_lock(
        $user_id,
        5 * MINUTE_IN_SECONDS
    );
    if ($voice_lock_token === '') {
        return new WP_Error(
            'account_operation_in_progress',
            'A secure account operation is in progress, so no voice note was stored.',
            ['status' => 409]
        );
    }

    try {
    if (!aimee_voice_note_atomic_store_upload(
        $audio_file['tmp_name'],
        $input_path,
        $audio_size,
        $user_id,
        $voice_lock_token
    )) {
        return new WP_Error(
            'voice_audio_store_failed',
            'The voice note could not be stored securely.',
            ['status' => 500]
        );
    }

    $recorded_ms = min(
        aimee_voice_call_max_turn_seconds() * 1000,
        max(250, intval($request->get_param('duration_ms')))
    );

    $now = current_time('mysql', true);
    $inserted = $wpdb->insert(
        aimee_voice_note_table(),
        [
            'note_token'     => $token,
            'user_id'        => $user_id,
            'status'         => 'queued',
            'result_status'  => 'processing',
            'route_hint'     => aimee_voice_last_route_before_call(
                $user_id
            ),
            'input_file'     => $input_filename,
            'input_mime'     => $mime_type,
            'input_bytes'    => $audio_size,
            'recorded_ms'    => $recorded_ms,
            'created_at'     => $now,
            'updated_at'     => $now,
            'expires_at'     => gmdate(
                'Y-m-d H:i:s',
                time() + 365 * DAY_IN_SECONDS
            ),
        ]
    );

    if (!$inserted) {
        wp_delete_file($input_path);

        return new WP_Error(
            'voice_note_job_failed',
            'The voice note could not be queued.',
            ['status' => 500]
        );
    }

    $job_id = intval($wpdb->insert_id);
    if (!aimee_voice_note_lock_allows_private_write($user_id, $voice_lock_token)) {
        $wpdb->delete(
            aimee_voice_note_table(),
            ['id' => $job_id, 'user_id' => $user_id],
            ['%d', '%d']
        );
        wp_delete_file($input_path);
        return new WP_Error(
            'account_deletion_pending',
            'The account state changed before the voice note could be queued.',
            ['status' => 409]
        );
    }
    aimee_voice_note_dispatch_job($job_id, $token);

    $wpdb->insert(aimee_table('aimee_analytics_events'), [
        'user_id'    => $user_id,
        'event_name' => 'voice_note_sent',
        'properties' => wp_json_encode([
            'audio_bytes' => $audio_size,
            'recorded_ms' => $recorded_ms,
            'mime_type'   => $mime_type,
        ]),
        'page_path'  => 'voice-note',
        'occurred_at'=> $now,
        'created_at' => $now,
    ]);

    return rest_ensure_response([
        'status'           => 'delivered',
        'note_token'       => $token,
        'recorded_ms'      => $recorded_ms,
        'max_turn_seconds' => aimee_voice_call_max_turn_seconds(),
    ]);
    } finally {
        aimee_release_subscription_checkout_lock($user_id, $voice_lock_token);
    }
}

function handle_aimee_voice_note_process(WP_REST_Request $request) {
    global $wpdb;

    $params = $request->get_json_params();
    if (!is_array($params)) $params = $request->get_params();

    $job_id = intval($params['job_id'] ?? 0);
    $token = sanitize_text_field((string) (
        $params['note_token'] ?? ''
    ));
    $signature = sanitize_text_field((string) (
        $params['signature'] ?? ''
    ));

    if (
        !$job_id
        || !aimee_voice_note_valid_token($token)
        || $signature === ''
        || !hash_equals(
            aimee_voice_note_internal_signature($job_id, $token),
            $signature
        )
    ) {
        return new WP_Error(
            'voice_note_worker_unauthorised',
            'Invalid voice-note worker request.',
            ['status' => 403]
        );
    }

    $exists = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM " . aimee_voice_note_table()
        . " WHERE id = %d AND note_token = %s LIMIT 1",
        $job_id,
        $token
    ));

    if (!$exists) {
        return new WP_Error(
            'voice_note_job_missing',
            'Voice-note job not found.',
            ['status' => 404]
        );
    }

    aimee_process_voice_note_job($job_id);

    return rest_ensure_response([
        'status' => 'accepted',
    ]);
}

function aimee_process_voice_note_job($job_id) {
    global $wpdb;

    $job_id = intval($job_id);
    if (!$job_id) return false;
    $pending = $wpdb->get_row($wpdb->prepare(
        'SELECT id, user_id, status FROM ' . aimee_voice_note_table()
        . ' WHERE id = %d LIMIT 1',
        $job_id
    ));
    if (!$pending || (string) ($pending->status ?? '') !== 'queued') return false;

    $user_id = intval($pending->user_id ?? 0);
    $voice_lock_token = aimee_acquire_subscription_checkout_lock(
        $user_id,
        20 * MINUTE_IN_SECONDS
    );
    if ($voice_lock_token === '') {
        // A checkout or deletion owns the same account-mutation lock. Keep the
        // job queued and retry later; never write around a deletion tombstone.
        if (!wp_next_scheduled('aimee_process_voice_note', [$job_id])) {
            wp_schedule_single_event(
                time() + MINUTE_IN_SECONDS,
                'aimee_process_voice_note',
                [$job_id]
            );
        }
        return false;
    }

    try {
        if (!aimee_voice_note_lock_allows_private_write($user_id, $voice_lock_token)) {
            return false;
        }
        return aimee_process_voice_note_job_locked(
            $job_id,
            $user_id,
            $voice_lock_token
        );
    } finally {
        aimee_release_subscription_checkout_lock($user_id, $voice_lock_token);
    }
}

function aimee_process_voice_note_job_locked($job_id, $expected_user_id, $voice_lock_token) {
    global $wpdb;

    $job_id = intval($job_id);
    if (!$job_id) return false;

    $table = aimee_voice_note_table();
    $started_at = current_time('mysql', true);

    $claimed = $wpdb->query($wpdb->prepare(
        "UPDATE $table
         SET status = 'listening',
             processing_started_at = %s,
             updated_at = %s
         WHERE id = %d
           AND status = 'queued'",
        $started_at,
        $started_at,
        $job_id
    ));

    if ($claimed !== 1) return false;

    $job = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $table WHERE id = %d LIMIT 1",
        $job_id
    ));

    if (
        !$job
        || intval($job->user_id ?? 0) !== intval($expected_user_id)
        || !aimee_voice_note_lock_allows_private_write(
            $expected_user_id,
            $voice_lock_token
        )
    ) return false;

    $input_path = aimee_voice_note_resolve_file(
        $job->input_file ?? ''
    );

    if ($input_path === '') {
        return aimee_voice_note_fail_job(
            $job_id,
            'voice_note_input_missing',
            'The original voice note is unavailable.'
        );
    }

    $audio_bytes = file_get_contents($input_path);

    if (!is_string($audio_bytes) || $audio_bytes === '') {
        return aimee_voice_note_fail_job(
            $job_id,
            'voice_note_input_read',
            'The original voice note could not be read.'
        );
    }

    $turn_started = microtime(true);
    $transcription = aimee_deepgram_transcribe_audio(
        $audio_bytes,
        (string) ($job->input_mime ?? 'audio/webm')
    );
    unset($audio_bytes);

    if (!aimee_voice_note_lock_allows_private_write(
        $expected_user_id,
        $voice_lock_token
    )) return false;

    if (is_wp_error($transcription)) {
        return aimee_voice_note_fail_job(
            $job_id,
            $transcription->get_error_code(),
            $transcription->get_error_message()
        );
    }

    $transcript = trim((string) (
        $transcription['transcript'] ?? ''
    ));

    if ($transcript === '') {
        return aimee_voice_note_fail_job(
            $job_id,
            'no_speech',
            'Aimee could not hear any words in that voice note.',
            'no_speech'
        );
    }

    aimee_voice_note_update_job(
        $job_id,
        [
            'transcript'     => $transcript,
            'stt_latency_ms' => intval(
                $transcription['latency_ms'] ?? 0
            ),
        ]
    );

    if (
        !aimee_refresh_subscription_checkout_lock(
            $expected_user_id,
            $voice_lock_token,
            20 * MINUTE_IN_SECONDS
        )
        || !aimee_voice_note_lock_allows_private_write(
            $expected_user_id,
            $voice_lock_token
        )
    ) return false;

    $llm_started = microtime(true);
    $message_result = handle_aimee_message([
        'user_id'          => intval($job->user_id),
        'message'          => $transcript,
        'is_voice'         => 1,
        'channel'          => 'voice_note',
        'request_id'       => 'voice-note:' . sanitize_text_field(
            (string) $job->note_token
        ),
        'voice_route_hint' => (string) (
            $job->route_hint ?? 'primary'
        ),
    ]);
    $llm_latency_ms = intval(round(
        (microtime(true) - $llm_started) * 1000
    ));

    if (!aimee_voice_note_lock_allows_private_write(
        $expected_user_id,
        $voice_lock_token
    )) return false;

    if (is_wp_error($message_result)) {
        return aimee_voice_note_fail_job(
            $job_id,
            $message_result->get_error_code(),
            $message_result->get_error_message()
        );
    }

    if (!is_array($message_result)) {
        return aimee_voice_note_fail_job(
            $job_id,
            'voice_note_reply_invalid',
            'Aimee could not prepare a voice-note reply.'
        );
    }

    $reply = trim((string) (
        $message_result['reply']
        ?? $message_result['reply_text']
        ?? ''
    ));

    if ($reply === '') {
        return aimee_voice_note_fail_job(
            $job_id,
            'voice_note_reply_empty',
            'Aimee did not produce a voice-note reply.'
        );
    }

    $result_status = sanitize_key((string) (
        $message_result['status'] ?? 'success'
    ));
    $voice_route = aimee_voice_route_family(
        $message_result['voice_route']
        ?? $job->route_hint
        ?? 'primary'
    );
    $user_message_id = intval(
        $message_result['user_message_id'] ?? 0
    );
    $aimee_message_id = intval(
        $message_result['aimee_message_id'] ?? 0
    );
    $reply_duration_ms = aimee_voice_note_estimated_duration_ms(
        $reply
    );
    $subscription_json = !empty($message_result['subscription'])
        ? wp_json_encode($message_result['subscription'])
        : null;
    $media_json = !empty($message_result['media'])
        ? wp_json_encode($message_result['media'])
        : null;

    aimee_voice_note_update_job(
        $job_id,
        [
            'status'              => 'recording',
            'result_status'       => $result_status,
            'reply_text'          => $reply,
            'route_used'          => $voice_route,
            'llm_latency_ms'      => $llm_latency_ms,
            'reply_duration_ms'   => $reply_duration_ms,
            'user_message_id'     => $user_message_id ?: null,
            'aimee_message_id'    => $aimee_message_id ?: null,
            'subscription_json'   => $subscription_json,
            'media_json'          => $media_json,
            'recording_started_at'=> current_time('mysql', true),
        ]
    );

    $messages_table = aimee_table('aimee_messages');
    $message_pk = aimee_messages_primary_key();

    if ($user_message_id) {
        $wpdb->update(
            $messages_table,
            [
                'voice_note_token'       => (string) $job->note_token,
                'voice_note_duration_ms' => intval($job->recorded_ms),
                'voice_note_mime'        => (string) $job->input_mime,
            ],
            [$message_pk => $user_message_id]
        );
    }

    if ($aimee_message_id) {
        $wpdb->update(
            $messages_table,
            [
                'voice_note_token'       => (string) $job->note_token,
                'voice_note_duration_ms' => $reply_duration_ms,
                'voice_note_mime'        => 'audio/mpeg',
            ],
            [$message_pk => $aimee_message_id]
        );
    }

    if (
        !aimee_refresh_subscription_checkout_lock(
            $expected_user_id,
            $voice_lock_token,
            20 * MINUTE_IN_SECONDS
        )
        || !aimee_voice_note_lock_allows_private_write(
            $expected_user_id,
            $voice_lock_token
        )
    ) return false;

    $speech = aimee_elevenlabs_synthesise($reply);
    $reply_filename = '';
    $reply_mime = '';
    $reply_bytes = 0;
    $tts_latency_ms = null;
    $audio_status = 'browser_fallback';
    $voice_error_code = '';
    $voice_error_message = '';

    if (!is_wp_error($speech)) {
        $decoded_audio = base64_decode(
            (string) ($speech['audio_base64'] ?? ''),
            true
        );

        if (is_string($decoded_audio) && $decoded_audio !== '') {
            $reply_filename = (string) $job->note_token
                . '-aimee.mp3';
            $voice_directory = aimee_voice_note_private_directory();
            $reply_path = $voice_directory !== ''
                ? trailingslashit($voice_directory) . $reply_filename
                : '';

            if (
                $reply_path !== ''
                && aimee_voice_note_atomic_store_bytes(
                    $decoded_audio,
                    $reply_path,
                    $expected_user_id,
                    $voice_lock_token
                )
            ) {
                $reply_mime = (string) ($speech['mime_type'] ?? 'audio/mpeg');
                $reply_bytes = filesize($reply_path) ?: strlen($decoded_audio);
                $tts_latency_ms = intval($speech['latency_ms'] ?? 0);
                $audio_status = 'ready';
            } else {
                $reply_filename = '';
                $voice_error_code = 'voice_note_audio_store_failed';
                $voice_error_message = 'Aimee recorded a reply, but the audio file could not be stored.';
            }
            unset($decoded_audio);
        }
    } else {
        $error_data = $speech->get_error_data();
        $error_data = is_array($error_data) ? $error_data : [];
        $voice_error_code = sanitize_key((string) (
            $error_data['voice_error_code']
            ?? $speech->get_error_code()
        ));
        $voice_error_message = sanitize_text_field(
            $speech->get_error_message()
        );
    }

    if (!aimee_voice_note_lock_allows_private_write(
        $expected_user_id,
        $voice_lock_token
    )) {
        if (!empty($reply_path) && is_file($reply_path)) wp_delete_file($reply_path);
        return false;
    }

    $finished_at = current_time('mysql', true);
    aimee_voice_note_update_job(
        $job_id,
        [
            'status'              => 'ready',
            'audio_status'        => $audio_status,
            'reply_file'          => $reply_filename ?: null,
            'reply_mime'          => $reply_mime ?: null,
            'reply_bytes'         => $reply_bytes,
            'tts_latency_ms'      => $tts_latency_ms,
            'voice_error_code'    => $voice_error_code ?: null,
            'voice_error_message' => $voice_error_message ?: null,
            'finished_at'         => $finished_at,
        ]
    );

    $wpdb->insert(aimee_table('aimee_analytics_events'), [
        'user_id'    => intval($job->user_id),
        'event_name' => 'voice_note_processed',
        'properties' => wp_json_encode([
            'audio_bytes'       => intval($job->input_bytes),
            'recorded_ms'       => intval($job->recorded_ms),
            'transcript_chars'  => mb_strlen($transcript),
            'reply_chars'       => mb_strlen($reply),
            'stt_latency_ms'    => intval(
                $transcription['latency_ms'] ?? 0
            ),
            'llm_latency_ms'    => $llm_latency_ms,
            'tts_latency_ms'    => $tts_latency_ms,
            'total_latency_ms'  => intval(round(
                (microtime(true) - $turn_started) * 1000
            )),
            'audio_status'      => $audio_status,
            'voice_route'       => $voice_route,
            'deepgram_model'    => aimee_deepgram_model_id(),
            'elevenlabs_model'  => aimee_elevenlabs_model_id(),
        ]),
        'page_path'  => 'voice-note',
        'occurred_at'=> $finished_at,
        'created_at' => $finished_at,
    ]);

    return true;
}

add_action(
    'aimee_process_voice_note',
    'aimee_process_voice_note_job',
    10,
    1
);

function handle_aimee_voice_note_status(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();

    if (!$user_id) {
        return new WP_Error(
            'authentication_required',
            'Authentication required.',
            ['status' => 401]
        );
    }

    $token = sanitize_text_field((string) (
        $request->get_param('token') ?? ''
    ));

    if (!aimee_voice_note_valid_token($token)) {
        return new WP_Error(
            'voice_note_token_invalid',
            'Invalid voice-note reference.',
            ['status' => 400]
        );
    }

    $job = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_voice_note_table()
        . " WHERE note_token = %s AND user_id = %d LIMIT 1",
        $token,
        $user_id
    ));

    if (!$job) {
        return new WP_Error(
            'voice_note_missing',
            'Voice note not found.',
            ['status' => 404]
        );
    }

    if ((string) $job->status === 'queued') {
        aimee_voice_note_dispatch_job(
            intval($job->id),
            (string) $job->note_token
        );
    }

    // Polling is a new authenticated read, so billing and adult-media access
    // must come from the current profile rather than the job's old snapshot.
    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles') . "
         WHERE user_id = %d LIMIT 1",
        $user_id
    ));
    $subscription = $profile
        ? aimee_get_subscription_snapshot($user_id, $profile)
        : null;

    $media = null;
    if (!empty($job->media_json)) {
        $decoded = json_decode((string) $job->media_json, true);
        if (is_array($decoded)) $media = $decoded;
    }

    $reply_text = (string) ($job->reply_text ?? '');
    $media_delivery_snapshot = null;
    $media_locked = false;
    $delivery_id = sanitize_text_field((string) (
        $media['delivery_id'] ?? ''
    ));
    $media_key = sanitize_key((string) ($media['key'] ?? ''));
    $delivery = $delivery_id !== ''
        ? aimee_media_delivery_find($delivery_id, $user_id)
        : null;
    $delivery_owned = is_array($delivery)
        && $media_key !== ''
        && (string) ($delivery['media_key'] ?? '') === $media_key
        && intval($delivery['message_id'] ?? 0) === intval($job->aimee_message_id ?? 0)
        && !empty($delivery['authorised_at'])
        && !empty($delivery['file_resolved_at'])
        && !empty($delivery['message_created_at'])
        && empty($delivery['failed_at']);
    $current_media_access = $profile
        && $media_key !== ''
        && aimee_media_item_is_viewable($user_id, $media_key, $profile);

    if ($media && (!$delivery_owned || !$current_media_access)) {
        // A sent/unlocked job is not a permanent adult-content entitlement.
        // Do not mutate or terminally fail the historical delivery merely
        // because current membership, consent, assurance or relationship
        // readiness has changed.
        $media = null;
        $media_locked = true;
        $delivery_id = '';
    }
    if (
        (string) ($job->status ?? '') === 'ready'
        && $media
        && $delivery_id !== ''
    ) {
        if (aimee_media_delivery_transition(
            $delivery_id,
            'returned_by_direct_api'
        )) {
            $media_delivery_snapshot = aimee_media_delivery_public_snapshot(
                aimee_media_delivery_find($delivery_id, $user_id)
            );
        } else {
            aimee_media_delivery_transition(
                $delivery_id,
                'failed',
                ['error_code' => 'voice_note_status_return_failed']
            );
            $media = null;
            $reply_text = "I chose a photograph, but it could not be returned with this voice note. I won't pretend it reached you.";
            $messages_table = aimee_table('aimee_messages');
            $message_pk = aimee_messages_primary_key();
            $aimee_message_id = intval($job->aimee_message_id ?? 0);
            if ($aimee_message_id) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE $messages_table
                     SET message_text = %s, image_url = NULL
                     WHERE `{$message_pk}` = %d AND user_id = %d",
                    $reply_text,
                    $aimee_message_id,
                    $user_id
                ));
            }
            aimee_voice_note_update_job(
                intval($job->id),
                [
                    'reply_text' => $reply_text,
                    'media_json' => null,
                ]
            );
        }
    }

    $response = new WP_REST_Response([
        'status'              => (string) $job->status,
        'result_status'       => (string) ($job->result_status ?? ''),
        'note_token'          => (string) $job->note_token,
        'transcript'          => (string) ($job->transcript ?? ''),
        'reply'               => $reply_text,
        'reply_text'          => $reply_text,
        'recorded_ms'         => intval($job->recorded_ms ?? 0),
        'reply_duration_ms'   => intval(
            $job->reply_duration_ms ?? 0
        ),
        'audio_status'        => (string) (
            $job->audio_status ?? 'processing'
        ),
        'audio_url'           => !empty($job->reply_file)
            ? aimee_voice_note_audio_url($token, 'aimee')
            : '',
        'input_audio_url'     => !empty($job->input_file)
            ? aimee_voice_note_audio_url($token, 'user')
            : '',
        'audio_mime'          => (string) ($job->reply_mime ?? ''),
        'subscription'        => $subscription ?: null,
        'media'               => $media,
        'media_locked'        => $media_locked,
        'media_delivery'      => $media_delivery_snapshot,
        'voice_error_code'    => (string) (
            $job->voice_error_code
            ?? $job->error_code
            ?? ''
        ),
        'voice_error_message' => (string) (
            $job->voice_error_message
            ?? $job->error_message
            ?? ''
        ),
    ], 200);

    $response->header(
        'Cache-Control',
        'no-store, no-cache, must-revalidate, max-age=0'
    );

    return $response;
}

function handle_aimee_voice_note_audio(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();
    if (!$user_id) {
        return new WP_Error(
            'authentication_required',
            'Authentication required.',
            ['status' => 401]
        );
    }

    $token = sanitize_text_field((string) $request['token']);
    $kind = sanitize_key((string) $request['kind']);

    if (
        !aimee_voice_note_valid_token($token)
        || !in_array($kind, ['user', 'aimee'], true)
    ) {
        return new WP_Error(
            'voice_note_audio_invalid',
            'Invalid voice-note audio reference.',
            ['status' => 400]
        );
    }

    $job = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_voice_note_table()
        . " WHERE note_token = %s AND user_id = %d LIMIT 1",
        $token,
        $user_id
    ));

    if (!$job) {
        return new WP_Error(
            'voice_note_missing',
            'Voice note not found.',
            ['status' => 404]
        );
    }

    $filename = $kind === 'user'
        ? (string) ($job->input_file ?? '')
        : (string) ($job->reply_file ?? '');
    $mime_type = $kind === 'user'
        ? (string) ($job->input_mime ?? 'audio/webm')
        : (string) ($job->reply_mime ?? 'audio/mpeg');
    $path = aimee_voice_note_resolve_file($filename);

    if ($path === '') {
        return new WP_Error(
            'voice_note_audio_missing',
            'This voice-note audio is no longer available.',
            ['status' => 404]
        );
    }

    $response = new WP_REST_Response([
        '__aimee_voice_audio_path' => $path,
        '__aimee_voice_audio_mime' => sanitize_mime_type($mime_type),
        '__aimee_voice_audio_name' => $kind === 'user'
            ? 'voice-note.webm'
            : 'aimee-voice-note.mp3',
    ], 200);

    $response->header('Content-Type', sanitize_mime_type($mime_type));
    $response->header('Accept-Ranges', 'bytes');
    $response->header('Cache-Control', 'private, max-age=3600');
    $response->header('X-Content-Type-Options', 'nosniff');

    return $response;
}

function aimee_voice_note_stream_audio(
    $served,
    $result,
    $request,
    $server
) {
    if ($served || !($result instanceof WP_REST_Response)) {
        return $served;
    }

    $data = $result->get_data();

    if (
        !is_array($data)
        || empty($data['__aimee_voice_audio_path'])
    ) {
        return $served;
    }

    $path = (string) $data['__aimee_voice_audio_path'];
    if (!is_file($path) || !is_readable($path)) return $served;

    $mime = sanitize_mime_type((string) (
        $data['__aimee_voice_audio_mime'] ?? 'audio/mpeg'
    ));
    $name = sanitize_file_name((string) (
        $data['__aimee_voice_audio_name'] ?? 'voice-note.mp3'
    ));
    $size = filesize($path);
    $start = 0;
    $end = max(0, $size - 1);
    $status = 200;

    if (
        !empty($_SERVER['HTTP_RANGE'])
        && preg_match(
            '/bytes=(\d*)-(\d*)/i',
            (string) $_SERVER['HTTP_RANGE'],
            $matches
        )
    ) {
        if ($matches[1] !== '') $start = intval($matches[1]);
        if ($matches[2] !== '') $end = intval($matches[2]);

        $start = max(0, min($start, $size - 1));
        $end = max($start, min($end, $size - 1));
        $status = 206;
    }

    while (ob_get_level() > 0) {
        @ob_end_clean();
    }

    status_header($status);
    header('Content-Type: ' . $mime);
    header('Content-Disposition: inline; filename="' . $name . '"');
    header('Accept-Ranges: bytes');
    header('Cache-Control: private, max-age=3600');
    header('X-Content-Type-Options: nosniff');
    header('Content-Length: ' . (($end - $start) + 1));

    if ($status === 206) {
        header(
            'Content-Range: bytes '
            . $start . '-' . $end . '/' . $size
        );
    }

    $handle = fopen($path, 'rb');
    if (!$handle) return true;

    fseek($handle, $start);
    $remaining = ($end - $start) + 1;

    while ($remaining > 0 && !feof($handle)) {
        $chunk = fread($handle, min(8192, $remaining));
        if ($chunk === false || $chunk === '') break;
        echo $chunk;
        $remaining -= strlen($chunk);
        flush();
    }

    fclose($handle);
    return true;
}

add_filter(
    'rest_pre_serve_request',
    'aimee_voice_note_stream_audio',
    10,
    4
);

function aimee_voice_note_delete_filename_family_from_directory(
    $directory,
    array $filenames,
    $allow_missing = true
) {
    $scan = aimee_voice_note_scan_directory($directory, $allow_missing);
    if (is_wp_error($scan)) return false;
    if (!$scan) return true;

    $root = $scan['root'];
    foreach ($scan['entries'] as $entry) {
        $owned = false;
        foreach ($filenames as $filename) {
            if (
                hash_equals((string) $filename, (string) $entry)
                || aimee_voice_note_storage_temp_filename_matches($entry, $filename)
            ) {
                $owned = true;
                break;
            }
        }
        if (!$owned) continue;

        $candidate = $root . DIRECTORY_SEPARATOR . $entry;
        if (is_link($candidate) || !is_file($candidate)) return false;
        $resolved = realpath($candidate);
        if (
            !$resolved
            || !aimee_profile_media_path_is_within($resolved, $root)
        ) return false;
        wp_delete_file($resolved);
        if (is_file($resolved) || is_link($candidate)) return false;
    }

    // Re-scan rather than trusting delete return values or the first snapshot.
    $remaining = aimee_voice_note_scan_directory($root, false);
    if (is_wp_error($remaining) || !$remaining) return false;
    foreach ($remaining['entries'] as $entry) {
        foreach ($filenames as $filename) {
            if (
                hash_equals((string) $filename, (string) $entry)
                || aimee_voice_note_storage_temp_filename_matches($entry, $filename)
            ) return false;
        }
    }
    return true;
}

function aimee_voice_note_delete_user_files($user_id) {
    static $deletion_manifests = [];

    $user_id = intval($user_id);
    if ($user_id < 1) return false;
    $referenced = aimee_voice_note_referenced_filenames($user_id);
    if (is_wp_error($referenced)) {
        if (empty($deletion_manifests[$user_id])) return false;
        $referenced = $deletion_manifests[$user_id];
    } elseif ($referenced) {
        $deletion_manifests[$user_id] = $referenced;
    } elseif (!empty($deletion_manifests[$user_id])) {
        // The REST erasure path deletes DB rows before wp_delete_user fires.
        // Reuse the exact pre-deletion manifest for a second filesystem scan.
        $referenced = $deletion_manifests[$user_id];
    }

    foreach ((array) $referenced as $filename) {
        if (!aimee_voice_note_storage_filename_is_valid($filename)) return false;
    }
    if (!$referenced) return true;

    $private_dir = aimee_voice_note_private_directory();
    if (
        $private_dir === ''
        || !aimee_voice_note_delete_filename_family_from_directory(
            $private_dir,
            $referenced,
            false
        )
    ) return false;

    $private_real = realpath($private_dir);
    foreach (aimee_voice_note_legacy_directory_specs() as $spec) {
        $legacy_real = file_exists($spec['path']) && !is_link($spec['path'])
            ? realpath($spec['path'])
            : false;
        if (
            $legacy_real
            && $private_real
            && wp_normalize_path($legacy_real) === wp_normalize_path($private_real)
        ) continue;
        if (!aimee_voice_note_delete_filename_family_from_directory(
            $spec['path'],
            $referenced,
            true
        )) return false;
    }
    return true;
}

/** Block an already-running worker before any ordinary WordPress user deletion. */
function aimee_voice_note_mark_core_user_deletion($user_id) {
    global $wpdb;
    $user_id = intval($user_id);
    if ($user_id < 1) return false;
    $updated = $wpdb->query($wpdb->prepare(
        "UPDATE " . aimee_table('aimee_user_profiles') . "
         SET account_deletion_started_at = COALESCE(account_deletion_started_at, %s)
         WHERE user_id = %d",
        current_time('mysql', true),
        $user_id
    ));
    return $updated !== false;
}
add_action('delete_user', 'aimee_voice_note_mark_core_user_deletion', 1, 1);
add_action('delete_user', 'aimee_voice_note_delete_user_files', 6, 1);


function aimee_voice_rest_retry_after_header(
    $response,
    $server,
    $request
) {
    if (
        !($response instanceof WP_REST_Response)
        || (
            strpos((string) $request->get_route(), '/aimee/v1/voice/') !== 0
            && strpos((string) $request->get_route(), '/aimee/v1/voice-note/') !== 0
        )
    ) {
        return $response;
    }

    $data = $response->get_data();

    if (
        $response->get_status() === 429
        && is_array($data)
        && !empty($data['data']['retry_after'])
    ) {
        $response->header(
            'Retry-After',
            max(1, intval($data['data']['retry_after']))
        );
    }

    return $response;
}

add_filter(
    'rest_post_dispatch',
    'aimee_voice_rest_retry_after_header',
    10,
    3
);

