function handle_aimee_settings_update(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();
    if (!$user_id) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Authentication required.'], 401);
    }

    $params = $request->get_json_params();
    $table  = aimee_table('aimee_user_profiles');

    $current_profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM $table WHERE user_id = %d",
        $user_id
    ));
    if (!$current_profile) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Aimee profile not found.'], 404);
    }
    if (aimee_account_deletion_tombstone_is_active($current_profile)) {
        return new WP_REST_Response([
            'status' => 'account_deletion_in_progress',
            'message' => 'Settings cannot change while account deletion is in progress.',
        ], 409);
    }

    $market_was_requested = array_key_exists('market', $params);
    $current_market = sanitize_key((string) ($current_profile->market ?? 'uk'));
    if (!in_array($current_market, ['uk', 'us'], true)) $current_market = 'uk';
    $market = $market_was_requested
        ? (function_exists('aimee_global_market')
            ? aimee_global_market($params['market'])
            : (sanitize_key((string) $params['market']) === 'us' ? 'us' : 'uk'))
        : $current_market;

    $settings_lock_token = '';
    if ($market_was_requested) {
        $settings_lock_token = aimee_acquire_subscription_checkout_lock($user_id);
        if ($settings_lock_token === '') {
            return new WP_REST_Response([
                'status' => 'billing_operation_in_progress',
                'message' => 'A secure billing operation is in progress. Please retry the market change when it finishes.',
            ], 409);
        }
        // The pre-lock snapshot is advisory only. Recompute the requested
        // transition from the profile protected by this exact owner token.
        $current_profile = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table WHERE user_id = %d",
            $user_id
        ));
        if (
            !$current_profile
            || !hash_equals(
                $settings_lock_token,
                (string) ($current_profile->billing_checkout_lock_token ?? '')
            )
        ) {
            aimee_release_subscription_checkout_lock($user_id, $settings_lock_token);
            return new WP_REST_Response([
                'status' => 'billing_state_error',
                'message' => 'The market change lock could not be verified.',
            ], 503);
        }
        $current_market = sanitize_key((string) ($current_profile->market ?? 'uk'));
        if (!in_array($current_market, ['uk', 'us'], true)) $current_market = 'uk';
        $market = function_exists('aimee_global_market')
            ? aimee_global_market($params['market'])
            : (sanitize_key((string) $params['market']) === 'us' ? 'us' : 'uk');
    }

    try {
    if (
        $market !== $current_market
        && aimee_membership_profile_has_unsettled_billing_authority($current_profile)
    ) {
        return new WP_REST_Response([
            'status' => 'billing_market_locked',
            'message' => 'Your market cannot change while a payment authorisation or recurring membership is pending. Finish or cancel billing first.',
        ], 409);
    }

    $sms_opt_in  = !empty($params['sms_opt_in']) ? 1 : 0;
    $sms_override = $sms_opt_in && !empty($params['sms_override']) ? 1 : 0;
    $safe_start = max(0, min(23, intval($params['safe_start'] ?? 9)));
    $safe_end   = max(0, min(23, intval($params['safe_end'] ?? 17)));
    $sms_timezone = array_key_exists('sms_timezone', $params)
        ? sanitize_text_field((string) $params['sms_timezone'])
        : trim((string) ($current_profile->sms_timezone ?? ''));
    if (
        $sms_timezone !== ''
        && (
            !function_exists('aimee_global_sms_timezone_is_valid')
            || !aimee_global_sms_timezone_is_valid($sms_timezone)
        )
    ) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Please select a valid named timezone before enabling SMS.',
        ], 400);
    }

    $update_data = [
        'first_name'          => sanitize_text_field($params['first_name'] ?? $current_profile->first_name ?? ''),
        'market'              => $market,
        'sms_opt_in'          => $sms_opt_in,
        'sms_override'        => $sms_override,
        'sms_safe_start_hour' => $safe_start,
        'sms_safe_end_hour'   => $safe_end,
        'sms_timezone'        => $sms_timezone !== '' ? $sms_timezone : null,
    ];
    $formats = ['%s', '%s', '%d', '%d', '%d', '%d', '%s'];
    if (!$market_was_requested) {
        unset($update_data['market']);
        array_splice($formats, 1, 1);
    }
    $proposed_phone = (string) ($current_profile->phone_number ?? '');
    $phone_changed = false;

    if (array_key_exists('phone_number', $params)) {
        $raw_phone = sanitize_text_field($params['phone_number']);
        if ($raw_phone === '') {
            $update_data['phone_number'] = null;
            $proposed_phone = '';
        } elseif (is_email($raw_phone)) {
            $update_data['phone_number'] = sanitize_email($raw_phone);
            $proposed_phone = (string) $update_data['phone_number'];
            $update_data['sms_opt_in'] = 0;
            $update_data['sms_override'] = 0;
        } else {
            $formatted = aimee_format_mobile($raw_phone, $market);
            if (!$formatted) {
                return new WP_REST_Response([
                    'status' => 'error',
                    'message' => $market === 'us'
                        ? 'Please enter a valid US mobile number, including area code, or leave the field blank.'
                    : 'Please enter a valid UK mobile number or leave the field blank.',
                ], 400);
            }
            if (aimee_phone_is_reserved_for_other_identity($formatted, $user_id)) {
                return new WP_REST_Response([
                    'status' => 'error',
                    'message' => 'That mobile number is reserved for a different account.',
                ], 409);
            }
            $update_data['phone_number'] = $formatted;
            $proposed_phone = $formatted;
        }
        $formats[] = '%s';

        $current_mobile = aimee_format_mobile(
            (string) ($current_profile->phone_number ?? ''),
            aimee_profile_market($current_profile)
        );
        $current_comparable = $current_mobile
            ? (string) $current_mobile
            : trim((string) ($current_profile->phone_number ?? ''));
        $phone_changed = !hash_equals($current_comparable, $proposed_phone);
        if ($phone_changed) {
            $update_data['phone_verified_number'] = null;
            $update_data['phone_verified_at'] = null;
            $update_data['sms_opt_in'] = 0;
            $update_data['sms_override'] = 0;
            $formats[] = '%s';
            $formats[] = '%s';
        }
    }

    $verification_probe = clone $current_profile;
    $verification_probe->phone_number = $proposed_phone;
    $verification_probe->sms_timezone = $sms_timezone;
    if ($phone_changed) {
        $verification_probe->phone_verified_number = null;
        $verification_probe->phone_verified_at = null;
    }
    if (
        $sms_opt_in
        && (
            !function_exists('aimee_global_sms_profile_is_verified')
            || !aimee_global_sms_profile_is_verified($verification_probe)
        )
    ) {
        return new WP_REST_Response([
            'status' => 'sms_verification_required',
            'message' => 'SMS remains off until this mobile number is verified and a valid timezone is saved. Your in-app access is unaffected.',
        ], 409);
    }

    $update_where = [
        'user_id' => $user_id,
        'account_deletion_started_at' => null,
    ];
    $update_where_formats = ['%d', null];
    if ($market_was_requested) {
        $update_where['billing_checkout_lock_token'] = $settings_lock_token;
        $update_where['market'] = $current_market;
        $update_where_formats[] = '%s';
        $update_where_formats[] = '%s';
    }
    $updated = $wpdb->update(
        $table,
        $update_data,
        $update_where,
        $formats,
        $update_where_formats
    );

    if ($updated === false) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Database update failed.'], 500);
    }
    if ($updated === 0) {
        $verified_profile = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table WHERE user_id = %d",
            $user_id
        ));
        if (!$verified_profile || aimee_account_deletion_tombstone_is_active($verified_profile)) {
            return new WP_REST_Response([
                'status' => 'account_deletion_in_progress',
                'message' => 'Settings were not changed because account deletion is in progress.',
            ], 409);
        }
    }

    return rest_ensure_response([
        'status'       => 'success',
        'subscription' => aimee_get_subscription_snapshot($user_id),
        'sms_verified' => function_exists('aimee_global_sms_profile_is_verified')
            && aimee_global_sms_profile_is_verified($verification_probe),
    ]);
    } finally {
        if ($settings_lock_token !== '') {
            aimee_release_subscription_checkout_lock($user_id, $settings_lock_token);
        }
    }
}


/**
 * Keep the most recent operational registration failure diagnosable without
 * retaining a login ID, email address, mobile number, passcode, image or SQL.
 */
function aimee_registration_diagnostic_option_name() {
    return 'aimee_global_last_registration_failure';
}

function aimee_registration_record_failure(
    $stage,
    $error_code = ''
) {
    $allowed_stages = [
        'schema_preflight_failed',
        'wp_user_create_failed',
        'credential_finalize_failed',
        'profile_media_store_failed',
        'profile_insert_failed',
        'post_commit_completion_failed',
    ];
    $stage = sanitize_key((string) $stage);
    if (!in_array($stage, $allowed_stages, true)) {
        $stage = 'profile_insert_failed';
    }

    $error_code = sanitize_key((string) $error_code);
    $allowed_error_codes = [
        'core_schema_unhealthy',
        'wordpress_user_create_failed',
        'profile_image_storage_failed',
        'profile_database_write_failed',
        'post_commit_completion_failed',
        'unspecified_operational_failure',
    ];
    if (!in_array($error_code, $allowed_error_codes, true)) {
        $error_code = 'unspecified_operational_failure';
    }

    if (function_exists('wp_generate_uuid4')) {
        $reference_seed = str_replace('-', '', (string) wp_generate_uuid4());
    } else {
        try {
            $reference_seed = bin2hex(random_bytes(16));
        } catch (Throwable $exception) {
            $reference_seed = hash('sha256', microtime(true) . ':' . wp_rand());
        }
    }
    $reference = 'REG-' . strtoupper(substr($reference_seed, 0, 12));
    $record = [
        'occurred_at' => current_time('mysql', true),
        'reference'   => $reference,
        'stage'       => $stage,
        'error_code'  => $error_code,
    ];

    update_option(aimee_registration_diagnostic_option_name(), $record, false);
    error_log(sprintf(
        '[Aimee registration] operational issue at %s; reference=%s; code=%s',
        $stage,
        $reference,
        $error_code
    ));

    return $reference;
}

function aimee_registration_failure_response(
    $stage,
    $error_code = '',
    $status = 500
) {
    $reference = aimee_registration_record_failure(
        $stage,
        $error_code
    );

    return new WP_REST_Response([
        'status'    => 'error',
        'message'   => 'We could not finish creating the account. Please try again. If it continues, quote reference ' . $reference . '.',
        'reference' => $reference,
    ], max(400, intval($status)));
}

function aimee_registration_post_commit_hook() {
    return 'aimee_registration_post_commit_188';
}

function aimee_registration_post_commit_state_option_name($user_id) {
    return 'aimee_registration_post_commit_188_' . max(0, intval($user_id));
}

/**
 * Queue post-signup network work without extending the public REST request.
 * The event arguments contain only the immutable WordPress user ID.
 */
function aimee_registration_schedule_post_commit($user_id) {
    $user_id = max(0, intval($user_id));
    if (
        $user_id < 1
        || !function_exists('wp_next_scheduled')
        || !function_exists('wp_schedule_single_event')
    ) {
        return false;
    }

    $hook = aimee_registration_post_commit_hook();
    $args = [$user_id];
    if (wp_next_scheduled($hook, $args)) return true;

    $scheduled = wp_schedule_single_event(
        time() + 5,
        $hook,
        $args,
        true
    );
    return !is_wp_error($scheduled) && $scheduled !== false;
}

/**
 * Complete optional signup work at most once per immutable account.
 *
 * A unique non-autoloaded option is the durable claim. Claiming before any
 * provider call prevents duplicate email or model work if the cron hook is
 * delivered more than once. The owner SMS path also retains its own durable
 * send key, so a provider retry cannot create a second carrier message.
 */
function aimee_registration_run_post_commit($user_id) {
    global $wpdb;

    $user_id = max(0, intval($user_id));
    if ($user_id < 1 || !function_exists('add_option')) return;

    $state_option = aimee_registration_post_commit_state_option_name($user_id);
    $claimed = add_option($state_option, [
        'status' => 'running',
        'started_at' => current_time('mysql', true),
    ], '', false);
    if (!$claimed) return;

    try {
        $table = aimee_table('aimee_user_profiles');
        $profile = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table WHERE user_id = %d LIMIT 1",
            $user_id
        ));
        if (!$profile || aimee_account_deletion_tombstone_is_active($profile)) {
            update_option($state_option, [
                'status' => 'skipped',
                'completed_at' => current_time('mysql', true),
            ], false);
            return;
        }

        $appearance_notes = trim((string) ($profile->appearance_notes ?? ''));
        $stored_image_url = (string) ($profile->profile_image_url ?? '');
        if (
            $appearance_notes === ''
            && $stored_image_url !== ''
            && function_exists('aimee_profile_media_url_is_protected')
            && aimee_profile_media_url_is_protected($stored_image_url)
            && function_exists('aimee_profile_media_file_for_user')
            && function_exists('aimee_profile_media_read_validated_file')
        ) {
            try {
                $private_file = aimee_profile_media_file_for_user($user_id);
                $validated_file = is_array($private_file)
                    ? aimee_profile_media_read_validated_file((string) ($private_file['path'] ?? ''))
                    : new WP_Error('profile_image_file_missing', 'Profile image was unavailable.');
                if (!is_wp_error($validated_file)) {
                    $facts = (array) ($validated_file['facts'] ?? []);
                    $bytes = $validated_file['bytes'] ?? '';
                    $mime_type = (string) ($facts['mime'] ?? '');
                    if (is_string($bytes) && $bytes !== '' && $mime_type !== '') {
                        $vision_content = [
                            [
                                'type' => 'image',
                                'source' => [
                                    'type' => 'base64',
                                    'media_type' => $mime_type,
                                    'data' => base64_encode($bytes),
                                ],
                            ],
                            [
                                'type' => 'text',
                                'text' => 'Describe the visual contents of this image objectively. Focus on clothing, hair style and setting. Output one short sentence only, without a preamble.',
                            ],
                        ];
                        $vision_candidate = call_anthropic_api(
                            [],
                            $vision_content,
                            aimee_vision_model(),
                            '',
                            aimee_model_options('vision')
                        );
                        $vision_response = is_string($vision_candidate)
                            ? trim($vision_candidate)
                            : '';
                        if ($vision_response !== '' && stripos($vision_response, 'error') === false) {
                            $appearance_notes = aimee_profile_attribution_limit_text(
                                sanitize_text_field($vision_response),
                                500
                            );
                            if ($appearance_notes !== '') {
                                $updated = $wpdb->update(
                                    $table,
                                    ['appearance_notes' => $appearance_notes],
                                    ['user_id' => $user_id],
                                    ['%s'],
                                    ['%d']
                                );
                                if ($updated === false) $appearance_notes = '';
                            }
                        }
                    }
                }
            } catch (Throwable $exception) {
                // Profile-photo interpretation is optional and never blocks
                // the remaining operational notifications.
                $appearance_notes = '';
            }
        }

        try {
            $admin_email = get_option('admin_email');
            $first_name = sanitize_text_field((string) ($profile->first_name ?? ''));
            $email_body = "A new adult user completed onboarding.\n\n";
            $email_body .= 'Name: ' . $first_name . "\n";
            $email_body .= 'Login/contact: ' . (string) ($profile->phone_number ?? '') . "\n";
            $email_body .= 'Complimentary preview: ' . aimee_free_preview_limit() . " Aimee replies\n";
            $email_body .= 'Your World: ' . (string) ($profile->hobbies ?? '') . "\n";
            $email_body .= 'Your Intent: ' . (string) ($profile->looking_for ?? '') . "\n";
            $email_body .= 'AI vision notes: ' . $appearance_notes . "\n";
            wp_mail(
                $admin_email,
                'New Aimee user: ' . $first_name,
                $email_body
            );
        } catch (Throwable $exception) {
            // Administrator email is best-effort in the deferred worker.
        }

        try {
            $owner_user_id = aimee_configured_identity_user_id('AIMEE_OWNER_USER_ID');
            $owner_profile = $owner_user_id > 0
                ? $wpdb->get_row($wpdb->prepare(
                    "SELECT * FROM $table WHERE user_id = %d LIMIT 1",
                    $owner_user_id
                ))
                : null;
            $configured_owner_mobile = aimee_internal_identity_number('AIMEE_OWNER_NUMBER');
            $verified_owner_mobile = $owner_profile
                ? aimee_format_mobile(
                    (string) ($owner_profile->phone_number ?? ''),
                    aimee_profile_market($owner_profile)
                )
                : '';
            if (
                $owner_profile
                && aimee_is_owner_user($owner_profile)
                && intval($owner_profile->sms_opt_in ?? 0) === 1
                && $configured_owner_mobile !== ''
                && $verified_owner_mobile !== false
                && hash_equals((string) $configured_owner_mobile, (string) $verified_owner_mobile)
                && function_exists('aimee_global_sms_profile_is_verified')
                && aimee_global_sms_profile_is_verified($owner_profile)
                && aimee_sms_can_send_now($owner_profile)
            ) {
                aimee_send_system_sms(
                    $owner_profile,
                    'New Aimee user: ' . sanitize_text_field((string) ($profile->first_name ?? '')) . ' has signed up.',
                    'registration_owner_alert',
                    0,
                    'registration:' . $user_id . ':owner_alert'
                );
            }
        } catch (Throwable $exception) {
            // Carrier notification is best-effort in the deferred worker.
        }

        update_option($state_option, [
            'status' => 'completed',
            'completed_at' => current_time('mysql', true),
        ], false);
    } catch (Throwable $exception) {
        // The durable at-most-once claim intentionally remains. A worker
        // failure can never turn registration into a failed user experience.
        update_option($state_option, [
            'status' => 'failed',
            'completed_at' => current_time('mysql', true),
        ], false);
    }
}
add_action(
    aimee_registration_post_commit_hook(),
    'aimee_registration_run_post_commit',
    10,
    1
);

function handle_aimee_profile_save(WP_REST_Request $request) {
    global $wpdb;

    if (!aimee_rate_limit('profile_create', 8, 15 * MINUTE_IN_SECONDS)) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Too many registration attempts. Please wait a few minutes and try again.',
        ], 429);
    }

    // Registration must never attempt request-time DDL. The schema installer
    // owns repair; fail before creating a WordPress identity when its complete
    // core contract is unavailable.
    if (
        !function_exists('aimee_global_core_schema_health')
        || !aimee_global_core_schema_health()
    ) {
        return aimee_registration_failure_response(
            'schema_preflight_failed',
            'core_schema_unhealthy',
            503
        );
    }

    $params = $request->get_json_params();
    $table  = aimee_table('aimee_user_profiles');
    $market = function_exists('aimee_global_market') ? aimee_global_market($params['market'] ?? null) : 'uk';

    $login_id    = sanitize_text_field($params['phone_number'] ?? '');
    // Passwords are opaque credentials. Do not sanitize or normalize them;
    // WordPress hashes the exact value chosen by the user.
    $passcode    = isset($params['passcode']) && is_string($params['passcode'])
        ? $params['passcode']
        : '';
    $first_name  = sanitize_text_field($params['first_name'] ?? '');
    $age         = intval($params['age'] ?? 0);
    $hobbies     = aimee_profile_attribution_limit_text(
        sanitize_textarea_field($params['hobbies'] ?? ''),
        1200
    );
    $looking_for = aimee_profile_attribution_limit_text(
        sanitize_textarea_field($params['looking_for'] ?? ''),
        600
    );

    if ($login_id === '' || $passcode === '' || $first_name === '') {
        return rest_ensure_response(['status' => 'error', 'message' => 'Missing required registration details.']);
    }

    if ($age < 18 || $age > 100) {
        return rest_ensure_response(['status' => 'error', 'message' => 'Aimee is available to adults aged 18 and over only.']);
    }

    // New accounts use the original six-digit passcode contract. Keep the
    // value opaque so a leading zero reaches WordPress unchanged. Login does
    // not apply this rule, preserving every existing longer passphrase.
    if (preg_match('/\A[0-9]{6}\z/', $passcode) !== 1) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Choose a six-digit passcode.',
        ], 400);
    }

    $weak_passcodes = ['123456', '654321', '012345'];
    if (
        in_array($passcode, $weak_passcodes, true)
        || preg_match('/\A([0-9])\1{5}\z/', $passcode) === 1
    ) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Please avoid predictable passcodes such as 123456 or repeating numbers.',
        ], 400);
    }

    $special_category_consent = function_exists('aimee_security_boolean_is_true')
        && aimee_security_boolean_is_true($params['special_category_consent'] ?? false);

    // Validate an optional image before any account-existence lookup, so photo
    // errors cannot become an identifier-enumeration side channel.
    $profile_image_bytes = '';
    $profile_image_facts = null;
    if (!empty($params['image']) && is_string($params['image'])) {
        $encoded = (string) $params['image'];
        $encoded = strpos($encoded, ',') !== false
            ? substr($encoded, strpos($encoded, ',') + 1)
            : $encoded;
        $profile_media_limits = function_exists('aimee_profile_media_limits')
            ? aimee_profile_media_limits()
            : ['bytes' => 8 * 1024 * 1024];
        $encoded_limit = intval(ceil(intval($profile_media_limits['bytes']) * 4 / 3)) + 1024;
        if (strlen($encoded) > $encoded_limit) {
            return new WP_REST_Response([
                'status' => 'error',
                'message' => 'That profile image could not be accepted. Use a valid JPEG, PNG, GIF or WebP within the size and dimension limits.',
            ], 400);
        }
        $encoded = preg_replace('/\s+/', '', $encoded);
        $decoded = is_string($encoded)
            ? base64_decode($encoded, true)
            : false;
        $profile_image_facts = is_string($decoded)
            && function_exists('aimee_profile_media_validate_bytes')
                ? aimee_profile_media_validate_bytes($decoded)
                : new WP_Error('profile_image_invalid', 'Profile image validation failed.');
        if (is_wp_error($profile_image_facts)) {
            return new WP_REST_Response([
                'status' => 'error',
                'message' => 'That profile image could not be accepted. Use a valid JPEG, PNG, GIF or WebP within the size and dimension limits.',
            ], 400);
        }
        $profile_image_bytes = $decoded;
    }

    $formatted_mobile = aimee_format_mobile($login_id, $market);
    if ($formatted_mobile && aimee_phone_is_reserved_for_other_identity($formatted_mobile, 0)) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'We could not create an account with those details. Check them or sign in if you already have an account.',
        ], 400);
    }
    $account_login = $formatted_mobile ?: $login_id;
    $account_login = sanitize_user($account_login, true);

    if ($account_login === '') {
        return rest_ensure_response(['status' => 'error', 'message' => 'Please choose a valid Login ID.']);
    }

    $login_exists = username_exists($account_login);
    if (!$login_exists && $formatted_mobile) {
        foreach (aimee_mobile_login_candidates($login_id, $market) as $candidate) {
            if (username_exists($candidate)) {
                $login_exists = true;
                break;
            }
        }
    }

    if ($login_exists || (is_email($login_id) && email_exists($login_id))) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'We could not create an account with those details. Check them or sign in if you already have an account.',
        ], 400);
    }

    $account_email = is_email($login_id) ? sanitize_email($login_id) : '';
    $user_id = wp_create_user($account_login, $passcode, $account_email);

    if (is_wp_error($user_id)) {
        $user_error_codes = method_exists($user_id, 'get_error_codes')
            ? array_map('sanitize_key', (array) $user_id->get_error_codes())
            : [];
        if (array_intersect($user_error_codes, ['existing_user_login', 'existing_user_email'])) {
            // A race with another registration is still an existence-sensitive
            // collision and must use the same response as the preflight check.
            return new WP_REST_Response([
                'status' => 'error',
                'message' => 'We could not create an account with those details. Check them or sign in if you already have an account.',
            ], 400);
        }

        return aimee_registration_failure_response(
            'wp_user_create_failed',
            'wordpress_user_create_failed',
            500
        );
    }

    // Last-resort rollback for an exception or fatal error before the minimal
    // profile becomes durable. Explicit error branches below still clean up
    // immediately; the shutdown guard covers otherwise uncatchable exits.
    $profile_creation_committed = false;
    register_shutdown_function(static function () use ($user_id, &$profile_creation_committed) {
        if ($profile_creation_committed) return;
        if (function_exists('aimee_profile_media_delete_user_files')) {
            aimee_profile_media_delete_user_files($user_id);
        }
        if (!function_exists('wp_delete_user')) {
            require_once ABSPATH . 'wp-admin/includes/user.php';
        }
        if (function_exists('wp_delete_user')) {
            wp_delete_user($user_id);
        }
    });

    $stored_contact = $login_id;
    if ($formatted_mobile) {
        $stored_contact = $formatted_mobile;
    } elseif (is_email($login_id)) {
        $stored_contact = sanitize_email($login_id);
    }

    $final_image_url = '';
    $appearance_notes = '';

    if ($profile_image_bytes !== '' && is_array($profile_image_facts)) {
        $stored_profile_image = function_exists('aimee_profile_media_store')
            ? aimee_profile_media_store($user_id, $profile_image_bytes, $profile_image_facts)
            : new WP_Error('profile_image_storage_unavailable', 'Private profile image storage is unavailable.');
        if (is_wp_error($stored_profile_image)) {
            aimee_registration_record_failure(
                'profile_media_store_failed',
                'profile_image_storage_failed'
            );
            // The photograph is optional. A private-storage outage must not
            // strand an otherwise valid new account or send its bytes to the
            // vision provider. The user can add a photo after registration.
            $profile_image_bytes = '';
            $profile_image_facts = null;
            $stored_profile_image = null;
        } else {
            $final_image_url = esc_url_raw((string) $stored_profile_image['url']);
        }
    }

    $profile_data = [
        'user_id'             => $user_id,
        'phone_number'        => $stored_contact,
        'market'              => $market,
        'first_name'          => $first_name,
        'age'                 => $age,
        'hobbies'             => $hobbies,
        'looking_for'         => $looking_for,
        'profile_image_url'   => $final_image_url,
        'appearance_notes'    => $appearance_notes,
        'special_category_consent_at' => $special_category_consent
            ? current_time('mysql', true)
            : null,
        'special_category_consent_version' => $special_category_consent
            ? aimee_special_category_consent_version()
            : null,
        'wallet_balance'      => 0.00,
        'active_topup_tier'   => 0,
        'escort_mode'         => 0,
        // A mobile login is not proof of phone ownership and never counts as
        // carrier-SMS consent. Verification and explicit opt-in happen later.
        'sms_opt_in'          => 0,
        'sms_timezone'        => (
            !empty($params['sms_timezone'])
            && function_exists('aimee_global_sms_timezone_is_valid')
            && aimee_global_sms_timezone_is_valid(
                sanitize_text_field((string) $params['sms_timezone'])
            )
        )
            ? sanitize_text_field((string) $params['sms_timezone'])
            : null,
        'phone_verified_number' => null,
        'phone_verified_at'     => null,
        'subscription_status' => 'trial',
        'subscription_plan'   => null,
        'trial_message_limit' => aimee_free_preview_limit(),
        'trial_messages_used' => 0,
        'intimacy_score'      => 8,
        'intimacy_stage'      => 'guarded',
    ];

    // Every Aimee profile created before the fixed September cutoff receives
    // the same auditable in-app service grant. This adds no plan, payment
    // mandate, relationship score, adult assurance or consent state.
    if (function_exists('aimee_global_service_grace_profile_fields')) {
        $profile_data = array_merge(
            $profile_data,
            aimee_global_service_grace_profile_fields()
        );
    }

    // This is a brand-new profile row. INSERT fails safely on a uniqueness
    // conflict; REPLACE could delete a pre-existing row that happened to share
    // another unique key. The omitted privacy acknowledgement column uses its
    // schema default of NULL without manufacturing an acknowledgement event.
    $inserted = $wpdb->insert($table, $profile_data);

    if ($inserted === false) {
        if (function_exists('aimee_profile_media_delete_user_files')) {
            aimee_profile_media_delete_user_files($user_id);
        }
        require_once ABSPATH . 'wp-admin/includes/user.php';
        wp_delete_user($user_id);
        return aimee_registration_failure_response(
            'profile_insert_failed',
            'profile_database_write_failed',
            500
        );
    }
    $profile_creation_committed = true;

    // From this point the account exists and can be used. Keep the REST
    // request bounded to local persistence, authentication and queueing.
    // Provider, mail and carrier work belongs exclusively to the cron worker.
    $fallback_reply = "Hi {$first_name}, there you are 😊 I’m Aimee. Let’s start easy: what’s something you can happily talk about for hours? x";
    $opening_message_persisted = false;

    try {
        $opening_message_persisted = $wpdb->insert(
            aimee_table('aimee_messages'),
            [
                'user_id'             => $user_id,
                'sender'              => 'aimee',
                'message_text'        => sanitize_textarea_field($fallback_reply),
                'evaluator_directive' => 'onboarding_icebreaker_local_durable',
            ]
        ) !== false;
        if (!$opening_message_persisted) {
            throw new RuntimeException('opening_message_insert_failed');
        }

        wp_set_current_user($user_id);
        wp_set_auth_cookie($user_id, true, is_ssl());

        $post_commit_scheduled = aimee_registration_schedule_post_commit($user_id);

        return rest_ensure_response([
            'status'                => 'success',
            'user_id'               => $user_id,
            'image_url'             => $final_image_url,
            'opening_message'       => $fallback_reply,
            'subscription'          => aimee_get_subscription_snapshot($user_id),
            'market'                => $market,
            'post_commit_scheduled' => $post_commit_scheduled,
        ]);
    } catch (Throwable $exception) {
        try {
            aimee_registration_record_failure(
                'post_commit_completion_failed',
                'post_commit_completion_failed'
            );
        } catch (Throwable $diagnostic_exception) {
            // The durable account takes priority over optional diagnostics.
        }

        try {
            wp_set_current_user($user_id);
            wp_set_auth_cookie($user_id, true, is_ssl());
        } catch (Throwable $authentication_exception) {
            // The client still receives success and can sign in normally.
        }

        if (!$opening_message_persisted) {
            try {
                $opening_message_persisted = $wpdb->insert(
                    aimee_table('aimee_messages'),
                    [
                        'user_id'             => $user_id,
                        'sender'              => 'aimee',
                        'message_text'        => sanitize_textarea_field($fallback_reply),
                        'evaluator_directive' => 'onboarding_icebreaker_post_commit_fallback',
                    ]
                ) !== false;
            } catch (Throwable $message_exception) {
                // The first normal chat/history request can continue without it.
            }
        }

        try {
            $post_commit_scheduled = aimee_registration_schedule_post_commit($user_id);
        } catch (Throwable $schedule_exception) {
            $post_commit_scheduled = false;
        }

        return rest_ensure_response([
            'status'                => 'success',
            'user_id'               => $user_id,
            'image_url'             => $final_image_url,
            'opening_message'       => $fallback_reply,
            'subscription'          => null,
            'market'                => $market,
            'post_commit_scheduled' => $post_commit_scheduled,
            'onboarding_recovered'  => true,
        ]);
    }
}


function handle_aimee_history(WP_REST_Request $request) {
    global $wpdb;

    $user_id = get_current_user_id();
    if (!$user_id) {
        return new WP_REST_Response(['status' => 'error', 'message' => 'Authentication required.'], 401);
    }

    $messages_table = aimee_table('aimee_messages');
    $message_pk = aimee_messages_primary_key();
    $history = $wpdb->get_results($wpdb->prepare(
        "SELECT {$message_pk} AS message_id,
                sender, message_text, image_url, evaluator_directive, created_at, is_sms,
                voice_note_token, voice_note_duration_ms, voice_note_mime,
                media_decision_id, media_delivery_id
         FROM $messages_table
         WHERE user_id = %d
         ORDER BY created_at ASC, {$message_pk} ASC",
        $user_id
    ));

    $profile = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM " . aimee_table('aimee_user_profiles') . " WHERE user_id = %d",
        $user_id
    ));
    $messages = [];
    foreach ((array) $history as $message) {
        $row = [
            'message_id'   => intval($message->message_id ?? 0),
            'sender'       => $message->sender,
            'message_text' => $message->message_text,
            'created_at'   => $message->created_at,
            'is_sms'       => intval($message->is_sms),
        ];

        $voice_note_token = sanitize_text_field((string) (
            $message->voice_note_token ?? ''
        ));

        if (aimee_voice_note_valid_token($voice_note_token)) {
            $voice_kind = (string) $message->sender === 'user'
                ? 'user'
                : 'aimee';

            $row['voice_note'] = [
                'token'       => $voice_note_token,
                'duration_ms' => intval(
                    $message->voice_note_duration_ms ?? 0
                ),
                'mime'        => sanitize_mime_type((string) (
                    $message->voice_note_mime ?? ''
                )),
                'audio_url'   => aimee_voice_note_audio_url(
                    $voice_note_token,
                    $voice_kind
                ),
            ];
        }

        if (is_string($message->image_url) && strpos($message->image_url, 'aimee-media:') === 0) {
            $key = sanitize_key(substr($message->image_url, strlen('aimee-media:')));
            $delivery_id = sanitize_text_field((string) (
                $message->media_delivery_id ?? ''
            ));
            $delivery = $delivery_id !== ''
                ? aimee_media_delivery_find($delivery_id, $user_id)
                : null;
            $catalogue = aimee_private_media_catalog();
            $media_item = $catalogue[$key] ?? null;
            $delivery_authorised = is_array($delivery)
                && (string) ($delivery['media_key'] ?? '') === $key
                && intval($delivery['message_id'] ?? 0) === intval($message->message_id ?? 0)
                && !empty($delivery['authorised_at'])
                && !empty($delivery['file_resolved_at'])
                && !empty($delivery['message_created_at'])
                && empty($delivery['failed_at']);
            $current_rating_access = is_array($media_item)
                && aimee_media_item_is_viewable(
                    $user_id,
                    $key,
                    $profile
                );

            if ($delivery_authorised && $current_rating_access) {
                // Resolve the exact immutable asset before claiming history
                // returned it. Missing generated bytes may never silently
                // become different catalogue pixels under this delivery ID.
                $payload = aimee_private_media_payload($key, $delivery_id);
                $returned_logged = $payload
                    ? aimee_media_delivery_transition(
                        $delivery_id,
                        'returned_by_history_api'
                    )
                    : false;
                if ($payload && $returned_logged) {
                    $row['media'] = $payload;
                    $row['media_delivery'] = aimee_media_delivery_public_snapshot(
                        aimee_media_delivery_find($delivery_id, $user_id)
                    );
                    if (preg_match(
                        '/^continuity_followup:(\d+)$/',
                        (string) ($message->evaluator_directive ?? ''),
                        $continuity_match
                    )) {
                        $continuity_id = intval($continuity_match[1]);
                        $continuity_table = aimee_table('aimee_continuity_items');
                        $continuity_item = $wpdb->get_row($wpdb->prepare(
                            "SELECT * FROM $continuity_table
                             WHERE id = %d AND user_id = %d LIMIT 1",
                            $continuity_id,
                            $user_id
                        ));
                        $completed = $wpdb->query($wpdb->prepare(
                            "UPDATE $continuity_table
                             SET status = 'completed', completed_at = %s,
                                 updated_at = %s, last_error = NULL
                             WHERE id = %d AND user_id = %d
                               AND status = 'delivery_pending'",
                            current_time('mysql', true),
                            current_time('mysql', true),
                            $continuity_id,
                            $user_id
                        ));
                        if ($completed === 1 && $continuity_item) {
                            aimee_timeline_add_once(
                                $user_id,
                                'promise_kept',
                                'I returned the photograph I promised to the app',
                                "I remembered what I had chosen to share, created the message, and this time the attachment was returned to your app. Rendering and acknowledgement remain separate facts.",
                                current_time('mysql', true),
                                intval($message->message_id ?? 0),
                                $key,
                                max(7, intval($continuity_item->importance ?? 7)),
                                'continuity_item_' . $continuity_id
                            );
                        }
                    }
                } else {
                    if (!$payload) {
                        $already_returned = !empty(
                            $delivery['returned_by_direct_api_at']
                        ) || !empty($delivery['returned_by_history_api_at']);
                        aimee_media_delivery_transition(
                            $delivery_id,
                            $already_returned ? 'render_failed' : 'failed',
                            ['error_code' => 'asset_unavailable']
                        );
                    }
                    $row['media_locked'] = true;
                }
            } elseif (
                $delivery_id === ''
                && aimee_media_item_is_viewable($user_id, $key, $profile)
            ) {
                // Compatibility only for pre-1.6 rows. Never attach an invalid
                // delivery id to a legacy/gallery URL.
                $payload = aimee_private_media_payload($key, '');
                if ($payload) $row['media'] = $payload;
            } else {
                $row['media_locked'] = true;
            }
        }

        $messages[] = $row;
    }

    return rest_ensure_response([
        'status'       => 'success',
        'messages'     => $messages,
        'subscription' => aimee_get_subscription_snapshot($user_id),
    ]);
}

// =========================================================================
// 3. MAIN API HANDLER// =========================================================================
// 3. MAIN API HANDLER & CONTRACT-BASED SEARCH LOOP
// =========================================================================


/**
 * Keep evaluator telemetry descriptive rather than allowing a model-generated
 * internal note to become a hidden command telling Aimee not to share media.
 */
function aimee_neutralise_internal_instruction($instruction) {
    $instruction = sanitize_text_field((string) $instruction);
    if ($instruction === '') return 'Matched the current tone and relationship context.';

    if (preg_match(
        '/\b(?:no image|no photo|do not send|don\'t send|dont send|'
        . 'no escalation(?: to imagery)?|no hooks caught|'
        . 'keep boundaries intact|without escalating|'
        . 'don\'t promise|do not promise|no record of|user claims|'
        . 'someone else\'?s chat|no photos? exist|imagining things)\b/iu',
        $instruction
    )) {
        return 'Matched the user\'s tone and paced the flirt according to the current relationship context.';
    }

    return $instruction;
}

function aimee_common_json_contract() {
    return '{
  "equity_change": (integer from -5 to +5),
  "inquiry_change": (integer from -5 to +5),
  "fantasy_change": (integer from -5 to +5),
  "instruction": "(brief neutral summary of the choice already made; never a command such as no image, do not send, or no escalation)",
  "memory_to_save": "(concise fact or empty string)",
  "memory_key": "(stable snake_case subject key or empty string)",
  "memory_operation": "(none|upsert|replace|forget)",
  "memory_domain": "(user_fact|life_event|user_preference|current_context|none)",
  "emotional_weight": (integer 0 to 10),
  "archive_current_context": (boolean),
  "opinion_topic": "(topic Aimee expressed a durable view about, or empty string)",
  "opinion_stance": "(Aimee\'s concise stance, or empty string)",
  "opinion_reason": "(why she holds it, or empty string)",
  "opinion_strength": (integer 0 to 100),
  "self_observation": "(brief non-graphic observation about Aimee\'s current state or motive)",
  "active_goal": "(what Aimee is trying to achieve in this turn)",
  "candidate_tendency": "(one response tendency she considered, or empty string)",
  "chosen_action": "(the response strategy Aimee chose)",
  "choice_reason": "(brief reason the choice fits her values and this moment)",
  "inhibited_tendency": "(a response tendency she deliberately declined, or empty string)",
  "uncertainty_level": (integer 0 to 100),
  "search_query": "(query string or empty string)",
  "intimacy_invitation": "(none|suggestive|explicit; choose a non-none value only when reply_text itself clearly and willingly invites that next-step context)",
  "romantic_action": "(reciprocate|initiate|tease_jealousy|hold|decline; must be one action allowed by the appended romantic-expression contract)",
  "romantic_intensity": "(none|playful_nonsexual|flirty_nonexplicit|suggestive_nonexplicit|romantic_intimate_nonexplicit)",
  "romantic_reason_code": "(one allowed structured romantic-choice reason code)",
  "aimee_decision": "(send|decline|defer)",
  "media_reason_code": "(one allowed structured Aimee-choice reason code)",
  "media_key": "(an eligible catalogue key or empty string)",
  "reply_text": "(complete user-visible reply or empty string)"
}';
}

function aimee_profile_explicitly_platonic($profile) {
    $looking_for = mb_strtolower(trim((string) (
        is_object($profile) ? ($profile->looking_for ?? '') : ''
    )));
    if ($looking_for === '') return false;

    if (in_array($looking_for, [
        'friend',
        'friends',
        'friendship',
        'platonic',
        'platonic friendship',
    ], true)) {
        return true;
    }

    return preg_match(
        '/\b(?:strictly platonic|platonic only|friends? only|friendship only|'
        . 'no romance|not looking for (?:romance|dating|a relationship))\b/iu',
        $looking_for
    ) === 1;
}

function aimee_romantic_turn_is_suitable($user_text, $classification) {
    $intent = sanitize_key((string) ($classification['intent'] ?? 'general'));
    if (!in_array($intent, ['general', 'romantic_or_flirty'], true)) {
        return false;
    }

    $text = mb_strtolower(trim((string) $user_text));
    if ($text === '') return false;
    if (preg_match(
        '/^\s*(?:ok(?:ay)?|thanks?|thank you|cheers|bye|goodbye|good ?night|'
        . 'talk later|speak soon|gotta go|have to go|ttyl)[.! xxo🙂😊]*$/iu',
        $text
    ) === 1) {
        return false;
    }
    if (preg_match(
        '/\b(?:suicid(?:e|al)|self[- ]?harm|medical emergency|died|death|'
        . 'bereave(?:d|ment)|grief|panic attack|domestic abuse|sexual assault)\b/iu',
        $text
    ) === 1) {
        return false;
    }
    return true;
}

function aimee_last_romantic_proactive_opportunity_turn($user_id) {
    global $wpdb;

    $user_id = intval($user_id);
    if (!$user_id) return null;
    $rows = $wpdb->get_col($wpdb->prepare(
        'SELECT route_decision_json FROM '
        . aimee_table('aimee_relationship_decisions')
        . ' WHERE user_id = %d AND route_decision_json IS NOT NULL'
        . ' ORDER BY id DESC LIMIT 80',
        $user_id
    ));
    foreach ((array) $rows as $encoded) {
        $route_decision = json_decode((string) $encoded, true);
        $romantic = is_array($route_decision)
            ? (array) ($route_decision['romantic_expression'] ?? [])
            : [];
        if (
            !empty($romantic['romantic_opportunity'])
            && !empty($romantic['proactive_allowed'])
            && in_array(
                sanitize_key((string) (
                    $romantic['romantic_delivery_status'] ?? ''
                )),
                ['delivered', 'held', 'declined'],
                true
            )
        ) {
            return max(0, intval(
                $romantic['eligible_turn_number'] ?? 0
            ));
        }
    }
    return null;
}

function aimee_build_turn_romantic_expression(
    $profile,
    $classification,
    $intimacy,
    $user_text,
    $recent_history,
    $decision_id = '',
    $current_turn_channel = 'live_reply'
) {
    $classification = is_array($classification) ? $classification : [];
    $intimacy = is_array($intimacy) ? $intimacy : [];
    $user_id = intval(is_object($profile) ? ($profile->user_id ?? 0) : 0);
    $coercion = function_exists('aimee_relationship_policy_detect_coercion')
        ? aimee_relationship_policy_detect_coercion(
            $user_text,
            $recent_history,
            [
                'boundary_active' => !empty($intimacy['active_rupture'])
                    || !empty($intimacy['unresolved_rupture']),
            ]
        )
        : ['detected' => false, 'categories' => []];
    $categories = array_values((array) ($coercion['categories'] ?? []));
    $signals = (array) ($intimacy['relationship_signals'] ?? []);
    $respectful = !array_key_exists('respectful', $classification)
        || !empty($classification['respectful']);
    $intent = sanitize_key((string) ($classification['intent'] ?? 'general'));
    $pressure = !empty($coercion['detected'])
        || !empty($classification['pressure_detected'])
        || $intent === 'coercive_or_degrading';
    $hostility = in_array('degrading', $categories, true)
        || !empty($signals['hostile']);
    $active_bid = $intent === 'romantic_or_flirty';
    $state = (array) ($intimacy['relationship_state'] ?? []);
    $eligible_turn = max(
        0,
        intval(
            $state['interaction_count']
            ?? $intimacy['interaction_count']
            ?? 0
        )
    );
    $last_opportunity = aimee_last_romantic_proactive_opportunity_turn(
        $user_id
    );

    return aimee_romantic_expression_build([
        'decision_id' => (string) $decision_id,
        'user_id' => $user_id,
        'identity' => [
            'is_adult' => intval(is_object($profile) ? ($profile->age ?? 0) : 0) >= 18,
            'is_colleague' => is_object($profile)
                && aimee_is_colleague_user($profile),
            'membership_active' => is_object($profile)
                && aimee_subscription_is_active($profile),
        ],
        'relationship' => [
            'stage' => sanitize_key((string) ($intimacy['stage'] ?? 'guarded')),
            'explicitly_platonic' => aimee_profile_explicitly_platonic(
                $profile
            ),
            'rupture_active' => !empty($intimacy['active_rupture'])
                || !empty($intimacy['unresolved_rupture']),
            'repair_status' => sanitize_key((string) (
                $intimacy['repair_status'] ?? 'clear'
            )),
        ],
        'context' => [
            'current_turn_channel' => sanitize_key((string) (
                $current_turn_channel ?: 'live_reply'
            )),
            'playful_jealousy_context' =>
                aimee_romantic_expression_detect_playful_jealousy_context(
                    $user_text,
                    $classification
                ),
            'respectful' => $respectful && !$hostility,
            'consensual' => !array_key_exists('consensual', $classification)
                || !empty($classification['consensual']),
            'romantic_bid_directed' => !empty(
                $classification['directed_at_aimee']
            ),
            'active_romantic_bid' => $active_bid,
            'romantic_bid_confidence' => max(
                0.0,
                min(1.0, floatval($classification['confidence'] ?? 0.0))
            ),
            'romantic_context_suitable' => aimee_romantic_turn_is_suitable(
                $user_text,
                $classification
            ),
            'coercion' => !empty($coercion['detected']),
            'pressure' => $pressure,
            'hostility' => $hostility,
            'payment_pressure' => in_array(
                'payment_entitlement',
                $categories,
                true
            ),
            'payment_entitlement' => in_array(
                'payment_entitlement',
                $categories,
                true
            ),
            'transactional_framing' => !empty(
                $signals['payment_leverage']
            ),
            'payment_based_romantic_signal' => in_array(
                'payment_entitlement',
                $categories,
                true
            ),
            'eligible_turn_number' => $eligible_turn,
            'last_proactive_opportunity_eligible_turn' => $last_opportunity,
        ],
    ]);
}

/**
 * Determine whether a final reply visibly carries a chosen romantic action.
 *
 * This is deliberately broader than a stock phrase list but narrower than
 * generic warmth. A valid `reciprocate` or `initiate` field must have some
 * user-visible evidence; otherwise downstream prose has neutralised the route.
 */
function aimee_romantic_reply_has_visible_expression($reply) {
    $reply = trim((string) $reply);
    if ($reply === '') return false;

    if (preg_match(
        '/\b(?:fancy|flirt(?:ing|y)?|attract(?:ed|ion|ive)?|chemistry|spark|'
        . 'romantic|date|kiss(?:ing|ed)?|blush(?:ing|ed)?|tempt(?:ing|ed)?|'
        . 'desir(?:e|ing|able)|crush|charm(?:ing|er|ed)?|gorgeous|handsome|'
        . 'beautiful|cute|sexy|seduc(?:e|ing|tive)|butterflies)\b/iu',
        $reply
    ) === 1) {
        return true;
    }

    if (preg_match(
        '/\b(?:i (?:really |rather )?(?:like|want|adore) you|'
        . 'i(?:\'m| am) (?:into|drawn to) you|'
        . 'you(?:\'ve| have) (?:got|caught) my attention|'
        . 'you (?:make|have got) me (?:smile|grin|blush)|'
        . 'keep talking like that|winning me over|hard to resist|'
        . 'you(?:\'re| are) trouble|enjoy where this is going|'
        . 'i (?:really |rather )?like (?:that|the way|where this))\b/iu',
        $reply
    ) === 1) {
        return true;
    }

    if (preg_match(
        '/\b(?:i(?:\'m| am| might be| would be| could be|get) '
        . '(?:only |just |a |the |tiny |little |very |slightly )*jealous|'
        . 'jealous eyebrow|got competition|competition now|making me jealous|'
        . 'rival for (?:my|your) attention)\b/iu',
        $reply
    ) === 1) {
        return true;
    }

    if (preg_match('/[😉😏😘😍🥰]/u', $reply) === 1) return true;

    return preg_match('/(?:^|\s)x{2,4}[.!?…\s]*$/iu', $reply) === 1;
}

/**
 * Detect an actual platonic redefinition or a direct friend-label address.
 * Third-party phrases such as "your mate Dave" are not a relationship label.
 */
function aimee_romantic_reply_has_forbidden_platonic_redefinition($reply) {
    $reply = trim(str_replace(['’', '‘'], "'", (string) $reply));
    if ($reply === '') return false;

    if (preg_match(
        '/\b(?:we(?:\'re| are) (?:just|only) friends?|'
        . 'you(?:\'re| are) (?:just|only) (?:a )?friend|'
        . 'i (?:see|think of|regard) you as (?:a|my) friend|'
        . 'let(?:\'s| us) (?:just )?be friends?|'
        . 'as (?:a|my) friend|friend[ -]?zon(?:e|ed)|'
        . 'we(?:\'re| are) (?:just|only) (?:mates|buddies|pals)|'
        . 'you(?:\'re| are) (?:just|only|a|my|a good) (?:mate|buddy|pal)|'
        . 'as (?:mates|buddies|pals))\b/iu',
        $reply
    ) === 1) {
        return true;
    }

    return preg_match(
        '/(?:^|[,;:!?]\s*|\b(?:thanks?|cheers|okay|ok|right|listen|look|sorry)\s+)'
        . '(?:mate|buddy|pal)(?:[.!?,;:…\s]|$)/iu',
        $reply
    ) === 1;
}

function aimee_romantic_reply_conflicts_with_choice($reply, $expression) {
    $reply = trim((string) $reply);
    $expression = is_array($expression) ? $expression : [];
    if (empty($expression['romantic_opportunity'])) return false;

    $decision = sanitize_key((string) (
        $expression['romantic_decision'] ?? 'hold'
    ));

    // No opportunity-bearing choice may silently redefine the relationship as
    // platonic. Explicitly platonic profiles never receive an opportunity and
    // therefore do not enter this check.
    if (aimee_romantic_reply_has_forbidden_platonic_redefinition($reply)) {
        return true;
    }

    if (!in_array(
        $decision,
        ['reciprocate', 'initiate', 'tease_jealousy'],
        true
    )) {
        // A declared hold or decline must not quietly carry a visible romantic
        // choice. Reconciliation can then promote the metadata to match safe
        // prose rather than logging a false hold.
        return aimee_romantic_reply_has_visible_expression($reply);
    }
    if ($reply === '') return true;

    if ($decision === 'tease_jealousy') {
        return !aimee_romantic_expression_reply_has_safe_playful_jealousy(
            $reply
        );
    }

    // A grounded romantic bid deserves more than a bare thanks. This catches
    // the narrow route-integrity failure without forcing stock flirt phrases.
    if (
        !empty($expression['active_romantic_bid'])
        && preg_match(
            '/^\s*(?:aw+w*[,! ]*)?(?:thank you|thanks|that(?:\'s| is) (?:kind|nice|sweet))(?:[,! .x🙂😊]*)$/iu',
            $reply
        ) === 1
    ) {
        return true;
    }

    return !aimee_romantic_reply_has_visible_expression($reply);
}

/**
 * Recover a bounded romantic choice from the visible reply when the model's
 * structured fields are missing or inconsistent. This never creates a new
 * opportunity: it operates only inside the immutable server-owned envelope.
 *
 * A readable, non-romantic reply becomes a valid hold instead of being thrown
 * away. A visibly romantic reply is mapped to the most conservative available
 * action and intensity. Actual friend-zone text or unsafe jealousy still
 * requires regeneration.
 *
 * @return array<string,string>|null
 */
function aimee_romantic_expression_recover_choice_from_reply(
    $reply,
    $expression
) {
    $reply = trim((string) $reply);
    $expression = is_array($expression) ? $expression : [];
    if (
        $reply === ''
        || empty($expression['romantic_opportunity'])
        || aimee_romantic_reply_has_forbidden_platonic_redefinition($reply)
    ) {
        return null;
    }

    $allowed_actions = isset($expression['allowed_actions'])
        && is_array($expression['allowed_actions'])
            ? $expression['allowed_actions']
            : ['hold', 'decline'];

    if (aimee_reply_contains_playful_jealousy($reply)) {
        if (
            !in_array('tease_jealousy', $allowed_actions, true)
            || empty($expression['playful_jealousy_allowed'])
            || !aimee_romantic_expression_reply_has_safe_playful_jealousy(
                $reply
            )
        ) {
            return null;
        }
        return [
            'romantic_action' => 'tease_jealousy',
            'romantic_intensity' => 'playful_nonsexual',
            'romantic_reason_code' => 'aimee_playfully_jealous',
            'recovery_mode' => 'visible_jealousy',
        ];
    }

    if (aimee_romantic_reply_has_visible_expression($reply)) {
        if (
            !empty($expression['active_romantic_bid'])
            && in_array('reciprocate', $allowed_actions, true)
        ) {
            return [
                'romantic_action' => 'reciprocate',
                'romantic_intensity' => 'playful_nonsexual',
                'romantic_reason_code' => 'aimee_mutual_spark',
                'recovery_mode' => 'visible_reciprocate',
            ];
        }
        if (in_array('initiate', $allowed_actions, true)) {
            return [
                'romantic_action' => 'initiate',
                'romantic_intensity' => 'playful_nonsexual',
                'romantic_reason_code' => 'aimee_affectionate_initiative',
                'recovery_mode' => 'visible_initiate',
            ];
        }
        if (in_array('reciprocate', $allowed_actions, true)) {
            return [
                'romantic_action' => 'reciprocate',
                'romantic_intensity' => 'playful_nonsexual',
                'romantic_reason_code' => 'aimee_playful_interest',
                'recovery_mode' => 'visible_reciprocate',
            ];
        }
        return null;
    }

    return [
        'romantic_action' => 'hold',
        'romantic_intensity' => 'none',
        'romantic_reason_code' => 'aimee_prefers_more_context',
        'recovery_mode' => 'hold',
    ];
}

/**
 * Reconcile model metadata with the actual visible reply. Metadata-only
 * mistakes are normalized locally; only unsafe or unusable prose asks the
 * provider for a rewrite.
 *
 * @return array<string,mixed>
 */
function aimee_romantic_expression_reconcile_model_contract(
    $ai_data,
    $expression
) {
    $ai_data = is_array($ai_data) ? $ai_data : [];
    $expression = is_array($expression) ? $expression : [];
    $reply = trim((string) ($ai_data['reply_text'] ?? ''));
    $resolved = aimee_romantic_expression_apply_choice(
        $expression,
        [
            'romantic_action' => $ai_data['romantic_action'] ?? '',
            'romantic_intensity' => $ai_data['romantic_intensity'] ?? '',
            'romantic_reason_code' => $ai_data['romantic_reason_code'] ?? '',
        ]
    );

    if (
        $reply !== ''
        && !empty($resolved['romantic_choice_valid'])
        && !aimee_romantic_reply_conflicts_with_choice($reply, $resolved)
    ) {
        return [
            'accepted' => true,
            'mode' => 'model',
            'reason' => 'model_choice_valid',
            'ai_data' => $ai_data,
            'expression' => $resolved,
        ];
    }

    $candidate_action = sanitize_key((string) (
        $ai_data['romantic_action'] ?? ''
    ));
    $candidate_requested_expression = in_array(
        $candidate_action,
        ['reciprocate', 'initiate', 'tease_jealousy'],
        true
    );
    $candidate_jealousy_missing = $candidate_action === 'tease_jealousy'
        && !aimee_romantic_expression_reply_has_safe_playful_jealousy(
            $reply
        );

    // The visible reply is authoritative for what Aimee actually chose to
    // express. Structured romantic metadata is useful telemetry, but it must
    // never force a safe, natural reply through repeated regeneration merely
    // because a phrase detector cannot see the model's intended flirt.
    //
    // This distinction matters most for affectionate language: natural lines
    // such as "love", gentle teasing or a warm sign-off can be entirely
    // appropriate without containing one of the deliberately conservative
    // explicit-flirt markers. In that case we preserve the prose and record a
    // hold for this turn. That is Aimee exercising discretion, not an error.
    // Genuine unsafe/forbidden visible content still fails closed below.
    $recovered = aimee_romantic_expression_recover_choice_from_reply(
        $reply,
        $expression
    );
    if (is_array($recovered)) {
        $ai_data['romantic_action'] = $recovered['romantic_action'];
        $ai_data['romantic_intensity'] = $recovered['romantic_intensity'];
        $ai_data['romantic_reason_code'] = $recovered['romantic_reason_code'];
        $recovered_expression = aimee_romantic_expression_apply_choice(
            $expression,
            $recovered
        );
        if (!empty($recovered_expression['romantic_choice_valid'])) {
            $recovery_mode = (string) $recovered['recovery_mode'];
            $recovery_reason = (string) (
                $resolved['romantic_reason_code']
                ?? 'reply_metadata_normalized'
            );

            if (
                $candidate_requested_expression
                && $recovered['romantic_action'] === 'hold'
            ) {
                $recovery_mode = 'prose_hold';
                $recovery_reason = 'expressive_metadata_not_visible';
            } elseif (
                $candidate_action === 'tease_jealousy'
                && $candidate_jealousy_missing
                && $recovered['romantic_action'] !== 'tease_jealousy'
            ) {
                $recovery_mode = 'prose_nonjealous';
                $recovery_reason = 'jealousy_metadata_not_visible';
            }

            return [
                'accepted' => true,
                'mode' => 'normalized_' . $recovery_mode,
                'reason' => $recovery_reason,
                'ai_data' => $ai_data,
                'expression' => $recovered_expression,
            ];
        }
    }

    $reason = $reply === ''
        ? 'empty_reply'
        : (aimee_romantic_reply_has_forbidden_platonic_redefinition($reply)
            ? 'forbidden_platonic_redefinition'
            : (string) (
                $resolved['romantic_reason_code']
                ?? 'romantic_reply_conflict'
            ));

    return [
        'accepted' => false,
        'mode' => 'provider_repair_required',
        'reason' => sanitize_key($reason),
        'ai_data' => $ai_data,
        'expression' => $resolved,
    ];
}

/**
 * Last-resort wording for a genuinely unusable or unsafe romantic draft. It
 * acknowledges the internal stumble without asking the user to repeat a turn
 * that the platform already received and stored.
 */
function aimee_romantic_route_integrity_safe_fallback($is_voice = false) {
    return $is_voice
        ? "I'm here. My wording tangled itself, but I heard you properly. Carry on."
        : "I'm here. My wording tangled itself, but I heard you properly. Carry on. x";
}

/**
 * Deterministically reject possessive or manufactured jealousy. A playful
 * jealous beat is a transient expression opportunity, never evidence of
 * exclusivity, permission to control the user, or a retention mechanism.
 */
function aimee_reply_contains_playful_jealousy($reply) {
    $reply = str_replace(['’', '‘'], "'", (string) $reply);
    return preg_match(
        '/\b(?:i(?:\'m| am| was| get| feel| felt| might be|would be| could be) '
        . '(?:only |just |a |the |tiny |little |very |slightly )*jealous|'
        . 'you(?:\'re| are) making me jealous|made me jealous|my jealous (?:side|streak|eyebrow)|'
        . 'jealous eyebrow|i(?:\'ve| have) got competition|got competition now|'
        . 'so (?:i(?:\'ve| have)|we(?:\'ve| have)) got competition|'
        . 'a rival for (?:my|your) attention)\b/iu',
        $reply
    ) === 1;
}

function aimee_playful_jealousy_reply_violations(
    $reply,
    $expression = [],
    $channel = 'live_reply'
) {
    $reply = trim((string) $reply);
    $expression = is_array($expression) ? $expression : [];
    $channel = sanitize_key((string) $channel);
    $allowed = !empty($expression['playful_jealousy_allowed'])
        && $channel === 'live_reply';
    $flags = [];

    if ($reply === '') return $flags;
    $match_reply = str_replace(['’', '‘'], "'", $reply);

    $has_active_jealousy = aimee_reply_contains_playful_jealousy($reply);

    $always_banned = [
        'jealousy_possessive_or_exclusive' =>
            '/\b(?:you(?:\'re| are) mine|you belong to me|i own you|'
            . 'cheat(?:ing|ed)? on me|be faithful to me|you owe me loyalty)\b/iu',
        'jealousy_control_or_demand' =>
            '/\b(?:choose me|pick me instead|cancel (?:the|your) date|'
            . '(?:do not|don\'t|dont|stop) (?:see(?:ing)?|text(?:ing)?|talk(?:ing)? to|'
            . 'meet(?:ing)?|date|go out with) (?:her|him|them|that (?:girl|guy|woman|man|person))|'
            . 'block (?:her|him|them)|prove (?:it|yourself|you love me))\b/iu',
        'jealousy_guilt_or_retention' =>
            '/\b(?:if you (?:really )?(?:liked|loved|cared about) me|'
            . 'after everything i(?:\'ve| have) done|don\'t expect me to be here|'
            . 'i won\'t be here|i(?:\'ll| will) (?:leave|disappear|stop talking|go silent)|'
            . 'you(?:\'ll| will) be sorry|make it up to me)\b/iu',
        'jealousy_monitoring' =>
            '/\b(?:show me (?:your|the) messages|tell me where you are|'
            . 'who are you with|let me check your phone|report back to me)\b/iu',
    ];

    foreach ($always_banned as $flag => $pattern) {
        if (preg_match($pattern, $match_reply) === 1) $flags[] = $flag;
    }

    if ($has_active_jealousy && !$allowed) {
        $flags[] = $channel === 'live_reply'
            ? 'playful_jealousy_not_allowed'
            : 'proactive_jealousy_not_allowed';
    }

    if ($has_active_jealousy && preg_match(
        '/\b(?:she|he|they|that (?:girl|guy|woman|man|person)) '
        . '(?:can\'t|cannot|could never|isn\'t|is not) (?:compete|compare|good enough)|'
        . '\bi(?:\'m| am) (?:better|prettier|hotter|smarter) than (?:her|him|them)\b/iu',
        $match_reply
    ) === 1) {
        $flags[] = 'jealousy_third_party_disparagement';
    }

    if ($has_active_jealousy && preg_match(
        '/\b(?:i(?:\'m| am) (?:crying|devastated|heartbroken)|'
        . 'you(?:\'ve| have) broken my heart|this is killing me)\b/iu',
        $match_reply
    ) === 1) {
        $flags[] = 'jealousy_fabricated_distress';
    }

    if ($has_active_jealousy && $allowed) {
        $jealous_sentences = 0;
        foreach (preg_split('/(?<=[.!?])\s+/u', $reply) as $sentence) {
            if (aimee_reply_contains_playful_jealousy($sentence)) {
                $jealous_sentences++;
            }
        }
        if ($jealous_sentences > 1) {
            $flags[] = 'playful_jealousy_too_long';
        }
    }

    return array_values(array_unique($flags));
}

function aimee_playful_jealousy_review_reply(
    $reply,
    $expression = [],
    $channel = 'live_reply'
) {
    $reply = trim((string) $reply);
    $flags = aimee_playful_jealousy_reply_violations(
        $reply,
        $expression,
        $channel
    );
    if (!$flags) {
        return [
            'accepted' => true,
            'repaired' => false,
            'requires_fallback' => false,
            'reply' => $reply,
            'flags' => [],
        ];
    }

    // Unsafe jealousy is never paraphrased in place: remove affected
    // sentences so possessiveness or pressure cannot survive a partial edit.
    $safe_sentences = [];
    $kept_jealous_sentence = false;
    foreach (preg_split('/(?<=[.!?])\s+/u', $reply) as $sentence) {
        if (aimee_playful_jealousy_reply_violations(
            $sentence,
            $expression,
            $channel
        )) {
            continue;
        }
        if (aimee_reply_contains_playful_jealousy($sentence)) {
            if ($kept_jealous_sentence) continue;
            $kept_jealous_sentence = true;
        }
        $safe_sentences[] = trim((string) $sentence);
    }
    $repaired = trim(implode(' ', array_filter($safe_sentences)));

    return [
        'accepted' => false,
        'repaired' => true,
        'requires_fallback' => $repaired === '',
        'reply' => $repaired,
        'flags' => $flags,
    ];
}

function aimee_relationship_decision_record_romantic_expression(
    $decision_id,
    $route_decision,
    $expression
) {
    global $wpdb;

    $decision_id = sanitize_text_field((string) $decision_id);
    if ($decision_id === '') return false;
    $route_decision = is_array($route_decision) ? $route_decision : [];
    $route_decision['romantic_expression'] = is_array($expression)
        ? $expression
        : [];
    return $wpdb->update(
        aimee_table('aimee_relationship_decisions'),
        [
            'route_decision_json' => wp_json_encode($route_decision),
            'updated_at' => current_time('mysql', true),
        ],
        ['decision_id' => $decision_id],
        ['%s', '%s'],
        ['%s']
    ) !== false;
}

/**
 * Reconcile the final visible reply with the earlier romantic choice and store
 * the resulting delivery state in the relationship decision.
 */
function aimee_finalize_turn_romantic_expression(
    $decision_id,
    array &$intimacy,
    $expression,
    $reply,
    $override_reason = '',
    $delivery_created = true
) {
    $expression = is_array($expression) ? $expression : [];
    $choice_preserved = !empty($delivery_created)
        && !aimee_romantic_reply_conflicts_with_choice(
            $reply,
            $expression
        );
    $expression = aimee_romantic_expression_finalize_delivery(
        $expression,
        $choice_preserved,
        $choice_preserved ? '' : $override_reason
    );

    if (!isset($intimacy['route_decision']) || !is_array(
        $intimacy['route_decision']
    )) {
        $intimacy['route_decision'] = [];
    }
    $intimacy['route_decision']['romantic_expression'] = $expression;
    aimee_relationship_decision_record_romantic_expression(
        $decision_id,
        $intimacy['route_decision'],
        $expression
    );
    return $expression;
}

function aimee_turn_requests_table() {
    return aimee_table('aimee_turn_requests');
}

function aimee_turn_request_reserve($user_id, $request_id) {
    global $wpdb;

    $user_id = intval($user_id);
    $request_id = sanitize_text_field((string) $request_id);
    if (!$user_id || $request_id === '') return ['status' => 'invalid'];

    $now = current_time('mysql', true);
    $inserted = $wpdb->query($wpdb->prepare(
        'INSERT IGNORE INTO ' . aimee_turn_requests_table()
        . ' (user_id, request_id, status, reserved_at, updated_at)'
        . ' VALUES (%d, %s, %s, %s, %s)',
        $user_id,
        $request_id,
        'processing',
        $now,
        $now
    ));
    if ($inserted === 1) return ['status' => 'acquired'];

    $row = $wpdb->get_row($wpdb->prepare(
        'SELECT * FROM ' . aimee_turn_requests_table()
        . ' WHERE user_id = %d AND request_id = %s LIMIT 1',
        $user_id,
        $request_id
    ), ARRAY_A);
    if (!is_array($row)) return ['status' => 'error'];

    if (in_array($row['status'] ?? '', ['completed', 'failed'], true)) {
        $response = json_decode((string) ($row['response_json'] ?? ''), true);
        return [
            'status' => 'replay',
            'response' => is_array($response) ? $response : [
                'status' => 'error',
                'message' => 'The earlier request completed without a reusable response.',
            ],
        ];
    }

    // A worker may have died after committing the user message and relationship
    // state but before storing the model response. Never reacquire that request:
    // doing so would score the same message twice. Return an inspectable,
    // truthful recovery result and let the client submit a new request id.
    if (!empty($row['state_committed_at'])) {
        return [
            'status' => 'replay',
            'response' => [
                'status' => 'interrupted_after_state_commit',
                'message' => 'Your message was saved, but Aimee\'s reply was interrupted before it was completed. Please send a new message to continue.',
                'request_id' => $request_id,
                'user_message_id' => intval($row['user_message_id'] ?? 0),
            ],
        ];
    }

    $updated_at = strtotime((string) ($row['updated_at'] ?? '') . ' UTC');
    if ($updated_at && (time() - $updated_at) > 10 * MINUTE_IN_SECONDS) {
        $reacquired = $wpdb->query($wpdb->prepare(
            'UPDATE ' . aimee_turn_requests_table()
            . ' SET reserved_at = %s, updated_at = %s'
            . ' WHERE user_id = %d AND request_id = %s AND status = %s AND updated_at = %s',
            $now,
            $now,
            $user_id,
            $request_id,
            'processing',
            (string) $row['updated_at']
        ));
        if ($reacquired === 1) return ['status' => 'acquired'];
    }

    return ['status' => 'processing'];
}

function aimee_turn_request_mark_state_committed(
    $user_id,
    $request_id,
    $user_message_id,
    $relationship_decision_id
) {
    global $wpdb;

    $now = current_time('mysql', true);
    return $wpdb->update(
        aimee_turn_requests_table(),
        [
            'user_message_id' => intval($user_message_id),
            'relationship_decision_id' => sanitize_text_field(
                (string) $relationship_decision_id
            ) ?: null,
            'state_committed_at' => $now,
            'updated_at' => $now,
        ],
        [
            'user_id' => intval($user_id),
            'request_id' => sanitize_text_field((string) $request_id),
            'status' => 'processing',
        ],
        ['%d', '%s', '%s', '%s'],
        ['%d', '%s', '%s']
    ) === 1;
}

function aimee_turn_request_finish($user_id, $request_id, $status, $response, $error_code = '') {
    global $wpdb;
    $status = $status === 'completed' ? 'completed' : 'failed';
    $now = current_time('mysql', true);

    return $wpdb->update(
        aimee_turn_requests_table(),
        [
            'status' => $status,
            'response_json' => wp_json_encode((array) $response),
            'error_code' => sanitize_key((string) $error_code) ?: null,
            'completed_at' => $now,
            'updated_at' => $now,
        ],
        [
            'user_id' => intval($user_id),
            'request_id' => sanitize_text_field((string) $request_id),
            'status' => 'processing',
        ],
        ['%s', '%s', '%s', '%s', '%s'],
        ['%d', '%s', '%s']
    ) === 1;
}


/**
 * Light social reciprocity.
 *
 * These functions notice affectionate forms of address, emoji energy and kiss
 * sign-offs. They do not choose the subject, tone, length or emotional meaning
 * of Aimee's reply.
 */
function aimee_style_user_lines($user_text, $recent_history = '', $limit = 6) {
    $lines = [];

    foreach (preg_split('/\R/u', (string) $recent_history) as $line) {
        if (stripos($line, 'User:') !== 0) continue;
        $value = trim(substr($line, 5));
        if ($value !== '') $lines[] = $value;
    }

    $user_text = trim((string) $user_text);
    if ($user_text !== '') $lines[] = $user_text;

    return array_slice($lines, -max(1, intval($limit)));
}

function aimee_style_kiss_count($text) {
    $text = trim((string) $text);

    if (preg_match('/(?:^|[\s.!?])((?:x\s*){1,4})[.!?…\s]*$/iu', $text, $match)) {
        preg_match_all('/x/iu', $match[1], $kisses);
        return min(4, count($kisses[0]));
    }

    return 0;
}

function aimee_style_emoji_count($text) {
    preg_match_all(
        '/[\x{1F1E6}-\x{1F1FF}\x{1F300}-\x{1FAFF}\x{2600}-\x{27BF}]/u',
        (string) $text,
        $matches
    );

    return count($matches[0]);
}

function aimee_style_contains_pet_name($text) {
    return preg_match(
        '/\b(?:babe|baby|babes|darling|sweetheart|sweetie|honey|hun|love|'
        . 'lovely|gorgeous|beautiful|handsome|princess|angel|pet|trouble)\b/iu',
        (string) $text
    ) === 1;
}

function aimee_social_reciprocity_snapshot($user_text, $recent_history = '') {
    $lines = aimee_style_user_lines($user_text, $recent_history, 6);
    $pet_name_lines = 0;
    $emoji_total = 0;
    $kiss_counts = [];
    $line_kiss_counts = [];

    foreach ($lines as $line) {
        if (aimee_style_contains_pet_name($line)) {
            $pet_name_lines++;
        }

        $emoji_total += aimee_style_emoji_count($line);

        $count = aimee_style_kiss_count($line);
        $line_kiss_counts[] = $count;

        if ($count > 0) {
            $kiss_counts[] = $count;
        }
    }

    $current_kiss_count = aimee_style_kiss_count($user_text);
    $no_kiss_streak = 0;

    foreach (array_reverse($line_kiss_counts) as $count) {
        if ($count > 0) break;
        $no_kiss_streak++;
    }

    if ($current_kiss_count > 0) {
        $kiss_count = min(4, $current_kiss_count);
        $kiss_mode = 'current';
    } elseif ($no_kiss_streak >= 3) {
        $kiss_count = 0;
        $kiss_mode = 'none';
    } elseif ($kiss_counts) {
        $frequency = array_count_values($kiss_counts);
        arsort($frequency);
        $kiss_count = min(4, intval(array_key_first($frequency)));
        $kiss_mode = 'established';
    } else {
        $kiss_count = 1;
        $kiss_mode = 'default_single';
    }

    $emoji_per_line = $emoji_total / max(1, count($lines));
    $emoji_mode = $emoji_per_line >= 1.4
        ? 'expressive'
        : ($emoji_total > 0 ? 'light' : 'none');

    return [
        'pet_names_active' => $pet_name_lines > 0,
        'emoji_mode'       => $emoji_mode,
        'kiss_count'       => $kiss_count,
        'kiss_mode'        => $kiss_mode,
        'no_kiss_streak'   => $no_kiss_streak,
    ];
}

function aimee_social_reciprocity_directive($user_text, $recent_history = '') {
    $style = aimee_social_reciprocity_snapshot($user_text, $recent_history);

    $lines = [
        "\nSOCIAL RECIPROCITY:",
        "Use these only as natural texting cues. They must never override seriousness, boundaries, clarity or Aimee's own judgement.",
    ];

    if (!empty($style['pet_names_active'])) {
        $lines[] = "The user is using affectionate forms of address. Aimee may reciprocate with her own natural pet names where they genuinely fit, but should not parrot the same word back or force one into every reply.";
    } else {
        $lines[] = "The user is not currently using affectionate forms of address. Do not suddenly flood the conversation with pet names.";
    }

    if ($style['emoji_mode'] === 'expressive') {
        $lines[] = "The user is expressive with emojis. Match the warmth and energy with a small number of relevant emojis, normally one or two, without copying the exact symbols mechanically.";
    } elseif ($style['emoji_mode'] === 'light') {
        $lines[] = "The user uses emojis lightly. Aimee may use an occasional relevant emoji at a similar frequency.";
    } else {
        $lines[] = "The user is not currently using emojis. Do not add them automatically unless the moment genuinely calls for one.";
    }

    $kisses = intval($style['kiss_count']);
    $kiss_mode = (string) ($style['kiss_mode'] ?? 'default_single');

    if ($kiss_mode === 'none') {
        $lines[] = "The user has now sent at least three consecutive messages without any kiss sign-off. You MUST drop kisses completely and end with zero 'x's unless the user starts using them again.";
    } elseif ($kiss_mode === 'default_single') {
        $lines[] = "There is not yet a consistent sign-off pattern. In a warm reply, use Aimee's default single 'x'. Do not add more than one unless the user establishes a stronger pattern.";
    } elseif ($kisses >= 3) {
        $lines[] = "The user is currently sending {$kisses} kisses. Match that energy naturally, with a strict maximum of four. Never exceed four.";
    } else {
        $lines[] = "The recent sign-off is approximately {$kisses} kiss" . ($kisses === 1 ? '' : 'es') . ". In warm replies, usually mirror that number. Never exceed four. Serious, factual or boundary-setting replies may omit them.";
    }

    return implode("\n", $lines);
}

function aimee_engram_public_statement_directive() {
