/**
 * Distinguish Georgia's written content planning from an instruction to attach
 * or deliver a real photograph. This is deliberately a professional workflow
 * classifier, not a relaxation of the private-media policy.
 */
function aimee_colleague_written_creative_brief($text, $recent_history = '') {
    $text = mb_strtolower(trim((string) $text));
    $history = mb_strtolower(trim((string) $recent_history));
    $text = str_replace(['’', '‘'], "'", $text);
    $history = str_replace(['’', '‘'], "'", $history);

    $creative_output_pattern = '/\b(?:ideas?|concepts?|brainstorm(?:s|ing)?|briefs?|shot\s*lists?|shoot\s*plans?|moodboards?|descriptions?|captions?|prompts?|content\s*plans?|campaign\s*plans?)\b/iu';
    $creative_subject_pattern = '/\b(?:social\s*media|instagram|tiktok|facebook|reels?|stories?|posts?|content|photos?|photographs?|pictures?|images?|selfies?|shoots?|outfits?|looks?|poses?|activities|campaigns?)\b/iu';
    $creative_action_pattern = '/\b(?:think\s+of|come\s+up\s+with|brainstorm|list|write|draft|describe|suggest|plan|give\s+me|send\s+me|can\s+you|could\s+you|would\s+you)\b/iu';
    $continuation_pattern = '/^\s*(?:more|more\s+please|another\s+(?:set|batch)|keep\s+going|continue|the\s+rest|rest\s+of\s+the\s+list)\b/iu';

    $explicit_creative_request = preg_match($creative_output_pattern, $text) === 1
        && preg_match($creative_subject_pattern, $text) === 1
        && (
            preg_match($creative_action_pattern, $text) === 1
            || preg_match('/\b(?:please|need|want|like)\b/iu', $text) === 1
        );
    $history_is_creative = preg_match($creative_output_pattern, $history) === 1
        && preg_match($creative_subject_pattern, $history) === 1;
    $continuation = preg_match($continuation_pattern, $text) === 1
        && $history_is_creative;
    $active = $explicit_creative_request || $continuation;

    $requested_count = 10;
    if (preg_match('/\b([1-9]|1[0-9]|20)\b/u', $text, $count_match) === 1) {
        $requested_count = intval($count_match[1]);
    } else {
        $number_words = [
            'one' => 1, 'two' => 2, 'three' => 3, 'four' => 4,
            'five' => 5, 'six' => 6, 'seven' => 7, 'eight' => 8,
            'nine' => 9, 'ten' => 10, 'eleven' => 11, 'twelve' => 12,
            'thirteen' => 13, 'fourteen' => 14, 'fifteen' => 15,
            'sixteen' => 16, 'seventeen' => 17, 'eighteen' => 18,
            'nineteen' => 19, 'twenty' => 20,
        ];
        foreach ($number_words as $word => $count) {
            if (preg_match('/\b' . $word . '\b/u', $text) === 1) {
                $requested_count = $count;
                break;
            }
        }
    }

    $deliverable_context = $text . ($continuation ? ' ' . $history : '');
    $deliverable_type = 'ideas';
    if (preg_match('/\bcaptions?\b/iu', $deliverable_context) === 1) {
        $deliverable_type = 'captions';
    } elseif (preg_match('/\bdescriptions?\b/iu', $deliverable_context) === 1) {
        $deliverable_type = 'descriptions';
    } elseif (preg_match('/\bprompts?\b/iu', $deliverable_context) === 1) {
        $deliverable_type = 'prompts';
    }

    return [
        'active' => $active,
        'requested_count' => max(1, min(20, intval($requested_count))),
        'allow_flirty' => preg_match('/\b(?:flirt|flirty|cheeky|playful|teasing)\b/iu', $text) === 1
            || (
                $continuation
                && preg_match('/\b(?:flirt|flirty|cheeky|playful|teasing)\b/iu', $history) === 1
            ),
        'text_only' => true,
        'continuation' => $continuation,
        'deliverable_type' => $deliverable_type,
        'workflow' => 'colleague_written_creative_brief',
    ];
}

function aimee_colleague_creative_brief_directive($brief) {
    $brief = is_array($brief) ? $brief : [];
    if (empty($brief['active'])) return '';

    $count = max(1, min(20, intval($brief['requested_count'] ?? 10)));
    $deliverable_type = sanitize_key((string) (
        $brief['deliverable_type'] ?? 'ideas'
    ));
    if (!in_array(
        $deliverable_type,
        ['ideas', 'captions', 'descriptions', 'prompts'],
        true
    )) {
        $deliverable_type = 'ideas';
    }
    $tone = !empty($brief['allow_flirty'])
        ? 'safe and brand-appropriate flirty ideas are both permitted; keep flirtation cheeky and non-explicit'
        : 'keep the ideas safe unless Georgia explicitly asks for a brand-appropriate flirty edge';

    return "\n\nCOLLEAGUE WRITTEN CREATIVE BRIEF: Georgia is asking for written planning, not asking you to attach or deliver an image. "
        . "Complete the professional task now with exactly {$count} clearly numbered, distinct {$deliverable_type} and enough detail to be useful. {$tone}. "
        . "Do not substitute a relationship-stage, membership, pressure, consent or photo-delivery refusal. Do not promise or claim an attachment. "
        . "Keep media_key empty. Her content brief is normal work between Aimee and her trusted talent manager.";
}

function aimee_colleague_reply_needs_creative_repair($reply, $brief) {
    $brief = is_array($brief) ? $brief : [];
    if (empty($brief['active'])) return false;

    $reply = trim((string) $reply);
    if ($reply === '') return true;
    if (preg_match(
        '/^\s*no[.!\s]|\b(?:membership|subscription|pressure|countdowns?|threatening\s+to\s+leave|does\s+not\s+buy\s+control|won\'t\s+send|will\s+not\s+send|can\'t\s+help\s+with|cannot\s+help\s+with|system\s+error|provider\s+temporarily\s+unavailable)\b/iu',
        $reply
    ) === 1) {
        return true;
    }

    $requested_count = max(1, min(20, intval($brief['requested_count'] ?? 10)));
    preg_match_all(
        '/(?:^|\s)([1-9]|1[0-9]|20)[\).:\-]\s+/u',
        $reply,
        $number_matches
    );
    $numbers = array_values(array_unique(array_map(
        'intval',
        (array) ($number_matches[1] ?? [])
    )));

    for ($number = 1; $number <= $requested_count; $number++) {
        if (!in_array($number, $numbers, true)) return true;
    }

    return false;
}

