        if (defined('AIMEE_PWA_START_PATH')) { $path = (string) AIMEE_PWA_START_PATH; }
        else { $path = function_exists('aimee_global_route') && aimee_global_market() === 'us' ? '/chat-us/' : '/chat/'; }
        $path = '/' . trim($path, '/') . '/';
        return $path === '//' ? '/' : $path;
    }
