if (!function_exists('aimee_pwa_asset_url')) {
    function aimee_pwa_asset_url($filename) {
        return defined('AIMEE_GLOBAL_URL') ? trailingslashit(AIMEE_GLOBAL_URL) . 'assets/pwa/' . ltrim((string) $filename, '/') : trailingslashit(get_stylesheet_directory_uri()) . 'assets/pwa/' . ltrim((string) $filename, '/');
    }
}

if (!function_exists('aimee_pwa_is_app_page')) {
    function aimee_pwa_is_app_page() {
        if (is_admin()) return false;

        $request_path = wp_parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH);
        $request_path = '/' . trim((string) $request_path, '/') . '/';
        if ($request_path === aimee_pwa_start_path()) return true;

        if (function_exists('is_page') && is_page(['chat', 'chat-us', 'portal'])) return true;

        $template = '';
        $queried_id = get_queried_object_id();
        if ($queried_id) {
            $template = (string) get_page_template_slug($queried_id);
        }

        return $template !== '' && (
            stripos($template, 'aimee-app') !== false ||
            stripos($template, 'claudia-prototype') !== false
        );
    }
}

