if (!function_exists('aimee_pwa_service_worker_source')) {
    function aimee_pwa_service_worker_source() {
        $cache_name = 'aimee-static-v2';
        $start_path = aimee_pwa_start_path();
        $icons = [
            aimee_pwa_asset_url('aimee-icon-180.png'),
            aimee_pwa_asset_url('aimee-icon-192.png'),
            aimee_pwa_asset_url('aimee-icon-512.png'),
            aimee_pwa_asset_url('aimee-icon-maskable-512.png'),
        ];

        $offline_html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0066CC"><title>Aimee is waiting</title><style>html,body{height:100%;margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#EFEAE2;color:#111B21}main{min-height:100%;display:grid;place-items:center;padding:28px;box-sizing:border-box}.card{width:min(420px,100%);background:#fff;border-radius:26px;padding:32px;text-align:center;box-shadow:0 24px 70px rgba(0,0,0,.14)}img{width:92px;height:92px;border-radius:50%;object-fit:cover;margin-bottom:18px}h1{font-size:24px;margin:0 0 10px}p{color:#667781;line-height:1.55;margin:0 0 22px}button{border:0;border-radius:999px;background:#0066CC;color:#fff;padding:14px 22px;font-size:15px;font-weight:700;cursor:pointer}</style></head><body><main><div class="card"><img src="' . esc_url(aimee_pwa_asset_url('aimee-icon-192.png')) . '" alt=""><h1>Aimee is still here</h1><p>Your connection appears to be offline. Reconnect and try again, and your conversation will continue where you left it.</p><button onclick="location.reload()">Try again</button></div></main></body></html>';

        $script = <<<'JS'
const CACHE_NAME = __CACHE_NAME__;
const APP_SCOPE_PATH = __APP_SCOPE_PATH__;
const PRECACHE_URLS = __PRECACHE_URLS__;
const OFFLINE_HTML = __OFFLINE_HTML__;

self.addEventListener('install', event => {
    event.waitUntil(
        caches.open(CACHE_NAME)
            .then(cache => cache.addAll(PRECACHE_URLS))
            .then(() => self.skipWaiting())
    );
});

self.addEventListener('activate', event => {
    event.waitUntil(
        caches.keys()
            .then(keys => Promise.all(
                keys
                    .filter(key => key.startsWith('aimee-static-') && key !== CACHE_NAME)
                    .map(key => caches.delete(key))
            ))
            .then(() => self.clients.claim())
    );
});

self.addEventListener('message', event => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
        self.skipWaiting();
        return;
    }

    if (event.data && event.data.type === 'AIMEE_SET_PUSH_DEVICE_TOKEN') {
        const token = String(event.data.token || '');
        event.waitUntil(
            caches.open('aimee-push-meta-v1').then(cache =>
                cache.put(
                    '/aimee-push-device-token',
                    new Response(token, {
                        headers: { 'Content-Type': 'text/plain; charset=UTF-8' }
                    })
                )
            )
        );
    }
});

async function aimeePushDeviceToken() {
    const cache = await caches.open('aimee-push-meta-v1');
    const response = await cache.match('/aimee-push-device-token');
    return response ? (await response.text()).trim() : '';
}

self.addEventListener('push', event => {
    event.waitUntil((async () => {
        const deviceToken = await aimeePushDeviceToken();
        let notification = {
            title: 'Aimee',
            body: 'I left you something in the app. x',
            tag: 'aimee-message',
            url: APP_SCOPE_PATH,
            icon: __PUSH_ICON__,
            badge: __PUSH_ICON__
        };

        if (deviceToken) {
            try {
                const response = await fetch(__PUSH_PAYLOAD_URL__, {
                    method: 'POST',
                    cache: 'no-store',
                    credentials: 'omit',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ device_token: deviceToken })
                });

                const data = await response.json();
                if (data && data.notification) {
                    notification = { ...notification, ...data.notification };
                }
            } catch (error) {
                // The generic notification above is deliberately discreet.
            }
        }

        await self.registration.showNotification(
            notification.title || 'Aimee',
            {
                body: notification.body || 'I left you something in the app. x',
                icon: notification.icon || __PUSH_ICON__,
                badge: notification.badge || __PUSH_ICON__,
                tag: notification.tag || 'aimee-message',
                renotify: false,
                data: { url: notification.url || APP_SCOPE_PATH }
            }
        );
    })());
});

self.addEventListener('notificationclick', event => {
    event.notification.close();
    const targetUrl = event.notification.data && event.notification.data.url
        ? event.notification.data.url
        : APP_SCOPE_PATH;

    event.waitUntil(
        clients.matchAll({ type: 'window', includeUncontrolled: true })
            .then(windowClients => {
                for (const client of windowClients) {
                    if ('focus' in client) {
                        client.navigate(targetUrl);
                        return client.focus();
                    }
                }
                return clients.openWindow ? clients.openWindow(targetUrl) : null;
            })
    );
});

function isSensitiveRequest(url) {
    return (
        url.pathname.startsWith('/wp-json/') ||
        url.pathname.startsWith('/wp-admin/') ||
        url.pathname.startsWith('/wp-login.php') ||
        url.pathname.includes('admin-post.php') ||
        url.searchParams.has('action') ||
        url.searchParams.has('_wpnonce')
    );
}

self.addEventListener('fetch', event => {
    const request = event.request;
    if (request.method !== 'GET') return;

    const url = new URL(request.url);
    if (url.origin !== self.location.origin) return;
    if (isSensitiveRequest(url)) return;

    if (request.mode === 'navigate') {
        event.respondWith(
            fetch(request).catch(() => new Response(OFFLINE_HTML, {
                status: 503,
                statusText: 'Offline',
                headers: { 'Content-Type': 'text/html; charset=UTF-8' }
            }))
        );
        return;
    }

    const cacheableDestinations = new Set(['style', 'script', 'image', 'font']);
    if (!cacheableDestinations.has(request.destination) || url.search) return;

    event.respondWith(
        caches.match(request).then(cached => {
            const refreshed = fetch(request).then(response => {
                if (response && response.ok && response.type === 'basic') {
                    const clone = response.clone();
                    caches.open(CACHE_NAME).then(cache => cache.put(request, clone));
                }
                return response;
            }).catch(() => cached);

            return cached || refreshed;
        })
    );
});
JS;

        return strtr($script, [
            '__CACHE_NAME__'    => wp_json_encode($cache_name),
            '__APP_SCOPE_PATH__'=> wp_json_encode($start_path),
            '__PRECACHE_URLS__' => wp_json_encode(array_values($icons)),
            '__OFFLINE_HTML__'    => wp_json_encode($offline_html),
            '__PUSH_PAYLOAD_URL__'=> wp_json_encode(rest_url('aimee/v1/push-payload')),
            '__PUSH_ICON__'       => wp_json_encode(aimee_pwa_asset_url('aimee-icon-192.png')),
        ]);
    }
}

if (!function_exists('aimee_pwa_serve_virtual_assets')) {
    function aimee_pwa_serve_virtual_assets() {
        $path = wp_parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH);

        if ($path === '/aimee.webmanifest') {
            status_header(200);
            header('Content-Type: application/manifest+json; charset=UTF-8');
            header('Cache-Control: public, max-age=3600');
            echo wp_json_encode(aimee_pwa_manifest(), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
            exit;
        }

        if ($path === '/aimee-sw.js') {
            status_header(200);
            header('Content-Type: application/javascript; charset=UTF-8');
            header('Cache-Control: no-cache, no-store, must-revalidate');
            header('Service-Worker-Allowed: ' . aimee_pwa_start_path());
            echo aimee_pwa_service_worker_source();
            exit;
        }
    }
}
add_action('template_redirect', 'aimee_pwa_serve_virtual_assets', -100);

