                    <div class="aimee-pwa-install-copy">
                        <h3 id="aimee-pwa-install-title">Keep Aimee close</h3>
                        <p id="aimee-pwa-install-description">Install Aimee for one-tap access and a private, full-screen app experience.</p>
                    </div>
                </div>
                <div id="aimee-pwa-install-instructions" class="aimee-pwa-instructions"></div>
                <div class="aimee-pwa-install-actions">
                    <button id="aimee-pwa-install-later" type="button">Not now</button>
                    <button id="aimee-pwa-install-primary" type="button">Install Aimee</button>
                </div>
            </div>
        </div>
        <?php endif; ?>

        <script>
        (function() {
            const config = <?php echo wp_json_encode($config, JSON_UNESCAPED_SLASHES); ?>;
            const DISMISS_KEY = 'aimee_pwa_dismissed_until';
            const INSTALLED_KEY = 'aimee_pwa_installed';
            const SNOOZE_MS = 7 * 24 * 60 * 60 * 1000;

            const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent)
                || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
            const isSafari = /^((?!chrome|android|crios|fxios|edgios).)*safari/i.test(navigator.userAgent);
            const isStandalone = () =>
                window.matchMedia('(display-mode: standalone)').matches ||
                window.matchMedia('(display-mode: fullscreen)').matches ||
                window.navigator.standalone === true;

            function track(eventName, properties) {
                if (!config.loggedIn || !config.nonce) return;

                window.dataLayer = window.dataLayer || [];
                window.dataLayer.push({
                    event: 'aimee_' + eventName,
                    ...(properties || {})
                });

                fetch(config.analyticsUrl, {
                    method: 'POST',
                    credentials: 'same-origin',
                    keepalive: true,
                    headers: {
                        'Content-Type': 'application/json',
                        'X-WP-Nonce': config.nonce
                    },
                    body: JSON.stringify({
                        event_name: eventName,
                        properties: properties || {},
                        page_path: window.location.pathname,
                        occurred_at: new Date().toISOString()
                    })
                }).catch(() => {});
            }

            function manualInstructions() {
                if (isIOS) {
                    return {
                        title: 'Add Aimee to your Home Screen',
                        description: 'Apple keeps the final install step inside the Share menu.',
                        instructions: 'Tap the <strong>Share</strong> button in Safari, choose <strong>Add to Home Screen</strong>, then tap <strong>Add</strong>.',
                        button: 'Got it'
                    };
                }

                if (isSafari) {
                    return {
                        title: 'Add Aimee to your Dock',
                        description: 'Safari installs web apps through its own menu.',
                        instructions: 'Open Safari’s <strong>File</strong> menu and choose <strong>Add to Dock</strong>. On older versions, use the Share menu and choose <strong>Add to Home Screen</strong>.',
                        button: 'Got it'
                    };
                }

                return {
                    title: 'Install Aimee',
                    description: 'Your browser can add Aimee as an app from its main menu.',
                    instructions: 'Open your browser menu and choose <strong>Install app</strong>, <strong>Add to Home screen</strong>, or the similarly named option.',
                    button: 'Got it'
                };
            }

            function installReady() {
                return Boolean(window.aimeeDeferredInstallPrompt);
            }

            function injectSettingsOption() {
                if (!config.loggedIn || document.getElementById('aimee-pwa-settings-block')) return;

                const saveButton = document.getElementById('update-profile-btn');
                if (!saveButton) return;

                const block = document.createElement('div');
                block.id = 'aimee-pwa-settings-block';
                block.innerHTML = `
                    <div class="settings-divider">App</div>
                    <div class="membership-status-card">
                        <div class="membership-status-row">
                            <div>
                                <div id="aimee-pwa-settings-status" class="aimee-pwa-status-pill">Available</div>
                                <p id="aimee-pwa-settings-detail" style="font-size:13px;color:var(--text-muted);margin:10px 0 0;line-height:1.45;">
                                    Install Aimee on this device for one-tap access and a full-screen experience.
                                </p>
                            </div>
                            <button id="aimee-pwa-settings-button" type="button">Install Aimee</button>
                        </div>
                    </div>
                `;
                saveButton.insertAdjacentElement('afterend', block);

                const button = document.getElementById('aimee-pwa-settings-button');
                if (button) {
                    button.addEventListener('click', () => openInstallModal(false));
                }

                updateSettingsOption();
            }

            function updateSettingsOption() {
                const status = document.getElementById('aimee-pwa-settings-status');
                const detail = document.getElementById('aimee-pwa-settings-detail');
                const button = document.getElementById('aimee-pwa-settings-button');
                if (!status || !detail || !button) return;

                if (isStandalone() || localStorage.getItem(INSTALLED_KEY) === '1') {
                    status.textContent = 'Installed';
                    status.classList.add('installed');
                    detail.textContent = 'Aimee is installed on this device and opens in her own full-screen window.';
                    button.textContent = 'Installed';
                    button.disabled = true;
                    return;
                }

                status.textContent = installReady() ? 'Ready to install' : 'Available';
                status.classList.remove('installed');
                detail.textContent = installReady()
                    ? 'Aimee can be installed directly on this device now.'
                    : 'Install Aimee on this device for one-tap access and a full-screen experience.';
                button.textContent = installReady() ? 'Install Aimee' : 'How to install';
                button.disabled = false;
            }

            function closeInstallModal(snooze) {
                const modal = document.getElementById('aimee-pwa-install-modal');
                if (!modal) return;

                modal.classList.remove('open');
                modal.setAttribute('aria-hidden', 'true');

                if (snooze) {
                    localStorage.setItem(DISMISS_KEY, String(Date.now() + SNOOZE_MS));
                    track('pwa_install_dismissed', { source: 'prompt' });
                }
            }

            function prepareModalForCurrentBrowser() {
                const title = document.getElementById('aimee-pwa-install-title');
                const description = document.getElementById('aimee-pwa-install-description');
                const instructions = document.getElementById('aimee-pwa-install-instructions');
                const primary = document.getElementById('aimee-pwa-install-primary');
                if (!title || !description || !instructions || !primary) return;

                if (installReady()) {
                    title.textContent = 'Keep Aimee close';
                    description.textContent = 'Install Aimee for one-tap access and a private, full-screen app experience.';
                    instructions.classList.remove('visible');
                    instructions.innerHTML = '';
                    primary.textContent = 'Install Aimee';
                    primary.dataset.mode = 'native';
                } else {
                    const manual = manualInstructions();
                    title.textContent = manual.title;
                    description.textContent = manual.description;
                    instructions.innerHTML = manual.instructions;
                    instructions.classList.add('visible');
                    primary.textContent = manual.button;
                    primary.dataset.mode = 'manual';
                }
            }

            function openInstallModal(automatic) {
                if (!config.loggedIn || isStandalone()) return;

                const modal = document.getElementById('aimee-pwa-install-modal');
                const primary = document.getElementById('aimee-pwa-install-primary');
                if (!modal || !primary) return;

                prepareModalForCurrentBrowser();
                modal.classList.add('open');
                modal.setAttribute('aria-hidden', 'false');
                setTimeout(() => primary.focus(), 50);

                track('pwa_prompt_shown', {
                    source: automatic ? 'automatic' : 'settings',
                    native_prompt_ready: installReady(),
                    ios: isIOS
                });
            }

            function maybeShowAutomaticPrompt() {
                if (!config.loggedIn || isStandalone()) return;

                const dismissedUntil = Number(localStorage.getItem(DISMISS_KEY) || 0);
                if (dismissedUntil > Date.now()) return;

                if (!installReady() && !isIOS) return;

                window.clearTimeout(window.aimeePwaPromptTimer);
                window.aimeePwaPromptTimer = window.setTimeout(() => {
                    openInstallModal(true);
                }, 4200);
            }

            async function runInstallAction() {
                const primary = document.getElementById('aimee-pwa-install-primary');
                if (!primary) return;

                if (primary.dataset.mode !== 'native' || !window.aimeeDeferredInstallPrompt) {
                    track('pwa_manual_instructions_shown', { ios: isIOS, safari: isSafari });
                    closeInstallModal(false);
                    return;
                }

                const promptEvent = window.aimeeDeferredInstallPrompt;
                primary.disabled = true;
                track('pwa_install_clicked', { source: 'prompt' });

                try {
                    await promptEvent.prompt();
                    const choice = await promptEvent.userChoice;
                    window.aimeeDeferredInstallPrompt = null;

                    if (choice && choice.outcome === 'accepted') {
                        localStorage.setItem(INSTALLED_KEY, '1');
                        track('pwa_install_accepted', {});
                    } else {
                        localStorage.setItem(DISMISS_KEY, String(Date.now() + SNOOZE_MS));
                        track('pwa_install_dismissed', { source: 'native_prompt' });
                    }
                } catch (error) {
                    console.warn('Aimee installation prompt failed.', error);
                } finally {
                    primary.disabled = false;
                    closeInstallModal(false);
                    updateSettingsOption();
                }
            }

            function initialisePwaUi() {
                if (isStandalone()) {
                    localStorage.setItem(INSTALLED_KEY, '1');
                }

                injectSettingsOption();
                updateSettingsOption();

                const later = document.getElementById('aimee-pwa-install-later');
                const primary = document.getElementById('aimee-pwa-install-primary');
                const modal = document.getElementById('aimee-pwa-install-modal');

                if (later) later.addEventListener('click', () => closeInstallModal(true));
                if (primary) primary.addEventListener('click', runInstallAction);
                if (modal) {
                    modal.addEventListener('click', event => {
                        if (event.target === modal) closeInstallModal(true);
                    });
                }

                document.addEventListener('keydown', event => {
                    if (event.key === 'Escape') closeInstallModal(true);
                });

                const params = new URLSearchParams(window.location.search);
                if (config.loggedIn && params.get('source') === 'pwa') {
                    window.setTimeout(() => {
                        const chatButton = document.getElementById('nav-to-chat-btn');
                        if (chatButton) chatButton.click();

                        const cleanUrl = window.location.pathname + window.location.hash;
                        window.history.replaceState({}, document.title, cleanUrl);
                    }, 120);
                }

                maybeShowAutomaticPrompt();
            }

            window.addEventListener('aimee:pwa-ready', () => {
                updateSettingsOption();
                maybeShowAutomaticPrompt();
            });

            window.addEventListener('appinstalled', () => {
                window.aimeeDeferredInstallPrompt = null;
                localStorage.setItem(INSTALLED_KEY, '1');
                closeInstallModal(false);
                updateSettingsOption();
                track('pwa_installed', {});
            });

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', initialisePwaUi);
            } else {
                initialisePwaUi();
            }
        })();
        </script>
        <?php
    }
}
add_action('wp_footer', 'aimee_pwa_footer_ui', 99);


