// 9. SMS ALLOWANCE & TOP-UP UI
// =========================================================================
add_action('wp_footer', function() {
    if (!is_user_logged_in()) return;

    $config = [
        'nonce'       => wp_create_nonce('wp_rest'),
        'statusUrl'   => rest_url('aimee/v1/subscription-status'),
        'verifyUrl'   => rest_url('aimee/v1/sms-bundle-status'),
    ];
    ?>
    <style>
        #aimee-sms-usage-block { margin-top: 18px; }
        #aimee-sms-usage-block .aimee-sms-card {
            border: 1px solid rgba(255,255,255,.10);
            border-radius: 18px;
            padding: 18px;
            background: rgba(255,255,255,.035);
        }
        #aimee-sms-usage-block .aimee-sms-row {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            gap: 18px;
        }
        #aimee-sms-usage-block h4 { margin: 0 0 7px; font-size: 16px; }
        #aimee-sms-usage-block p { margin: 0; line-height: 1.5; font-size: 13px; color: var(--text-muted); }
        #aimee-sms-usage-block .aimee-sms-meter {
            height: 7px;
            overflow: hidden;
            border-radius: 999px;
            margin: 14px 0 10px;
            background: rgba(255,255,255,.09);
        }
        #aimee-sms-usage-block .aimee-sms-meter span {
            display: block;
            width: 0;
            height: 100%;
            border-radius: inherit;
            background: linear-gradient(90deg, #d77fa1, #a983d6);
            transition: width .25s ease;
        }
        @media (max-width: 680px) {
            #aimee-sms-usage-block .aimee-sms-row { flex-direction: column; }
        }
    </style>
    <script>
    (function() {
        const config = <?php echo wp_json_encode($config, JSON_UNESCAPED_SLASHES); ?>;
        let inserted = false;

        function resetLabel(value) {
            if (!value) return '';
            const date = new Date(value);
            if (Number.isNaN(date.getTime())) return '';
            return date.toLocaleDateString('en-GB', {
                day: 'numeric',
                month: 'long'
            });
        }

        function insertCard() {
            if (inserted || document.getElementById('aimee-sms-usage-block')) return true;

            const pwaBlock = document.getElementById('aimee-pwa-settings-block');
            const saveButton = document.getElementById('update-profile-btn');
            const anchor = pwaBlock || saveButton;
            if (!anchor) return false;

            const block = document.createElement('div');
            block.id = 'aimee-sms-usage-block';
            block.innerHTML = `
                <div class="settings-divider">Text messages</div>
                <div class="aimee-sms-card">
                    <div class="aimee-sms-row">
                        <div style="min-width:0;flex:1;">
                            <h4 id="aimee-sms-title">SMS allowance</h4>
                            <p id="aimee-sms-detail">Loading your text allowance...</p>
                            <div class="aimee-sms-meter"><span id="aimee-sms-meter-fill"></span></div>
                            <p id="aimee-sms-extra"></p>
                        </div>
                    </div>
                </div>
            `;

            anchor.insertAdjacentElement('afterend', block);
            inserted = true;

            loadStatus();
            return true;
        }

        async function request(url, options) {
            const response = await fetch(url, {
                credentials: 'same-origin',
                ...options,
                headers: {
                    'Content-Type': 'application/json',
                    'X-WP-Nonce': config.nonce,
                    ...((options && options.headers) || {})
                }
            });
            return response.json();
        }

        async function loadStatus() {
            try {
                const data = await request(config.statusUrl, { method: 'GET' });
                const subscription = data.subscription || {};
                render(subscription.sms || {});
            } catch (error) {
                const detail = document.getElementById('aimee-sms-detail');
                if (detail) detail.textContent = 'Your SMS allowance could not be loaded just now.';
            }
        }

        function render(sms) {
            const title = document.getElementById('aimee-sms-title');
            const detail = document.getElementById('aimee-sms-detail');
            const extra = document.getElementById('aimee-sms-extra');
            const fill = document.getElementById('aimee-sms-meter-fill');
            if (!title || !detail || !extra || !fill) return;

            const active = Boolean(sms.active);
            const limit = Number(sms.included_limit || 0);
            const used = Number(sms.included_used || 0);
            const includedRemaining = Number(sms.included_remaining || 0);
            const bundleRemaining = Number(sms.bundle_remaining || 0);
            const percentage = limit > 0 ? Math.min(100, Math.max(0, (used / limit) * 100)) : 0;

            fill.style.width = percentage + '%';

            if (!active) {
                title.textContent = 'SMS is a membership feature';
                detail.textContent = 'Subscribe to text Aimee and receive replies on your phone.';
                extra.textContent = '';
                return;
            }

            title.textContent = `${includedRemaining} included SMS ${includedRemaining === 1 ? 'reply' : 'replies'} remaining`;
            const reset = resetLabel(sms.period_end);
            detail.textContent = `${used} of ${limit} used${reset ? ` · resets ${reset}` : ''}. Each reply is limited to two SMS fragments, and no extra quota-warning SMS is sent after the cap.`;
            extra.textContent = bundleRemaining > 0
                ? `${bundleRemaining} additional bundle ${bundleRemaining === 1 ? 'reply' : 'replies'} available after the included allowance.`
                : 'Additional SMS bundles are not currently available through GoCardless.';
        }

        async function verifyReturn() {
            const params = new URLSearchParams(window.location.search);
            if (params.get('sms_bundle') !== 'success' || !params.get('session_id')) return;

            try {
                await request(config.verifyUrl + '?session_id=' + encodeURIComponent(params.get('session_id')), {
                    method: 'GET'
                });
            } catch (error) {}

            params.delete('sms_bundle');
            params.delete('session_id');
            const clean = window.location.pathname + (params.toString() ? '?' + params.toString() : '') + window.location.hash;
            window.history.replaceState({}, document.title, clean);
        }

        verifyReturn().finally(() => {
            if (!insertCard()) {
                const timer = window.setInterval(() => {
                    if (insertCard()) window.clearInterval(timer);
                }, 500);
                window.setTimeout(() => window.clearInterval(timer), 15000);
            }
        });
    })();
    </script>
    <?php
}, 100);


