    .aimee-story-item p { margin: 0; color: #52525B; line-height: 1.58; font-size: 14px; }
    .aimee-story-item img {
        display: block;
        width: min(280px, 100%);
        max-height: 360px;
        object-fit: cover;
        border-radius: 16px;
