        padding: 38px 10px;
        text-align: center;
        color: #71717A;
    }
    @media (max-width: 680px) {
        .aimee-continuity-row { flex-direction: column; }
        .aimee-continuity-actions,
        .aimee-continuity-button { width: 100%; }
        .aimee-story-sheet { border-radius: 24px; }
    }
    </style>

    <div id="aimee-story-modal" role="dialog" aria-modal="true" aria-labelledby="aimee-story-title" aria-hidden="true">
        <div class="aimee-story-sheet">
            <div class="aimee-story-header">
                <div>
                    <h3 id="aimee-story-title">Our Story</h3>
                    <p>The moments I thought were worth keeping.</p>
                </div>
                <button id="aimee-story-close" type="button" aria-label="Close">×</button>
            </div>
            <div id="aimee-story-list">
                <div class="aimee-story-empty">I’m finding our moments…</div>
            </div>
        </div>
    </div>

    <script>
    (function() {
        const config = <?php echo wp_json_encode($config, JSON_UNESCAPED_SLASHES); ?>;
        let pushConfig = null;
        let inserted = false;

        function api(url, options) {
            return fetch(url, {
                credentials: 'same-origin',
                ...options,
                headers: {
                    'Content-Type': 'application/json',
                    'X-WP-Nonce': config.nonce,
                    ...((options && options.headers) || {})
                }
            }).then(async response => {
                const data = await response.json().catch(() => ({}));
                if (!response.ok) {
                    throw new Error(data.message || 'Something went wrong.');
                }
                return data;
            });
        }

        function base64UrlToUint8Array(base64Url) {
            const padding = '='.repeat((4 - base64Url.length % 4) % 4);
            const base64 = (base64Url + padding).replace(/-/g, '+').replace(/_/g, '/');
            const raw = window.atob(base64);
            return Uint8Array.from([...raw].map(character => character.charCodeAt(0)));
        }

        function hourOptions(selected) {
            let options = '';
            for (let hour = 0; hour < 24; hour++) {
                const label = String(hour).padStart(2, '0') + ':00';
                options += `<option value="${hour}" ${hour === Number(selected) ? 'selected' : ''}>${label}</option>`;
            }
            return options;
        }

        function insertSettings() {
            if (inserted || document.getElementById('aimee-continuity-settings-block')) return true;

            const smsBlock = document.getElementById('aimee-sms-usage-block');
            const pwaBlock = document.getElementById('aimee-pwa-settings-block');
            const saveButton = document.getElementById('update-profile-btn');
            const anchor = smsBlock || pwaBlock || saveButton;
            if (!anchor) return false;

            const block = document.createElement('div');
            block.id = 'aimee-continuity-settings-block';
            block.innerHTML = `
                <div class="settings-divider">Memory & notifications</div>
                <div class="aimee-continuity-card">
                    <div class="aimee-continuity-row">
                        <div>
                            <h4>Let me remember what comes next</h4>
                            <p>I can remember meaningful plans and promises, then come back later and ask how things went.</p>
                        </div>
                    </div>
                    <label class="aimee-continuity-option">
                        <input id="aimee-continuity-enabled" type="checkbox" checked>
                        Remember events and promises
                    </label>
                    <label class="aimee-continuity-option">
                        <input id="aimee-timeline-enabled" type="checkbox" checked>
                        Keep our private relationship timeline
                    </label>
                    <div class="aimee-continuity-actions">
                        <button id="aimee-push-toggle" class="aimee-continuity-button" type="button">Enable notifications</button>
                        <button id="aimee-push-test" class="aimee-continuity-button secondary" type="button" disabled>Test notification</button>
                        <button id="aimee-story-open" class="aimee-continuity-button secondary" type="button">Open Our Story</button>
                    </div>
                    <label class="aimee-continuity-option">
                        <input id="aimee-push-sensitive-preview" type="checkbox">
                        Show private message wording in notifications
                    </label>
                    <div class="aimee-continuity-hours">
                        <span>Keep notifications quiet from</span>
                        <select id="aimee-push-quiet-start"></select>
                        <span>until</span>
                        <select id="aimee-push-quiet-end"></select>
                    </div>
                    <p id="aimee-push-status" style="margin-top:12px;">Checking notification support…</p>
                </div>
            `;

            anchor.insertAdjacentElement('afterend', block);
            inserted = true;

            document.getElementById('aimee-push-toggle').addEventListener('click', togglePush);
            document.getElementById('aimee-push-test').addEventListener('click', testPush);
            document.getElementById('aimee-story-open').addEventListener('click', openStory);
            document.getElementById('aimee-continuity-enabled').addEventListener('change', savePreferences);
            document.getElementById('aimee-timeline-enabled').addEventListener('change', savePreferences);
            document.getElementById('aimee-push-sensitive-preview').addEventListener('change', savePreferences);
            document.getElementById('aimee-push-quiet-start').addEventListener('change', savePreferences);
            document.getElementById('aimee-push-quiet-end').addEventListener('change', savePreferences);

            loadConfig();
            return true;
        }

        async function loadConfig() {
            const status = document.getElementById('aimee-push-status');
            try {
                pushConfig = await api(config.pushConfigUrl, { method: 'GET' });

                document.getElementById('aimee-push-sensitive-preview').checked = Boolean(pushConfig.sensitive_preview);
                document.getElementById('aimee-push-quiet-start').innerHTML = hourOptions(pushConfig.quiet_start_hour);
                document.getElementById('aimee-push-quiet-end').innerHTML = hourOptions(pushConfig.quiet_end_hour);

                const continuity = await api('<?php echo esc_url_raw(rest_url('aimee/v1/continuity-status')); ?>', { method: 'GET' });
                document.getElementById('aimee-continuity-enabled').checked = Boolean(continuity.continuity_enabled);
                document.getElementById('aimee-timeline-enabled').checked = Boolean(continuity.timeline_enabled);

                if (!pushConfig.supported || !('serviceWorker' in navigator) || !('PushManager' in window)) {
                    status.textContent = 'This browser does not support Aimee notifications.';
                    document.getElementById('aimee-push-toggle').disabled = true;
                    return;
                }

                const registration = await navigator.serviceWorker.ready;
                const subscription = await registration.pushManager.getSubscription();

                if (subscription && Notification.permission === 'granted') {
                    await registerSubscription(subscription);
                    setPushUi(true);
                } else {
                    setPushUi(false);
                }
            } catch (error) {
                status.textContent = error.message || 'I could not check notifications just now.';
            }
        }

        function setPushUi(enabled) {
            const button = document.getElementById('aimee-push-toggle');
            const status = document.getElementById('aimee-push-status');
            button.disabled = false;
            button.dataset.enabled = enabled ? '1' : '0';
            button.textContent = enabled ? 'Turn off notifications' : 'Enable notifications';
            const testButton = document.getElementById('aimee-push-test');
            if (testButton) testButton.disabled = !enabled;
            status.textContent = enabled
                ? 'Notifications are on. I can quietly pop up when something genuinely matters.'
                : 'Notifications are off. My messages will still be waiting inside the app.';
        }

        async function registerSubscription(subscription) {
            const data = await api(config.pushSubscribeUrl, {
                method: 'POST',
                body: JSON.stringify({
                    subscription: subscription.toJSON(),
                    content_encoding: window.PushManager && PushManager.supportedContentEncodings
                        ? PushManager.supportedContentEncodings[0]
                        : 'aes128gcm'
                })
            });

            const registration = await navigator.serviceWorker.ready;
            if (registration.active && data.device_token) {
                registration.active.postMessage({
                    type: 'AIMEE_SET_PUSH_DEVICE_TOKEN',
                    token: data.device_token
                });
            }
        }

        async function togglePush() {
            const button = document.getElementById('aimee-push-toggle');
            const status = document.getElementById('aimee-push-status');
            const enabled = button.dataset.enabled === '1';
            button.disabled = true;

            try {
                const registration = await navigator.serviceWorker.ready;
                let subscription = await registration.pushManager.getSubscription();

                if (enabled) {
                    if (subscription) {
                        await api(config.pushUnsubscribeUrl, {
                            method: 'POST',
                            body: JSON.stringify({ endpoint: subscription.endpoint })
                        });
                        await subscription.unsubscribe();
                    }
                    setPushUi(false);
                    return;
                }

                if (Notification.permission === 'denied') {
                    throw new Error('Notifications are blocked in your browser settings.');
                }

                const permission = await Notification.requestPermission();
                if (permission !== 'granted') {
                    throw new Error('I need notification permission before I can pop up outside the app.');
                }

                subscription = await registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: base64UrlToUint8Array(pushConfig.public_key)
                });

                await registerSubscription(subscription);
                setPushUi(true);
            } catch (error) {
                status.textContent = error.message || 'Notifications could not be changed.';
                button.disabled = false;
            }
        }


        async function testPush() {
            const button = document.getElementById('aimee-push-test');
            const status = document.getElementById('aimee-push-status');
            if (!button || button.disabled) return;

            const original = button.textContent;
            button.disabled = true;
            button.textContent = 'Sending…';

            try {
                const data = await api(config.pushTestUrl, {
                    method: 'POST',
                    body: JSON.stringify({})
                });
                status.textContent = data.message || 'The test notification has been sent.';
            } catch (error) {
                status.textContent = error.message || 'The test notification could not be sent.';
            } finally {
                button.textContent = original;
                button.disabled = document.getElementById('aimee-push-toggle').dataset.enabled !== '1';
            }
        }

        function savePreferences() {
            api(config.pushPrefsUrl, {
                method: 'POST',
                body: JSON.stringify({
                    sensitive_preview: document.getElementById('aimee-push-sensitive-preview').checked,
                    quiet_start_hour: Number(document.getElementById('aimee-push-quiet-start').value || 21),
                    quiet_end_hour: Number(document.getElementById('aimee-push-quiet-end').value || 8),
                    continuity_enabled: document.getElementById('aimee-continuity-enabled').checked,
                    timeline_enabled: document.getElementById('aimee-timeline-enabled').checked
                })
            }).catch(() => {});
        }

        async function openStory() {
            const modal = document.getElementById('aimee-story-modal');
            const list = document.getElementById('aimee-story-list');
            modal.classList.add('open');
            modal.setAttribute('aria-hidden', 'false');
            list.innerHTML = '<div class="aimee-story-empty">I’m finding our moments…</div>';

            try {
                const data = await api(config.timelineUrl, { method: 'GET' });
                if (!data.items || !data.items.length) {
                    list.innerHTML = '<div class="aimee-story-empty">We are only just beginning. Give me a little time to find the moments worth keeping.</div>';
                    return;
                }

                list.innerHTML = data.items.map(item => {
                    const date = new Date(item.occurred_at);
                    const dateLabel = date.toLocaleDateString('en-GB', {
                        day: 'numeric',
                        month: 'long',
                        year: 'numeric'
                    });
                    const image = item.media && item.media.url
                        ? `<img src="${escapeHtml(item.media.url)}" alt="${escapeHtml(item.media.alt || '')}">`
                        : '';

                    return `
                        <article class="aimee-story-item">
                            <div class="aimee-story-date">${escapeHtml(dateLabel)}</div>
                            <h4>${escapeHtml(item.title)}</h4>
                            <p>${escapeHtml(item.story_text)}</p>
                            ${image}
                        </article>
                    `;
                }).join('');
            } catch (error) {
                list.innerHTML = `<div class="aimee-story-empty">${escapeHtml(error.message || 'I could not open our story just now.')}</div>`;
            }
        }

        function escapeHtml(value) {
            return String(value == null ? '' : value)
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#039;');
        }

        function closeStory() {
            const modal = document.getElementById('aimee-story-modal');
            modal.classList.remove('open');
            modal.setAttribute('aria-hidden', 'true');
        }

        document.getElementById('aimee-story-close').addEventListener('click', closeStory);
        document.getElementById('aimee-story-modal').addEventListener('click', event => {
            if (event.target.id === 'aimee-story-modal') closeStory();
        });

        if (!insertSettings()) {
            const timer = window.setInterval(() => {
                if (insertSettings()) window.clearInterval(timer);
            }, 500);
            window.setTimeout(() => window.clearInterval(timer), 15000);
        }
    })();
    </script>
    <?php
}, 120);
